INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物や人が、いっしょに助け合って生きること。", "primary_collocate": null, "pronunciation": "きょうせい", "ipa": "kʲoːseː", "syllable_count": 4, "sentences": [{"text": "イソギンチャクとクマノミは、助け合って共生している。", "target_word": "共生", "complexity_tier": "T3", "furigana": "イソギンチャクとクマノミは、助[たす]け合[あ]って共生[きょうせい]している。", "sentence_source": "generated"}, {"text": "老人と若者が共生する町づくりが進んでいる。", "target_word": "共生", "complexity_tier": "T3", "furigana": "老人[ろうじん]と若者[わかもの]が共生[きょうせい]する町[まち]づくりが進[すす]んでいる。", "sentence_source": "generated"}, {"text": "犬と人間は、長い間共生してきた。", "target_word": "共生", "complexity_tier": "T3", "furigana": "犬[いぬ]と人間[にんげん]は、長[なが]い間[あいだ]共生[きょうせい]してきた。", "sentence_source": "generated"}, {"text": "アリとアブラムシは共生しており、アリは甘い汁をもらう代わりにアブラムシを敵から守る。", "target_word": "共生", "complexity_tier": "T3", "furigana": "アリとアブラムシは共生[きょうせい]しており、アリは甘[あま]い汁[しる]をもらう代[か]わりにアブラムシを敵[てき]から守[まも]る。", "sentence_source": "generated"}, {"text": "森の木とキノコは共生していて、互いに必要な栄養を分け合う。", "target_word": "共生", "complexity_tier": "T3", "furigana": "森[もり]の木[き]とキノコは共生[きょうせい]していて、互[たが]いに必要[ひつよう]な栄養[えいよう]を分[わ]け合[あ]う。", "sentence_source": "generated"}, {"text": "クラスの全員が気持ちよく共生できるよう、みんなでルールを決めた。", "target_word": "共生", "complexity_tier": "T3", "furigana": "クラスの全員[ぜんいん]が気持[きも]ちよく共生[きょうせい]できるよう、みんなでルールを決[き]めた。", "sentence_source": "generated"}, {"text": "田舎の暮らしでは、隣の家と共生する気持ちが大切だ。", "target_word": "共生", "complexity_tier": "T3", "furigana": "田舎[いなか]の暮[く]らしでは、隣[となり]の家[いえ]と共生[きょうせい]する気持[きも]ちが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "水槽の中で、エビとハゼが共生する様子を観察した。", "target_word": "共生", "complexity_tier": "T3", "furigana": "水槽[すいそう]の中[なか]で、エビとハゼが共生[きょうせい]する様子[ようす]を観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "地域の人と学校が助け合う共生の取り組みが、ニュースで紹介された。", "target_word": "共生", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]と学校[がっこう]が助[たす]け合[あ]う共生[きょうせい]の取[と]り組[く]みが、ニュースで紹介[しょうかい]された。", "sentence_source": "generated"}, {"text": "人と自然の共生について、小学生が発表した。", "target_word": "共生", "complexity_tier": "T3", "furigana": "人[ひと]と自然[しぜん]の共生[きょうせい]について、小学生[しょうがくせい]が発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共生する", "label": "終止形"}, {"form": "共生した", "label": "過去形"}, {"form": "共生して", "label": "て形"}, {"form": "共生しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "生き物や人がいっしょに助け合って生きること(する名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38546, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "本文の形。助け合って共に生きる関係を表し、文に合う。"}, {"text": "放電", "is_correct": false, "explanation": "電気を逃がす意味で、「助け合って放電している」は生き物の関係として成り立たない。"}, {"text": "解体", "is_correct": false, "explanation": "ばらばらにする意味で、助け合う関係を表さないので文に合わない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、「助け合って施錠している」は文脈に合わない。"}], "explanations": {"共生": "本文の形。助け合って共に生きる関係を表し、文に合う。", "放電": "電気を逃がす意味で、「助け合って放電している」は生き物の関係として成り立たない。", "解体": "ばらばらにする意味で、助け合う関係を表さないので文に合わない。", "施錠": "鍵をかける意味で、「助け合って施錠している」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの店は共生して、客を奪い合っている。", "explanation": "ここは〈競争〉の意味。相手と争う関係を表す語で、互いに助け合う共生とは逆なので合わない。"}, {"text": "私たちは毎月、商品を共生して売り買いしている。", "explanation": "ここは〈取引〉の意味。物を売り買いする意味で、助け合って共に生きる共生とは違うので合わない。"}, {"text": "彼は親の仕送りに共生して生活している。", "explanation": "ここは〈依存〉の意味。頼り切る関係を表す語で、互いに助け合って共に生きる共生とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38546, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "本文の形。隣の家と共に生きる意味で、「共生する気持ち」として文に合う。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届ける意味で、「隣の家と配送する気持ち」は成り立たない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、人との関係を表す文脈に合わない。"}, {"text": "包装", "is_correct": false, "explanation": "物を包む意味で、隣の家との関係を表す文脈に合わない。"}], "explanations": {"共生": "本文の形。隣の家と共に生きる意味で、「共生する気持ち」として文に合う。", "配送": "荷物を届ける意味で、「隣の家と配送する気持ち」は成り立たない。", "点火": "火をつける意味で、人との関係を表す文脈に合わない。", "包装": "物を包む意味で、隣の家との関係を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二種類の金属が共生して、一つの新しい合金になった。", "explanation": "ここは〈融合〉の意味。別々のものが一体になる意味で、互いの存在を保ったまま共に生きる共生とは違うので合わない。"}, {"text": "工場では、作業員が部品を共生して、順番に組み立てる。", "explanation": "ここは〈分業〉の意味。仕事を分けて担当する意味で、共に生きる関係を表す共生は使わないので合わない。"}, {"text": "彼の話に共生して、家族は皆涙を流した。", "explanation": "ここは〈共感〉の意味。相手の気持ちを分かち合う意味で、共に生きる関係を表す共生とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38546, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホンヤドカリはイソギンチャクを共生して、天敵から身を守る。", "corrected_sentence": "ホンヤドカリはイソギンチャクと共生して、天敵から身を守る。", "error_description": "「共生」の相手は「と」で示す。「イソギンチャクを共生して」は誤りで、正しくは「イソギンチャクと共生して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38546, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この池では、魚と水草が共生な関係を築いている。", "corrected_sentence": "この池では、魚と水草が共生的な関係を築いている。", "error_description": "「共生」を連体修飾するには「共生的な」とする。「共生な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
