INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "異なるもの同士が、互いの存在を認め合いながら、共に生きていくこと。", "primary_collocate": null, "pronunciation": "きょうせい", "ipa": "kʲoːseː", "syllable_count": 4, "sentences": [{"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "共生", "complexity_tier": "T4", "furigana": "静謐[せいひつ]な工房[こうぼう]において、作[つく]り手[て]は野生酵母[やせいこうぼ]と乳酸菌[にゅうさんきん]の共生[きょうせい]するサワードウの種起[たねお]こしから営為[えいい]を開始[かいし]する。", "sentence_source": "mined"}, {"text": "多様な背景を持つ人々が共生できる社会を目指している。", "target_word": "共生", "complexity_tier": "T3", "furigana": "多様[たよう]な背景[はいけい]を持[も]つ人々[ひとびと]が共生[きょうせい]できる社会[しゃかい]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "私たちの町では、外国人住民と日本人住民が共生するための交流会を開いている。", "target_word": "共生", "complexity_tier": "T3", "furigana": "私[わたし]たちの町[まち]では、外国人[がいこくじん]住民[じゅうみん]と日本人[にほんじん]住民[じゅうみん]が共生[きょうせい]するための交流会[こうりゅうかい]を開[ひら]いている。", "sentence_source": "generated"}, {"text": "異なる言葉を話す人々が、互いの存在を認め合いながら共生している町だ。", "target_word": "共生", "complexity_tier": "T3", "furigana": "異[こと]なる言葉[ことば]を話[はな]す人々[ひとびと]が、互[たが]いの存在[そんざい]を認[みと]め合[あ]いながら共生[きょうせい]している町[まち]だ。", "sentence_source": "generated"}, {"text": "人間と自然が共生するためには、森を守る努力が欠かせない。", "target_word": "共生", "complexity_tier": "T3", "furigana": "人間[にんげん]と自然[しぜん]が共生[きょうせい]するためには、森[もり]を守[まも]る努力[どりょく]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "障害の有無にかかわらず、誰もが共生できる学校をつくりたい。", "target_word": "共生", "complexity_tier": "T3", "furigana": "障害[しょうがい]の有無[うむ]にかかわらず、誰[だれ]もが共生[きょうせい]できる学校[がっこう]をつくりたい。", "sentence_source": "generated"}, {"text": "異なる国の人々が同じ町で共生するため、互いの習慣を尊重している。", "target_word": "共生", "complexity_tier": "T3", "furigana": "異[こと]なる国[くに]の人々[ひとびと]が同[おな]じ町[まち]で共生[きょうせい]するため、互[たが]いの習慣[しゅうかん]を尊重[そんちょう]している。", "sentence_source": "generated"}, {"text": "異なる宗教の人々が共生してきた歴史が、この古い町にはある。", "target_word": "共生", "complexity_tier": "T3", "furigana": "異[こと]なる宗教[しゅうきょう]の人々[ひとびと]が共生[きょうせい]してきた歴史[れきし]が、この古[ふる]い町[まち]にはある。", "sentence_source": "generated"}, {"text": "共生を目指すなら、まず相手の考えを理解することが大切だ。", "target_word": "共生", "complexity_tier": "T3", "furigana": "共生[きょうせい]を目指[めざ]すなら、まず相手[あいて]の考[かんが]えを理解[りかい]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "都市の中で野生動物と共生する方法を、専門家が話し合った。", "target_word": "共生", "complexity_tier": "T3", "furigana": "都市[とし]の中[なか]で野生動物[やせいどうぶつ]と共生[きょうせい]する方法[ほうほう]を、専門家[せんもんか]が話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共生する", "label": "終止形"}, {"form": "共生した", "label": "過去形"}, {"form": "共生して", "label": "て形"}, {"form": "共生しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "異なる者同士が互いを認め合いながら共に生きること(する名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38547, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "本文の形。異なる生き物同士が共に生きる意味で、乳酸菌とサワードウの関係に合う。"}, {"text": "計量", "is_correct": false, "explanation": "分量をはかる意味で、「乳酸菌の計量するサワードウ」は文脈に合わない。"}, {"text": "縮小", "is_correct": false, "explanation": "規模を小さくする意味で、「乳酸菌の縮小するサワードウ」は成り立たない。"}, {"text": "解体", "is_correct": false, "explanation": "組み立てたものをばらす意味で、「乳酸菌の解体するサワードウ」は文脈に合わない。"}], "explanations": {"共生": "本文の形。異なる生き物同士が共に生きる意味で、乳酸菌とサワードウの関係に合う。", "計量": "分量をはかる意味で、「乳酸菌の計量するサワードウ」は文脈に合わない。", "縮小": "規模を小さくする意味で、「乳酸菌の縮小するサワードウ」は成り立たない。", "解体": "組み立てたものをばらす意味で、「乳酸菌の解体するサワードウ」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一つの細胞が共生して、二つに分かれた。", "explanation": "ここは〈分裂〉の意味。一つのものが二つに分かれる意味で、異なるもの同士が共に生きる共生とは違うので合わない。"}, {"text": "二つの色は共生して、一つの新しい色になった。", "explanation": "ここは〈融合〉の意味。別々のものが一つになる意味で、互いを保ったまま共に生きる共生とは逆なので合わない。"}, {"text": "工場は共生して、部品を毎日千個作っている。", "explanation": "ここは〈生産〉の意味。ものを作り出す意味で、共に生きる関係を表す共生は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38547, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "本文の形。異なる国の人々が共に生きる意味で、「共生するため」の目的として文に合う。"}, {"text": "放棄", "is_correct": false, "explanation": "権利や物を手放す意味で、「同じ町で放棄するため」は目的として成り立たない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、人々が町で共に暮らす目的にはならない。"}, {"text": "撤回", "is_correct": false, "explanation": "前の発言や決定を取り消す意味で、空欄に入ると文脈に合わない。"}], "explanations": {"共生": "本文の形。異なる国の人々が共に生きる意味で、「共生するため」の目的として文に合う。", "放棄": "権利や物を手放す意味で、「同じ町で放棄するため」は目的として成り立たない。", "施錠": "鍵をかける意味で、人々が町で共に暮らす目的にはならない。", "撤回": "前の発言や決定を取り消す意味で、空欄に入ると文脈に合わない。"}, "sentence_index": 6, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は友人の悲しみに共生して、一緒に涙を流した。", "explanation": "ここは〈共感〉の意味。相手の気持ちに寄り添う意味で、共に生きる関係を表す共生とは違うので合わない。"}, {"text": "与党と野党が共生して、激しく対立している。", "explanation": "ここは〈対立〉の意味。互いに争う関係を表し、認め合いながら共に生きる共生とは違うので合わない。"}, {"text": "三人は仕事を共生して分け、一日で終わらせた。", "explanation": "ここは〈分担〉の意味。作業を分けることで、異なるもの同士が共に生きる共生の意味とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38547, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農家は田んぼで、カエルを共生する稲作を試している。", "corrected_sentence": "農家は田んぼで、カエルと共生する稲作を試している。", "error_description": "「共生」は「〜と共生する」の形で相手を「と」で示す。「カエルを共生する」は誤りで、正しくは「カエルと共生する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38547, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々は、共生な取り組みで子育てを支えている。", "corrected_sentence": "町の人々は、共生的な取り組みで子育てを支えている。", "error_description": "「共生」を連体修飾するには「共生的な」とする。「共生な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知る」の目的語を示す。「社員の志向を知る」で意味が通る。"}, {"text": "が", "is_correct": false, "explanation": "「知る」の主語は会社なので、志向が主語になる形は文の意味に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「知る」は対象を直接取るので、「志向に知る」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、知る対象を示す場面では使えない。"}], "correct_answer": "を", "explanations": {"を": "「知る」の目的語を示す。「社員の志向を知る」で意味が通る。", "が": "「知る」の主語は会社なので、志向が主語になる形は文の意味に合わない。", "に": "「知る」は対象を直接取るので、「志向に知る」は不自然。", "へ": "方向を表す「へ」は、知る対象を示す場面では使えない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の対象を示す。「客の志向を調べる」で意味が通る。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」は、調べる対象を示す場面には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の語で、調べる対象を示すことはできない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ語で、動詞「調べる」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の対象を示す。「客の志向を調べる」で意味が通る。", "と": "相手や並列を示す「と」は、調べる対象を示す場面には合わない。", "より": "比較の語で、調べる対象を示すことはできない。", "の": "名詞をつなぐ語で、動詞「調べる」の対象にはならない。"}, "error_tags": {"と": "相手・並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目指すこと。したいと思うこと。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "彼は海外で働きたいという志向が強く、毎日英語を勉強している。", "target_word": "志向", "complexity_tier": "T3", "furigana": "彼[かれ]は海外[かいがい]で働[はたら]きたいという志向[しこう]が強[つよ]く、毎日[まいにち]英語[えいご]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "会社は若い社員の志向を知るために、アンケートを行った。", "target_word": "志向", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は若[わか]い社員[しゃいん]の志向[しこう]を知[し]るために、アンケートを行[おこな]った。", "sentence_source": "generated"}, {"text": "姉は安定した生活を望む志向があるので、公務員になった。", "target_word": "志向", "complexity_tier": "T3", "furigana": "姉[あね]は安定[あんてい]した生活[せいかつ]を望[のぞ]む志向[しこう]があるので、公務員[こうむいん]になった。", "sentence_source": "generated"}, {"text": "父は新しい物を好む志向があり、最新のカメラをすぐ買う。", "target_word": "志向", "complexity_tier": "T3", "furigana": "父[ちち]は新[あたら]しい物[もの]を好[この]む志向[しこう]があり、最新[さいしん]のカメラをすぐ買[か]う。", "sentence_source": "generated"}, {"text": "人によって志向が違うので、同じ映画を見ても感想が分かれる。", "target_word": "志向", "complexity_tier": "T3", "furigana": "人[ひと]によって志向[しこう]が違[ちが]うので、同[おな]じ映画[えいが]を見[み]ても感想[かんそう]が分[わ]かれる。", "sentence_source": "generated"}, {"text": "彼女の志向は研究者になることで、毎晩遅くまで図書館にいる。", "target_word": "志向", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の志向[しこう]は研究者[けんきゅうしゃ]になることで、毎晩[まいばん]遅[おそ]くまで図書館[としょかん]にいる。", "sentence_source": "generated"}, {"text": "学生の志向が変わり、小さな会社を選ぶ人が増えた。", "target_word": "志向", "complexity_tier": "T3", "furigana": "学生[がくせい]の志向[しこう]が変[か]わり、小[ちい]さな会社[かいしゃ]を選[えら]ぶ人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "店長は客の志向を調べてから、売り場を作り直した。", "target_word": "志向", "complexity_tier": "T3", "furigana": "店長[てんちょう]は客[きゃく]の志向[しこう]を調[しら]べてから、売[う]り場[ば]を作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "彼は上を目指す志向が強いのに、努力はあまりしない。", "target_word": "志向", "complexity_tier": "T3", "furigana": "彼[かれ]は上[うえ]を目指[めざ]す志向[しこう]が強[つよ]いのに、努力[どりょく]はあまりしない。", "sentence_source": "generated"}, {"text": "進路を決める前に、自分の志向をはっきりさせたほうがいい。", "target_word": "志向", "complexity_tier": "T3", "furigana": "進路[しんろ]を決[き]める前[まえ]に、自分[じぶん]の志向[しこう]をはっきりさせたほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "志向", "label": "基本形"}, {"form": "志向する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "個人が目指す、したいと思う方向や願い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志向", "is_correct": true, "explanation": "働きたいという、目指す方向への気持ちの強さを表す。主語の心情として自然に続く。"}, {"text": "経歴", "is_correct": false, "explanation": "これまでの職歴や学歴を指す語。「働きたいという経歴が強く」では意味がつながらない。"}, {"text": "予算", "is_correct": false, "explanation": "使える金額を指す語。「働きたいという予算が強く」は成り立たない。"}, {"text": "義務", "is_correct": false, "explanation": "しなければならない務めを指す語。働きたいという自発的な気持ちの強さには合わない。"}], "explanations": {"志向": "働きたいという、目指す方向への気持ちの強さを表す。主語の心情として自然に続く。", "経歴": "これまでの職歴や学歴を指す語。「働きたいという経歴が強く」では意味がつながらない。", "予算": "使える金額を指す語。「働きたいという予算が強く」は成り立たない。", "義務": "しなければならない務めを指す語。働きたいという自発的な気持ちの強さには合わない。"}, "sentence_index": 0, "correct_answer": "志向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアンテナは後ろの電波を拾う志向が強い。", "explanation": "ここは〈指向〉（電波や音が特定の方向へ向くこと）の意味。人の目指す方向ではないので、この文脈には合わない。"}, {"text": "このマイクは正面の音を拾う志向が強い。", "explanation": "ここは〈指向〉（音が特定の方向へ向くこと）の意味。人の願いや目標ではないので合わない。"}, {"text": "最近は野菜の値段が上がる志向にある。", "explanation": "ここは〈傾向〉（物事の流れ）の意味。志向は人が目指す方向なので、物価のような動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志向", "is_correct": true, "explanation": "学生が目指す方向が変わったという意味になり、文脈に合う。"}, {"text": "給料", "is_correct": false, "explanation": "働いて得る金額を指す語。目指す方向の変化を表す文には合わない。"}, {"text": "制服", "is_correct": false, "explanation": "着る服の種類を指す語。学生の考えの変化という文脈では意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本を指す語。学生の考えが変わるという文には合わない。"}], "explanations": {"志向": "学生が目指す方向が変わったという意味になり、文脈に合う。", "給料": "働いて得る金額を指す語。目指す方向の変化を表す文には合わない。", "制服": "着る服の種類を指す語。学生の考えの変化という文脈では意味が通らない。", "教科書": "授業で使う本を指す語。学生の考えが変わるという文には合わない。"}, "sentence_index": 6, "correct_answer": "志向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は穏やかな志向で、人と争うことがほとんどない。", "explanation": "ここは〈気質〉（生まれつきの性格）の意味。志向は目指す方向なので、性格の特徴を言うには合わない。"}, {"text": "彼は几帳面な志向で、書類の整理を欠かさない。", "explanation": "ここは〈性格〉（人柄）の意味。志向は心が向かう先を表すので、人柄の説明には合わない。"}, {"text": "この受信機は上空の電波を拾う志向をもつ。", "explanation": "ここは〈指向〉（電波が特定の方向へ向くこと）の意味。人の願いや目標ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は人前で話す仕事を選ぶ志向に強い。", "corrected_sentence": "彼は人前で話す仕事を選ぶ志向が強い。", "error_description": "助詞の誤り。「志向」は「強い」の主語なので「が」を使う。「に強い」は「〜に強い（得意だ）」の形で、志向の強さは表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は地域を支える仕事に就く志向を食べている。", "corrected_sentence": "彼女は地域を支える仕事に就く志向を持っている。", "error_description": "語の組み合わせの誤り。「志向」は「持つ」「抱く」と結びつく。「食べる」とは結びつかないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「広まる」の主語は「志向」なので、「が」で受ける。"}, {"text": "を", "is_correct": false, "explanation": "「広まる」は自動詞なので、目的語の「を」は取らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は広まる先を示すが、志向を主語にする文では不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」は、広まる主体を示す場面には合わない。"}], "correct_answer": "が", "explanations": {"が": "「広まる」の主語は「志向」なので、「が」で受ける。", "を": "「広まる」は自動詞なので、目的語の「を」は取らない。", "に": "「に」は広まる先を示すが、志向を主語にする文では不自然。", "と": "並列や相手を示す「と」は、広まる主体を示す場面には合わない。"}, "error_tags": {"を": "対象", "に": "場所・相手", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「目立つ」の主語は「志向」なので、「が」で受ける。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、目立つ主体を示す場面では使えない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、目立つ主体を示す場面には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、目立つ主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「目立つ」の主語は「志向」なので、「が」で受ける。", "へ": "方向を表す「へ」は、目立つ主体を示す場面では使えない。", "から": "起点を表す「から」は、目立つ主体を示す場面には合わない。", "より": "比較を表す「より」は、目立つ主語の位置には入らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目標や状態を目指して、心が向かうこと。考えや行動の方向性。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "この会社の経営は、環境を大切にする志向で一貫している。", "target_word": "志向", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の経営[けいえい]は、環境[かんきょう]を大切[たいせつ]にする志向[しこう]で一貫[いっかん]している。", "sentence_source": "generated"}, {"text": "若者の間で、健康を重視する志向が広まっている。", "target_word": "志向", "complexity_tier": "T3", "furigana": "若者[わかもの]の間[あいだ]で、健康[けんこう]を重視[じゅうし]する志向[しこう]が広[ひろ]まっている。", "sentence_source": "generated"}, {"text": "彼の発言には、結果より過程を重んじる志向が表れている。", "target_word": "志向", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]には、結果[けっか]より過程[かてい]を重[おも]んじる志向[しこう]が表[あらわ]れている。", "sentence_source": "generated"}, {"text": "世界の人々の志向が多様になり、商品の種類も増えた。", "target_word": "志向", "complexity_tier": "T3", "furigana": "世界[せかい]の人々[ひとびと]の志向[しこう]が多様[たよう]になり、商品[しょうひん]の種類[しゅるい]も増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼女は目標に向かって進む志向が強く、困難があってもあきらめない。", "target_word": "志向", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は目標[もくひょう]に向[む]かって進[すす]む志向[しこう]が強[つよ]く、困難[こんなん]があってもあきらめない。", "sentence_source": "generated"}, {"text": "国の政策には、輸出を増やす志向がはっきり見える。", "target_word": "志向", "complexity_tier": "T3", "furigana": "国[くに]の政策[せいさく]には、輸出[ゆしゅつ]を増[ふ]やす志向[しこう]がはっきり見[み]える。", "sentence_source": "generated"}, {"text": "二人は志向が似ているので、話し合いがいつも早く終わる。", "target_word": "志向", "complexity_tier": "T3", "furigana": "二人[ふたり]は志向[しこう]が似[に]ているので、話[はな]し合[あ]いがいつも早[はや]く終[お]わる。", "sentence_source": "generated"}, {"text": "都市部では、広さより便利さを求める志向が目立つ。", "target_word": "志向", "complexity_tier": "T3", "furigana": "都市部[としぶ]では、広[ひろ]さより便利[べんり]さを求[もと]める志向[しこう]が目立[めだ]つ。", "sentence_source": "generated"}, {"text": "作家の志向が変わったことは、新しい作品を読めばわかる。", "target_word": "志向", "complexity_tier": "T3", "furigana": "作家[さっか]の志向[しこう]が変[か]わったことは、新[あたら]しい作品[さくひん]を読[よ]めばわかる。", "sentence_source": "generated"}, {"text": "社長の志向を理解しないまま、計画を進めるのは危険だ。", "target_word": "志向", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の志向[しこう]を理解[りかい]しないまま、計画[けいかく]を進[すす]めるのは危険[きけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "志向", "label": "基本形"}, {"form": "志向する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "人や組織の考え・行動が向かう方向性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志向", "is_correct": true, "explanation": "環境を大切にする方向への一貫した姿勢を表し、経営方針の文脈に合う。"}, {"text": "予算", "is_correct": false, "explanation": "使える金額を指す語。「環境を大切にする予算で一貫している」は意味が通らない。"}, {"text": "人数", "is_correct": false, "explanation": "人の数を指す語。方針が一貫しているという文には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年の数を指す語。経営の方針を表す文脈には合わない。"}], "explanations": {"志向": "環境を大切にする方向への一貫した姿勢を表し、経営方針の文脈に合う。", "予算": "使える金額を指す語。「環境を大切にする予算で一貫している」は意味が通らない。", "人数": "人の数を指す語。方針が一貫しているという文には合わない。", "年齢": "年の数を指す語。経営の方針を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "志向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このマイクは後ろの音を拾う志向が強い。", "explanation": "ここは〈指向〉（音や電波が特定の方向へ向くこと）の意味。志向は人の目指す方向を表すので、マイクの向きには合わない。"}, {"text": "彼は穏やかな志向で、人と争うことがほとんどない。", "explanation": "ここは〈気質〉（生まれつきの性質）の意味。方向性ではなく性格を表すので、この文脈では合わない。"}, {"text": "景気は上向く志向にある。", "explanation": "ここは〈傾向〉（物事の流れ）の意味。志向は人が目指す方向なので、景気の動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志向", "is_correct": true, "explanation": "二人の考えの向かう方向が似ているという意味になり、話し合いが早く終わる理由として合う。"}, {"text": "病院", "is_correct": false, "explanation": "医療機関を指す語。「病院が似ている」は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章を指す語。二人の考えが似ているという文には合わない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指す語。似ているという述語とは結びつかない。"}], "explanations": {"志向": "二人の考えの向かう方向が似ているという意味になり、話し合いが早く終わる理由として合う。", "病院": "医療機関を指す語。「病院が似ている」は意味が通らない。", "手紙": "書いた文章を指す語。二人の考えが似ているという文には合わない。", "会議": "話し合いの場を指す語。似ているという述語とは結びつかない。"}, "sentence_index": 6, "correct_answer": "志向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は落ち着いた志向で、人前でも動じない。", "explanation": "ここは〈気質〉（生まれつきの気の質）の意味。志向は目指す方向なので、気の質を言うには合わない。"}, {"text": "彼は几帳面な志向で、書類の整理を欠かさない。", "explanation": "ここは〈性格〉（人柄）の意味。志向は心が向かう先を表すので、人柄の説明には合わない。"}, {"text": "その知らせに、うれしい志向がわき上がった。", "explanation": "ここは〈感情〉（わき上がる気持ち）の意味。志向は目指す方向なので、一瞬わく感情には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若い世代の志向を変わったことは、アンケートで明らかになった。", "corrected_sentence": "若い世代の志向が変わったことは、アンケートで明らかになった。", "error_description": "助詞の誤り。「変わる」は自動詞で、主語に「が」を取る。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若者の間で、環境を守る志向が広めている。", "corrected_sentence": "若者の間で、環境を守る志向が広まっている。", "error_description": "自他の誤り。「広まる」は自動詞で主語に「が」を取る。「広める」は他動詞で目的語に「を」を取るので、「志向が広めている」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「バッグの中」と名詞をつなぎ、中身のある場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「バッグが中に財布」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「バッグで中に」では場所の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「バッグへ中に」とは続けられない。"}], "correct_answer": "の", "explanations": {"の": "「バッグの中」と名詞をつなぎ、中身のある場所を示す。", "が": "「が」は主語を示すが、「バッグが中に財布」では意味が通らない。", "で": "「で」は手段や場所を示すが、「バッグで中に」では場所の関係が成り立たない。", "へ": "「へ」は方向を示すが、「バッグへ中に」とは続けられない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「忘れた」の対象は持ち物の「バッグ」なので、「を」で目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、「バッグと忘れた」では対象を正しく示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「バッグから忘れた」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「バッグより忘れた」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「忘れた」の対象は持ち物の「バッグ」なので、「を」で目的語を示す。", "と": "「と」は並列を示すが、「バッグと忘れた」では対象を正しく示せない。", "から": "「から」は起点を示すが、「バッグから忘れた」は意味が通らない。", "より": "「より」は比較を示すが、「バッグより忘れた」は成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをいれるための、ふくろのことです。", "primary_collocate": null, "pronunciation": "ばっぐ", "ipa": "baɡːɯ", "syllable_count": 3, "sentences": [{"text": "机の上にバッグを置いて、手を洗いました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]にバッグを置[お]いて、手[て]を洗[あら]いました。", "sentence_source": "generated"}, {"text": "バッグの中に財布とかぎが入っています。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "バッグの中[なか]に財布[さいふ]とかぎが入[はい]っています。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、折りたたみ傘をバッグに入れました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、折[お]りたたみ傘[がさ]をバッグに入れました。", "sentence_source": "generated"}, {"text": "このバッグは軽いので、旅行に便利です。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "このバッグは軽[かる]いので、旅行[りょこう]に便利[べんり]です。", "sentence_source": "generated"}, {"text": "母は黒いバッグを肩にかけて出かけました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "母[はは]は黒[くろ]いバッグを肩[かた]にかけて出[で]かけました。", "sentence_source": "generated"}, {"text": "バッグのチャックがこわれて、中身が落ちました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "バッグのチャックがこわれて、中身[なかみ]が落[お]ちました。", "sentence_source": "generated"}, {"text": "バッグが重すぎて、肩がいたくなりました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "バッグが重[おも]すぎて、肩[かた]がいたくなりました。", "sentence_source": "generated"}, {"text": "電車にバッグを忘れたので、駅員に聞きました。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "電車[でんしゃ]にバッグを忘[わす]れたので、駅員[えきいん]に聞[き]きました。", "sentence_source": "generated"}, {"text": "新しいバッグを買ったから、古いのは姉にあげた。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "新[あたら]しいバッグを買[か]ったから、古[ふる]いのは姉[あね]にあげた。", "sentence_source": "generated"}, {"text": "学校へ行く前に、バッグにノートを入れた。", "target_word": "バッグ", "complexity_tier": "T3", "furigana": "学校[がっこう]へ行[い]く前[まえ]に、バッグにノートを入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バッグ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を入れて持つ袋・かばん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バッグ", "is_correct": true, "explanation": "「机の上に〇〇を置いて」に入るのは、持ち歩く袋のバッグだけ。"}, {"text": "ひざ", "is_correct": false, "explanation": "ひざは体の部分で、机の上に置いて手を洗う物ではないので合わない。"}, {"text": "うで", "is_correct": false, "explanation": "うでは体の一部で、机の上に置く物ではないので合わない。"}, {"text": "山", "is_correct": false, "explanation": "山は地形で、机の上には置けないので合わない。"}], "explanations": {"バッグ": "「机の上に〇〇を置いて」に入るのは、持ち歩く袋のバッグだけ。", "ひざ": "ひざは体の部分で、机の上に置いて手を洗う物ではないので合わない。", "うで": "うでは体の一部で、机の上に置く物ではないので合わない。", "山": "山は地形で、机の上には置けないので合わない。"}, "sentence_index": 0, "correct_answer": "バッグ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒くなったので、バッグを首に巻いて外に出た。", "explanation": "ここは〈マフラー〉の意味。バッグは首に巻くものではないので合わない。"}, {"text": "手紙をバッグに入れて、切手を貼ってポストに出した。", "explanation": "ここは〈封筒〉の意味。切手は封筒に貼るもので、バッグには貼らないので合わない。"}, {"text": "ごはんを、バッグで炊いた。", "explanation": "ここは〈炊飯器〉の意味。米を炊くのは炊飯器で、バッグは炊く道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バッグ", "is_correct": true, "explanation": "「〇〇が重すぎて肩が痛くなった」に入るのは、重さのある持ち物のバッグだけ。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチは軽く、重すぎて肩が痛くなる物ではないので合わない。"}, {"text": "はがき", "is_correct": false, "explanation": "はがきは非常に軽く、重すぎて肩が痛くなる物ではないので合わない。"}, {"text": "ペン", "is_correct": false, "explanation": "ペンは軽い筆記具で、肩が痛くなるほど重くはならないので合わない。"}], "explanations": {"バッグ": "「〇〇が重すぎて肩が痛くなった」に入るのは、重さのある持ち物のバッグだけ。", "ハンカチ": "ハンカチは軽く、重すぎて肩が痛くなる物ではないので合わない。", "はがき": "はがきは非常に軽く、重すぎて肩が痛くなる物ではないので合わない。", "ペン": "ペンは軽い筆記具で、肩が痛くなるほど重くはならないので合わない。"}, "sentence_index": 6, "correct_answer": "バッグ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ってきたので、バッグを広げて差した。", "explanation": "ここは〈傘〉の意味。傘は広げて差すものなので、バッグには合わない。"}, {"text": "風邪をひいて、バッグで鼻をかんだ。", "explanation": "ここは〈ティッシュ〉の意味。鼻をかむのに使うのはティッシュで、バッグは鼻をかむ物ではないので合わない。"}, {"text": "宿題を、バッグで書いた。", "explanation": "ここは〈ペン〉の意味。字を書く道具にバッグは使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノートをバッグで入れて学校へ行った。", "corrected_sentence": "ノートをバッグに入れて学校へ行った。", "error_description": "「バッグ」に続く助詞の誤り。「入れる」の入れ先を示すには「に」が正しく、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38550, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、電車にバッグを忘れるたので、駅員にすぐ聞いた。", "corrected_sentence": "昨日、電車にバッグを忘れたので、駅員にすぐ聞いた。", "error_description": "「忘れる」の活用の誤り。過去の「た」に続けるには「忘れた」が正しく、「忘れるた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
