INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38558, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "すごいとおもうこと。", "primary_collocate": null, "pronunciation": "えらい", "ipa": "eɾai", "syllable_count": 3, "sentences": [{"text": "毎朝六時に起きて勉強するなんて、君は偉い。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]六時[ろくじ]に起[お]きて勉強[べんきょう]するなんて、君[きみ]は偉[えら]い。", "sentence_source": "generated"}, {"text": "まだ五歳なのに、一人でお使いに行けて偉い。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "まだ五歳[ごさい]なのに、一人[ひとり]でお使[つか]いに行[い]けて偉[えら]い。", "sentence_source": "generated"}, {"text": "熱があっても仕事を休まなかった彼は偉いと思う。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "熱[ねつ]があっても仕事[しごと]を休[やす]まなかった彼[かれ]は偉[えら]いと思[おも]う。", "sentence_source": "generated"}, {"text": "宿題を自分から始めたので、母は「偉いね」とほめた。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を自分[じぶん]から始[はじ]めたので、母[はは]は「偉[えら]いね」とほめた。", "sentence_source": "generated"}, {"text": "苦しい時に人に優しくできる彼女は偉い。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "苦[くる]しい時[とき]に人[ひと]に優[やさ]しくできる彼女[かのじょ]は偉[えら]い。", "sentence_source": "generated"}, {"text": "弟は小遣いを全部使わず貯金していて、偉い。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "弟[おとうと]は小遣[こづか]いを全部[ぜんぶ]使[つか]わず貯金[ちょきん]していて、偉[えら]い。", "sentence_source": "generated"}, {"text": "誰も見ていないのにゴミを拾うなんて、偉いなあと思った。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "誰[だれ]も見[み]ていないのにゴミを拾[ひろ]うなんて、偉[えら]いなあと思[おも]った。", "sentence_source": "generated"}, {"text": "重い荷物を最後まで一人で運んだ子は偉かった。", "target_word": "偉かった", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を最後[さいご]まで一人[ひとり]で運[はこ]んだ子[こ]は偉[えら]かった。", "sentence_source": "generated"}, {"text": "毎日日記を十年も続けているとは、本当に偉い。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "毎日[まいにち]日記[にっき]を十年[じゅうねん]も続[つづ]けているとは、本当[ほんとう]に偉[えら]い。", "sentence_source": "generated"}, {"text": "失敗しても文句を言わずに謝れたのは偉かった。", "target_word": "偉かった", "complexity_tier": "T3", "furigana": "失敗[しっぱい]しても文句[もんく]を言[い]わずに謝[あやま]れたのは偉[えら]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偉い", "label": "終止形"}, {"form": "偉く", "label": "連用形"}, {"form": "偉かった", "label": "過去形"}, {"form": "偉くない", "label": "否定形"}, {"form": "偉ければ", "label": "仮定形"}], "register": "colloquial", "sense_fingerprint": "努力や行いに感心してほめる、立派だと思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38558, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偉い", "is_correct": true, "explanation": "早朝から勉強する努力への感心を表し、「なんて、君は〜」の文に合う。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度や冷淡な態度を表す語。努力を称える文脈には合わない。"}, {"text": "細い", "is_correct": false, "explanation": "太さや幅が小さいことを表す語。人の行いへの評価には使えない。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさや陰気な様子を表す語。努力への感心を述べる文には合わない。"}], "explanations": {"偉い": "早朝から勉強する努力への感心を表し、「なんて、君は〜」の文に合う。", "冷たい": "温度や冷淡な態度を表す語。努力を称える文脈には合わない。", "細い": "太さや幅が小さいことを表す語。人の行いへの評価には使えない。", "暗い": "明るさや陰気な様子を表す語。努力への感心を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "偉い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は町で偉い先生に教わり、ピアノが上達した。", "explanation": "ここは〈地位・すぐれた立場〉（他より上であること）の意味。努力や行いへの感心ではないので、この文脈では合わない。"}, {"text": "父は会社で偉い立場になり、式で挨拶した。", "explanation": "ここは〈地位〉（社会的な立場が高いこと）の意味。行いへの感心ではないので、この文脈では合わない。"}, {"text": "店員は偉い言葉で客に謝った。", "explanation": "ここは〈丁寧〉（言葉づかいが礼儀正しいこと）の意味。偉いは行いの立派さを表すので、言葉づかいの説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38558, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偉い", "is_correct": true, "explanation": "誰も見ていないのにゴミを拾う行いへの感心を表し、「偉いなあ」の文に合う。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語。ゴミを拾う行いへの感心には合わない。"}, {"text": "固い", "is_correct": false, "explanation": "硬さや堅さを表す語。行いへの評価としては使えない。"}, {"text": "甘い", "is_correct": false, "explanation": "味や甘やかしを表す語。ゴミを拾う行いを評価する文には合わない。"}], "explanations": {"偉い": "誰も見ていないのにゴミを拾う行いへの感心を表し、「偉いなあ」の文に合う。", "重い": "重さを表す語。ゴミを拾う行いへの感心には合わない。", "固い": "硬さや堅さを表す語。行いへの評価としては使えない。", "甘い": "味や甘やかしを表す語。ゴミを拾う行いを評価する文には合わない。"}, "sentence_index": 6, "correct_answer": "偉い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町で偉い人と言われる父の子として、彼は育った。", "explanation": "ここは〈地位〉（社会的な立場が高いこと）の意味。行いへの感心ではないので、人柄の評価には合わない。"}, {"text": "偉い庭で、子どもたちがボールを追いかけた。", "explanation": "ここは〈広い〉（面積が大きいこと）の意味。偉いは人の行いや地位を表すので、庭の広さには使えない。"}, {"text": "子どもは偉い声で挨拶した。", "explanation": "ここは〈元気〉（活気がある様子）の意味。偉いは行いへの感心を表し、声の調子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38558, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日五時に起きて練習するなんて、君は偉く。", "corrected_sentence": "毎日五時に起きて練習するなんて、君は偉い。", "error_description": "活用形の誤り。「偉い」は終止形で文を言い切る。「偉く」は連用形なので、文末には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "偉い", "is_correct": true, "explanation": "終止形で文を言い切る形。「行けて偉い。」の文末に合う。"}, {"text": "偉く", "is_correct": false, "explanation": "連用形なので後ろに続く語が必要で、文末では言い切れない。"}, {"text": "偉くて", "is_correct": false, "explanation": "て形なので文末で言い切れず、「行けて偉くて。」は成り立たない。"}, {"text": "偉ければ", "is_correct": false, "explanation": "仮定形なので文を言い切れず、「行けて偉ければ。」は成り立たない。"}], "correct_form": "偉い", "base_form": "偉い", "form_label": "終止形", "sentence_index": 1, "explanations": {"偉い": "終止形で文を言い切る形。「行けて偉い。」の文末に合う。", "偉く": "連用形なので後ろに続く語が必要で、文末では言い切れない。", "偉くて": "て形なので文末で言い切れず、「行けて偉くて。」は成り立たない。", "偉ければ": "仮定形なので文を言い切れず、「行けて偉ければ。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38558, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "失敗しても挑戦をやめなかった彼は偉いを思う。", "corrected_sentence": "失敗しても挑戦をやめなかった彼は偉いと思う。", "error_description": "助詞の誤り。「偉い」の後には「と思う」（引用）が続く。「を思う」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "偉かった", "is_correct": true, "explanation": "過去形で、「重い荷物を最後まで運んだ」という過去の行いへの感心に合う。"}, {"text": "偉いだった", "is_correct": false, "explanation": "形容詞「偉い」に「だった」は続かず、「偉いだった」は誤った形。"}, {"text": "偉さ", "is_correct": false, "explanation": "名詞形なので、文末の述語としては成り立たない。"}, {"text": "偉かっ", "is_correct": false, "explanation": "「かっ」で切れた形は存在せず、文を言い切れない。"}], "correct_form": "偉かった", "base_form": "偉い", "form_label": "過去形", "sentence_index": 7, "explanations": {"偉かった": "過去形で、「重い荷物を最後まで運んだ」という過去の行いへの感心に合う。", "偉いだった": "形容詞「偉い」に「だった」は続かず、「偉いだった」は誤った形。", "偉さ": "名詞形なので、文末の述語としては成り立たない。", "偉かっ": "「かっ」で切れた形は存在せず、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
