INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38559, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "他人よりもすぐれている、または、立派であること。", "primary_collocate": null, "pronunciation": "えらい", "ipa": "eɾai", "syllable_count": 3, "sentences": [{"text": "彼は国で一番偉い学者として知られている。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "彼[かれ]は国[くに]で一番[いちばん]偉[えら]い学者[がくしゃ]として知[し]られている。", "sentence_source": "generated"}, {"text": "会社で偉い人ほど、実は謙虚に話を聞く。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "会社[かいしゃ]で偉[えら]い人[ひと]ほど、実[じつ]は謙虚[けんきょ]に話[はなし]を聞[き]く。", "sentence_source": "generated"}, {"text": "偉い人になるより、人を助けられる人になりたい。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "偉[えら]い人[ひと]になるより、人[ひと]を助[たす]けられる人[ひと]になりたい。", "sentence_source": "generated"}, {"text": "祖父は村の偉い人で、祭りの時はいつも一番前に座った。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "祖父[そふ]は村[むら]の偉[えら]い人[ひと]で、祭[まつ]りの時[とき]はいつも一番前[いちばんまえ]に座[すわ]った。", "sentence_source": "generated"}, {"text": "偉くなっても、昔の友達を忘れてはいけない。", "target_word": "偉く", "complexity_tier": "T3", "furigana": "偉[えら]くなっても、昔[むかし]の友達[ともだち]を忘[わす]れてはいけない。", "sentence_source": "generated"}, {"text": "偉い先生の講演を聞くために、大勢の人が集まった。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "偉[えら]い先生[せんせい]の講演[こうえん]を聞[き]くために、大勢[おおぜい]の人[ひと]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "あの人は社長だから偉いが、威張ってはいない。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "あの人[ひと]は社長[しゃちょう]だから偉[えら]いが、威張[いば]ってはいない。", "sentence_source": "generated"}, {"text": "子どもに「偉い人とは誰か」と聞かれ、答えに困った。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "子[こ]どもに「偉[えら]い人[ひと]とは誰[だれ]か」と聞[き]かれ、答[こた]えに困[こま]った。", "sentence_source": "generated"}, {"text": "偉い政治家でも、法律を守らなければ罰を受ける。", "target_word": "偉い", "complexity_tier": "T3", "furigana": "偉[えら]い政治家[せいじか]でも、法律[ほうりつ]を守[まも]らなければ罰[ばつ]を受[う]ける。", "sentence_source": "generated"}, {"text": "彼は画家として偉くなり、故郷に美術館を建てた。", "target_word": "偉く", "complexity_tier": "T3", "furigana": "彼[かれ]は画家[がか]として偉[えら]くなり、故郷[こきょう]に美術館[びじゅつかん]を建[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偉い", "label": "終止形"}, {"form": "偉く", "label": "連用形"}, {"form": "偉かった", "label": "過去形"}, {"form": "偉くない", "label": "否定形"}, {"form": "偉ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "地位や能力が他人より高く、立派な人物であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38559, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偉い", "is_correct": true, "explanation": "地位や能力が他より高く、社会的に立派な学者であることを表す。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す語。学者の地位を述べる文には合わない。"}, {"text": "寒い", "is_correct": false, "explanation": "気温を表す語。学者の地位や能力には使えない。"}, {"text": "暗い", "is_correct": false, "explanation": "陰気な様子を表す語。学者の社会的な地位を述べる文には合わない。"}], "explanations": {"偉い": "地位や能力が他より高く、社会的に立派な学者であることを表す。", "眠い": "眠気を表す語。学者の地位を述べる文には合わない。", "寒い": "気温を表す語。学者の地位や能力には使えない。", "暗い": "陰気な様子を表す語。学者の社会的な地位を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "偉い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "偉いかばんを背負って登校した。", "explanation": "ここは〈重い〉（重さがあること）の意味。偉いは地位や立場の高さを表すので、かばんの重さには合わない。"}, {"text": "祖父は毎朝五時に畑へ出て、村の人から偉いとほめられた。", "explanation": "ここは〈感心〉（努力や行いをほめる）の意味。人の地位ではなく行いへの評価なので、今回の意味とは違う。"}, {"text": "祖母は偉い言葉で私を励ました。", "explanation": "ここは〈優しい〉（言葉の温かさ）の意味。偉いは立場や努力の高さを表し、言葉の温かさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38559, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偉い", "is_correct": true, "explanation": "社長という地位の高さを表し、「だから偉いが、威張ってはいない」の文に合う。"}, {"text": "細い", "is_correct": false, "explanation": "太さや幅が小さいことを表す語。社長の地位を述べる文には合わない。"}, {"text": "騒がしい", "is_correct": false, "explanation": "音や場の騒がしさを表す語。社長の地位を述べる文には合わない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚さや濃さが少ないことを表す語。社長の地位とは結びつかない。"}], "explanations": {"偉い": "社長という地位の高さを表し、「だから偉いが、威張ってはいない」の文に合う。", "細い": "太さや幅が小さいことを表す語。社長の地位を述べる文には合わない。", "騒がしい": "音や場の騒がしさを表す語。社長の地位を述べる文には合わない。", "薄い": "厚さや濃さが少ないことを表す語。社長の地位とは結びつかない。"}, "sentence_index": 6, "correct_answer": "偉い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "偉い果物を、子どもたちが喜んで食べた。", "explanation": "ここは〈甘い〉（味が甘いこと）の意味。偉いは人の地位や行いを表すので、果物の味には使えない。"}, {"text": "偉い糸で、きれいな布を織った。", "explanation": "ここは〈細い〉（太さが小さいこと）の意味。偉いは人の地位や行いを表すので、糸の細さには合わない。"}, {"text": "偉い床で転んで、膝をすりむいた。", "explanation": "ここは〈硬い〉（かたいこと）の意味。偉いは人の地位や行いを表すので、床のかたさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町で一番偉く人が、今年の祭りを開いた。", "corrected_sentence": "町で一番偉い人が、今年の祭りを開いた。", "error_description": "活用形の誤り。「偉い」は連体形で「人」を修飾する。「偉く」は連用形なので、名詞に直接続けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "偉い", "is_correct": true, "explanation": "連体形で「人」を修飾する形。「会社で偉い人」の形に合う。"}, {"text": "偉く", "is_correct": false, "explanation": "連用形なので、名詞「人」を直接修飾できない。"}, {"text": "偉くて", "is_correct": false, "explanation": "て形なので、名詞「人」を修飾できず「会社で偉くて人ほど」は成り立たない。"}, {"text": "偉ければ", "is_correct": false, "explanation": "仮定形になり「偉いならば人」となって、文の意味が変わってしまう。"}], "correct_form": "偉い", "base_form": "偉い", "form_label": "連体形", "sentence_index": 1, "explanations": {"偉い": "連体形で「人」を修飾する形。「会社で偉い人」の形に合う。", "偉く": "連用形なので、名詞「人」を直接修飾できない。", "偉くて": "て形なので、名詞「人」を修飾できず「会社で偉くて人ほど」は成り立たない。", "偉ければ": "仮定形になり「偉いならば人」となって、文の意味が変わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は村で偉いを言われている人だ。", "corrected_sentence": "彼は村で偉いと言われている人だ。", "error_description": "助詞の誤り。「偉い」の後には「と言われる」（引用）が続く。「を言われる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "偉い", "is_correct": true, "explanation": "連体形で「偉い人」と名詞を修飾する形。「子どもに「偉い人とは誰か」」の文に合う。"}, {"text": "偉さ", "is_correct": false, "explanation": "名詞形なので、名詞「人」を修飾できず「偉さ人」は成り立たない。"}, {"text": "偉いだ", "is_correct": false, "explanation": "断定の「だ」は名詞を修飾できず、「偉いだ人」は成り立たない。"}, {"text": "偉かろう", "is_correct": false, "explanation": "推量形は名詞を直接修飾できず、「偉かろう人」は文として成り立たない。"}], "correct_form": "偉い", "base_form": "偉い", "form_label": "連体形", "sentence_index": 7, "explanations": {"偉い": "連体形で「偉い人」と名詞を修飾する形。「子どもに「偉い人とは誰か」」の文に合う。", "偉さ": "名詞形なので、名詞「人」を修飾できず「偉さ人」は成り立たない。", "偉いだ": "断定の「だ」は名詞を修飾できず、「偉いだ人」は成り立たない。", "偉かろう": "推量形は名詞を直接修飾できず、「偉かろう人」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
