INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38560, 3, 'prompt1_core', '{"pos": "助動詞", "semantic_class": "function", "definition": "ものの、ようすやすがたがどうか、ということをいうことば。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "空が暗くなってきて、今にも雨が降りそうだ。", "target_word": "そう", "complexity_tier": "T3", "furigana": "空[そら]が暗[くら]くなってきて、今[いま]にも雨[あめ]が降[ふ]りそうだ。", "sentence_source": "generated"}, {"text": "このケーキはとてもおいしそうなので、一つ買った。", "target_word": "そう", "complexity_tier": "T3", "furigana": "このケーキはとてもおいしそうなので、一[ひと]つ買[か]った。", "sentence_source": "generated"}, {"text": "彼女は嬉しそうに、合格の知らせを母に伝えた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は嬉[うれ]しそうに、合格[ごうかく]の知[し]らせを母[はは]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "重そうな荷物を持つ老人を見て、手伝うことにした。", "target_word": "そう", "complexity_tier": "T3", "furigana": "重[おも]そうな荷物[にもつ]を持[も]つ老人[ろうじん]を見[み]て、手伝[てつだ]うことにした。", "sentence_source": "generated"}, {"text": "疲れていそうだったから、早く帰らせてあげた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "疲[つか]れていそうだったから、早[はや]く帰[かえ]らせてあげた。", "sentence_source": "generated"}, {"text": "このコップは薄くて、すぐに割れそうで心配だ。", "target_word": "そう", "complexity_tier": "T3", "furigana": "このコップは薄[うす]くて、すぐに割[わ]れそうで心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "彼は難しそうな本を、毎日電車で読んでいる。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼[かれ]は難[むずか]しそうな本[ほん]を、毎日[まいにち]電車[でんしゃ]で読[よ]んでいる。", "sentence_source": "generated"}, {"text": "今日は仕事が早く終わりそうなので、夕食を作れる。", "target_word": "そう", "complexity_tier": "T3", "furigana": "今日[きょう]は仕事[しごと]が早[はや]く終[お]わりそうなので、夕食[ゆうしょく]を作[つく]れる。", "sentence_source": "generated"}, {"text": "子どもが眠そうな顔をしているので、もう寝かせた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "子[こ]どもが眠[ねむ]そうな顔[かお]をしているので、もう寝[ね]かせた。", "sentence_source": "generated"}, {"text": "木の枝が折れそうなほど、雪がたくさん積もっていた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]が折[お]れそうなほど、雪[ゆき]がたくさん積[つ]もっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "そうだ", "label": "終止形"}, {"form": "そうな", "label": "連体形"}, {"form": "そうに", "label": "連用形"}, {"form": "そうで", "label": "接続形"}, {"form": "そうだった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "見た目や様子から判断して「〜という様子だ」と言う様態の「そう」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「降りそうだ」は、今にも降る様子だと見た目から判断する様態の「そう」。"}, {"text": "たい", "is_correct": false, "explanation": "「降りたい」は話し手の願望を表す形で、様子の判断にはならないので入らない。"}, {"text": "ない", "is_correct": false, "explanation": "「降りないだ」は成り立たず、様子の判断も表せない。"}, {"text": "せる", "is_correct": false, "explanation": "使役・許容の助動詞で、「降りせるだ」は文として成り立たない。"}], "explanations": {"そう": "「降りそうだ」は、今にも降る様子だと見た目から判断する様態の「そう」。", "たい": "「降りたい」は話し手の願望を表す形で、様子の判断にはならないので入らない。", "ない": "「降りないだ」は成り立たず、様子の判断も表せない。", "せる": "使役・許容の助動詞で、「降りせるだ」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日の試合で負けたそうだ。", "explanation": "ここは〈伝聞〉の「そうだ」（人から聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、この文では様子を述べていない。"}, {"text": "彼は来週の旅行の話をされて、「そう、それなら行こう」と答えた。", "explanation": "ここは〈肯定〉の「そう」（そのとおり）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子の判断は含まれない。"}, {"text": "その絵は昔の人が描いたそうで、今も大切に飾られている。", "explanation": "ここは〈伝聞〉の「そう」（人から聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、この文では様子の判断ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「難しそうな」は、難しい様子に見えるという判断を表す様態の「そう」。"}, {"text": "さ", "is_correct": false, "explanation": "「難しさ」は名詞化した形で、「難しさな本」とは続かない。"}, {"text": "らしい", "is_correct": false, "explanation": "推定の「らしい」は「難しいらしい」の形になり、「難しらしい」とは続かない。"}, {"text": "みたい", "is_correct": false, "explanation": "「みたい」は語幹「難し」には続かず、「難しみたいな本」は不自然。"}], "explanations": {"そう": "「難しそうな」は、難しい様子に見えるという判断を表す様態の「そう」。", "さ": "「難しさ」は名詞化した形で、「難しさな本」とは続かない。", "らしい": "推定の「らしい」は「難しいらしい」の形になり、「難しらしい」とは続かない。", "みたい": "「みたい」は語幹「難し」には続かず、「難しみたいな本」は不自然。"}, "sentence_index": 6, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話を聞いて、彼は「そうか」と小さくうなずいた。", "explanation": "ここは〈相槌〉の「そうか」（相手の話に納得して返す言葉）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子を述べていない。"}, {"text": "あっ、そうだ、鍵をかけ忘れてしまった。", "explanation": "ここは〈思い出し〉の「そうだ」（思い当たったときに言う言葉）の意味。見た様子から判断する〈様態〉の「そう」とは別で、この文では様子の判断は含まれない。"}, {"text": "彼は試験に合格したそうだ。", "explanation": "ここは〈伝聞〉の「そうだ」（人から聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子を述べていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
