INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38561, 3, 'prompt1_core', '{"pos": "助動詞", "semantic_class": "function", "definition": "物事の状態や様子を表す言葉。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "空が暗くて、今にも雨が降りそうです。", "target_word": "そう", "complexity_tier": "T3", "furigana": "空(そら)が暗(くら)くて、今(いま)にも雨(あめ)が降(ふ)りそうです。", "sentence_source": "generated"}, {"text": "このケーキはとてもおいしそうですね。", "target_word": "そう", "complexity_tier": "T3", "furigana": "このケーキはとてもおいしそうですね。", "sentence_source": "generated"}, {"text": "彼は疲れていて、今にも倒れそうだった。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼(かれ)は疲(つか)れていて、今(いま)にも倒(たお)れそうだった。", "sentence_source": "generated"}, {"text": "子どもたちは楽しそうに遊んでいます。", "target_word": "そう", "complexity_tier": "T3", "furigana": "子(こ)どもたちは楽(たの)しそうに遊(あそ)んでいます。", "sentence_source": "generated"}, {"text": "その箱は重そうなので、二人で運びましょう。", "target_word": "そう", "complexity_tier": "T3", "furigana": "その箱(はこ)は重(おも)そうなので、二人(ふたり)で運(はこ)びましょう。", "sentence_source": "generated"}, {"text": "田中さんは忙しそうで、話しかけられなかった。", "target_word": "そう", "complexity_tier": "T3", "furigana": "田中(たなか)さんは忙(いそが)しそうで、話(はな)しかけられなかった。", "sentence_source": "generated"}, {"text": "弟は眠そうな顔で朝ごはんを食べている。", "target_word": "そう", "complexity_tier": "T3", "furigana": "弟(おとうと)は眠(ねむ)そうな顔(かお)で朝(あさ)ごはんを食(た)べている。", "sentence_source": "generated"}, {"text": "このかばんは丈夫そうだから、旅行に使えます。", "target_word": "そう", "complexity_tier": "T3", "furigana": "このかばんは丈夫(じょうぶ)そうだから、旅行(りょこう)に使(つか)えます。", "sentence_source": "generated"}, {"text": "彼女はうれしそうに手紙を読んでいた。", "target_word": "そう", "complexity_tier": "T3", "furigana": "彼女(かのじょ)はうれしそうに手紙(てがみ)を読(よ)んでいた。", "sentence_source": "generated"}, {"text": "今日の試験は難しそうで、少し心配だ。", "target_word": "そう", "complexity_tier": "T3", "furigana": "今日(きょう)の試験(しけん)は難(むずか)しそうで、少(すこ)し心配(しんぱい)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "そうだ", "label": "終止形"}, {"form": "そうです", "label": "丁寧形"}, {"form": "そうに", "label": "連用形"}, {"form": "そうな", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "様態の「そう」。見た様子から、そうなりそうだ・そう見えると判断する(伝聞の「そうだ」ではない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「降りそうです」は、今にも降る様子だと見た目から判断する様態の「そう」。"}, {"text": "たい", "is_correct": false, "explanation": "「降りたいです」は話し手の願望を表す形で、様子の判断ではないので入らない。"}, {"text": "ない", "is_correct": false, "explanation": "「降りないです」は不自然で、様子の判断にもならない。"}, {"text": "せる", "is_correct": false, "explanation": "使役・許容の助動詞で、「降りせるです」は成り立たない。"}], "explanations": {"そう": "「降りそうです」は、今にも降る様子だと見た目から判断する様態の「そう」。", "たい": "「降りたいです」は話し手の願望を表す形で、様子の判断ではないので入らない。", "ない": "「降りないです」は不自然で、様子の判断にもならない。", "せる": "使役・許容の助動詞で、「降りせるです」は成り立たない。"}, "sentence_index": 0, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田中さんは今日、忙しいそうです。", "explanation": "ここは〈伝聞〉の「そうです」（人から聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、ここでは様子を見ていない。"}, {"text": "先生に「そうですか」と答えて、その箱を渡しました。", "explanation": "ここは〈相槌〉の「そうですか」（相手の言ったことを受ける言葉）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子を述べていない。"}, {"text": "弟はいつも朝ごはんを残すそうです。", "explanation": "ここは〈伝聞〉の「そうです」（聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "そう", "is_correct": true, "explanation": "「眠そうな」は、眠たい様子に見えるという判断を表す様態の「そう」。"}, {"text": "さ", "is_correct": false, "explanation": "「眠さ」は名詞化した形で、「眠さな顔」とは続かない。"}, {"text": "みたい", "is_correct": false, "explanation": "「みたい」は語幹「眠」には続かず、「眠みたいな顔」は不自然。"}, {"text": "らしい", "is_correct": false, "explanation": "推定の「らしい」は「眠いらしい」の形になり、「眠らしい」とは続かない。"}], "explanations": {"そう": "「眠そうな」は、眠たい様子に見えるという判断を表す様態の「そう」。", "さ": "「眠さ」は名詞化した形で、「眠さな顔」とは続かない。", "みたい": "「みたい」は語幹「眠」には続かず、「眠みたいな顔」は不自然。", "らしい": "推定の「らしい」は「眠いらしい」の形になり、「眠らしい」とは続かない。"}, "sentence_index": 6, "correct_answer": "そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の会議は三時からかと聞かれ、彼は「そうです」と答えた。", "explanation": "ここは〈肯定〉の「そうです」（相手の言ったことを認める）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子を述べる文ではない。"}, {"text": "記録によると、先週の注文はすでに届いたそうです。", "explanation": "ここは〈伝聞〉の「そうです」（記録などで聞いた情報）の意味。見た様子から判断する〈様態〉の「そう」とは別で、様子の判断は含まれない。"}, {"text": "そうだ、明日は休みでした。", "explanation": "ここは〈思い出し〉の「そうだ」（思い当たったときに言う言葉）の意味。見た様子から判断する〈様態〉の「そう」とは別で、この文では様子の判断は含まれない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
