INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "眠そうない顔の子が、朝ごはんを食べています。", "corrected_sentence": "眠そうな顔の子が、朝ごはんを食べています。", "error_description": "様態の「そう」に続く連体形は「眠そうな」。「眠そうない」は形容詞の「ない」が誤って付いている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「樟の材」の「の」で、材が樟に属することを示す。"}, {"text": "を", "is_correct": false, "explanation": "「樟を材は」と対象が二重になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「樟に材は」と続かず、所属を示す「の」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「樟で材は」は場所・手段になり、所属を示せない。"}], "correct_answer": "の", "explanations": {"の": "「樟の材」の「の」で、材が樟に属することを示す。", "を": "「樟を材は」と対象が二重になり不自然。", "に": "「樟に材は」と続かず、所属を示す「の」と合わない。", "で": "「樟で材は」は場所・手段になり、所属を示せない。"}, "error_tags": {"を": "二重の対象", "に": "相手・場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "クスノキ。暖かい地方に生える常緑の高木で、材は香りがよく、樟脳の原料になる。", "primary_collocate": null, "pronunciation": "くすのき", "ipa": "kɯsɯnoki", "syllable_count": 4, "sentences": [{"text": "樟は暖かい地方に多く、一年中緑の葉をつけている。", "target_word": "樟", "complexity_tier": "T3", "furigana": "樟(くすのき)は暖(あたた)かい地方(ちほう)に多(おお)く、一年中(いちねんじゅう)緑(みどり)の葉(は)をつけている。", "sentence_source": "generated"}, {"text": "樟の材は香りがよく、たんすや箱に使われる。", "target_word": "樟", "complexity_tier": "T3", "furigana": "樟(くすのき)の材(ざい)は香(かお)りがよく、たんすや箱(はこ)に使(つか)われる。", "sentence_source": "generated"}, {"text": "九州には、樹齢千年を超える樟の大木が各地にある。", "target_word": "樟", "complexity_tier": "T3", "furigana": "九州(きゅうしゅう)には、樹齢(じゅれい)千年(せんねん)を超(こ)える樟(くすのき)の大木(たいぼく)が各地(かくち)にある。", "sentence_source": "generated"}, {"text": "樟は大きく育つので、広い場所に植えるのがよい。", "target_word": "樟", "complexity_tier": "T3", "furigana": "樟(くすのき)は大(おお)きく育(そだ)つので、広(ひろ)い場所(ばしょ)に植(う)えるのがよい。", "sentence_source": "generated"}, {"text": "町の街路樹に樟が選ばれたのは、暑さに強いからだ。", "target_word": "樟", "complexity_tier": "T3", "furigana": "町(まち)の街路樹(がいろじゅ)に樟(くすのき)が選(えら)ばれたのは、暑(あつ)さに強(つよ)いからだ。", "sentence_source": "generated"}, {"text": "樟の香りには虫を遠ざける働きがあるといわれる。", "target_word": "樟", "complexity_tier": "T3", "furigana": "樟(くすのき)の香(かお)りには虫(むし)を遠(とお)ざける働(はたら)きがあるといわれる。", "sentence_source": "generated"}, {"text": "樟の高木が並ぶ参道は、夏でも涼しい。", "target_word": "樟", "complexity_tier": "T3", "furigana": "樟(くすのき)の高木(こうぼく)が並(なら)ぶ参道(さんどう)は、夏(なつ)でも涼(すず)しい。", "sentence_source": "generated"}, {"text": "寒い地方では樟は育ちにくいので、東北ではあまり見かけない。", "target_word": "樟", "complexity_tier": "T3", "furigana": "寒(さむ)い地方(ちほう)では樟(くすのき)は育(そだ)ちにくいので、東北(とうほく)ではあまり見(み)かけない。", "sentence_source": "generated"}, {"text": "この寺の樟は、国の天然記念物に指定されている。", "target_word": "樟", "complexity_tier": "T3", "furigana": "この寺(てら)の樟(くすのき)は、国(くに)の天然記念物(てんねんきねんぶつ)に指定(してい)されている。", "sentence_source": "generated"}, {"text": "古い船は、腐りにくい樟の材で造られた。", "target_word": "樟", "complexity_tier": "T3", "furigana": "古(ふる)い船(ふね)は、腐(くさ)りにくい樟(くすのき)の材(ざい)で造(つく)られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "樟", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "暖地に育つ常緑高木クスノキ、香りのよい材と樟脳の原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "樟", "is_correct": true, "explanation": "暖地に生える常緑の木で、「緑の葉をつけている」と合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は葉をつけないので、「緑の葉をつけている」の主語にならない。"}, {"text": "石", "is_correct": false, "explanation": "石は葉をつけず、「暖かい地方に多く」という描写と合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は葉をつけず、植物の描写と合わない。"}], "explanations": {"樟": "暖地に生える常緑の木で、「緑の葉をつけている」と合う。", "雨": "雨は葉をつけないので、「緑の葉をつけている」の主語にならない。", "石": "石は葉をつけず、「暖かい地方に多く」という描写と合わない。", "紙": "紙は葉をつけず、植物の描写と合わない。"}, "sentence_index": 0, "correct_answer": "樟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "樟の材を、窯で焼いてコップにした。", "explanation": "ここは〈陶器〉の場面（窯で焼いて作る器）。樟は木で、窯で焼いて器にする材ではないので合わない。"}, {"text": "樟を、ホットケーキの粉に混ぜて焼いた。", "explanation": "ここは〈小麦粉〉の場面（焼き菓子の材料）。樟は木で、粉にして菓子に混ぜる材料ではないので合わない。"}, {"text": "樟を、味噌汁の具にして煮た。", "explanation": "ここは〈野菜〉の場面（煮る具材）。樟は木で、煮て食べる具材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "樟", "is_correct": true, "explanation": "木を指す名詞で、「〜の高木が並ぶ参道」と合う。"}, {"text": "柱", "is_correct": false, "explanation": "柱は高木ではなく、「柱の高木」は並ぶ木の描写に合わない。"}, {"text": "岩", "is_correct": false, "explanation": "岩は木ではなく、高木が並ぶ参道と合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は高木にならず、涼しい参道の描写に合わない。"}], "explanations": {"樟": "木を指す名詞で、「〜の高木が並ぶ参道」と合う。", "柱": "柱は高木ではなく、「柱の高木」は並ぶ木の描写に合わない。", "岩": "岩は木ではなく、高木が並ぶ参道と合わない。", "砂": "砂は高木にならず、涼しい参道の描写に合わない。"}, "sentence_index": 6, "correct_answer": "樟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "樟を、食後のデザートとして、ひと口かじった。", "explanation": "ここは〈果物〉の場面（デザートの食材）。樟は木で、かじって食べる果物ではないので合わない。"}, {"text": "樟を、庭の小道にびっしり敷き詰めた。", "explanation": "ここは〈砂利〉の場面（小道に敷く材料）。樟は木で、敷き詰めて道を作る材ではないので合わない。"}, {"text": "樟を、糸のように細く紡いで、布を織った。", "explanation": "ここは〈綿〉の場面（糸にして布を織る材料）。樟は木で、紡いで糸にする材ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の街路樹として、樟を多く植えられている。", "corrected_sentence": "町の街路樹として、樟が多く植えられている。", "error_description": "受身の主語は「が」で示す。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38563, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い地方では、樟に育ちにくいと聞いた。", "corrected_sentence": "寒い地方では、樟が育ちにくいと聞いた。", "error_description": "「育ちにくい」の主語は「が」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「海の底に沈む」の「に」。沈む先を示し、文中の位置と一致する。"}, {"text": "を", "is_correct": false, "explanation": "「沈む」は自動詞なので「を」で対象を取れない。「海の底を沈んで」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表すので、沈む先を示す文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞同士をつなぐだけで、動詞の前に置けない。"}], "correct_answer": "に", "explanations": {"に": "「海の底に沈む」の「に」。沈む先を示し、文中の位置と一致する。", "を": "「沈む」は自動詞なので「を」で対象を取れない。「海の底を沈んで」は不自然。", "と": "相手や引用を表すので、沈む先を示す文脈に合わない。", "の": "連体修飾の「の」は名詞同士をつなぐだけで、動詞の前に置けない。"}, "error_tags": {"を": "対象", "と": "相手・引用", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浮く", "is_correct": true, "explanation": "「沈む」の対義語。水の下へ行かず、水面に留まって上へ動く意味。"}, {"text": "流れる", "is_correct": false, "explanation": "水に運ばれて移動する意味で、沈むの対義語ではない。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "空中を移動する意味で、水中への下降と反対の関係にはない。"}, {"text": "進む", "is_correct": false, "explanation": "前へ動く意味で、沈むの対義語ではない。"}], "correct_answer": "浮く", "explanations": {"浮く": "「沈む」の対義語。水の下へ行かず、水面に留まって上へ動く意味。", "流れる": "水に運ばれて移動する意味で、沈むの対義語ではない。", "飛ぶ": "空中を移動する意味で、水中への下降と反対の関係にはない。", "進む": "前へ動く意味で、沈むの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「糸が沈まない」の「が」。沈む主体を示し、文中の位置と一致する。"}, {"text": "に", "is_correct": false, "explanation": "「糸に沈まない」は沈む先を示す「に」が主語の位置に入るため、主体を示せず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「糸で沈まない」は手段や場所を示す「で」が主語の位置に入るため、主体を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「糸へ沈まない」は方向を示す「へ」が主語の位置に入るため、主体を示せず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「糸が沈まない」の「が」。沈む主体を示し、文中の位置と一致する。", "に": "「糸に沈まない」は沈む先を示す「に」が主語の位置に入るため、主体を示せず文が成り立たない。", "で": "「糸で沈まない」は手段や場所を示す「で」が主語の位置に入るため、主体を示せず文が成り立たない。", "へ": "「糸へ沈まない」は方向を示す「へ」が主語の位置に入るため、主体を示せず文が成り立たない。"}, "error_tags": {"に": "位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浮く", "is_correct": true, "explanation": "「沈む」の対義語。水中へ下がらず、水面に上がって留まる意味。"}, {"text": "残る", "is_correct": false, "explanation": "その場にとどまる意味で、水中への下降と反対の関係にはない。"}, {"text": "届く", "is_correct": false, "explanation": "ある場所まで到達する意味で、沈むの対義語ではない。"}, {"text": "集まる", "is_correct": false, "explanation": "一か所に寄り集まる意味で、沈むの対義語ではない。"}], "correct_answer": "浮く", "explanations": {"浮く": "「沈む」の対義語。水中へ下がらず、水面に上がって留まる意味。", "残る": "その場にとどまる意味で、水中への下降と反対の関係にはない。", "届く": "ある場所まで到達する意味で、沈むの対義語ではない。", "集まる": "一か所に寄り集まる意味で、沈むの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水の下に行く。", "primary_collocate": null, "pronunciation": "しずむ", "ipa": "ɕizɯmɯ", "syllable_count": 3, "sentences": [{"text": "石は水に入れるとすぐに沈む。", "target_word": "沈む", "complexity_tier": "T3", "furigana": "石(いし)は水(みず)に入(い)れるとすぐに沈(しず)む。", "sentence_source": "generated"}, {"text": "古い船が海の底に沈んでしまった。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "古(ふる)い船(ふね)が海(うみ)の底(そこ)に沈(しず)んでしまった。", "sentence_source": "generated"}, {"text": "重い鉄の玉はプールの底に沈みました。", "target_word": "沈み", "complexity_tier": "T3", "furigana": "重(おも)い鉄(てつ)の玉(たま)はプールの底(そこ)に沈(しず)みました。", "sentence_source": "generated"}, {"text": "木の葉は浮くが、小さな石は沈む。", "target_word": "沈む", "complexity_tier": "T3", "furigana": "木(き)の葉(は)は浮(う)くが、小(ちい)さな石(いし)は沈(しず)む。", "sentence_source": "generated"}, {"text": "氷は水に浮くが、鉄は水に沈みます。", "target_word": "沈み", "complexity_tier": "T3", "furigana": "氷(こおり)は水(みず)に浮(う)くが、鉄(てつ)は水(みず)に沈(しず)みます。", "sentence_source": "generated"}, {"text": "湖に落とした鍵は、ゆっくり沈んでいった。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "湖(みずうみ)に落(お)とした鍵(かぎ)は、ゆっくり沈(しず)んでいった。", "sentence_source": "generated"}, {"text": "大きな波で小さなボートが沈んだ。", "target_word": "沈んだ", "complexity_tier": "T3", "furigana": "大(おお)きな波(なみ)で小(ちい)さなボートが沈(しず)んだ。", "sentence_source": "generated"}, {"text": "糸が沈まないように、小さな浮きをつけます。", "target_word": "沈ま", "complexity_tier": "T3", "furigana": "糸(いと)が沈(しず)まないように、小(ちい)さな浮(う)きをつけます。", "sentence_source": "generated"}, {"text": "海に投げたコインは、光りながら沈んだ。", "target_word": "沈んだ", "complexity_tier": "T3", "furigana": "海(うみ)に投(な)げたコインは、光(ひか)りながら沈(しず)んだ。", "sentence_source": "generated"}, {"text": "コップの中のスプーンが沈んで、見えなくなった。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "コップの中(なか)のスプーンが沈(しず)んで、見(み)えなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "沈む", "label": "辞書形"}, {"form": "沈みます", "label": "丁寧形"}, {"form": "沈んで", "label": "て形"}, {"form": "沈んだ", "label": "た形"}, {"form": "沈まない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "物が水の中に入り、水の底や下へ行く(船・石・コインなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沈む", "is_correct": true, "explanation": "文中の形そのもの。水に入れると下へ行く意味で、「すぐに」に続く辞書形として自然。"}, {"text": "沈めて", "is_correct": false, "explanation": "他動詞「沈める」のて形。目的語の「を」がなく、文を終えられない。"}, {"text": "沈んで", "is_correct": false, "explanation": "て形のままでは文が終わらず、「すぐに沈んで。」とは言えない。"}, {"text": "沈もう", "is_correct": false, "explanation": "意向形になり、石の性質を述べる文の述語として合わない。"}], "explanations": {"沈む": "文中の形そのもの。水に入れると下へ行く意味で、「すぐに」に続く辞書形として自然。", "沈めて": "他動詞「沈める」のて形。目的語の「を」がなく、文を終えられない。", "沈んで": "て形のままでは文が終わらず、「すぐに沈んで。」とは言えない。", "沈もう": "意向形になり、石の性質を述べる文の述語として合わない。"}, "sentence_index": 0, "correct_answer": "沈む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪が屋根に沈んで、重くなった。", "explanation": "ここは〈水の下に行く〉の意味。雪が屋根に積もる話は〈積もる〉で表し、〈沈む〉は水の中で下へ行く動きに限られる。"}, {"text": "その知らせを聞いて、彼の気持ちが沈んだ。", "explanation": "ここは〈気分が落ち込む〉の意味。気持ちの落ち込みは〈落ち込む〉で表し、〈沈む〉は水の下へ行く動きに限られる。"}, {"text": "エレベーターが地下の駐車場まで沈んだ。", "explanation": "ここは〈水の下に行く〉の意味。機械が下へ移動する話は〈下りる〉で表し、〈沈む〉は物が水や液体の中で下へ行く動きに限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沈んだ", "is_correct": true, "explanation": "文中の形そのもの。過去の出来事として文を終えられる。"}, {"text": "沈ませる", "is_correct": false, "explanation": "使役の辞書形。目的語がなく、「ボートが沈ませる。」は成り立たない。"}, {"text": "沈め", "is_correct": false, "explanation": "命令形になり、「沈め。」は文の述べ方として合わない。"}, {"text": "沈みなさい", "is_correct": false, "explanation": "丁寧な命令形で、出来事を述べる文には合わない。"}], "explanations": {"沈んだ": "文中の形そのもの。過去の出来事として文を終えられる。", "沈ませる": "使役の辞書形。目的語がなく、「ボートが沈ませる。」は成り立たない。", "沈め": "命令形になり、「沈め。」は文の述べ方として合わない。", "沈みなさい": "丁寧な命令形で、出来事を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "沈んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の水がゆっくり沈んで、流れていった。", "explanation": "ここは〈水の下に行く〉の意味。水が横へ流れていく話は〈流れる〉で表し、〈沈む〉は物が水中を下へ行く動きに限られる。"}, {"text": "鍵が机から床に沈んだ。", "explanation": "ここは〈水の下に行く〉の意味。机から床へ落ちる動きは〈落ちる〉で表し、〈沈む〉は水中での下降に限られる。"}, {"text": "値段がぐっと沈んで、買いやすくなった。", "explanation": "ここは〈水の下に行く〉の意味。値段が下がる話は〈下がる〉で表し、〈沈む〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな石が水の底を沈みます。", "corrected_sentence": "小さな石が水の底に沈みます。", "error_description": "「沈む」は行き先を表す「に」を取る。「を」は誤りで、正しくは「水の底に沈みます」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "沈んで", "is_correct": true, "explanation": "「〜てしまった」に続くて形。文中の形と一致する。"}, {"text": "沈んだ", "is_correct": false, "explanation": "た形では「しまった」と続かず、「沈んだしまった」になる。"}, {"text": "沈み", "is_correct": false, "explanation": "連用形は「しまった」の前に置けず、「沈みしまった」になる。"}, {"text": "沈まない", "is_correct": false, "explanation": "ない形は「しまった」と続かず、打ち消しの意味になってしまう。"}], "correct_form": "沈んで", "base_form": "沈む", "form_label": "て形（〜てしまった）", "sentence_index": 1, "explanations": {"沈んで": "「〜てしまった」に続くて形。文中の形と一致する。", "沈んだ": "た形では「しまった」と続かず、「沈んだしまった」になる。", "沈み": "連用形は「しまった」の前に置けず、「沈みしまった」になる。", "沈まない": "ない形は「しまった」と続かず、打ち消しの意味になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉄の玉は水に沈みなかった。", "corrected_sentence": "鉄の玉は水に沈まなかった。", "error_description": "「沈む」の否定形は「沈まない」。「沈みなかった」は活用を誤っており、正しくは「沈まなかった」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "沈ま", "is_correct": true, "explanation": "「〜ないように」に続く未然形。文中の形と一致する。"}, {"text": "沈め", "is_correct": false, "explanation": "他動詞「沈める」の形。「糸が沈めないように」は他動詞に「が」を付けて不自然で、沈む（自動詞）の未然形ではない。"}, {"text": "沈むな", "is_correct": false, "explanation": "禁止の形で、「沈むなないように」となり成り立たない。"}, {"text": "沈みたい", "is_correct": false, "explanation": "願望の形で、「糸が沈みたいように」は文として合わない。"}], "correct_form": "沈ま", "base_form": "沈む", "form_label": "未然形（〜ないように）", "sentence_index": 7, "explanations": {"沈ま": "「〜ないように」に続く未然形。文中の形と一致する。", "沈め": "他動詞「沈める」の形。「糸が沈めないように」は他動詞に「が」を付けて不自然で、沈む（自動詞）の未然形ではない。", "沈むな": "禁止の形で、「沈むなないように」となり成り立たない。", "沈みたい": "願望の形で、「糸が沈みたいように」は文として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
