INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「地面が沈む」の「が」。沈む主体を示し、文中の位置と一致する。"}, {"text": "を", "is_correct": false, "explanation": "「沈む」は自動詞なので、「地面を沈むので」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、主語を示す文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は、動詞に直接つけて文を作れない。"}], "correct_answer": "が", "explanations": {"が": "「地面が沈む」の「が」。沈む主体を示し、文中の位置と一致する。", "を": "「沈む」は自動詞なので、「地面を沈むので」とは言えない。", "と": "相手や並列を表すので、主語を示す文脈に合わない。", "の": "連体修飾の「の」は、動詞に直接つけて文を作れない。"}, "error_tags": {"を": "対象", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水面や地面の下へ下がる。", "primary_collocate": null, "pronunciation": "しずむ", "ipa": "ɕizɯmɯ", "syllable_count": 3, "sentences": [{"text": "大雨のあとで、庭の地面が少し沈んだ。", "target_word": "沈んだ", "complexity_tier": "T3", "furigana": "大雨(おおあめ)のあとで、庭(にわ)の地面(じめん)が少(すこ)し沈(しず)んだ。", "sentence_source": "generated"}, {"text": "泥の道で、足が深く沈んで動けなくなった。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "泥(どろ)の道(みち)で、足(あし)が深(ふか)く沈(しず)んで動(うご)けなくなった。", "sentence_source": "generated"}, {"text": "雪の上を歩くと、体が沈むので歩きにくい。", "target_word": "沈む", "complexity_tier": "T3", "furigana": "雪(ゆき)の上(うえ)を歩(ある)くと、体(からだ)が沈(しず)むので歩(ある)きにくい。", "sentence_source": "generated"}, {"text": "地震のあと、海のそばの土地が沈んだ。", "target_word": "沈んだ", "complexity_tier": "T3", "furigana": "地震(じしん)のあと、海(うみ)のそばの土地(とち)が沈(しず)んだ。", "sentence_source": "generated"}, {"text": "浮きが沈んだら、魚がかかった合図です。", "target_word": "沈んだ", "complexity_tier": "T3", "furigana": "浮(う)きが沈(しず)んだら、魚(さかな)がかかった合図(あいず)です。", "sentence_source": "generated"}, {"text": "重い机を置いたので、床が少し沈んでいる。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "重(おも)い机(つくえ)を置(お)いたので、床(ゆか)が少(すこ)し沈(しず)んでいる。", "sentence_source": "generated"}, {"text": "柔らかい砂に、車のタイヤが沈んでしまった。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "柔(やわ)らかい砂(すな)に、車(くるま)のタイヤが沈(しず)んでしまった。", "sentence_source": "generated"}, {"text": "湿地では、地面が沈むので注意してください。", "target_word": "沈む", "complexity_tier": "T3", "furigana": "湿地(しっち)では、地面(じめん)が沈(しず)むので注意(ちゅうい)してください。", "sentence_source": "generated"}, {"text": "沼に落ちた石は、ゆっくり泥の中へ沈みました。", "target_word": "沈み", "complexity_tier": "T3", "furigana": "沼(ぬま)に落(お)ちた石(いし)は、ゆっくり泥(どろ)の中(なか)へ沈(しず)みました。", "sentence_source": "generated"}, {"text": "古い家は、土台が沈んで少し傾いている。", "target_word": "沈んで", "complexity_tier": "T3", "furigana": "古(ふる)い家(いえ)は、土台(どだい)が沈(しず)んで少(すこ)し傾(かたむ)いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "沈む", "label": "辞書形"}, {"form": "沈みます", "label": "丁寧形"}, {"form": "沈んで", "label": "て形"}, {"form": "沈んだ", "label": "た形"}, {"form": "沈まない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "水面や地面・床などが下へ下がる、または物が泥や雪、地面の中へ埋まるように下がる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b705311-54ad-4c07-a166-2274a4d3c9f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沈んだ", "is_correct": true, "explanation": "文中の形そのもの。地面が下がったという過去の出来事として文を終えられる。"}, {"text": "沈もう", "is_correct": false, "explanation": "意向形になり、地面の変化を述べる文には合わない。"}, {"text": "沈め", "is_correct": false, "explanation": "命令形になり、「地面が少し沈め。」は述べ方として合わない。"}, {"text": "沈める", "is_correct": false, "explanation": "他動詞で、「地面が沈める」は目的語のない文として成り立たない。"}], "explanations": {"沈んだ": "文中の形そのもの。地面が下がったという過去の出来事として文を終えられる。", "沈もう": "意向形になり、地面の変化を述べる文には合わない。", "沈め": "命令形になり、「地面が少し沈め。」は述べ方として合わない。", "沈める": "他動詞で、「地面が沈める」は目的語のない文として成り立たない。"}, "sentence_index": 0, "correct_answer": "沈んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜になって、気温がぐっと沈んだ。", "explanation": "ここは〈下へ下がる〉の意味。気温が下がる話は〈下がる〉で表し、〈沈む〉は地面や床が下へ下がる動きに限られる。"}, {"text": "ぶつけた車のドアが少し沈んだ。", "explanation": "ここは〈下へ下がる〉の意味。ドアのへこみは〈凹む〉で表し、〈沈む〉は使わない。"}, {"text": "彼の言葉を聞いて、部屋の空気が沈んだ。", "explanation": "ここは〈気分が落ち込む〉の意味。雰囲気が暗くなる話は〈暗くなる〉で表し、〈沈む〉は地面や床が下へ下がる動きに限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沈んで", "is_correct": true, "explanation": "「〜てしまった」に続くて形。文中の形と一致する。"}, {"text": "沈まない", "is_correct": false, "explanation": "ない形では「しまった」と続かず、「沈まないしまった」になる。"}, {"text": "沈む", "is_correct": false, "explanation": "辞書形では「しまった」と続かず、「沈むしまった」になる。"}, {"text": "沈みます", "is_correct": false, "explanation": "丁寧形では「しまった」と続かず、「沈みますしまった」になる。"}], "explanations": {"沈んで": "「〜てしまった」に続くて形。文中の形と一致する。", "沈まない": "ない形では「しまった」と続かず、「沈まないしまった」になる。", "沈む": "辞書形では「しまった」と続かず、「沈むしまった」になる。", "沈みます": "丁寧形では「しまった」と続かず、「沈みますしまった」になる。"}, "sentence_index": 6, "correct_answer": "沈んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その知らせに、彼女の気持ちが沈んだ。", "explanation": "ここは〈気分が落ち込む〉の意味。気持ちの落ち込みは〈落ち込む〉で表し、〈沈む〉は地面や床が下へ下がる動きに限られる。"}, {"text": "最後のひとことで、会議の場がすっかり沈んだ。", "explanation": "ここは〈気分が落ち込む〉の意味。場の雰囲気が暗くなる話は〈暗くなる〉で表し、〈沈む〉は地面や床が下へ下がる動きに限られる。"}, {"text": "重いカーテンが沈んで、窓が暗くなった。", "explanation": "ここは〈下へ下がる〉の意味。垂れ下がる布は〈垂れる〉で表し、〈沈む〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱を置いたので、畳が少し沈みた。", "corrected_sentence": "重い箱を置いたので、畳が少し沈んだ。", "error_description": "「沈む」の過去形は「沈んだ」。「沈みた」は活用を誤っており、正しくは「沈んだ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "沈んで", "is_correct": true, "explanation": "「〜て動けなくなった」に続くて形。文中の形と一致する。"}, {"text": "沈んだ", "is_correct": false, "explanation": "た形では「動けなくなった」と続かず、文が成り立たない。"}, {"text": "沈み", "is_correct": false, "explanation": "連用形では「動けなくなった」と続かない。"}, {"text": "沈もう", "is_correct": false, "explanation": "意向形では「動けなくなった」と続かず、文の意味も合わない。"}], "correct_form": "沈んで", "base_form": "沈む", "form_label": "て形（〜て動けなくなった）", "sentence_index": 1, "explanations": {"沈んで": "「〜て動けなくなった」に続くて形。文中の形と一致する。", "沈んだ": "た形では「動けなくなった」と続かず、文が成り立たない。", "沈み": "連用形では「動けなくなった」と続かない。", "沈もう": "意向形では「動けなくなった」と続かず、文の意味も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ぬかるんだ道では、靴が泥を沈むことがある。", "corrected_sentence": "ぬかるんだ道では、靴が泥に沈むことがある。", "error_description": "「沈む」は行き先を表す「に」を取る。「を」は誤りで、正しくは「泥に沈む」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "沈む", "is_correct": true, "explanation": "「〜ので注意」に続く辞書形。文中の形と一致する。"}, {"text": "沈ませる", "is_correct": false, "explanation": "使役の辞書形で、「地面が沈ませるので」は主語と述語が合わない。"}, {"text": "沈みたい", "is_correct": false, "explanation": "願望の形で、地面の変化を注意として述べる文には合わない。"}, {"text": "沈むな", "is_correct": false, "explanation": "禁止の形で、「地面が沈むなので注意」は成り立たない。"}], "correct_form": "沈む", "base_form": "沈む", "form_label": "辞書形（〜ので）", "sentence_index": 7, "explanations": {"沈む": "「〜ので注意」に続く辞書形。文中の形と一致する。", "沈ませる": "使役の辞書形で、「地面が沈ませるので」は主語と述語が合わない。", "沈みたい": "願望の形で、地面の変化を注意として述べる文には合わない。", "沈むな": "禁止の形で、「地面が沈むなので注意」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9255542c-9c5f-43b8-beb6-a64e2d9d7cc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「行く」の向かう先を表す「へ」。「海へ行きました」で自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、「海で行きました」は文として不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒に行く相手を表すが、海は一緒に行く相手にならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、「海の行きました」は文が成り立たない。"}], "correct_answer": "へ", "explanations": {"へ": "「行く」の向かう先を表す「へ」。「海へ行きました」で自然な文になる。", "で": "「で」は場所や手段を表すが、「海で行きました」は文として不自然になる。", "と": "「と」は一緒に行く相手を表すが、海は一緒に行く相手にならないので合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、「海の行きました」は文が成り立たない。"}, "error_tags": {"へ": "方向", "で": "場所", "と": "相手", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入る」の到達点を表す「に」。「海に入りました」で自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は通り抜ける道を表すが、「海を入りました」は不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる対象を表すので、「海より入りました」は文として意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「海の入りました」は名詞のあとに動詞が続かず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「入る」の到達点を表す「に」。「海に入りました」で自然な文になる。", "を": "「を」は通り抜ける道を表すが、「海を入りました」は不自然になる。", "より": "「より」は比べる対象を表すので、「海より入りました」は文として意味が通らない。", "の": "「海の入りました」は名詞のあとに動詞が続かず、文が成り立たない。"}, "error_tags": {"に": "到達点", "を": "通過点", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うみ。たくさんのお水が広がっている場所。", "primary_collocate": null, "pronunciation": "うみ", "ipa": "ɯmi", "syllable_count": 2, "sentences": [{"text": "海は水がたくさんあって、むこうが見えません。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]は水[みず]がたくさんあって、むこうが見[み]えません。", "sentence_source": "generated"}, {"text": "夏休みに、家族みんなで海へ行きました。", "target_word": "海", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、家族[かぞく]みんなで海[うみ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "海には、大きな魚や小さな貝がいます。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]には、大[おお]きな魚[さかな]や小[ちい]さな貝[かい]がいます。", "sentence_source": "generated"}, {"text": "私は海で泳ぐのが好きです。", "target_word": "海", "complexity_tier": "T3", "furigana": "私[わたし]は海[うみ]で泳[およ]ぐのが好[す]きです。", "sentence_source": "generated"}, {"text": "海の水はしょっぱいので、飲めません。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]はしょっぱいので、飲[の]めません。", "sentence_source": "generated"}, {"text": "海から風がふいて、すずしくなりました。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]から風[かぜ]がふいて、すずしくなりました。", "sentence_source": "generated"}, {"text": "船に乗って、広い海をわたりました。", "target_word": "海", "complexity_tier": "T3", "furigana": "船[ふね]に乗[の]って、広[ひろ]い海[うみ]をわたりました。", "sentence_source": "generated"}, {"text": "砂のおしろを作ったあと、海に入りました。", "target_word": "海", "complexity_tier": "T3", "furigana": "砂[すな]のおしろを作[つく]ったあと、海[うみ]に入[はい]りました。", "sentence_source": "generated"}, {"text": "きれいな海を見て、とても気持ちがよかったです。", "target_word": "海", "complexity_tier": "T3", "furigana": "きれいな海[うみ]を見[み]て、とても気持[きも]ちがよかったです。", "sentence_source": "generated"}, {"text": "山ではなく、海でキャンプをしたいです。", "target_word": "海", "complexity_tier": "T3", "furigana": "山[やま]ではなく、海[うみ]でキャンプをしたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "海", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "子ども向けの「うみ」。水がたくさん広がる場所として、遊びや生き物と結びつく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: すずしく (Zipf 1.49)']::text[], '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "ここには、たくさんの水が広がる場所を表す「海」が入る。むこうが見えないほど広い水の場所という意味で文が自然になる。"}, {"text": "山", "is_correct": false, "explanation": "山は水がたくさんある場所ではない。水がたくさんあって見通せない場所は海で、山では文が成り立たない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は水が広がる場所ではないので、「水がたくさんあって」と続けると意味が合わない。"}, {"text": "空", "is_correct": false, "explanation": "空は水が広がる場所ではないので、「水がたくさんある」と続けると不自然になる。"}], "explanations": {"海": "ここには、たくさんの水が広がる場所を表す「海」が入る。むこうが見えないほど広い水の場所という意味で文が自然になる。", "山": "山は水がたくさんある場所ではない。水がたくさんあって見通せない場所は海で、山では文が成り立たない。", "砂": "砂は水が広がる場所ではないので、「水がたくさんあって」と続けると意味が合わない。", "空": "空は水が広がる場所ではないので、「水がたくさんある」と続けると不自然になる。"}, "sentence_index": 0, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この海は水草が多く、夏はカエルの声がうるさい。", "explanation": "ここは〈沼〉の意味。水草が茂り、カエルが鳴く淡水の浅い水域は沼で、塩水が広がる海には合わない。"}, {"text": "山の上の海から水が流れて、下の村の畑をうるおします。", "explanation": "ここは〈川〉の意味。上から下へ流れて畑をうるおすのは川の水で、海は流れ出る元にならないので合わない。"}, {"text": "海はせまいので、水がすぐにきれいになります。", "explanation": "ここは〈池〉の意味。せまくて水がすぐきれいになるのは池。海は広がっている場所なので、せまいとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "船で渡るほど広い水の場所を表す「海」。「広い海をわたる」が自然な組み合わせになる。"}, {"text": "雲", "is_correct": false, "explanation": "雲は船で渡る広い場所ではない。「広い雲をわたる」は不自然。"}, {"text": "花", "is_correct": false, "explanation": "花は船で渡る場所ではない。「広い」と「わたる」の両方が合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は船で渡る広い場所ではないので、「広い石をわたる」は意味が通らない。"}], "explanations": {"海": "船で渡るほど広い水の場所を表す「海」。「広い海をわたる」が自然な組み合わせになる。", "雲": "雲は船で渡る広い場所ではない。「広い雲をわたる」は不自然。", "花": "花は船で渡る場所ではない。「広い」と「わたる」の両方が合わない。", "石": "石は船で渡る広い場所ではないので、「広い石をわたる」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この海は人が掘ったもので、大きな船が通ります。", "explanation": "ここは〈運河〉の意味。人が陸を掘って作った水路は運河で、自然にできた広い海とは合わない。"}, {"text": "雨のあと、道にできた海は、すぐにかわいてなくなりました。", "explanation": "ここは〈水たまり〉の意味。道のくぼみにできる小さな水に、海という言葉は使わない。"}, {"text": "この海は山の中腹からわき出て、いつも冷たい水が流れています。", "explanation": "ここは〈泉〉の意味。山の斜面からわき出して流れ出す水は泉で、地表に広がる海とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は海に泳ぎます。", "corrected_sentence": "週末は海で泳ぎます。", "error_description": "泳ぐ場所は「で」で表す。「に」は到着点や行く先につく助詞なので、「海に泳ぐ」は誤り。正しくは「海で泳ぐ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜明けに、船で広い海をのぼりました。", "corrected_sentence": "夜明けに、船で広い海をわたりました。", "error_description": "広い水の上を進むのは「わたる」。「のぼる」は山や川を上へ進む時に使うので、「広い海をのぼる」は誤り。正しくは「わたる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
