INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「海と湖」と並べて比べる時の「と」。「海と湖のちがい」が自然な言い方になる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしを所属でつなぐ助詞で、「海の湖のちがい」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「海が湖のちがい」は文として合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「海を湖のちがい」は意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「海と湖」と並べて比べる時の「と」。「海と湖のちがい」が自然な言い方になる。", "の": "「の」は名詞どうしを所属でつなぐ助詞で、「海の湖のちがい」は意味が通らない。", "が": "「が」は主語を表すが、「海が湖のちがい」は文として合わない。", "を": "「を」は目的語を表すが、「海を湖のちがい」は意味が通らない。"}, "error_tags": {"と": "並列", "の": "連体", "が": "主語", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "海。地球の表面の大部分を覆う、塩水の大きな水体。", "primary_collocate": null, "pronunciation": "うみ", "ipa": "ɯmi", "syllable_count": 2, "sentences": [{"text": "海は地球の表面の約七割をおおっています。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]は地球[ちきゅう]の表面[ひょうめん]の約[やく]七割[ななわり]をおおっています。", "sentence_source": "generated"}, {"text": "海の水には塩が多くふくまれているため、そのまま飲めません。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]には塩[しお]が多[おお]くふくまれているため、そのまま飲[の]めません。", "sentence_source": "generated"}, {"text": "太平洋は世界でいちばん大きな海です。", "target_word": "海", "complexity_tier": "T3", "furigana": "太平洋[たいへいよう]は世界[せかい]でいちばん大[おお]きな海[うみ]です。", "sentence_source": "generated"}, {"text": "海の深いところには、太陽の光がほとんど届きません。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]の深[ふか]いところには、太陽[たいよう]の光[ひかり]がほとんど届[とど]きません。", "sentence_source": "generated"}, {"text": "海に流れこむ川の水は、少しずつ塩分をはこんでいきます。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]に流[なが]れこむ川[かわ]の水[みず]は、少[すこ]しずつ塩分[えんぶん]をはこんでいきます。", "sentence_source": "generated"}, {"text": "海の温度が上がると、台風が強くなりやすいです。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]の温度[おんど]が上[あ]がると、台風[たいふう]が強[つよ]くなりやすいです。", "sentence_source": "generated"}, {"text": "地球が「青い星」と呼ばれるのは、海が広いからです。", "target_word": "海", "complexity_tier": "T3", "furigana": "地球[ちきゅう]が「青[あお]い星[ほし]」と呼[よ]ばれるのは、海[うみ]が広[ひろ]いからです。", "sentence_source": "generated"}, {"text": "海と湖のちがいは、水に塩がふくまれているかどうかです。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]と湖[みずうみ]のちがいは、水[みず]に塩[しお]がふくまれているかどうかです。", "sentence_source": "generated"}, {"text": "研究者たちは、海の底にすむ生き物を調べています。", "target_word": "海", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、海[うみ]の底[そこ]にすむ生[い]き物[もの]を調[しら]べています。", "sentence_source": "generated"}, {"text": "海の水が蒸発して雲になり、やがて雨としてもどってきます。", "target_word": "海", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]が蒸発[じょうはつ]して雲[くも]になり、やがて雨[あめ]としてもどってきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "海", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "地球科学的な「海」。塩水で地球の表面の大部分を占める大きな水のかたまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: ふくま (Zipf 2.34)','sentence 4 above tier T1: 3 words above tier T1 (max 2): こむ (Zipf 3.71), 塩分 (Zipf 3.63), はこん (Zipf 2.89)','sentence 7 above tier T1: contains vocabulary far above tier T1: ふくま (Zipf 2.34)']::text[], '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "地球の表面の約七割をおおう、塩水の大きな水体を表す「海」が入る。文の意味として正しい。"}, {"text": "山", "is_correct": false, "explanation": "山は地球の表面の七割をおおうものではない。「七割をおおっています」とは合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は地球の表面を七割もおおう水体ではないので、文の主語として合わない。"}, {"text": "森", "is_correct": false, "explanation": "森は地球の表面を七割もおおうものではない。ここには塩水の大きな水体を指す語が入る。"}], "explanations": {"海": "地球の表面の約七割をおおう、塩水の大きな水体を表す「海」が入る。文の意味として正しい。", "山": "山は地球の表面の七割をおおうものではない。「七割をおおっています」とは合わない。", "砂": "砂は地球の表面を七割もおおう水体ではないので、文の主語として合わない。", "森": "森は地球の表面を七割もおおうものではない。ここには塩水の大きな水体を指す語が入る。"}, "sentence_index": 0, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海は淡水なので、そのまま飲むことができます。", "explanation": "ここは〈湖〉の意味。湖は淡水だが、海は定義どおり塩水なので、そのまま飲めるとは言わない。"}, {"text": "海は山の上の雪どけ水から始まり、広い平野を流れて村を通ります。", "explanation": "ここは〈川〉の意味。山から流れ出て平野を通る水は川で、塩水の大きな水体である海は流れ始める場所ではない。"}, {"text": "この海は高さが百メートルもあり、落ちる水の音が遠くまで響きます。", "explanation": "ここは〈滝〉の意味。高い崖から落ちる水は滝で、地表をおおう塩水の大きな水体の海とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海", "is_correct": true, "explanation": "地球を青く見せる、広い塩水の水体を表す「海」が入る。「海が広いから青い」と自然に続く。"}, {"text": "草", "is_correct": false, "explanation": "草は緑色で、地球が青く見える理由にはならない。"}, {"text": "花", "is_correct": false, "explanation": "花は地球全体を青く見せるものではなく、「花が広いから」は意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "石は地球を青く見せる理由にはならず、「石が広いから」は説明として成り立たない。"}], "explanations": {"海": "地球を青く見せる、広い塩水の水体を表す「海」が入る。「海が広いから青い」と自然に続く。", "草": "草は緑色で、地球が青く見える理由にはならない。", "花": "花は地球全体を青く見せるものではなく、「花が広いから」は意味が通らない。", "石": "石は地球を青く見せる理由にはならず、「石が広いから」は説明として成り立たない。"}, "sentence_index": 6, "correct_answer": "海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海は小さいので、水が夏にすぐあたたまります。", "explanation": "ここは〈池〉の意味。地球の表面の大部分をおおう海は小さいとは言えず、池のせまさを表す文には合わない。"}, {"text": "雨のあと、道にできた海は、すぐに消えました。", "explanation": "ここは〈水たまり〉の意味。道のくぼみにできる小さな水に、海という言葉は使わない。"}, {"text": "この海は人が陸を掘ってつくったもので、貨物船が行き来します。", "explanation": "ここは〈運河〉の意味。人が陸を掘って作った細長い水路は運河で、自然にできた地球規模の海とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太陽の光は、海を深いところまで届きます。", "corrected_sentence": "太陽の光は、海の深いところまで届きます。", "error_description": "「海の深いところ」と「の」でつなぐのが正しい。「海を」と目的語にすると、文の意味が崩れるので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38569, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太陽の熱で海を水が蒸発し、雲になります。", "corrected_sentence": "太陽の熱で海の水が蒸発し、雲になります。", "error_description": "「海の水」の「の」は海と水の所属関係を示す。「海を水」の「を」は海を目的語にしてしまい、水が蒸発する主語の関係が崩れるので誤り。正しくは「海の水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
