INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38570, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "よるに、そらにひかるまるいもの。", "primary_collocate": null, "pronunciation": "ほし", "ipa": "hoɕi", "syllable_count": 2, "sentences": [{"text": "夜になると、空に星がたくさん出ます。", "target_word": "星", "complexity_tier": "T3", "furigana": "夜[よる]になると、空[そら]に星[ほし]がたくさん出[で]ます。", "sentence_source": "generated"}, {"text": "星は小さくて、きらきら光っています。", "target_word": "星", "complexity_tier": "T3", "furigana": "星[ほし]は小[ちい]さくて、きらきら光[ひか]っています。", "sentence_source": "generated"}, {"text": "昨日の夜、空を見上げて星をかぞえました。", "target_word": "星", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]、空[そら]を見上[みあ]げて星[ほし]をかぞえました。", "sentence_source": "generated"}, {"text": "雨の日は雲が多いので、星が見えません。", "target_word": "星", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は雲[くも]が多[おお]いので、星[ほし]が見[み]えません。", "sentence_source": "generated"}, {"text": "山の上では、星がとてもきれいに見えます。", "target_word": "星", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、星[ほし]がとてもきれいに見[み]えます。", "sentence_source": "generated"}, {"text": "弟は星に願いをかけて、目を閉じました。", "target_word": "星", "complexity_tier": "T3", "furigana": "弟[おとうと]は星[ほし]に願[ねが]いをかけて、目[め]を閉[と]じました。", "sentence_source": "generated"}, {"text": "夜空で、いちばん明るい星を見つけました。", "target_word": "星", "complexity_tier": "T3", "furigana": "夜空[よぞら]で、いちばん明[あか]るい星[ほし]を見[み]つけました。", "sentence_source": "generated"}, {"text": "昼は太陽が出ていますが、夜は星が光ります。", "target_word": "星", "complexity_tier": "T3", "furigana": "昼[ひる]は太陽[たいよう]が出[で]ていますが、夜[よる]は星[ほし]が光[ひか]ります。", "sentence_source": "generated"}, {"text": "母と一緒に、星を見ながら歩いて帰りました。", "target_word": "星", "complexity_tier": "T3", "furigana": "母[はは]と一緒[いっしょ]に、星[ほし]を見[み]ながら歩[ある]いて帰[かえ]りました。", "sentence_source": "generated"}, {"text": "星が出ているから、あしたは晴れそうです。", "target_word": "星", "complexity_tier": "T3", "furigana": "星[ほし]が出[で]ているから、あしたは晴[は]れそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "星", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "子ども向けの「ほし」。夜空に見えるきらきら光る小さなもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: かぞえ (Zipf 2.42)']::text[], '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38570, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "夜空に多く見える光る点を表す「星」。「たくさん出る」と自然に続く。"}, {"text": "月", "is_correct": false, "explanation": "月は夜空に一つしか見えないので、「たくさん出ます」とは合わない。"}, {"text": "鳥", "is_correct": false, "explanation": "鳥は夜に空へたくさん出てくるものではない。夜空の光る点として文が成り立たない。"}, {"text": "風", "is_correct": false, "explanation": "風は目に見える点ではなく、空に「たくさん出る」ものでもないので合わない。"}], "explanations": {"星": "夜空に多く見える光る点を表す「星」。「たくさん出る」と自然に続く。", "月": "月は夜空に一つしか見えないので、「たくさん出ます」とは合わない。", "鳥": "鳥は夜に空へたくさん出てくるものではない。夜空の光る点として文が成り立たない。", "風": "風は目に見える点ではなく、空に「たくさん出る」ものでもないので合わない。"}, "sentence_index": 0, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この星は夏の夜空に大きな音をたてて開き、光の花を散らします。", "explanation": "ここは〈花火〉の意味。夜空に大きな音を立てて開き、光の花を散らすのは花火で、夜空にただ光って見える星とは合わない。"}, {"text": "星は夜になると、いつも空にひとつだけ出ます。", "explanation": "ここは〈月〉の意味。空にひとつだけ出るのは月で、夜空に多く見える星とは合わない。"}, {"text": "星は昼に空に出て、まぶしくて見上げられません。", "explanation": "ここは〈太陽〉の意味。昼の空に出てまぶしく見上げられないものは太陽で、夜空に見える星とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38570, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "夜空で明るく光って見える天体を表す「星」。「いちばん明るい星を見つけた」と自然に続く。"}, {"text": "花", "is_correct": false, "explanation": "夜空に明るく光る花はないので、「いちばん明るい花を見つけました」は意味が合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は夜空で明るさを比べて見つけるものではなく、「明るい石」は意味が合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は夜空で明るさを比べて見つけるものではなく、「明るい砂」は不自然。"}], "explanations": {"星": "夜空で明るく光って見える天体を表す「星」。「いちばん明るい星を見つけた」と自然に続く。", "花": "夜空に明るく光る花はないので、「いちばん明るい花を見つけました」は意味が合わない。", "石": "石は夜空で明るさを比べて見つけるものではなく、「明るい石」は意味が合わない。", "砂": "砂は夜空で明るさを比べて見つけるものではなく、「明るい砂」は不自然。"}, "sentence_index": 6, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "星が空をおおって、雨がふってきます。", "explanation": "ここは〈雲〉の意味。空をおおって雨をふらせるのは雲で、夜空に光って見える星とは合わない。"}, {"text": "星は雨のあとに空へ出て、七色にかがやきます。", "explanation": "ここは〈虹〉の意味。雨のあとに七色の弧を描いて現れるのは虹で、夜空の星とは合わない。"}, {"text": "星は白くて、地面にふわふわ積もります。", "explanation": "ここは〈雪〉の意味。地面に積もる白いものは雪で、夜空の光る点の星とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38570, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空の星を光っています。", "corrected_sentence": "夜空の星が光っています。", "error_description": "光るのは主語の星なので「が」が正しい。「を」は目的語を取る他動詞に使うので、自動詞の「光る」には誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38570, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜空に星が見ますから、あしたは晴れそうです。", "corrected_sentence": "夜空に星が見えますから、あしたは晴れそうです。", "error_description": "星が自然に目に入ることを表すには「見える」を使う。「星が見ます」は星が見る主体のように読めてしまうので誤り。正しくは「見えます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "見えるの主語は星で、「星が見えません」の「が」が自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は目的語を取らない動詞なので、「星を見えません」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、「星の見えません」は文として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる対象を表すので、「星より見えません」は文として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "見えるの主語は星で、「星が見えません」の「が」が自然になる。", "を": "「見える」は目的語を取らない動詞なので、「星を見えません」は文が成り立たない。", "の": "「の」は名詞どうしをつなぐ助詞で、「星の見えません」は文として意味が通らない。", "より": "「より」は比べる対象を表すので、「星より見えません」は文として意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "天体の一つ。太陽のように自ら光るものや、惑星のように反射して光るもの。また、夜空に見える光る点。", "primary_collocate": null, "pronunciation": "ほし", "ipa": "hoɕi", "syllable_count": 2, "sentences": [{"text": "太陽のように自分で光る星もあれば、太陽の光を反射して光る星もあります。", "target_word": "星", "complexity_tier": "T3", "furigana": "太陽[たいよう]のように自分[じぶん]で光[ひか]る星[ほし]もあれば、太陽[たいよう]の光[ひかり]を反射[はんしゃ]して光[ひか]る星[ほし]もあります。", "sentence_source": "generated"}, {"text": "地球は太陽のまわりを回る星の一つです。", "target_word": "星", "complexity_tier": "T3", "furigana": "地球[ちきゅう]は太陽[たいよう]のまわりを回[まわ]る星[ほし]の一[ひと]つです。", "sentence_source": "generated"}, {"text": "望遠鏡を使うと、肉眼では見えない星も観察できます。", "target_word": "星", "complexity_tier": "T3", "furigana": "望遠鏡[ぼうえんきょう]を使[つか]うと、肉眼[にくがん]では見[み]えない星[ほし]も観察[かんさつ]できます。", "sentence_source": "generated"}, {"text": "夜空で赤く光る星の中には、とても大きいものもあります。", "target_word": "星", "complexity_tier": "T3", "furigana": "夜空[よぞら]で赤[あか]く光[ひか]る星[ほし]の中[なか]には、とても大[おお]きいものもあります。", "sentence_source": "generated"}, {"text": "太陽は私たちにいちばん近い星です。", "target_word": "星", "complexity_tier": "T3", "furigana": "太陽[たいよう]は私[わたし]たちにいちばん近[ちか]い星[ほし]です。", "sentence_source": "generated"}, {"text": "あの星の光は、何年もかけて地球に届いたものです。", "target_word": "星", "complexity_tier": "T3", "furigana": "あの星[ほし]の光[ひかり]は、何年[なんねん]もかけて地球[ちきゅう]に届[とど]いたものです。", "sentence_source": "generated"}, {"text": "遠くにある星ほど、夜空では小さな点に見えます。", "target_word": "星", "complexity_tier": "T3", "furigana": "遠[とお]くにある星[ほし]ほど、夜空[よぞら]では小[ちい]さな点[てん]に見[み]えます。", "sentence_source": "generated"}, {"text": "都会は明るすぎて、夜でも星があまり見えません。", "target_word": "星", "complexity_tier": "T3", "furigana": "都会[とかい]は明[あか]るすぎて、夜[よる]でも星[ほし]があまり見[み]えません。", "sentence_source": "generated"}, {"text": "科学者は、新しく見つかった星の大きさを調べています。", "target_word": "星", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、新[あたら]しく見[み]つかった星[ほし]の大[おお]きさを調[しら]べています。", "sentence_source": "generated"}, {"text": "星の一生は長く、何十億年も続くことがあります。", "target_word": "星", "complexity_tier": "T3", "furigana": "星[ほし]の一生[いっしょう]は長[なが]く、何十億年[なんじゅうおくねん]も続[つづ]くことがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "星", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "天文学的な「星」。太陽や惑星などの天体、または夜空に見える光る点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 夜空 (Zipf 3.49), 赤く (Zipf 3.88), 光る (Zipf 3.99)']::text[], '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "自分で光る天体、または光を反射して光る天体を表す「星」が入る。文の意味として正しい。"}, {"text": "光", "is_correct": false, "explanation": "光は天体ではない。「自分で光る光もあれば」と続けると、文の意味がずれる。"}, {"text": "夜", "is_correct": false, "explanation": "夜は時間を表す語で、自分で光るものではない。天体の説明として成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "石は自分で光る天体ではなく、光を反射する天体としても合わない。"}], "explanations": {"星": "自分で光る天体、または光を反射して光る天体を表す「星」が入る。文の意味として正しい。", "光": "光は天体ではない。「自分で光る光もあれば」と続けると、文の意味がずれる。", "夜": "夜は時間を表す語で、自分で光るものではない。天体の説明として成り立たない。", "石": "石は自分で光る天体ではなく、光を反射する天体としても合わない。"}, "sentence_index": 0, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "星は朝、山あいに白くたちこめて、昼には消えます。", "explanation": "ここは〈霧〉の意味。山あいに白くたちこめ、昼には消える細かい水の粒は霧で、天体の星とは合わない。"}, {"text": "星は水のつぶで、空をおおいます。", "explanation": "ここは〈雲〉の意味。空をおおう水のつぶは雲で、天体の星とは合わない。"}, {"text": "星は雲から落ちてきて、地面をぬらします。", "explanation": "ここは〈雨〉の意味。雲から落ちて地面をぬらすのは雨で、天体の星は地面をぬらさない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "夜空で小さな点に見える天体を表す「星」が入る。「遠くにある星ほど小さな点に見える」と自然になる。"}, {"text": "花", "is_correct": false, "explanation": "花は夜空に点として見えるものではないので、「遠くにある花ほど小さな点に見える」は成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "石は夜空に見える光る点にはならないので、小さな点に見えるとは言えない。"}, {"text": "風", "is_correct": false, "explanation": "風は目で点として見えないので、遠いほど小さな点に見えるとは言えない。"}], "explanations": {"星": "夜空で小さな点に見える天体を表す「星」が入る。「遠くにある星ほど小さな点に見える」と自然になる。", "花": "花は夜空に点として見えるものではないので、「遠くにある花ほど小さな点に見える」は成り立たない。", "石": "石は夜空に見える光る点にはならないので、小さな点に見えるとは言えない。", "風": "風は目で点として見えないので、遠いほど小さな点に見えるとは言えない。"}, "sentence_index": 6, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "星はすぐにしぼんで、一週間ほどで散ってしまいます。", "explanation": "ここは〈花〉の意味。すぐしぼんで一週間ほどで散るのは花で、何十億年も続く星の一生とは合わない。"}, {"text": "星は水が冷えてできて、夏になるととけていきます。", "explanation": "ここは〈氷〉の意味。水が冷えて固まり、夏にとけるのは氷で、星は水からできないので合わない。"}, {"text": "星は木をくべると、赤く燃えて灰になります。", "explanation": "ここは〈火〉の意味。木をくべて赤く燃え、灰になるのは火で、天体の星とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火星は太陽のまわりを回る星を一つです。", "corrected_sentence": "火星は太陽のまわりを回る星の一つです。", "error_description": "「〜の一つ」と全体の中の一つを表すには「の」が正しい。「星を一つです」と目的語にすると文が成り立たないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38571, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな星を、やがて寿命を迎えるものです。", "corrected_sentence": "大きな星が、やがて寿命を迎えるものです。", "error_description": "「大きな星が」の「が」は星を主語として示す。「星を」とすると星が目的語になり、「寿命を迎える」の主語が成り立たないので誤り。正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
