INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38574, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "だれかが、ものをしらべたり、べんきょうしたりすること。", "primary_collocate": null, "pronunciation": "けんきゅうされる", "ipa": "keŋkʲɯːsaɾeɾɯ", "syllable_count": 7, "sentences": [{"text": "この病気は、世界中の大学で研究されています。", "target_word": "研究されています", "complexity_tier": "T3", "furigana": "この病気[びょうき]は、世界中[せかいじゅう]の大学[だいがく]で研究[けんきゅう]されています。", "sentence_source": "generated"}, {"text": "昔の言葉は、今も多くの学者によって研究されています。", "target_word": "研究されています", "complexity_tier": "T3", "furigana": "昔[むかし]の言葉[ことば]は、今[いま]も多[おお]くの学者[がくしゃ]によって研究[けんきゅう]されています。", "sentence_source": "generated"}, {"text": "その薬は十年かけて研究されましたが、まだ使えません。", "target_word": "研究されました", "complexity_tier": "T3", "furigana": "その薬[くすり]は十年[じゅうねん]かけて研究[けんきゅう]されましたが、まだ使[つか]えません。", "sentence_source": "generated"}, {"text": "宇宙のなぞは、これからも研究されるでしょう。", "target_word": "研究される", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]のなぞは、これからも研究[けんきゅう]されるでしょう。", "sentence_source": "generated"}, {"text": "新しい電池が研究されているので、将来は充電が早くなります。", "target_word": "研究されている", "complexity_tier": "T3", "furigana": "新[あたら]しい電池[でんち]が研究[けんきゅう]されているので、将来[しょうらい]は充電[じゅうでん]が早[はや]くなります。", "sentence_source": "generated"}, {"text": "魚のくらしは、水槽の中でも研究されています。", "target_word": "研究されています", "complexity_tier": "T3", "furigana": "魚[さかな]のくらしは、水槽[すいそう]の中[なか]でも研究[けんきゅう]されています。", "sentence_source": "generated"}, {"text": "このテーマはまだあまり研究されていません。", "target_word": "研究されていません", "complexity_tier": "T3", "furigana": "このテーマはまだあまり研究[けんきゅう]されていません。", "sentence_source": "generated"}, {"text": "この問題は昔は研究されませんでしたが、今は注目されています。", "target_word": "研究されませんでした", "complexity_tier": "T3", "furigana": "この問題[もんだい]は昔[むかし]は研究[けんきゅう]されませんでしたが、今[いま]は注目[ちゅうもく]されています。", "sentence_source": "generated"}, {"text": "動物の行動は、森の中で長く研究されてきました。", "target_word": "研究されてきました", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の行動[こうどう]は、森[もり]の中[なか]で長[なが]く研究[けんきゅう]されてきました。", "sentence_source": "generated"}, {"text": "古い建物の作り方も、研究されて、今の家づくりに使われています。", "target_word": "研究されて", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]の作[つく]り方[かた]も、研究[けんきゅう]されて、今[いま]の家[いえ]づくりに使[つか]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "研究される", "label": "基本形"}, {"form": "研究されます", "label": "丁寧形"}, {"form": "研究された", "label": "過去形"}, {"form": "研究されて", "label": "て形"}, {"form": "研究されない", "label": "否定形"}], "register": "丁寧", "sense_fingerprint": "受け身の「研究される」。だれかによってものごとが調べられ、学ばれること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究されています", "is_correct": true, "explanation": "受け身の丁寧な進行形で、「この病気は世界中の大学で研究されている」と文意に合う。"}, {"text": "研究されていません", "is_correct": false, "explanation": "否定形。「研究されていない」となり、世界中の大学で研究されているという文意と逆になる。"}, {"text": "研究させています", "is_correct": false, "explanation": "使役形。誰かに研究させる意味になり、病気を主語とする文意に合わない。"}, {"text": "研究されて", "is_correct": false, "explanation": "て形で文が途中で止まり、文末の「。」に続かない。"}], "explanations": {"研究されています": "受け身の丁寧な進行形で、「この病気は世界中の大学で研究されている」と文意に合う。", "研究されていません": "否定形。「研究されていない」となり、世界中の大学で研究されているという文意と逆になる。", "研究させています": "使役形。誰かに研究させる意味になり、病気を主語とする文意に合わない。", "研究されて": "て形で文が途中で止まり、文末の「。」に続かない。"}, "sentence_index": 0, "correct_answer": "研究されています"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新入社員は来月、本社で研究されます。", "explanation": "ここは〈研修〉の意味。社員が訓練を受けることには「研究される」は使わず、研究は学問的に対象を調べることなので合わない。"}, {"text": "この荷物は、来週、業者によって研究されます。", "explanation": "ここは〈配達〉の意味。荷物を届けることには「研究する」は使わず、研究は対象を学問的に調べることなので合わない。"}, {"text": "この苗は、来週、庭師によって研究されます。", "explanation": "ここは〈植える〉の意味。苗を土に植えることには「研究する」は使わず、研究は対象を学問的に調べることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究されていません", "is_correct": true, "explanation": "受け身の丁寧な否定の進行形で、「このテーマはまだあまり研究されていない」と文意に合う。"}, {"text": "研究させていません", "is_correct": false, "explanation": "使役の否定形。誰かに研究させない意味になり、テーマが研究されていないという文意と合わない。"}, {"text": "研究されていて", "is_correct": false, "explanation": "て形で文が途中で止まり、文末の「。」に続かない。"}, {"text": "研究されずに", "is_correct": false, "explanation": "「〜ずに」で文が途中で止まり、文末の「。」に続かない。"}], "explanations": {"研究されていません": "受け身の丁寧な否定の進行形で、「このテーマはまだあまり研究されていない」と文意に合う。", "研究させていません": "使役の否定形。誰かに研究させない意味になり、テーマが研究されていないという文意と合わない。", "研究されていて": "て形で文が途中で止まり、文末の「。」に続かない。", "研究されずに": "「〜ずに」で文が途中で止まり、文末の「。」に続かない。"}, "sentence_index": 6, "correct_answer": "研究されていません"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この壁は、来週、業者によって研究されます。", "explanation": "ここは〈塗る〉の意味。壁を塗ることには「研究する」は使わず、研究は対象を学問的に調べることなので合わない。"}, {"text": "木箱は、毎朝トラックで研究されています。", "explanation": "ここは〈運搬〉の意味。木箱を運ぶことには「研究する」は使わず、研究は対象を学問的に調べることなので合わない。"}, {"text": "教室の床は、毎朝、係によって研究されます。", "explanation": "ここは〈掃除〉の意味。床をきれいにすることには「研究する」は使わず、研究は対象を学問的に調べることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は、東京の大学で研究させています。", "corrected_sentence": "この薬は、東京の大学で研究されています。", "error_description": "「研究させています」は使役形で、「薬が研究させる」という意味になり文意が合わない。受け身の「研究されています」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "研究されています", "is_correct": true, "explanation": "受け身の丁寧な進行形。文中の「研究されています」がそのまま正解。"}, {"text": "研究されていて", "is_correct": false, "explanation": "て形で、文末の「。」で言い切れず、文が完結しない。"}, {"text": "研究された", "is_correct": false, "explanation": "過去形。「今も学者によって研究されている」という現在の状態と時制が合わない。"}, {"text": "研究されない", "is_correct": false, "explanation": "否定形。「研究されていない」となり、文の内容と逆になる。"}], "correct_form": "研究されています", "base_form": "研究される", "form_label": "丁寧な〜ている形", "sentence_index": 1, "explanations": {"研究されています": "受け身の丁寧な進行形。文中の「研究されています」がそのまま正解。", "研究されていて": "て形で、文末の「。」で言い切れず、文が完結しない。", "研究された": "過去形。「今も学者によって研究されている」という現在の状態と時制が合わない。", "研究されない": "否定形。「研究されていない」となり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この虫の仕組みは、大学で研究されないました。", "corrected_sentence": "この虫の仕組みは、大学で研究されませんでした。", "error_description": "過去の否定は「研究されませんでした」が正しい。「研究されないました」は「されない」と「ました」が結びつかない誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "研究されませんでした", "is_correct": true, "explanation": "丁寧な否定過去形。「昔は研究されなかった」という過去の否定が文意に合う。"}, {"text": "研究される", "is_correct": false, "explanation": "基本形で、過去の否定を表せず、今後の受け身の意味になってしまう。"}, {"text": "研究されました", "is_correct": false, "explanation": "過去の肯定形。「昔は研究されなかった」という否定の内容と逆になる。"}, {"text": "研究されず", "is_correct": false, "explanation": "連用中止形で、文末の「。」に続けるには「〜ずに」などが必要で、ここでは文が完結しない。"}], "correct_form": "研究されませんでした", "base_form": "研究される", "form_label": "丁寧な否定過去形", "sentence_index": 7, "explanations": {"研究されませんでした": "丁寧な否定過去形。「昔は研究されなかった」という過去の否定が文意に合う。", "研究される": "基本形で、過去の否定を表せず、今後の受け身の意味になってしまう。", "研究されました": "過去の肯定形。「昔は研究されなかった」という否定の内容と逆になる。", "研究されず": "連用中止形で、文末の「。」に続けるには「〜ずに」などが必要で、ここでは文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「タイプ」と「スマートフォン」をつなぎ、後の名詞を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「タイプを スマートフォンが売られ」では成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「タイプでスマートフォン」は不自然なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「タイプへスマートフォン」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「タイプ」と「スマートフォン」をつなぎ、後の名詞を修飾する。", "を": "「を」は目的語を示すが、「タイプを スマートフォンが売られ」では成り立たない。", "で": "「で」は手段を示すが、「タイプでスマートフォン」は不自然なので合わない。", "へ": "「へ」は方向を示すが、「タイプへスマートフォン」は成り立たない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「小さいタイプ」を話題にしているので、「は」で話題を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「小さいタイプに安い」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「小さいタイプから安い」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するが、「小さいタイプの安い」は文の形が合わない。"}], "correct_answer": "は", "explanations": {"は": "「小さいタイプ」を話題にしているので、「は」で話題を示す。", "に": "「に」は場所や相手を示すが、「小さいタイプに安い」では意味が通らない。", "から": "「から」は起点を示すが、「小さいタイプから安い」は成り立たない。", "の": "「の」は名詞を修飾するが、「小さいタイプの安い」は文の形が合わない。"}, "error_tags": {"に": "場所", "から": "起点", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "かたちやしくみが、ほかのものとちがう、ひとつのグループ。", "primary_collocate": null, "pronunciation": "たいぷ", "ipa": "taipɯ", "syllable_count": 3, "sentences": [{"text": "この車には、大きさのちがう三つのタイプがあります。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "この車[くるま]には、大[おお]きさのちがう三[みっ]つのタイプがあります。", "sentence_source": "generated"}, {"text": "新しいタイプのスマートフォンが売られ始めました。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "新[あたら]しいタイプのスマートフォンが売[う]られ始[はじ]めました。", "sentence_source": "generated"}, {"text": "このタイプの机は、高さを変えることができます。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "このタイプの机[つくえ]は、高[たか]さを変[か]えることができます。", "sentence_source": "generated"}, {"text": "ドアには、おして開けるタイプと引いて開けるタイプがある。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "ドアには、おして開[あ]けるタイプと引[ひ]いて開[あ]けるタイプがある。", "sentence_source": "generated"}, {"text": "古いタイプのエンジンは、音が大きいです。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "古[ふる]いタイプのエンジンは、音[おと]が大[おお]きいです。", "sentence_source": "generated"}, {"text": "どのタイプの掃除機がいいか、店の人に聞きました。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "どのタイプの掃除機[そうじき]がいいか、店[みせ]の人[ひと]に聞[き]きました。", "sentence_source": "generated"}, {"text": "このタイプは水に強いので、台所でも使えます。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "このタイプは水[みず]に強[つよ]いので、台所[だいどころ]でも使[つか]えます。", "sentence_source": "generated"}, {"text": "小さいタイプは安いが、大きいタイプは高いです。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "小[ちい]さいタイプは安[やす]いが、大[おお]きいタイプは高[たか]いです。", "sentence_source": "generated"}, {"text": "コードがないタイプのヘッドホンを買いました。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "コードがないタイプのヘッドホンを買[か]いました。", "sentence_source": "generated"}, {"text": "二つのタイプを比べてから、軽いほうにしました。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "二[ふた]つのタイプを比[くら]べてから、軽[かる]いほうにしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "タイプ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "形や仕組みで分けた型・型式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: おして (Zipf 2.47)']::text[], '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "タイプ", "is_correct": true, "explanation": "「三つの〇〇がある」に入るのは、形や仕組みで分けた種類のタイプだけ。"}, {"text": "ゆとり", "is_correct": false, "explanation": "ゆとりは余裕のある状態で、車に三つある種類としては数えられないので合わない。"}, {"text": "ねむけ", "is_correct": false, "explanation": "ねむけは眠い感覚で、車の種類を数える言葉ではないので合わない。"}, {"text": "ふるさと", "is_correct": false, "explanation": "ふるさとは故郷の意味で、大きさで分けた車の種類にはならないので合わない。"}], "explanations": {"タイプ": "「三つの〇〇がある」に入るのは、形や仕組みで分けた種類のタイプだけ。", "ゆとり": "ゆとりは余裕のある状態で、車に三つある種類としては数えられないので合わない。", "ねむけ": "ねむけは眠い感覚で、車の種類を数える言葉ではないので合わない。", "ふるさと": "ふるさとは故郷の意味で、大きさで分けた車の種類にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "タイプ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝のタイプに、ごはんを食べました。", "explanation": "ここは〈時間帯〉の意味。タイプは時期の区切りではなく、形や仕組みで分けた種類なので合わない。"}, {"text": "私は先頭のタイプで、列に並んだ。", "explanation": "ここは〈順番〉の意味。タイプは並ぶ位置を表さないので合わない。"}, {"text": "お湯のタイプは、九十度です。", "explanation": "ここは〈温度〉の意味。タイプは数値で測るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "タイプ", "is_correct": true, "explanation": "「この〇〇は水に強い」に入るのは、形や仕組みで分けた種類のタイプだけ。"}, {"text": "気分", "is_correct": false, "explanation": "気分は心の状態で、「この気分は水に強い」は意味が通らないので合わない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きで、水に強いという性質を持たないので合わない。"}, {"text": "不安", "is_correct": false, "explanation": "不安は心の状態で、「この不安は水に強い」は成り立たないので合わない。"}], "explanations": {"タイプ": "「この〇〇は水に強い」に入るのは、形や仕組みで分けた種類のタイプだけ。", "気分": "気分は心の状態で、「この気分は水に強い」は意味が通らないので合わない。", "感情": "感情は心の動きで、水に強いという性質を持たないので合わない。", "不安": "不安は心の状態で、「この不安は水に強い」は成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "タイプ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉が渇いたので、タイプを一杯飲んだ。", "explanation": "ここは〈飲み物〉の意味。「タイプ」は飲める物ではないので合わない。"}, {"text": "駅でタイプを待った。", "explanation": "ここは〈人〉の意味。「タイプ」は待つ相手にはならないので合わない。"}, {"text": "春になって、タイプが咲いた。", "explanation": "ここは〈花〉の意味。「タイプ」は咲く物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいタイプを掃除機が売られ始めました。", "corrected_sentence": "新しいタイプの掃除機が売られ始めました。", "error_description": "「タイプ」に続く助詞の誤り。後ろの名詞を修飾するには「の」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つのタイプを比べるてから、重いほうを選んだ。", "corrected_sentence": "二つのタイプを比べてから、重いほうを選んだ。", "error_description": "「比べる」の活用の誤り。「比べてから」の「比べて」が正しく、「比べるて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
