INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを、その性質や特徴によって分類したときの、ある種類。", "primary_collocate": null, "pronunciation": "たいぷ", "ipa": "taipɯ", "syllable_count": 3, "sentences": [{"text": "私は朝型のタイプなので、早く起きるのが得意です。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "私[わたし]は朝型[あさがた]のタイプなので、早[はや]く起[お]きるのが得意[とくい]です。", "sentence_source": "generated"}, {"text": "彼は人前で話すのが好きなタイプです。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "彼[かれ]は人前[ひとまえ]で話[はな]すのが好[す]きなタイプです。", "sentence_source": "generated"}, {"text": "血液型によって、性格のタイプが分かれるという人もいる。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "血液型[けつえきがた]によって、性格[せいかく]のタイプが分[わ]かれるという人[ひと]もいる。", "sentence_source": "generated"}, {"text": "肌のタイプに合う化粧水を選んでください。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "肌[はだ]のタイプに合[あ]う化粧水[けしょうすい]を選[えら]んでください。", "sentence_source": "generated"}, {"text": "この犬は、おとなしいタイプだと言われています。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "この犬[いぬ]は、おとなしいタイプだと言[い]われています。", "sentence_source": "generated"}, {"text": "あの先生はきびしいタイプだが、とても親切だ。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "あの先生[せんせい]はきびしいタイプだが、とても親切[しんせつ]だ。", "sentence_source": "generated"}, {"text": "植物は、日なたを好むタイプと日かげを好むタイプに分けられる。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は、日[ひ]なたを好[この]むタイプと日[ひ]かげを好[この]むタイプに分[わ]けられる。", "sentence_source": "generated"}, {"text": "兄は考えてから動くタイプで、失敗が少ない。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "兄[あに]は考[かんが]えてから動[うご]くタイプで、失敗[しっぱい]が少[すく]ない。", "sentence_source": "generated"}, {"text": "すぐ決めるタイプの人と、よく悩むタイプの人がいる。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "すぐ決[き]めるタイプの人[ひと]と、よく悩[なや]むタイプの人[ひと]がいる。", "sentence_source": "generated"}, {"text": "彼女は自分から話しかけるタイプではない。", "target_word": "タイプ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]から話[はな]しかけるタイプではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "タイプ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "性質や特徴で分けた種類・型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: 日なた (Zipf 2.15)']::text[], '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "タイプ", "is_correct": true, "explanation": "「朝型の〇〇なので早く起きる」に入るのは、性質で分けた種類のタイプだけ。"}, {"text": "目的", "is_correct": false, "explanation": "目的は行動の狙いで、「朝型の目的」では性質による分類にならないので合わない。"}, {"text": "夕方", "is_correct": false, "explanation": "夕方は時間帯で、「朝型の夕方」は意味が通らないので合わない。"}, {"text": "大きさ", "is_correct": false, "explanation": "大きさは程度で、「朝型の大きさ」は性質の分類にならないので合わない。"}], "explanations": {"タイプ": "「朝型の〇〇なので早く起きる」に入るのは、性質で分けた種類のタイプだけ。", "目的": "目的は行動の狙いで、「朝型の目的」では性質による分類にならないので合わない。", "夕方": "夕方は時間帯で、「朝型の夕方」は意味が通らないので合わない。", "大きさ": "大きさは程度で、「朝型の大きさ」は性質の分類にならないので合わない。"}, "sentence_index": 0, "correct_answer": "タイプ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝、起きてすぐにタイプを測った。", "explanation": "ここは〈体温〉の意味。タイプは体の状態を測る数値ではないので合わない。"}, {"text": "レポートを、パソコンでタイプした。", "explanation": "ここは〈キーボードで文字を打つ〉の意味。タイプは種類の意味で、文字を入力する意味ではないので合わない。"}, {"text": "明日のタイプは晴れです。", "explanation": "ここは〈天気〉の意味。タイプは空模様を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "タイプ", "is_correct": true, "explanation": "両方の空欄に入るのは、性質で分けた種類のタイプだけ。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さで、日なたや日かげの好みで分けられないので合わない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は集まりで、「日なたを好む会議」は意味が通らないので合わない。"}, {"text": "休憩", "is_correct": false, "explanation": "休憩は一時的な中断で、「日かげを好む休憩」は成り立たないので合わない。"}], "explanations": {"タイプ": "両方の空欄に入るのは、性質で分けた種類のタイプだけ。", "体重": "体重は体の重さで、日なたや日かげの好みで分けられないので合わない。", "会議": "会議は集まりで、「日なたを好む会議」は意味が通らないので合わない。", "休憩": "休憩は一時的な中断で、「日かげを好む休憩」は成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "タイプ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休みの日は、タイプを読んだ。", "explanation": "ここは〈本〉の意味。「タイプ」は読める本ではないので合わない。"}, {"text": "駅で、タイプを一枚買った。", "explanation": "ここは〈切符〉の意味。「タイプ」は切符ではないので合わない。"}, {"text": "彼女は、タイプを高い所に飾った。", "explanation": "ここは〈置物〉の意味。「タイプ」は飾る物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は夜型をタイプなので、遅く寝るのが得意です。", "corrected_sentence": "私は夜型のタイプなので、遅く寝るのが得意です。", "error_description": "「夜型」と「タイプ」の間の助詞の誤り。性質を修飾するには「の」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自分から話しかけるたタイプではない。", "corrected_sentence": "彼は自分から話しかけるタイプではない。", "error_description": "「話しかける」に続く語形の誤り。タイプを修飾する辞書形「話しかける」が正しく、余分な「た」を付けた「話しかけるた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。「おばあさんの手で作られました」と受け身に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。受け身の文では「手を作られました」となり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「手に作られました」は意味が通らない。「に」は手段を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「手へ作られました」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。「おばあさんの手で作られました」と受け身に合う。", "を": "目的語を表す「を」。受け身の文では「手を作られました」となり不自然。", "に": "「手に作られました」は意味が通らない。「に」は手段を表せない。", "へ": "方向を表す「へ」で、「手へ作られました」は意味が通らない。"}, "error_tags": {"を": "目的語（受け身と合わない）", "に": "対象（手段に合わない）", "へ": "方向（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
