INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "誰かが何かをつくったことを、やさしく言う言葉です。", "primary_collocate": null, "pronunciation": "つくられました", "ipa": "tsɯkɯɾaɾemaɕita", "syllable_count": 7, "sentences": [{"text": "この絵本は、若い作家によって三年かけて作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "この絵本[えほん]は、若[わか]い作家[さっか]によって三年[さんねん]かけて作[つく]られました。", "sentence_source": "generated"}, {"text": "この人形は、おばあさんの手で作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "この人形[にんぎょう]は、おばあさんの手[て]で作[つく]られました。", "sentence_source": "generated"}, {"text": "町の公園は、地元の人たちによって作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "町[まち]の公園[こうえん]は、地元[じもと]の人[ひと]たちによって作[つく]られました。", "sentence_source": "generated"}, {"text": "この歌は、病気の友だちのために作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "この歌[うた]は、病気[びょうき]の友[とも]だちのために作[つく]られました。", "sentence_source": "generated"}, {"text": "学校のにわに小さな池が、校長先生によって作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "学校[がっこう]のにわに小[ちい]さな池[いけ]が、校長[こうちょう]先生[せんせい]によって作[つく]られました。", "sentence_source": "generated"}, {"text": "この椅子は、木の好きなおじいさんが一つずつ作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "この椅子[いす]は、木[き]の好[す]きなおじいさんが一[ひと]つずつ作[つく]られました。", "sentence_source": "generated"}, {"text": "昔、この道は、村の人たちが石を運んで作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "昔[むかし]、この道[みち]は、村[むら]の人[ひと]たちが石[いし]を運[はこ]んで作[つく]られました。", "sentence_source": "generated"}, {"text": "先生が作られたお弁当は、とてもおいしかったです。", "target_word": "作られた", "complexity_tier": "T3", "furigana": "先生[せんせい]が作[つく]られたお弁当[べんとう]は、とてもおいしかったです。", "sentence_source": "generated"}, {"text": "このお皿は、有名な焼き物の町で作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "このお皿[さら]は、有名[ゆうめい]な焼[や]き物[もの]の町[まち]で作[つく]られました。", "sentence_source": "generated"}, {"text": "運動会のポスターは、六年生によって作られました。", "target_word": "作られました", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]のポスターは、六年生[ろくねんせい]によって作[つく]られました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作る", "label": "基本形"}, {"form": "作られる", "label": "受け身形"}, {"form": "作られます", "label": "丁寧形"}, {"form": "作られた", "label": "過去形"}, {"form": "作られて", "label": "て形"}, {"form": "作られました", "label": "丁寧過去形"}], "register": "丁寧", "sense_fingerprint": "「作られました」。だれかが何かを作ったことを、丁寧にやさしく言う形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作られました", "is_correct": true, "explanation": "「によって」と受け身が呼応し、「三年かけて作られました」と文意に合う。"}, {"text": "作りました", "is_correct": false, "explanation": "能動形。「によって」は受け身と呼応するため、「作家によって作りました」は不自然。"}, {"text": "作られて", "is_correct": false, "explanation": "て形で文が途中で止まり、文末の「。」に続かない。"}, {"text": "作る", "is_correct": false, "explanation": "能動の基本形。「によって」と呼応せず、文末の形としても文意が合わない。"}], "explanations": {"作られました": "「によって」と受け身が呼応し、「三年かけて作られました」と文意に合う。", "作りました": "能動形。「によって」は受け身と呼応するため、「作家によって作りました」は不自然。", "作られて": "て形で文が途中で止まり、文末の「。」に続かない。", "作る": "能動の基本形。「によって」と呼応せず、文末の形としても文意が合わない。"}, "sentence_index": 0, "correct_answer": "作られました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この卵は、めんどりによって作られました。", "explanation": "ここは〈産む〉の意味。鳥が卵を産むことには「作る」は使わず、作るは人が手を加えて物を作ることなので合わない。"}, {"text": "ひどい言葉を聞いて、怒りが作られました。", "explanation": "ここは〈湧く〉（感情が起こる）の意味。怒りが生じることには「作る」は使わず、作るは人が物を作ることなので合わない。"}, {"text": "朝ご飯を食べた後、眠気が作られました。", "explanation": "ここは〈さす〉（眠気が来る）の意味。眠気が現れることには「作る」は使わず、作るは人が物を作ることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作られました", "is_correct": true, "explanation": "受け身の丁寧過去形。「村の人たちが石を運んで」と合わせ、昔この道が造られた経緯を表す。"}, {"text": "作ったら", "is_correct": false, "explanation": "条件形で文が途中で止まり、文末の「。」に続かない。"}, {"text": "作っていて", "is_correct": false, "explanation": "て形で文が途中で止まり、文末の「。」に続かない。"}, {"text": "作れなくて", "is_correct": false, "explanation": "可能形の否定のて形で、文が途中で止まり、文末に続かない。"}], "explanations": {"作られました": "受け身の丁寧過去形。「村の人たちが石を運んで」と合わせ、昔この道が造られた経緯を表す。", "作ったら": "条件形で文が途中で止まり、文末の「。」に続かない。", "作っていて": "て形で文が途中で止まり、文末の「。」に続かない。", "作れなくて": "可能形の否定のて形で、文が途中で止まり、文末に続かない。"}, "sentence_index": 6, "correct_answer": "作られました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、とうとう冬が作られました。", "explanation": "ここは〈来る〉（訪れる）の意味。季節が訪れることには「作る」は使わず、作るは人が物を作ることなので合わない。"}, {"text": "悲しい話を聞いて、ため息が作られました。", "explanation": "ここは〈つく〉（ため息をつく）の意味。ため息を出すことには「作る」は使わず、作るは人が物を作ることなので合わない。"}, {"text": "弟の風邪が作られました。", "explanation": "ここは〈かかる〉の意味。病気は人がかかるもので、人が作るものではないので「作る」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このかさは、祖父の手で作られるました。", "corrected_sentence": "このかさは、祖父の手で作られました。", "error_description": "過去の丁寧形「ました」の前に、動詞の終止形「る」が残っている。正しくは「作られました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "作られました", "is_correct": true, "explanation": "受け身の丁寧過去形。文中の「作られました」がそのまま正解。"}, {"text": "作られません", "is_correct": false, "explanation": "丁寧な否定形。作られなかったという否定の内容になり、作られたという文意と合わない。"}, {"text": "作られなかった", "is_correct": false, "explanation": "普通体の否定過去形。作られなかったという否定の内容になり、文意と逆になる。"}, {"text": "作られて", "is_correct": false, "explanation": "て形で、文末の「。」で言い切れない。"}], "correct_form": "作られました", "base_form": "作る", "form_label": "受け身の丁寧過去形", "sentence_index": 1, "explanations": {"作られました": "受け身の丁寧過去形。文中の「作られました」がそのまま正解。", "作られません": "丁寧な否定形。作られなかったという否定の内容になり、作られたという文意と合わない。", "作られなかった": "普通体の否定過去形。作られなかったという否定の内容になり、文意と逆になる。", "作られて": "て形で、文末の「。」で言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この机は、祖父の手を作られました。", "corrected_sentence": "この机は、祖父の手で作られました。", "error_description": "「作られました」は手段を表す「で」を取る。「手を」は目的語の「を」なので、受け身の文では不自然。正しくは「手で」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "作られた", "is_correct": true, "explanation": "受け身の過去形。「先生が作られたお弁当」と名詞を修飾する形で、「お弁当」に続く。"}, {"text": "作られません", "is_correct": false, "explanation": "丁寧な否定形で名詞を直接修飾できず、「作られませんお弁当」は成り立たない。"}, {"text": "作られれば", "is_correct": false, "explanation": "仮定形（条件形）で、名詞「お弁当」を修飾できず、文が途中で止まる。"}, {"text": "作られませんでした", "is_correct": false, "explanation": "否定の丁寧過去形で、名詞を修飾できず、「作られなかった」の意味になるため文意が合わない。"}], "correct_form": "作られた", "base_form": "作る", "form_label": "受け身の過去形（連体修飾）", "sentence_index": 7, "explanations": {"作られた": "受け身の過去形。「先生が作られたお弁当」と名詞を修飾する形で、「お弁当」に続く。", "作られません": "丁寧な否定形で名詞を直接修飾できず、「作られませんお弁当」は成り立たない。", "作られれば": "仮定形（条件形）で、名詞「お弁当」を修飾できず、文が途中で止まる。", "作られませんでした": "否定の丁寧過去形で、名詞を修飾できず、「作られなかった」の意味になるため文意が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
