INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "プラスチックのような、長い糸みたいな形をした材料のことです。", "primary_collocate": null, "pronunciation": "ぽりまー", "ipa": "poɾimaː", "syllable_count": 4, "sentences": [{"text": "このふくろは、ポリマーという材料で作られています。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "このふくろは、ポリマーという材料[ざいりょう]で作[つく]られています。", "sentence_source": "generated"}, {"text": "ポリマーは、軽くて水に強いので、いろいろな物に使われる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーは、軽[かる]くて水[みず]に強[つよ]いので、いろいろな物[もの]に使[つか]われる。", "sentence_source": "generated"}, {"text": "ポリマーの糸は、ぬのよりも早くかわきます。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーの糸[いと]は、ぬのよりも早[はや]くかわきます。", "sentence_source": "generated"}, {"text": "実験で、ポリマーをお湯に入れてやわらかくした。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "実験[じっけん]で、ポリマーをお湯[ゆ]に入[い]れてやわらかくした。", "sentence_source": "generated"}, {"text": "ペットボトルもポリマーでできています。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ペットボトルもポリマーでできています。", "sentence_source": "generated"}, {"text": "この服はポリマーが入っているので、しわになりにくいです。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "この服[ふく]はポリマーが入[はい]っているので、しわになりにくいです。", "sentence_source": "generated"}, {"text": "ポリマーは火に近づけると、とけることがある。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーは火[ひ]に近[ちか]づけると、とけることがある。", "sentence_source": "generated"}, {"text": "先生は、ポリマーの見本を生徒に見せてくれた。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ポリマーの見本[みほん]を生徒[せいと]に見[み]せてくれた。", "sentence_source": "generated"}, {"text": "ポリマーを使えば、鉄より軽いいすが作れる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーを使[つか]えば、鉄[てつ]より軽[かる]いいすが作[つく]れる。", "sentence_source": "generated"}, {"text": "古いポリマーは、日光に当たるともろくなります。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "古[ふる]いポリマーは、日光[にっこう]に当[あ]たるともろくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリマー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "プラスチックなどの材料としての高分子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリマー", "is_correct": true, "explanation": "材料の名前として、ふくろの素材を正しく示す。"}, {"text": "ボタン", "is_correct": false, "explanation": "ボタンは留め具の名前で、「という材料で」とは続かない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は道具で、ふくろの材料としては成り立たない。"}, {"text": "風船", "is_correct": false, "explanation": "風船はふくらませて使う物で、材料を表す語としては不自然。"}], "explanations": {"ポリマー": "材料の名前として、ふくろの素材を正しく示す。", "ボタン": "ボタンは留め具の名前で、「という材料で」とは続かない。", "時計": "時計は道具で、ふくろの材料としては成り立たない。", "風船": "風船はふくらませて使う物で、材料を表す語としては不自然。"}, "sentence_index": 0, "correct_answer": "ポリマー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は英語がポリマーのように上手で、ネイティブとも自然に話せる。", "explanation": "ここは語学力の比喩が入る場所。ポリマーは素材の名前なので、人の能力を表す語としては使えない。"}, {"text": "朝ごはんに、ポリマーのサラダを食べた。", "explanation": "ここは食べ物の意味ではない。ポリマーは食べられる物ではなく、素材を指す語。"}, {"text": "夕方の空に、ポリマーの虹が大きくかかっていた。", "explanation": "ここは〈虹〉の意味が入る場所。ポリマーは素材の名前で、空に現れる現象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリマー", "is_correct": true, "explanation": "材料として、火に近づけるととける性質を持つものを指すので合う。"}, {"text": "木", "is_correct": false, "explanation": "木は火で燃える素材で、とけるという性質の説明には合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は燃える物で、火に近づけるととけるという説明とは合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は高温でもふつうとけないので、この文には入らない。"}], "explanations": {"ポリマー": "材料として、火に近づけるととける性質を持つものを指すので合う。", "木": "木は火で燃える素材で、とけるという性質の説明には合わない。", "紙": "紙は燃える物で、火に近づけるととけるという説明とは合わない。", "石": "石は高温でもふつうとけないので、この文には入らない。"}, "sentence_index": 6, "correct_answer": "ポリマー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日はポリマーになりそうなので、傘を忘れないでね。", "explanation": "ここは天気の意味ではない。ポリマーは天気を表す語ではなく、素材の名前。"}, {"text": "夏休みに、家族でポリマーの海へ泳ぎに行った。", "explanation": "ここは場所の意味ではない。ポリマーは海のような場所を指す語ではない。"}, {"text": "うちの弟はポリマーで、宿題を一度もしない。", "explanation": "ここは人の性格を表す意味ではない。ポリマーは人を形容する語ではなく、素材の名前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このバッグは、ポリマーにできているので軽いです。", "corrected_sentence": "このバッグは、ポリマーでできているので軽いです。", "error_description": "正しくは「で」（材料を表す）。「に」は「できている」と続かないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このカップは、ポリマーに作られているので割れにくい。", "corrected_sentence": "このカップは、ポリマーで作られているので割れにくい。", "error_description": "「に」は誤り。材料を表す「で」を使い、「ポリマーで作られている」とする。「に作られる」は材料の意味では使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
