INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38581, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "多くの小さな分子が鎖のように長くつながった物質。プラスチックやゴムなどの材料に使われる。", "primary_collocate": null, "pronunciation": "ぽりまー", "ipa": "poɾimaː", "syllable_count": 4, "sentences": [{"text": "ポリマーは、小さな分子が鎖のようにつながってできる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーは、小[ちい]さな分子[ぶんし]が鎖[くさり]のようにつながってできる。", "sentence_source": "generated"}, {"text": "研究室では、新しいポリマーの性質を調べている。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "研究室[けんきゅうしつ]では、新[あたら]しいポリマーの性質[せいしつ]を調[しら]べている。", "sentence_source": "generated"}, {"text": "ポリエチレンは、エチレンが結合してできたポリマーです。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリエチレンは、エチレンが結合[けつごう]してできたポリマーです。", "sentence_source": "generated"}, {"text": "天然ゴムも、自然にできたポリマーの一つである。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "天然[てんねん]ゴムも、自然[しぜん]にできたポリマーの一[ひと]つである。", "sentence_source": "generated"}, {"text": "ポリマーの分子量が大きいほど、材料は強くなる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "ポリマーの分子量[ぶんしりょう]が大[おお]きいほど、材料[ざいりょう]は強[つよ]くなる。", "sentence_source": "generated"}, {"text": "このポリマーは熱に強いため、自動車の部品に使われる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "このポリマーは熱[ねつ]に強[つよ]いため、自動車[じどうしゃ]の部品[ぶひん]に使[つか]われる。", "sentence_source": "generated"}, {"text": "タンパク質もポリマーの一種で、体の中にあります。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "タンパク質[しつ]もポリマーの一種[いっしゅ]で、体[からだ]の中[なか]にあります。", "sentence_source": "generated"}, {"text": "企業は、環境にやさしいポリマーの開発を進めている。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "企業[きぎょう]は、環境[かんきょう]にやさしいポリマーの開発[かいはつ]を進[すす]めている。", "sentence_source": "generated"}, {"text": "重合とは、小さな分子をつなげてポリマーを作る反応です。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "重合[じゅうごう]とは、小[ちい]さな分子[ぶんし]をつなげてポリマーを作[つく]る反応[はんのう]です。", "sentence_source": "generated"}, {"text": "温度が上がると、ポリマーの鎖が動きやすくなる。", "target_word": "ポリマー", "complexity_tier": "T3", "furigana": "温度[おんど]が上[あ]がると、ポリマーの鎖[くさり]が動[うご]きやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリマー", "label": "基本形"}], "register": "technical", "sense_fingerprint": "化学で、分子が鎖状につながった高分子物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ce4cc5-c8da-46a3-b4ee-7c87b1d3a9d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリマー", "is_correct": true, "explanation": "多くの分子が鎖状につながってできる物質で、文の主語に合う。"}, {"text": "原子", "is_correct": false, "explanation": "原子は分子より小さい粒で、分子が鎖状につながってできるという説明には合わない。"}, {"text": "電子", "is_correct": false, "explanation": "電子は粒子の一種で、分子が鎖状につながって作られるものではない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は気体の一種で、鎖状の大きな分子としてできるという説明とは合わない。"}], "explanations": {"ポリマー": "多くの分子が鎖状につながってできる物質で、文の主語に合う。", "原子": "原子は分子より小さい粒で、分子が鎖状につながってできるという説明には合わない。", "電子": "電子は粒子の一種で、分子が鎖状につながって作られるものではない。", "酸素": "酸素は気体の一種で、鎖状の大きな分子としてできるという説明とは合わない。"}, "sentence_index": 0, "correct_answer": "ポリマー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会議では、ポリマーの参加者が一番多かった。", "explanation": "ここは人を指す意味ではない。ポリマーは分子が長くつながった物質の名前で、人には使わない。"}, {"text": "ポリマーを沸かして、お茶を入れた。", "explanation": "ここは〈水〉の意味。ポリマーは材料の名前で、沸かして飲む液体ではないので、お茶には合わない。"}, {"text": "ポリマーの試合は、来週の日曜日に行われる。", "explanation": "ここは催しの意味ではない。ポリマーは物質の名前で、試合や行事を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリマー", "is_correct": true, "explanation": "タンパク質が属する物質の大分類として合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、タンパク質の一種という分類には合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は道具で、体の中にあるという説明と合わない。"}, {"text": "車", "is_correct": false, "explanation": "車は乗り物で、タンパク質の一種という分類には入らない。"}], "explanations": {"ポリマー": "タンパク質が属する物質の大分類として合う。", "鉛筆": "鉛筆は文房具で、タンパク質の一種という分類には合わない。", "時計": "時計は道具で、体の中にあるという説明と合わない。", "車": "車は乗り物で、タンパク質の一種という分類には入らない。"}, "sentence_index": 6, "correct_answer": "ポリマー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリマーの歌は、みんなに愛されている名曲だ。", "explanation": "ここは音楽作品の意味ではない。ポリマーは物質の名前で、歌や曲を指す語ではない。"}, {"text": "日曜日、家族でポリマーを一杯ずつ飲んで、ゆっくり休んだ。", "explanation": "ここは飲み物の意味。ポリマーは固体の物質の名前で、飲めるものではない。"}, {"text": "庭には、ポリマーの花が春に一面に咲いた。", "explanation": "ここは花の名前の意味ではない。ポリマーは植物ではなく、物質の名前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分子が鎖のようにつながったポリマーを、材料として使われる。", "corrected_sentence": "分子が鎖のようにつながったポリマーは、材料として使われる。", "error_description": "正しくは「は」（主題）。「を」では「使われる」の主語を示せず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このポリマーを、水に溶けにくいので、容器によく使われる。", "corrected_sentence": "このポリマーは、水に溶けにくいので、容器によく使われる。", "error_description": "正しくは「は」（主題）。「を」では「使われる」の主語を示せず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9adf17c2-0e2e-46f1-b6f6-84ec18578646') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38584, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大きい", "is_correct": true, "explanation": "「小さい」の反対で、箱の大きさに合う。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの話で、大きさの反対ではない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚さや濃さの話で、大きさの反対ではない。"}, {"text": "安い", "is_correct": false, "explanation": "値段の話で、大きさの反対ではない。"}], "correct_answer": "大きい", "explanations": {"大きい": "「小さい」の反対で、箱の大きさに合う。", "暗い": "明るさの話で、大きさの反対ではない。", "薄い": "厚さや濃さの話で、大きさの反対ではない。", "安い": "値段の話で、大きさの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38584, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大きく", "is_correct": true, "explanation": "「小さく」の反対で、体の大きさが上という意味。"}, {"text": "古く", "is_correct": false, "explanation": "年月の話で、大きさの反対ではない。"}, {"text": "弱く", "is_correct": false, "explanation": "強さの話で、大きさの反対ではない。"}, {"text": "遅く", "is_correct": false, "explanation": "速さの話で、大きさの反対ではない。"}], "correct_answer": "大きく", "explanations": {"大きく": "「小さく」の反対で、体の大きさが上という意味。", "古く": "年月の話で、大きさの反対ではない。", "弱く": "強さの話で、大きさの反対ではない。", "遅く": "速さの話で、大きさの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38584, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "大きさが、ふつうより、もっと少ないこと。", "primary_collocate": null, "pronunciation": "ちいさい", "ipa": "tɕiːsai", "syllable_count": 4, "sentences": [{"text": "小さい家です。", "target_word": "小さい", "complexity_tier": "T1", "furigana": "小[ちい]さい家[いえ]です。", "sentence_source": "generated"}, {"text": "この猫は小さいです。", "target_word": "小さい", "complexity_tier": "T2", "furigana": "この猫[ねこ]は小[ちい]さいです。", "sentence_source": "generated"}, {"text": "私の手は小さい。", "target_word": "小さい", "complexity_tier": "T1", "furigana": "私[わたし]の手[て]は小[ちい]さい。", "sentence_source": "generated"}, {"text": "小さい箱を探しています。", "target_word": "小さい", "complexity_tier": "T2", "furigana": "小[ちい]さい箱[はこ]を探[さが]しています。", "sentence_source": "generated"}, {"text": "この服は、私には小さかった。", "target_word": "小さかった", "complexity_tier": "T2", "furigana": "この服[ふく]は、私[わたし]には小[ちい]さかった。", "sentence_source": "generated"}, {"text": "部屋が小さくて、ベッドしか置けない。", "target_word": "小さくて", "complexity_tier": "T3", "furigana": "部屋[へや]が小[ちい]さくて、ベッドしか置[お]けない。", "sentence_source": "generated"}, {"text": "字を小さく書くと、読みにくくなる。", "target_word": "小さく", "complexity_tier": "T4", "furigana": "字[じ]を小[ちい]さく書[か]くと、読[よ]みにくくなる。", "sentence_source": "generated"}, {"text": "小さければ、かばんに入れて持ち運べる。", "target_word": "小さければ", "complexity_tier": "T4", "furigana": "小[ちい]さければ、かばんに入[い]れて持[も]ち運[はこ]べる。", "sentence_source": "generated"}, {"text": "去年買った靴が、もう小さくなってしまった。", "target_word": "小さく", "complexity_tier": "T3", "furigana": "去年[きょねん]買[か]った靴[くつ]が、もう小[ちい]さくなってしまった。", "sentence_source": "generated"}, {"text": "体は小さくても、力の強い選手がチームを支えている。", "target_word": "小さく", "complexity_tier": "T4", "furigana": "体[からだ]は小[ちい]さくても、力[ちから]の強[つよ]い選手[せんしゅ]がチームを支[ささ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小さく", "label": "活用"}, {"form": "小さかった", "label": "活用"}, {"form": "小さくて", "label": "活用"}, {"form": "小さければ", "label": "活用"}, {"form": "小さくなる", "label": "活用"}], "register": "plain", "sense_fingerprint": "形容詞 | 大きさが普通より少ないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小さい", "is_correct": true, "explanation": "「小さい家」で、大きさの意味が合う。"}, {"text": "甘い", "is_correct": false, "explanation": "形は合うが、家の性質として意味が合わない。"}, {"text": "辛い", "is_correct": false, "explanation": "形は合うが、家を表す意味として合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "形は合うが、家には意味が合わない。"}], "explanations": {"小さい": "「小さい家」で、大きさの意味が合う。", "甘い": "形は合うが、家の性質として意味が合わない。", "辛い": "形は合うが、家を表す意味として合わない。", "眠い": "形は合うが、家には意味が合わない。"}, "sentence_index": 0, "correct_answer": "小さい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は小さい気温で寒い。", "explanation": "気温には「低い」を使うので、「小さい」は誤用。"}, {"text": "この本は小さい値段で買えた。", "explanation": "値段には「安い」を使うので、「小さい」は誤用。"}, {"text": "この川は小さい長さで、とても短い。", "explanation": "長さには「小さい」を使わないので、誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
