nce_source": "generated"}], "morphological_forms": [{"form": "小さく", "label": "活用"}, {"form": "小さかった", "label": "活用"}, {"form": "小さくて", "label": "活用"}, {"form": "小さければ", "label": "活用"}, {"form": "小さすぎる", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 大きさや量が標準より少ないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
