INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38585, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小さく", "is_correct": true, "explanation": "「家は今より小さく感じた」で、大きさの印象として意味が合う。"}, {"text": "甘く", "is_correct": false, "explanation": "形は合うが、家の印象に味の意味は合わない。"}, {"text": "眠く", "is_correct": false, "explanation": "形は合うが、家の感じ方として意味が合わない。"}, {"text": "痛く", "is_correct": false, "explanation": "形は合うが、家について感じる意味として合わない。"}], "explanations": {"小さく": "「家は今より小さく感じた」で、大きさの印象として意味が合う。", "甘く": "形は合うが、家の印象に味の意味は合わない。", "眠く": "形は合うが、家の感じ方として意味が合わない。", "痛く": "形は合うが、家について感じる意味として合わない。"}, "sentence_index": 6, "correct_answer": "小さく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は天井が小さいので、頭をぶつけそうだ。", "explanation": "天井の高さには「低い」を使うので、「小さい」は誤用。"}, {"text": "彼は小さい声で話したので、会場の全員にはっきり聞こえた。", "explanation": "「小さい声」は聞こえにくい声なので、全員にはっきり聞こえたという内容と合わず、使い方が不適切。"}, {"text": "スープの塩が小さいので、味が薄い。", "explanation": "塩などの量の多少には「少ない」を使うので、「小さい」は誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38585, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さいの犬が公園にいます。", "corrected_sentence": "小さい犬が公園にいます。", "error_description": "形容詞「小さい」が名詞を修飾するとき、「の」は不要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "小さい", "is_correct": true, "explanation": "名詞「犬」を修飾する連体形で、文に合う。"}, {"text": "小さく", "is_correct": false, "explanation": "連用形なので、名詞「犬」を直接修飾できない。"}, {"text": "小さければ", "is_correct": false, "explanation": "仮定形なので、名詞を修飾できない。"}, {"text": "小さくて", "is_correct": false, "explanation": "て形なので、名詞を直接修飾できない。"}], "correct_form": "小さい", "base_form": "小さい", "form_label": "連体形", "sentence_index": 1, "explanations": {"小さい": "名詞「犬」を修飾する連体形で、文に合う。", "小さく": "連用形なので、名詞「犬」を直接修飾できない。", "小さければ": "仮定形なので、名詞を修飾できない。", "小さくて": "て形なので、名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38585, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どものころ、部屋は今より小さいに見えた。", "corrected_sentence": "子どものころ、部屋は今より小さく見えた。", "error_description": "「見える」につなぐ形は連用形「小さく」であるべき。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "小さければ", "is_correct": true, "explanation": "「サイズが小さければ、交換できる」という条件を表す仮定形。"}, {"text": "小さかった", "is_correct": false, "explanation": "過去形では「交換できます」と時制や条件の意味が合わない。"}, {"text": "小さすぎる", "is_correct": false, "explanation": "終止形では条件にならず、文がつながらない。"}, {"text": "小さかろう", "is_correct": false, "explanation": "推量形で、この条件の文には合わない。"}], "correct_form": "小さければ", "base_form": "小さい", "form_label": "仮定形", "sentence_index": 7, "explanations": {"小さければ": "「サイズが小さければ、交換できる」という条件を表す仮定形。", "小さかった": "過去形では「交換できます」と時制や条件の意味が合わない。", "小さすぎる": "終止形では条件にならず、文がつながらない。", "小さかろう": "推量形で、この条件の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "「増える」の対義語。数や量が前より少なくなる意味で、ここでの反対の動きにあたる。"}, {"text": "残る", "is_correct": false, "explanation": "余りとして残る意味で、数や量の減少を表さないので対義語ではない。"}, {"text": "続く", "is_correct": false, "explanation": "期間が続く意味で、量の増減とは関係しない。"}, {"text": "変わる", "is_correct": false, "explanation": "状態が変化する意味で、増加と反対の動きを特定しない。"}], "correct_answer": "減る", "explanations": {"減る": "「増える」の対義語。数や量が前より少なくなる意味で、ここでの反対の動きにあたる。", "残る": "余りとして残る意味で、数や量の減少を表さないので対義語ではない。", "続く": "期間が続く意味で、量の増減とは関係しない。", "変わる": "状態が変化する意味で、増加と反対の動きを特定しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「増える」の主体（学生が）を示す格で、ここで正しい。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示すが、「学生と増える」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「学生へ増える」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「学生より増える」では比較の文にならない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「増える」の主体（学生が）を示す格で、ここで正しい。", "と": "相手や引用を示すが、「学生と増える」は成り立たない。", "へ": "方向を示すが、「学生へ増える」は意味が通らない。", "より": "比較を示すが、「学生より増える」では比較の文にならない。"}, "error_tags": {"と": "相手・引用の格", "へ": "方向の格", "より": "比較の格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "「増える」の対義語。数が少なくなる意味で、買う物が少なくなるという見通しに合う。"}, {"text": "戻る", "is_correct": false, "explanation": "元の状態へ戻る意味で、数量の増減を表さないので対義語ではない。"}, {"text": "進む", "is_correct": false, "explanation": "前へ進む意味で、数量の変化を表さないので対義語ではない。"}, {"text": "続ける", "is_correct": false, "explanation": "行為を続けるという意味で、数量の変化とは関係しない。"}], "correct_answer": "減る", "explanations": {"減る": "「増える」の対義語。数が少なくなる意味で、買う物が少なくなるという見通しに合う。", "戻る": "元の状態へ戻る意味で、数量の増減を表さないので対義語ではない。", "進む": "前へ進む意味で、数量の変化を表さないので対義語ではない。", "続ける": "行為を続けるという意味で、数量の変化とは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが前より多くなること。", "primary_collocate": null, "pronunciation": "ふえるかもしれません", "ipa": "ɸɯeɾɯ kamoɕiɾemaseɴ", "syllable_count": 10, "sentences": [{"text": "来年は、この町に住む外国人がもっと増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "来年[らいねん]は、この町[まち]に住[す]む外国人[がいこくじん]がもっと増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "雨が続くと、川の水の量が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、川[かわ]の水[みず]の量[りょう]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "冬になると、風邪をひく人が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、風邪[かぜ]をひく人[ひと]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "駅の近くに新しい店ができて、お客さんが増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに新[あたら]しい店[みせ]ができて、お客[きゃく]さんが増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "毎日おやつを食べていると、体重が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "毎日[まいにち]おやつを食[た]べていると、体重[たいじゅう]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "給料が上がれば、貯金も増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が上[あ]がれば、貯金[ちょきん]も増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "明日は祭りなので、公園に来る人が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "明日[あした]は祭[まつ]りなので、公園[こうえん]に来[く]る人[ひと]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "夏休みに入ると、図書館で勉強する学生が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに入[はい]ると、図書館[としょかん]で勉強[べんきょう]する学生[がくせい]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "このまま暖かい日が続くと、虫が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "このまま暖[あたた]かい日[ひ]が続[つづ]くと、虫[むし]が増[ふ]えるかもしれません。", "sentence_source": "generated"}, {"text": "新しい家に住むと、買う物が増えるかもしれません。", "target_word": "増えるかもしれません", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]に住[す]むと、買[か]う物[もの]が増[ふ]えるかもしれません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増える", "label": "辞書形"}, {"form": "増えます", "label": "ます形"}, {"form": "増えた", "label": "た形"}, {"form": "増えない", "label": "ない形"}, {"form": "増えて", "label": "て形"}, {"form": "増えれば", "label": "仮定形"}, {"form": "増えるかもしれない", "label": "推量（普通体）"}, {"form": "増えるかもしれません", "label": "推量（丁寧体）"}], "register": "丁寧体", "sense_fingerprint": "数や量が前より多くなる可能性があることを、丁寧に推量して述べる言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増えるかもしれません", "is_correct": true, "explanation": "推量を丁寧に述べる形で、来年の見通しを述べる文に合う。"}, {"text": "増えて", "is_correct": false, "explanation": "て形は文を続けるための形で、文末に置くと途中で切れてしまう。"}, {"text": "増えれば", "is_correct": false, "explanation": "仮定形は条件を表す節で、主節がないと文が成り立たない。"}, {"text": "増えず", "is_correct": false, "explanation": "連用中止の形で文を途中で切るため、ここでは文が完結しない。"}], "explanations": {"増えるかもしれません": "推量を丁寧に述べる形で、来年の見通しを述べる文に合う。", "増えて": "て形は文を続けるための形で、文末に置くと途中で切れてしまう。", "増えれば": "仮定形は条件を表す節で、主節がないと文が成り立たない。", "増えず": "連用中止の形で文を途中で切るため、ここでは文が完結しない。"}, "sentence_index": 0, "correct_answer": "増えるかもしれません"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年は、野菜の値段が増えるかもしれません。", "explanation": "「値段が上がる」と混同している。〈増える〉は数や量が多くなる意味なので、値段の上昇には使わない。"}, {"text": "来年は子どもの身長が増えるかもしれません。", "explanation": "「身長が伸びる」と混同している。〈増える〉は数や量の話で、体の高さの変化には使わない。"}, {"text": "寝不足で体温が増えるかもしれません。", "explanation": "「体温が上がる」と混同している。〈増える〉は数や量を言うので、温度の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増えるかもしれません", "is_correct": true, "explanation": "推量を丁寧に述べる形で、祭りの日に人が多くなるという見通しに合う。"}, {"text": "増えたら", "is_correct": false, "explanation": "条件を表す形で、文末に置くと途中で切れてしまう。"}, {"text": "増えなくて", "is_correct": false, "explanation": "て形で理由を述べる途中の形のため、文末に置くと文が完結しない。"}, {"text": "増えつつ", "is_correct": false, "explanation": "同時進行を表す形で、文を完結させられない。"}], "explanations": {"増えるかもしれません": "推量を丁寧に述べる形で、祭りの日に人が多くなるという見通しに合う。", "増えたら": "条件を表す形で、文末に置くと途中で切れてしまう。", "増えなくて": "て形で理由を述べる途中の形のため、文末に置くと文が完結しない。", "増えつつ": "同時進行を表す形で、文を完結させられない。"}, "sentence_index": 6, "correct_answer": "増えるかもしれません"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "練習を続ければ、腕前が増えるかもしれません。", "explanation": "「腕前が上達する」と混同している。〈増える〉は数や量の話で、技量の向上には使わない。"}, {"text": "坂道を走ったら、息が増えるかもしれません。", "explanation": "「息が切れる」と混同している。〈増える〉は数や量を言うので、呼吸の乱れには使えない。"}, {"text": "健康に気をつければ、寿命が増えるかもしれません。", "explanation": "「寿命が延びる」と混同している。〈増える〉は数や量を言うので、期間の延長には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月は、電車の利用者を増えるかもしれません。", "corrected_sentence": "来月は、電車の利用者が増えるかもしれません。", "error_description": "誤りは「利用者を」。「増える」は自動詞なので、増える主体は「が」で示す。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増えるかもしれません", "is_correct": true, "explanation": "推量の丁寧形で文末に置き、文を完結させる。"}, {"text": "増えて", "is_correct": false, "explanation": "て形は文を続ける形で、文末に置くと文が完結しない。"}, {"text": "増えれば", "is_correct": false, "explanation": "仮定形は条件節の形で、主節がないと文が成り立たない。"}, {"text": "増えず", "is_correct": false, "explanation": "連用中止の形で文を途中で切るため、文末では完結しない。"}], "correct_form": "増えるかもしれません", "base_form": "増える", "form_label": "推量（丁寧体）", "sentence_index": 1, "explanations": {"増えるかもしれません": "推量の丁寧形で文末に置き、文を完結させる。", "増えて": "て形は文を続ける形で、文末に置くと文が完結しない。", "増えれば": "仮定形は条件節の形で、主節がないと文が成り立たない。", "増えず": "連用中止の形で文を途中で切るため、文末では完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨の後は、川の水かさが増えかもしれません。", "corrected_sentence": "大雨の後は、川の水かさが増えるかもしれません。", "error_description": "誤りは「増えかもしれません」。推量の「増えるかもしれません」の「る」が抜けて活用が崩れている。正しくは「増えるかもしれません」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "増えるかもしれません", "is_correct": true, "explanation": "推量の丁寧形で文末に置き、文を完結させる。"}, {"text": "増えて", "is_correct": false, "explanation": "て形は文を続ける形で、文末に置くと文が完結しない。"}, {"text": "増えたら", "is_correct": false, "explanation": "条件の形で、文末に置くと文が完結しない。"}, {"text": "増えず", "is_correct": false, "explanation": "連用中止の形で文を途中で切るため、文末では完結しない。"}], "correct_form": "増えるかもしれません", "base_form": "増える", "form_label": "推量（丁寧体）", "sentence_index": 7, "explanations": {"増えるかもしれません": "推量の丁寧形で文末に置き、文を完結させる。", "増えて": "て形は文を続ける形で、文末に置くと文が完結しない。", "増えたら": "条件の形で、文末に置くと文が完結しない。", "増えず": "連用中止の形で文を途中で切るため、文末では完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
