INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38598, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "作業などが、なかなか終わらない・進まない様子を表す副詞。", "primary_collocate": null, "pronunciation": "なかなか", "ipa": "nakanaka", "syllable_count": 4, "sentences": [{"text": "宿題が多すぎて、なかなか終わらない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]すぎて、なかなか終[お]わらない。", "sentence_source": "generated"}, {"text": "道が混んでいて、車がなかなか進まない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "道[みち]が混[こ]んでいて、車[くるま]がなかなか進[すす]まない。", "sentence_source": "generated"}, {"text": "説明書を読んでも、組み立てがなかなか進まなかった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]んでも、組[く]み立[た]てがなかなか進[すす]まなかった。", "sentence_source": "generated"}, {"text": "会議がなかなか終わらなくて、帰るのが遅くなった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "会議[かいぎ]がなかなか終[お]わらなくて、帰[かえ]るのが遅[おそ]くなった。", "sentence_source": "generated"}, {"text": "部屋の片づけがなかなか終わらず、夜になってしまった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "部屋[へや]の片[かた]づけがなかなか終[お]わらず、夜[よる]になってしまった。", "sentence_source": "generated"}, {"text": "長い列がなかなか進まないので、私はあきらめて帰った。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "長[なが]い列[れつ]がなかなか進[すす]まないので、私[わたし]はあきらめて帰[かえ]った。", "sentence_source": "generated"}, {"text": "難しい問題で、作業がなかなか進まなくて困っている。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "難[むずか]しい問題[もんだい]で、作業[さぎょう]がなかなか進[すす]まなくて困[こま]っている。", "sentence_source": "generated"}, {"text": "先生の話がなかなか終わらないから、みんな眠くなった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]がなかなか終[お]わらないから、みんな眠[ねむ]くなった。", "sentence_source": "generated"}, {"text": "荷物が多いので、引っ越しの準備がなかなか終わらなかった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]いので、引[ひ]っ越[こ]しの準備[じゅんび]がなかなか終[お]わらなかった。", "sentence_source": "generated"}, {"text": "風邪のせいで、仕事がなかなか進まず、上司に謝った。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "風邪[かぜ]のせいで、仕事[しごと]がなかなか進[すす]まず、上司[じょうし]に謝[あやま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "なかなか", "label": "基本形"}, {"form": "中々", "label": "漢字表記"}], "register": "普通体", "sense_fingerprint": "否定と結びつき、作業や進行がなかなか終わらない・進まないことを表す副詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38598, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "なかなか", "is_correct": true, "explanation": "否定と結びつき、終わらない様子を表す。宿題が多い状況に合う。"}, {"text": "大いに", "is_correct": false, "explanation": "程度の大きさを表すが、「大いに終わらない」は意味が通らない。"}, {"text": "急に", "is_correct": false, "explanation": "突然を表すため、進み具合の遅さを表せず文脈に合わない。"}, {"text": "早速", "is_correct": false, "explanation": "すぐに何かをする意味で、否定の「終わらない」と結びつかない。"}], "explanations": {"なかなか": "否定と結びつき、終わらない様子を表す。宿題が多い状況に合う。", "大いに": "程度の大きさを表すが、「大いに終わらない」は意味が通らない。", "急に": "突然を表すため、進み具合の遅さを表せず文脈に合わない。", "早速": "すぐに何かをする意味で、否定の「終わらない」と結びつかない。"}, "sentence_index": 0, "correct_answer": "なかなか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方になって、雨がなかなか降り出した。", "explanation": "「急に」と混同している。〈なかなか〉は時間がかかる意味なので、急な変化を表す文とは合わない。"}, {"text": "会議がなかなか終わったので、みんなほっとした。", "explanation": "「ようやく」（やっと）と混同している。〈なかなか〉は否定と結びつくので、肯定の「終わった」とは合わない。"}, {"text": "電車がなかなか来たので、乗り遅れずに済んだ。", "explanation": "「すぐに」と混同している。〈なかなか〉は遅れを表すので、肯定の「来た」と結びつけると意味が逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38598, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "なかなか", "is_correct": true, "explanation": "否定と結びつき、作業が進まない状況を表す。文脈に合う。"}, {"text": "直ちに", "is_correct": false, "explanation": "すぐに、の意味で、進まずに困っている状況とは合わない。"}, {"text": "わざと", "is_correct": false, "explanation": "意図して、の意味で、困っている状況の説明にならない。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "急いで、の意味で、困っている状況と結びつかない。"}], "explanations": {"なかなか": "否定と結びつき、作業が進まない状況を表す。文脈に合う。", "直ちに": "すぐに、の意味で、進まずに困っている状況とは合わない。", "わざと": "意図して、の意味で、困っている状況の説明にならない。", "大急ぎで": "急いで、の意味で、困っている状況と結びつかない。"}, "sentence_index": 6, "correct_answer": "なかなか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が上がって、道路の水がなかなか引いた。", "explanation": "「すぐに」と混同している。〈なかなか〉は思うように進まない意味なので、すぐ引いた文とは合わない。"}, {"text": "急用ができたので、なかなかさっと出かけた。", "explanation": "「すばやく」（手早く）と混同している。〈なかなか〉は思うように進まない意味なので、手早く出かけた文とは合わない。"}, {"text": "作業が一気に進んで、なかなか終わった。", "explanation": "「あっという間に」と混同している。〈なかなか〉は思うように進まない意味なので、どんどん進んで終わった文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38598, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降り続いて、洗濯物がなかなか乾いた。", "corrected_sentence": "雨が降り続いて、洗濯物がなかなか乾かない。", "error_description": "誤りは「乾いた」。「なかなか」は否定の「〜ない」と結びつくので、「乾かない」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38598, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "道路の工事が続いて、車の列がなかなか動かしない。", "corrected_sentence": "道路の工事が続いて、車の列がなかなか動かない。", "error_description": "誤りは「動かしない」。「動かす」の否定形と混同して活用が崩れている。正しくは「動かない」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
