INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38599, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "物事が思うように進まず、簡単には実現しない様子を表す副詞。", "primary_collocate": null, "pronunciation": "なかなか", "ipa": "nakanaka", "syllable_count": 4, "sentences": [{"text": "人気の店で、予約がなかなか取れない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "人気[にんき]の店[みせ]で、予約[よやく]がなかなか取[と]れない。", "sentence_source": "generated"}, {"text": "忙しくて、友達となかなか会えない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "忙[いそが]しくて、友達[ともだち]となかなか会[あ]えない。", "sentence_source": "generated"}, {"text": "落とした鍵がなかなか見つからなくて、一時間も探した。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "落[お]とした鍵[かぎ]がなかなか見[み]つからなくて、一時間[いちじかん]も探[さが]した。", "sentence_source": "generated"}, {"text": "日本語の発音は、なかなか上手にならない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "日本語[にほんご]の発音[はつおん]は、なかなか上手[じょうず]にならない。", "sentence_source": "generated"}, {"text": "夜はうるさくて、なかなか眠れなかった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "夜[よる]はうるさくて、なかなか眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "緊張していて、なかなか言葉が出てこなかった。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "緊張[きんちょう]していて、なかなか言葉[ことば]が出[で]てこなかった。", "sentence_source": "generated"}, {"text": "近くに病院がないので、具合が悪くてもなかなか診てもらえない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "近[ちか]くに病院[びょういん]がないので、具合[ぐあい]が悪[わる]くてもなかなか診[み]てもらえない。", "sentence_source": "generated"}, {"text": "彼は頑固だから、みんなが頼んでもなかなか意見を変えない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "彼[かれ]は頑固[がんこ]だから、みんなが頼[たの]んでもなかなか意見[いけん]を変[か]えない。", "sentence_source": "generated"}, {"text": "春なのに寒くて、なかなか桜が咲かない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "春[はる]なのに寒[さむ]くて、なかなか桜[さくら]が咲[さ]かない。", "sentence_source": "generated"}, {"text": "この本は人気で、図書館でもなかなか借りられない。", "target_word": "なかなか", "complexity_tier": "T3", "furigana": "この本[ほん]は人気[にんき]で、図書館[としょかん]でもなかなか借[か]りられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "なかなか", "label": "基本形"}, {"form": "中々", "label": "漢字表記"}], "register": "普通体", "sense_fingerprint": "否定と結びつき、望むことが簡単には実現しない・できないことを表す副詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38599, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "なかなか", "is_correct": true, "explanation": "否定と結びつき、思うように予約が取れない状況を表す。"}, {"text": "早速", "is_correct": false, "explanation": "すぐに、の意味で、予約が取れないという状況とは意味が合わない。"}, {"text": "大きく", "is_correct": false, "explanation": "程度の大きさを表すが、「大きく取れない」は文脈に合わない。"}, {"text": "わざと", "is_correct": false, "explanation": "意図して、の意味で、予約が取れないという状況とは合わない。"}], "explanations": {"なかなか": "否定と結びつき、思うように予約が取れない状況を表す。", "早速": "すぐに、の意味で、予約が取れないという状況とは意味が合わない。", "大きく": "程度の大きさを表すが、「大きく取れない」は文脈に合わない。", "わざと": "意図して、の意味で、予約が取れないという状況とは合わない。"}, "sentence_index": 0, "correct_answer": "なかなか"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布を探していたら、鍵がなかなか見つかった。", "explanation": "「ようやく」（やっと）と混同している。〈なかなか〉は否定と結びつくので、肯定の「見つかった」とは合わない。"}, {"text": "駅に着くと、電車がなかなか来た。", "explanation": "「すぐに」と混同している。〈なかなか〉は時間がかかる意味なので、すぐ来た文とは合わない。"}, {"text": "宿題を始めたら、計算がなかなか終わった。", "explanation": "「あっという間に」と混同している。〈なかなか〉は思うように進まない意味なので、早く終わった文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38599, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "なかなか", "is_correct": true, "explanation": "否定と結びつき、思うように診てもらえない状況を表す。"}, {"text": "偶然", "is_correct": false, "explanation": "たまたま、の意味で、診てもらえない状況の説明にならない。"}, {"text": "わざと", "is_correct": false, "explanation": "意図して、の意味で、診てもらえない状況の説明にならない。"}, {"text": "同時に", "is_correct": false, "explanation": "一緒に、の意味で、ここでは文脈に合わない。"}], "explanations": {"なかなか": "否定と結びつき、思うように診てもらえない状況を表す。", "偶然": "たまたま、の意味で、診てもらえない状況の説明にならない。", "わざと": "意図して、の意味で、診てもらえない状況の説明にならない。", "同時に": "一緒に、の意味で、ここでは文脈に合わない。"}, "sentence_index": 6, "correct_answer": "なかなか"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "予約をしたら、本がなかなか借りられた。", "explanation": "「すぐに」（即座に）と混同している。〈なかなか〉は否定と結びつくので、すぐ借りられたという肯定の文とは合わない。"}, {"text": "締め切り前に、なかなかさっさと読み終えた。", "explanation": "「手早く」と混同している。〈なかなか〉は思うように進まない意味なので、手早く読み終えた文とは合わない。"}, {"text": "その講座は、なかなかあっさり申し込めた。", "explanation": "「簡単に」と混同している。〈なかなか〉は否定と結びつくので、簡単に申し込めたという肯定の文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38599, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、道路がなかなか乾いた。", "corrected_sentence": "雨の日は、道路がなかなか乾かない。", "error_description": "誤りは「乾いた」。「なかなか」は否定の「〜ない」と結びつくので、「乾かない」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38599, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近くに店がないので、欲しい本をなかなか手に入らない。", "corrected_sentence": "近くに店がないので、欲しい本がなかなか手に入らない。", "error_description": "誤りは「本を」。「手に入る」は主語を「が」で示すので、「本が」が正しい。「を」は目的語を示す格で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
