INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38600, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "じゅうぶんは、もうたりていることです。", "primary_collocate": null, "pronunciation": "じゅうふん", "ipa": "dʑɯːɸɯɴ", "syllable_count": 4, "sentences": [{"text": "お弁当は一つで十分だから、二つも作らなくていい。", "target_word": "十分", "complexity_tier": "T3", "furigana": "お弁当[べんとう]は一[ひと]つで十分[じゅうふん]だから、二[ふた]つも作[つく]らなくていい。", "sentence_source": "generated"}, {"text": "三人で食べるなら、このケーキの大きさで十分だ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "三人[さんにん]で食[た]べるなら、このケーキの大[おお]きさで十分[じゅうふん]だ。", "sentence_source": "generated"}, {"text": "今日の宿題は少ないので、一時間あれば十分だ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "今日[きょう]の宿題[しゅくだい]は少[すく]ないので、一時間[いちじかん]あれば十分[じゅうふん]だ。", "sentence_source": "generated"}, {"text": "旅行のお金は、これだけあれば十分だ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "旅行[りょこう]のお金[かね]は、これだけあれば十分[じゅうふん]だ。", "sentence_source": "generated"}, {"text": "この部屋は一人で住むには十分な広さだ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "この部屋[へや]は一人[ひとり]で住[す]むには十分[じゅうふん]な広[ひろ]さだ。", "sentence_source": "generated"}, {"text": "水はもう十分あるので、これ以上買わなくていい。", "target_word": "十分", "complexity_tier": "T3", "furigana": "水[みず]はもう十分[じゅうふん]あるので、これ以上[いじょう]買[か]わなくていい。", "sentence_source": "generated"}, {"text": "昼ごはんをしっかり食べたから、夜は軽いもので十分だ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんをしっかり食[た]べたから、夜[よる]は軽[かる]いもので十分[じゅうふん]だ。", "sentence_source": "generated"}, {"text": "傘は一本あれば十分なのに、彼は三本も持ってきた。", "target_word": "十分", "complexity_tier": "T3", "furigana": "傘[かさ]は一本[いっぽん]あれば十分[じゅうふん]なのに、彼[かれ]は三本[さんぼん]も持[も]ってきた。", "sentence_source": "generated"}, {"text": "食事の量はこれで十分だから、おかわりはいらない。", "target_word": "十分", "complexity_tier": "T3", "furigana": "食事[しょくじ]の量[りょう]はこれで十分[じゅうふん]だから、おかわりはいらない。", "sentence_source": "generated"}, {"text": "部屋を暖めるには、小さなストーブ一つで十分だった。", "target_word": "十分", "complexity_tier": "T3", "furigana": "部屋[へや]を暖[あたた]めるには、小[ちい]さなストーブ一[ひと]つで十分[じゅうふん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "十分だ", "label": "終止形"}, {"form": "十分な", "label": "連体形"}, {"form": "十分に", "label": "連用形"}, {"form": "十分で", "label": "で形"}, {"form": "十分だった", "label": "過去形"}, {"form": "十分ではない", "label": "否定形"}], "register": "普通体", "sense_fingerprint": "物や量がすでに足りていて、これ以上は要らない状態。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38600, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "「十分だ」の語幹。「一つで足りる」の意味になり、文の流れに合う。"}, {"text": "静か", "is_correct": false, "explanation": "「静かだ」は音や様子が穏やかという意味。弁当の数の判断には合わず、「一つで静かだから」は意味が通らない。"}, {"text": "派手", "is_correct": false, "explanation": "「派手だ」は目立つ様子の意味。量を判断する文脈には合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧だ」は注意深さや礼儀正しさの意味。数量の話には合わない。"}], "explanations": {"十分": "「十分だ」の語幹。「一つで足りる」の意味になり、文の流れに合う。", "静か": "「静かだ」は音や様子が穏やかという意味。弁当の数の判断には合わず、「一つで静かだから」は意味が通らない。", "派手": "「派手だ」は目立つ様子の意味。量を判断する文脈には合わない。", "丁寧": "「丁寧だ」は注意深さや礼儀正しさの意味。数量の話には合わない。"}, "sentence_index": 0, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は約束の時間に十分来た。", "explanation": "〈ちょうど〉（時刻がぴったり合う）の意味。〈十分〉は「足りている」ことなので、時刻が合う様子には使わない。"}, {"text": "彼は十分な人だから、みんなに慕われている。", "explanation": "〈立派〉の意味。〈十分〉は「足りている」を表すので、人柄をほめる言い方には合わない。"}, {"text": "彼は十分な笑みを浮かべて、みんなに手を振った。", "explanation": "〈満面〉（顔いっぱいに）の意味。〈十分〉は量が足りていることなので、表情の広がりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38600, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "「十分だ」の語幹。「軽いもので足りる」の意味になり、文の流れに合う。"}, {"text": "大胆", "is_correct": false, "explanation": "「大胆だ」は思い切りがよいという意味。夜の食事の量の話には合わない。"}, {"text": "複雑", "is_correct": false, "explanation": "「複雑だ」は入り組んでいる様子の意味。食べ物の量には合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔だ」は汚れがない様子の意味。食事の量を表す文には合わない。"}], "explanations": {"十分": "「十分だ」の語幹。「軽いもので足りる」の意味になり、文の流れに合う。", "大胆": "「大胆だ」は思い切りがよいという意味。夜の食事の量の話には合わない。", "複雑": "「複雑だ」は入り組んでいる様子の意味。食べ物の量には合わない。", "清潔": "「清潔だ」は汚れがない様子の意味。食事の量を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は十分に飲むと、体に害が出るので注意してください。", "explanation": "ここは〈過剰〉の意味。〈十分〉は「足りている」なので、多すぎることの危険を述べる文には合わない。"}, {"text": "この壁の色は十分で、部屋が暗く見える。", "explanation": "〈鮮やか〉などの色の印象を表す語の意味。〈十分〉は数量や程度に使うので、色の印象には使わない。"}, {"text": "余計な荷物は、十分な荷物として置いていきましょう。", "explanation": "〈余計〉（不要な）の意味。〈十分〉は「足りている」なので、不要なものを指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38600, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鍋は一人分なら十分に大きさだ。", "corrected_sentence": "この鍋は一人分なら十分な大きさだ。", "error_description": "「十分」が名詞「大きさ」を修飾するときは連体形「十分な」になる。「十分に大きさ」は連用形を名詞の前に置いた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "十分", "is_correct": true, "explanation": "「十分だ」の語幹。「大きさで十分だ」の位置に入る形。"}, {"text": "十分な", "is_correct": false, "explanation": "連体形。「大きさで十分な だ」とは続かず、文が成り立たない。"}, {"text": "十分に", "is_correct": false, "explanation": "連用形。「十分にだ」は文法的に続かない。"}, {"text": "十分だった", "is_correct": false, "explanation": "過去形。「十分だった だ」は文が成り立たない。"}], "correct_form": "十分", "base_form": "十分", "form_label": "語幹", "sentence_index": 1, "explanations": {"十分": "「十分だ」の語幹。「大きさで十分だ」の位置に入る形。", "十分な": "連体形。「大きさで十分な だ」とは続かず、文が成り立たない。", "十分に": "連用形。「十分にだ」は文法的に続かない。", "十分だった": "過去形。「十分だった だ」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38600, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人なら、この車を十分だ。", "corrected_sentence": "三人なら、この車で十分だ。", "error_description": "誤りは「を」。「十分」が受ける助詞は「で」。「を」は目的語を示す格で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "十分", "is_correct": true, "explanation": "語幹。後ろの「なのに」と合わさって「十分なのに」になる。"}, {"text": "十分だ", "is_correct": false, "explanation": "終止形。「だなのに」は文法的に続かない。"}, {"text": "十分で", "is_correct": false, "explanation": "で形。「でなのに」は続かない。"}, {"text": "十分ではない", "is_correct": false, "explanation": "否定形。「ではないなのに」は文が成り立たない。"}], "correct_form": "十分", "base_form": "十分", "form_label": "語幹", "sentence_index": 7, "explanations": {"十分": "語幹。後ろの「なのに」と合わさって「十分なのに」になる。", "十分だ": "終止形。「だなのに」は文法的に続かない。", "十分で": "で形。「でなのに」は続かない。", "十分ではない": "否定形。「ではないなのに」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
