INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38601, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "必要な量や程度に達していて、それ以上いらない様子。", "primary_collocate": null, "pronunciation": "じゅうぶん", "ipa": "dʑɯːbɯɴ", "syllable_count": 4, "sentences": [{"text": "試験の前に、十分に準備をしておいた。", "target_word": "十分", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、十分[じゅうぶん]に準備[じゅんび]をしておいた。", "sentence_source": "generated"}, {"text": "夜は十分に休まないと、翌日の仕事に差し支える。", "target_word": "十分", "complexity_tier": "T3", "furigana": "夜[よる]は十分[じゅうぶん]に休[やす]まないと、翌日[よくじつ]の仕事[しごと]に差[さ]し支[つか]える。", "sentence_source": "generated"}, {"text": "医者は、風邪を治すには十分な睡眠が大切だと言った。", "target_word": "十分", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、風邪[かぜ]を治[なお]すには十分[じゅうぶん]な睡眠[すいみん]が大切[たいせつ]だと言[い]った。", "sentence_source": "generated"}, {"text": "山に登るときは、十分に気をつけたほうがいい。", "target_word": "十分", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]るときは、十分[じゅうぶん]に気[き]をつけたほうがいい。", "sentence_source": "generated"}, {"text": "説明が十分だったので、質問する人は一人もいなかった。", "target_word": "十分", "complexity_tier": "T3", "furigana": "説明[せつめい]が十分[じゅうぶん]だったので、質問[しつもん]する人[ひと]は一人[ひとり]もいなかった。", "sentence_source": "generated"}, {"text": "この資料だけでは、計画の理由を説明するのに十分ではない。", "target_word": "十分", "complexity_tier": "T3", "furigana": "この資料[しりょう]だけでは、計画[けいかく]の理由[りゆう]を説明[せつめい]するのに十分[じゅうぶん]ではない。", "sentence_source": "generated"}, {"text": "十分に練習したから、本番でも緊張しなかった。", "target_word": "十分", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に練習[れんしゅう]したから、本番[ほんばん]でも緊張[きんちょう]しなかった。", "sentence_source": "generated"}, {"text": "彼は十分な経験があるので、新人の指導を任された。", "target_word": "十分", "complexity_tier": "T3", "furigana": "彼[かれ]は十分[じゅうぶん]な経験[けいけん]があるので、新人[しんじん]の指導[しどう]を任[まか]された。", "sentence_source": "generated"}, {"text": "十分に火を通さないと、この肉は食べられない。", "target_word": "十分", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に火[ひ]を通[とお]さないと、この肉[にく]は食[た]べられない。", "sentence_source": "generated"}, {"text": "準備は十分にできたので、あとは出発するだけだ。", "target_word": "十分", "complexity_tier": "T3", "furigana": "準備[じゅんび]は十分[じゅうぶん]にできたので、あとは出発[しゅっぱつ]するだけだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "十分だ", "label": "終止形"}, {"form": "十分な", "label": "連体形"}, {"form": "十分に", "label": "連用形"}, {"form": "十分で", "label": "で形"}, {"form": "十分だった", "label": "過去形"}, {"form": "十分ではない", "label": "否定形"}], "register": "普通体", "sense_fingerprint": "準備・説明・注意などの程度が必要な水準に達していて、それ以上は要らない様子。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 差し支える (Zipf 2.08)']::text[], '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38601, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "「十分に準備」の語幹。「必要な程度まで準備した」の意味に合う。"}, {"text": "不便", "is_correct": false, "explanation": "「不便だ」は使いにくい様子の意味。準備の程度を表せず、「不便に準備」は不自然。"}, {"text": "幸福", "is_correct": false, "explanation": "「幸福だ」は幸せな状態の意味。準備の仕方を表す語ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈だ」は丈夫な様子の意味。準備の程度の文には合わない。"}], "explanations": {"十分": "「十分に準備」の語幹。「必要な程度まで準備した」の意味に合う。", "不便": "「不便だ」は使いにくい様子の意味。準備の程度を表せず、「不便に準備」は不自然。", "幸福": "「幸福だ」は幸せな状態の意味。準備の仕方を表す語ではない。", "頑丈": "「頑丈だ」は丈夫な様子の意味。準備の程度の文には合わない。"}, "sentence_index": 0, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "列車は予定の時刻に十分着いた。", "explanation": "〈ちょうど〉（時刻がぴったり合う）の意味。〈十分〉は「足りている」ことなので、時刻が合う様子には使わない。"}, {"text": "彼は十分な人間だと、みんなが感心している。", "explanation": "〈立派〉の意味。〈十分〉は足りている程度を表すので、人の人柄をほめる文には合わない。"}, {"text": "彼は十分な心の持ち主で、みんなに優しい。", "explanation": "〈豊か〉（中身が満ちている）の意味。〈十分〉は足りている量を表すので、心の豊かさを表す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38601, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "「十分に練習」の語幹。「練習して本番で緊張しなかった」の流れに合う。"}, {"text": "不快", "is_correct": false, "explanation": "「不快だ」は気分が悪いという意味。練習の仕方には合わない。"}, {"text": "莫大", "is_correct": false, "explanation": "「莫大だ」は非常に大きい量の意味。練習の仕方を表せない。"}, {"text": "幸運", "is_correct": false, "explanation": "「幸運だ」は運がよいという意味。練習の程度を表す語ではない。"}], "explanations": {"十分": "「十分に練習」の語幹。「練習して本番で緊張しなかった」の流れに合う。", "不快": "「不快だ」は気分が悪いという意味。練習の仕方には合わない。", "莫大": "「莫大だ」は非常に大きい量の意味。練習の仕方を表せない。", "幸運": "「幸運だ」は運がよいという意味。練習の程度を表す語ではない。"}, "sentence_index": 6, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このバッテリーは十分に充電すると、故障の原因になる。", "explanation": "ここは〈過充電〉の意味。〈十分〉は足りている程度なので、多すぎる充電の危険を述べる文には合わない。"}, {"text": "彼は十分な泣き声を上げて、教室を出ていった。", "explanation": "〈大きい〉（声が大きい）の意味。〈十分〉は量が足りていることなので、声の大きさを表す文には使わない。"}, {"text": "その知らせを聞いて、彼は十分な気持ちになった。", "explanation": "〈不安〉の意味。〈十分〉は足りている程度を表すので、感情の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38601, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この量なら十分くて、もう買わなくていい。", "corrected_sentence": "この量なら十分で、もう買わなくていい。", "error_description": "「十分」は形容動詞なので、イ形容詞の「くて」は付かない。で形「十分で」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "十分", "is_correct": true, "explanation": "連用形の語幹。「十分に休まない」の「に」の前に入る形。"}, {"text": "十分な", "is_correct": false, "explanation": "連体形。「十分な休まない」は文法的に続かない。"}, {"text": "十分だった", "is_correct": false, "explanation": "過去形。「十分だった休まない」は続かない。"}, {"text": "十分ではない", "is_correct": false, "explanation": "否定形。「十分ではない休まない」は続かない。"}], "correct_form": "十分", "base_form": "十分", "form_label": "連用形", "sentence_index": 1, "explanations": {"十分": "連用形の語幹。「十分に休まない」の「に」の前に入る形。", "十分な": "連体形。「十分な休まない」は文法的に続かない。", "十分だった": "過去形。「十分だった休まない」は続かない。", "十分ではない": "否定形。「十分ではない休まない」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38601, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資料は十分を用意できたので、会議を始めよう。", "corrected_sentence": "資料は十分に用意できたので、会議を始めよう。", "error_description": "「十分」が動詞「用意できた」の前に来るときは連用形「十分に」。「十分を」と格助詞「を」を付けたのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "十分な", "is_correct": true, "explanation": "連体形。「十分な経験」のように名詞を修飾する形で、文の「十分な」に合う。"}, {"text": "十分だ", "is_correct": false, "explanation": "終止形。名詞の前に置けず、「十分だ経験」は成り立たない。"}, {"text": "十分さ", "is_correct": false, "explanation": "名詞化した「十分さ」。「経験」を直接修飾できず、「十分さ経験」は成り立たない。"}, {"text": "十分だった", "is_correct": false, "explanation": "過去形。「十分だった経験」は過去の経験を指し、現在の経験の文と時制が合わない。"}], "correct_form": "十分な", "base_form": "十分", "form_label": "連体形", "sentence_index": 7, "explanations": {"十分な": "連体形。「十分な経験」のように名詞を修飾する形で、文の「十分な」に合う。", "十分だ": "終止形。名詞の前に置けず、「十分だ経験」は成り立たない。", "十分さ": "名詞化した「十分さ」。「経験」を直接修飾できず、「十分さ経験」は成り立たない。", "十分だった": "過去形。「十分だった経験」は過去の経験を指し、現在の経験の文と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
