INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38602, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が、いたところにもう一度行くということです。", "primary_collocate": null, "pronunciation": "もどる", "ipa": "modoɾɯ", "syllable_count": 3, "sentences": [{"text": "忘れ物をしたので、急いで家に戻った。", "target_word": "戻った", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]をしたので、急[いそ]いで家[いえ]に戻[もど]った。", "sentence_source": "generated"}, {"text": "財布を取りに、すぐ教室に戻ります。", "target_word": "戻ります", "complexity_tier": "T3", "furigana": "財布[さいふ]を取[と]りに、すぐ教室[きょうしつ]に戻[もど]ります。", "sentence_source": "generated"}, {"text": "母は買い物から戻ると、すぐ夕飯を作り始めた。", "target_word": "戻ると", "complexity_tier": "T3", "furigana": "母[はは]は買[か]い物[もの]から戻[もど]ると、すぐ夕飯[ゆうはん]を作[つく]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "雨が強くなってきたから、ホテルに戻ろう。", "target_word": "戻ろう", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなってきたから、ホテルに戻[もど]ろう。", "sentence_source": "generated"}, {"text": "兄は東京で働いたあと、生まれた町に戻って来た。", "target_word": "戻って", "complexity_tier": "T3", "furigana": "兄[あに]は東京[とうきょう]で働[はたら]いたあと、生[う]まれた町[まち]に戻[もど]って来[き]た。", "sentence_source": "generated"}, {"text": "先生は五分後に職員室へ戻ると言っていた。", "target_word": "戻る", "complexity_tier": "T3", "furigana": "先生[せんせい]は五分後[ごふんご]に職員室[しょくいんしつ]へ戻[もど]ると言[い]っていた。", "sentence_source": "generated"}, {"text": "道を間違えたので、駅まで戻らなければならない。", "target_word": "戻らなければ", "complexity_tier": "T3", "furigana": "道[みち]を間違[まちが]えたので、駅[えき]まで戻[もど]らなければならない。", "sentence_source": "generated"}, {"text": "彼は十時までに寮に戻れば、怒られない。", "target_word": "戻れば", "complexity_tier": "T3", "furigana": "彼[かれ]は十時[じゅうじ]までに寮[りょう]に戻[もど]れば、怒[おこ]られない。", "sentence_source": "generated"}, {"text": "祖父は散歩に出て、三十分ほどで戻ってきた。", "target_word": "戻ってきた", "complexity_tier": "T3", "furigana": "祖父[そふ]は散歩[さんぽ]に出[で]て、三十分[さんじゅっぷん]ほどで戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "山で道に迷ったが、日が暮れる前に小屋へ戻れた。", "target_word": "戻れた", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]ったが、日[ひ]が暮[く]れる前[まえ]に小屋[こや]へ戻[もど]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戻る", "label": "辞書形"}, {"form": "戻ります", "label": "丁寧形"}, {"form": "戻らない", "label": "否定形"}, {"form": "戻った", "label": "過去形"}, {"form": "戻って", "label": "て形"}, {"form": "戻れば", "label": "仮定形"}, {"form": "戻ろう", "label": "意向形"}, {"form": "戻れる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "人が、いた場所へもう一度行く・帰る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戻った", "is_correct": true, "explanation": "「戻る」の過去形。「家に戻った」の動作を表し、文の流れに合う。"}, {"text": "眺めた", "is_correct": false, "explanation": "「眺める」は見渡す動作。「家に眺めた」は場所への移動を表せない。"}, {"text": "片付けた", "is_correct": false, "explanation": "「片付ける」は整理する動作。「家に片付けた」は文が成り立たない。"}, {"text": "買った", "is_correct": false, "explanation": "「買う」は入手する動作。「家に買った」は助詞「に」と合わず、移動の文にならない。"}], "explanations": {"戻った": "「戻る」の過去形。「家に戻った」の動作を表し、文の流れに合う。", "眺めた": "「眺める」は見渡す動作。「家に眺めた」は場所への移動を表せない。", "片付けた": "「片付ける」は整理する動作。「家に片付けた」は文が成り立たない。", "買った": "「買う」は入手する動作。「家に買った」は助詞「に」と合わず、移動の文にならない。"}, "sentence_index": 0, "correct_answer": "戻った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "初めて戻る町は、道がわからず不安だ。", "explanation": "ここは〈行く〉の意味。戻るは以前いた場所への再訪なので、初めて行く町には使わない。"}, {"text": "その村には、生まれて初めて戻った。", "explanation": "〈初めて行く〉の意味。戻るは以前いた場所への再訪なので、生まれて初めての場所には使わない。"}, {"text": "彼女は今日、初めて入った店に戻った。", "explanation": "〈入る〉（初めて店に入る）の意味。戻るは以前いた場所への再訪なので、初めて入る店には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戻らなければ", "is_correct": true, "explanation": "「戻る」の未然形＋「なければ」。「駅まで戻らなければならない」の義務を表す。"}, {"text": "眠らなければ", "is_correct": false, "explanation": "「眠る」は寝る動作。「駅まで眠らなければ」は文が成り立たない。"}, {"text": "研究しなければ", "is_correct": false, "explanation": "「研究する」は調べる行為。「駅まで研究」は場所の移動の文に合わない。"}, {"text": "点検しなければ", "is_correct": false, "explanation": "「点検する」は調べる行為。「駅まで点検」は移動の意味に合わない。"}], "explanations": {"戻らなければ": "「戻る」の未然形＋「なければ」。「駅まで戻らなければならない」の義務を表す。", "眠らなければ": "「眠る」は寝る動作。「駅まで眠らなければ」は文が成り立たない。", "研究しなければ": "「研究する」は調べる行為。「駅まで研究」は場所の移動の文に合わない。", "点検しなければ": "「点検する」は調べる行為。「駅まで点検」は移動の意味に合わない。"}, "sentence_index": 6, "correct_answer": "戻らなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い登山の末、ついに山頂に戻った。", "explanation": "〈着く〉の意味。戻るは以前いた場所への再訪なので、初めて着いた山頂には使わない。"}, {"text": "彼は一度も行ったことのない展望台に、何度も戻った。", "explanation": "〈訪れる〉（初めて行く）の意味。戻るは以前いた場所への再訪なので、行ったことのない展望台には使わない。"}, {"text": "彼は子どもの頃、住んだことのない海外へ戻った。", "explanation": "〈行く〉の意味。戻るは以前いた場所への再訪なので、一度もいたことのない海外には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鍵を忘れたので、もう一度事務所を戻った。", "corrected_sentence": "鍵を忘れたので、もう一度事務所に戻った。", "error_description": "「戻る」は移動先を「に」で示す。「を」は他動詞の目的語に使う助詞なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戻ります", "is_correct": true, "explanation": "丁寧形。「すぐ教室に戻ります」と予定を述べる文に合う。"}, {"text": "戻らない", "is_correct": false, "explanation": "否定形。戻るのを打ち消す意味になり、取りに行く流れと合わない。"}, {"text": "戻れ", "is_correct": false, "explanation": "命令形。話し手自身の行動を述べる文に入れると命令になり、文が不自然になる。"}, {"text": "戻れる", "is_correct": false, "explanation": "可能形。「戻ることができる」の意味になり、文の意図と合わない。"}], "correct_form": "戻ります", "base_form": "戻る", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"戻ります": "丁寧形。「すぐ教室に戻ります」と予定を述べる文に合う。", "戻らない": "否定形。戻るのを打ち消す意味になり、取りに行く流れと合わない。", "戻れ": "命令形。話し手自身の行動を述べる文に入れると命令になり、文が不自然になる。", "戻れる": "可能形。「戻ることができる」の意味になり、文の意図と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38602, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は三十分後に戻ってきるだろう。", "corrected_sentence": "祖父は三十分後に戻ってくるだろう。", "error_description": "補助動詞「くる」の活用の誤り。「戻ってきる」は「きる」と書いた誤りで、正しくは「戻ってくる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戻れば", "is_correct": true, "explanation": "仮定形。「戻れば、怒られない」の条件を表す形。"}, {"text": "戻ろう", "is_correct": false, "explanation": "意向形。「寮に戻ろう、怒られない」は文が続かない。"}, {"text": "戻る", "is_correct": false, "explanation": "辞書形。「寮に戻る、怒られない」は条件の接続にならず不自然。"}, {"text": "戻りました", "is_correct": false, "explanation": "丁寧過去形。「寮に戻りました、怒られない」は文が続かない。"}], "correct_form": "戻れば", "base_form": "戻る", "form_label": "仮定形", "sentence_index": 7, "explanations": {"戻れば": "仮定形。「戻れば、怒られない」の条件を表す形。", "戻ろう": "意向形。「寮に戻ろう、怒られない」は文が続かない。", "戻る": "辞書形。「寮に戻る、怒られない」は条件の接続にならず不自然。", "戻りました": "丁寧過去形。「寮に戻りました、怒られない」は文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「元に戻る」の「に」。回復した先の状態を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主格。「元が戻りました」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的格。戻るは目的語を取らないので「元を戻りました」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段。「元で戻りました」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「元に戻る」の「に」。回復した先の状態を示す格助詞。", "が": "主格。「元が戻りました」は意味が通らない。", "を": "目的格。戻るは目的語を取らないので「元を戻りました」は成り立たない。", "で": "場所・手段。「元で戻りました」は文が成り立たない。"}, "error_tags": {"が": "主格", "を": "目的格", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所から、もとの場所や状態にもう一度移動すること。", "primary_collocate": null, "pronunciation": "もどる", "ipa": "modoɾɯ", "syllable_count": 3, "sentences": [{"text": "休みが終わって、普段の生活に戻った。", "target_word": "戻った", "complexity_tier": "T3", "furigana": "休[やす]みが終[お]わって、普段[ふだん]の生活[せいかつ]に戻[もど]った。", "sentence_source": "generated"}, {"text": "熱が下がって、体調がやっと元に戻りました。", "target_word": "戻りました", "complexity_tier": "T3", "furigana": "熱[ねつ]が下[さ]がって、体調[たいちょう]がやっと元[もと]に戻[もど]りました。", "sentence_source": "generated"}, {"text": "散歩のあと、犬は自分の小屋に戻った。", "target_word": "戻った", "complexity_tier": "T3", "furigana": "散歩[さんぽ]のあと、犬[いぬ]は自分[じぶん]の小屋[こや]に戻[もど]った。", "sentence_source": "generated"}, {"text": "電話を切って、すぐ席に戻ると、会議が始まっていた。", "target_word": "戻ると", "complexity_tier": "T3", "furigana": "電話[でんわ]を切[き]って、すぐ席[せき]に戻[もど]ると、会議[かいぎ]が始[はじ]まっていた。", "sentence_source": "generated"}, {"text": "一度縮んだセーターは、洗っても元の形に戻らない。", "target_word": "戻らない", "complexity_tier": "T3", "furigana": "一度[いちど]縮[ちぢ]んだセーターは、洗[あら]っても元[もと]の形[かたち]に戻[もど]らない。", "sentence_source": "generated"}, {"text": "雨がやんで、川の水は元の高さに戻った。", "target_word": "戻った", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで、川[かわ]の水[みず]は元[もと]の高[たか]さに戻[もど]った。", "sentence_source": "generated"}, {"text": "話が横道にそれたので、本題に戻りましょう。", "target_word": "戻りましょう", "complexity_tier": "T3", "furigana": "話[はなし]が横道[よこみち]にそれたので、本題[ほんだい]に戻[もど]りましょう。", "sentence_source": "generated"}, {"text": "出張から会社に戻ったら、机の上に手紙があった。", "target_word": "戻ったら", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]から会社[かいしゃ]に戻[もど]ったら、机[つくえ]の上[うえ]に手紙[てがみ]があった。", "sentence_source": "generated"}, {"text": "春になると、渡り鳥は北の森へ戻ってくる。", "target_word": "戻ってくる", "complexity_tier": "T3", "furigana": "春[はる]になると、渡[わた]り鳥[どり]は北[きた]の森[もり]へ戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "風邪が治れば、また元気な姿に戻れるはずだ。", "target_word": "戻れる", "complexity_tier": "T3", "furigana": "風邪[かぜ]が治[なお]れば、また元気[げんき]な姿[すがた]に戻[もど]れるはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戻る", "label": "辞書形"}, {"form": "戻ります", "label": "丁寧形"}, {"form": "戻らない", "label": "否定形"}, {"form": "戻った", "label": "過去形"}, {"form": "戻って", "label": "て形"}, {"form": "戻れば", "label": "仮定形"}, {"form": "戻りましょう", "label": "丁寧な意向形"}, {"form": "戻れる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "もとの場所や状態にもう一度移る・帰る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 治れ (Zipf 2.34)']::text[], '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戻った", "is_correct": true, "explanation": "過去形。「普段の生活に戻った」の「もとの状態に再び移る」の意味に合う。"}, {"text": "壊した", "is_correct": false, "explanation": "「壊す」は破損させる動作。「生活に壊した」は意味が通らない。"}, {"text": "眺めた", "is_correct": false, "explanation": "「眺める」は見渡す動作。「生活に眺めた」は文が成り立たない。"}, {"text": "買った", "is_correct": false, "explanation": "「買う」は入手する動作。「生活に買った」は意味が通らない。"}], "explanations": {"戻った": "過去形。「普段の生活に戻った」の「もとの状態に再び移る」の意味に合う。", "壊した": "「壊す」は破損させる動作。「生活に壊した」は意味が通らない。", "眺めた": "「眺める」は見渡す動作。「生活に眺めた」は文が成り立たない。", "買った": "「買う」は入手する動作。「生活に買った」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "戻った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の日程を変更したので、日程は新しい案に戻った。", "explanation": "〈変更する〉の意味。戻るは前にあった状態への回帰なので、新しく決めた案には使わない。"}, {"text": "研究は予定どおり戻った。", "explanation": "〈進む〉の意味。戻るは元の状態への逆行なので、順調な進行を表す文には合わない。"}, {"text": "その選手は、初めての試合でいきなり新しい記録に戻った。", "explanation": "〈達する〉の意味。戻るは前にあった状態への回帰なので、初めて達した新記録には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戻りましょう", "is_correct": true, "explanation": "意向形（丁寧）。「本題に戻りましょう」と話題を戻す提案の文に合う。"}, {"text": "踊りましょう", "is_correct": false, "explanation": "「踊る」は体を動かす行為。「本題に踊りましょう」は意味が通らない。"}, {"text": "食べましょう", "is_correct": false, "explanation": "「食べる」は飲食の動作。「本題に食べましょう」は文が成り立たない。"}, {"text": "洗いましょう", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作。「本題に洗いましょう」は意味が通らない。"}], "explanations": {"戻りましょう": "意向形（丁寧）。「本題に戻りましょう」と話題を戻す提案の文に合う。", "踊りましょう": "「踊る」は体を動かす行為。「本題に踊りましょう」は意味が通らない。", "食べましょう": "「食べる」は飲食の動作。「本題に食べましょう」は文が成り立たない。", "洗いましょう": "「洗う」は汚れを落とす動作。「本題に洗いましょう」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "戻りましょう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国の技術は、年々新しい水準に戻っている。", "explanation": "〈進歩する〉の意味。戻るは元の状態への回帰なので、新しい水準へ進む文には合わない。"}, {"text": "引っ越しで、家族は初めての町に戻った。", "explanation": "〈移る〉の意味。戻るは以前いた場所へ再び移ることなので、初めての町には使わない。"}, {"text": "会社の方針が変わったので、彼は新しい部署に戻った。", "explanation": "〈異動する〉の意味。戻るは以前いた場所へ再び移ることなので、初めての部署には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬を飲んだら、熱が下がって元の体調を戻った。", "corrected_sentence": "薬を飲んだら、熱が下がって元の体調に戻った。", "error_description": "「戻る」は回復先を「に」で示す。「を」を付けたのは、他動詞の目的語の形と混同した誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "戻りました", "is_correct": true, "explanation": "丁寧過去形。「やっと元に戻りました」と回復を述べる形。"}, {"text": "戻れば", "is_correct": false, "explanation": "仮定形。「やっと元に戻れば」は文が途中で切れる。"}, {"text": "戻ろう", "is_correct": false, "explanation": "意向形。話し手の意志を表し、回復した事実の文と合わない。"}, {"text": "戻って", "is_correct": false, "explanation": "て形。「やっと元に戻って」は文が完結しない。"}], "correct_form": "戻りました", "base_form": "戻る", "form_label": "丁寧過去形", "sentence_index": 1, "explanations": {"戻りました": "丁寧過去形。「やっと元に戻りました」と回復を述べる形。", "戻れば": "仮定形。「やっと元に戻れば」は文が途中で切れる。", "戻ろう": "意向形。話し手の意志を表し、回復した事実の文と合わない。", "戻って": "て形。「やっと元に戻って」は文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38603, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "片付けが終わったら、みんなは席に戻てください。", "corrected_sentence": "片付けが終わったら、みんなは席に戻ってください。", "error_description": "て形は「戻って」。「戻て」と促音「っ」を落とした誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "戻ったら", "is_correct": true, "explanation": "仮定形（〜たら）。「会社に戻ったら、手紙があった」と条件を述べる形。"}, {"text": "戻らない", "is_correct": false, "explanation": "否定形。「会社に戻らない、机の上に」は文が続かない。"}, {"text": "戻りたい", "is_correct": false, "explanation": "願望形。「会社に戻りたい、机の上に手紙があった」は続かず、不自然になる。"}, {"text": "戻れる", "is_correct": false, "explanation": "可能形。「戻れる、机の上に」は文の意味が合わない。"}], "correct_form": "戻ったら", "base_form": "戻る", "form_label": "仮定形（〜たら）", "sentence_index": 7, "explanations": {"戻ったら": "仮定形（〜たら）。「会社に戻ったら、手紙があった」と条件を述べる形。", "戻らない": "否定形。「会社に戻らない、机の上に」は文が続かない。", "戻りたい": "願望形。「会社に戻りたい、机の上に手紙があった」は続かず、不自然になる。", "戻れる": "可能形。「戻れる、机の上に」は文の意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れる」の目的語を示す助詞で、とうもろこしを入れる形になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「入れる」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「とうもろこしに入れた」では入れる対象として成り立たず、文が不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、「とうもろこしで入れた」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「入れる」の目的語を示す助詞で、とうもろこしを入れる形になる。", "が": "主語を示す助詞で、「入れる」の目的語にはならない。", "に": "「とうもろこしに入れた」では入れる対象として成り立たず、文が不自然になる。", "で": "手段や場所を示す助詞で、「とうもろこしで入れた」では意味が通らない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべものになる、きいろいみがなるしょくぶつです。", "primary_collocate": null, "pronunciation": "とうもろこし", "ipa": "toːmoɾokoɕi", "syllable_count": 6, "sentences": [{"text": "夏になると、畑のとうもろこしが大きく育つ。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "夏[なつ]になると、畑[はたけ]のとうもろこしが大[おお]きく育[そだ]つ。", "sentence_source": "generated"}, {"text": "母がゆでたとうもろこしは、甘くておいしかった。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "母[はは]がゆでたとうもろこしは、甘[あま]くておいしかった。", "sentence_source": "generated"}, {"text": "祭りで、焼いたとうもろこしを一本買った。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "祭[まつ]りで、焼[や]いたとうもろこしを一本[いっぽん]買[か]った。", "sentence_source": "generated"}, {"text": "とうもろこしの実は黄色くて、小さな粒が並んでいる。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "とうもろこしの実[み]は黄色[きいろ]くて、小[ちい]さな粒[つぶ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "農家の人が、朝とうもろこしを収穫していた。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]が、朝[あさ]とうもろこしを収穫[しゅうかく]していた。", "sentence_source": "generated"}, {"text": "子どものころ、祖母の庭でとうもろこしを育てた。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "子[こ]どものころ、祖母[そぼ]の庭[にわ]でとうもろこしを育[そだ]てた。", "sentence_source": "generated"}, {"text": "とうもろこしの皮をむくと、中から黄色い実が出てきた。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "とうもろこしの皮[かわ]をむくと、中[なか]から黄色[きいろ]い実[み]が出[で]てきた。", "sentence_source": "generated"}, {"text": "スープにとうもろこしを入れたら、甘みが出ておいしくなった。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "スープにとうもろこしを入[い]れたら、甘[あま]みが出[で]ておいしくなった。", "sentence_source": "generated"}, {"text": "弟はとうもろこしが好きで、毎年夏に何本も食べる。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "弟[おとうと]はとうもろこしが好[す]きで、毎年[まいとし]夏[なつ]に何本[なんぼん]も食[た]べる。", "sentence_source": "generated"}, {"text": "市場で、とれたてのとうもろこしを安く売っていた。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "市場[いちば]で、とれたてのとうもろこしを安[やす]く売[う]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "とうもろこし", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "黄色い実を食べる、夏の野菜としてのとうもろこし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "とうもろこし", "is_correct": true, "explanation": "畑で育ち、夏に大きくなる作物の名前なので文に合う。"}, {"text": "花火", "is_correct": false, "explanation": "夏の夜に打ち上げるもので、畑で大きく育つものではない。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物で、畑で大きく育つものではない。"}, {"text": "教科書", "is_correct": false, "explanation": "学校で使う本で、畑で大きく育つものではない。"}], "explanations": {"とうもろこし": "畑で育ち、夏に大きくなる作物の名前なので文に合う。", "花火": "夏の夜に打ち上げるもので、畑で大きく育つものではない。", "電車": "線路を走る乗り物で、畑で大きく育つものではない。", "教科書": "学校で使う本で、畑で大きく育つものではない。"}, "sentence_index": 0, "correct_answer": "とうもろこし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "とうもろこしは、土を掘って根を収穫する。", "explanation": "ここは〈さつまいも〉の意味。土を掘って根を収穫するのはさつまいもで、とうもろこしは実を茎からもいで収穫するので合わない。"}, {"text": "とうもろこしは、田んぼに水を張って苗を植える。", "explanation": "ここは〈米〉の意味。田んぼに水を張って苗を植えるのは米で、とうもろこしは畑に種をまくので合わない。"}, {"text": "とうもろこしは、房ごと搾ってワインにする。", "explanation": "ここは〈ぶどう〉の意味。房ごと搾ってワインにするのはぶどうで、とうもろこしでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "とうもろこし", "is_correct": true, "explanation": "皮をむくと黄色い実が出てくる野菜なので文に合う。"}, {"text": "水道", "is_correct": false, "explanation": "蛇口から水を出す設備で、皮をむくものではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、皮をむくものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文字を書く道具で、皮をむくものではない。"}], "explanations": {"とうもろこし": "皮をむくと黄色い実が出てくる野菜なので文に合う。", "水道": "蛇口から水を出す設備で、皮をむくものではない。", "冷蔵庫": "食品を冷やす家電で、皮をむくものではない。", "鉛筆": "文字を書く道具で、皮をむくものではない。"}, "sentence_index": 6, "correct_answer": "とうもろこし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ごはんは、とうもろこしを研いでから炊く。", "explanation": "ここは〈米〉の意味。研いでから炊くのは米で、とうもろこしは研がないので合わない。"}, {"text": "うどんは、とうもろこしを水で練って打つ。", "explanation": "ここは〈小麦粉〉の意味。水で練って打つのは小麦粉で、とうもろこしでは合わない。"}, {"text": "梅干しは、とうもろこしを塩に漬けて作る。", "explanation": "ここは〈梅〉の意味。塩に漬けて作る梅干しは梅から作るので、とうもろこしでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの屋台で、焼いたとうもろこしが二本買った。", "corrected_sentence": "祭りの屋台で、焼いたとうもろこしを二本買った。", "error_description": "誤りは「とうもろこし」に続く助詞。「買う」の目的語を示すには「を」を使うので、「が」を「を」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、畑で採れたとうもろこしに茹でて食べた。", "corrected_sentence": "夕方、畑で採れたとうもろこしを茹でて食べた。", "error_description": "誤りは「とうもろこし」に続く助詞。「茹でる」の目的語には「を」を使うので、「に」を「を」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
