INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38605, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「とうもろこしの生産量」と、生産量の所属を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「とうもろこしを生産量」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「とうもろこしに生産量が」では結び付かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「とうもろこしへ生産量が」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「とうもろこしの生産量」と、生産量の所属を示す。", "を": "目的語を示す助詞で、「とうもろこしを生産量」では文が成り立たない。", "に": "「とうもろこしに生産量が」では結び付かず、文が成り立たない。", "へ": "方向を示す助詞で、「とうもろこしへ生産量が」では意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38605, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "トウモロコシのこと。イネ科の一年草で、実は食用や飼料、工業原料などに使われる。", "primary_collocate": null, "pronunciation": "とうもろこし", "ipa": "toːmoɾokoɕi", "syllable_count": 6, "sentences": [{"text": "とうもろこしはイネ科の一年草で、春に種をまく。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "とうもろこしはイネ科[か]の一年草[いちねんそう]で、春[はる]に種[たね]をまく。", "sentence_source": "generated"}, {"text": "とうもろこしは、牛や豚の飼料としても世界中で使われている。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "とうもろこしは、牛[うし]や豚[ぶた]の飼料[しりょう]としても世界中[せかいじゅう]で使[つか]われている。", "sentence_source": "generated"}, {"text": "この国では、とうもろこしから作った油が食卓に並ぶ。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "この国[くに]では、とうもろこしから作[つく]った油[あぶら]が食卓[しょくたく]に並[なら]ぶ。", "sentence_source": "generated"}, {"text": "とうもろこしは、燃料や接着剤などの工業原料にもなる。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "とうもろこしは、燃料[ねんりょう]や接着剤[せっちゃくざい]などの工業原料[こうぎょうげんりょう]にもなる。", "sentence_source": "generated"}, {"text": "輸入されるとうもろこしの多くは、家畜のえさに回される。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "輸入[ゆにゅう]されるとうもろこしの多[おお]くは、家畜[かちく]のえさに回[まわ]される。", "sentence_source": "generated"}, {"text": "とうもろこしの価格が上がると、肉の値段にも影響が出る。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "とうもろこしの価格[かかく]が上[あ]がると、肉[にく]の値段[ねだん]にも影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "とうもろこしの茎は二メートル以上に伸び、先に花がつく。", "target_word": "とうもろこし", "complexity_tier": "T3", "furigana": "とうもろこしの茎[くき]は二[に]メートル以上[いじょう]に伸[の]び、先[さき]に花[はな]がつく。", "sentence_source": "generated"}, {"text": "世界では、とうもろこしの生産量が米や小麦と並んで多い。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "世界[せかい]では、とうもろこしの生産量[せいさんりょう]が米[こめ]や小麦[こむぎ]と並[なら]んで多[おお]い。", "sentence_source": "generated"}, {"text": "とうもろこしのでんぷんは、食品や紙の製造にも利用される。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "とうもろこしのでんぷんは、食品[しょくひん]や紙[かみ]の製造[せいぞう]にも利用[りよう]される。", "sentence_source": "generated"}, {"text": "とうもろこしを原料にした燃料は、環境に優しいと言われる。", "target_word": "とうもろこし", "complexity_tier": "T4", "furigana": "とうもろこしを原料[げんりょう]にした燃料[ねんりょう]は、環境[かんきょう]に優[やさ]しいと言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "とうもろこし", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "イネ科の一年草で、食用・飼料・工業原料になる作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "とうもろこし", "is_correct": true, "explanation": "イネ科の一年草で春に種をまく作物なので文に合う。"}, {"text": "花火", "is_correct": false, "explanation": "夏の夜に打ち上げるもので、種をまく植物ではない。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物で、種をまく植物ではない。"}, {"text": "教科書", "is_correct": false, "explanation": "学校で使う本で、種をまく植物ではない。"}], "explanations": {"とうもろこし": "イネ科の一年草で春に種をまく作物なので文に合う。", "花火": "夏の夜に打ち上げるもので、種をまく植物ではない。", "電車": "線路を走る乗り物で、種をまく植物ではない。", "教科書": "学校で使う本で、種をまく植物ではない。"}, "sentence_index": 0, "correct_answer": "とうもろこし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "とうもろこしは、山で切り出して柱にする。", "explanation": "ここは〈木材〉の意味。山で切り出して柱にするのは木材で、とうもろこしでは合わない。"}, {"text": "とうもろこしは、糸に紡いで布を織る。", "explanation": "ここは〈綿〉の意味。糸に紡いで布を織るのは綿で、とうもろこしでは合わない。"}, {"text": "とうもろこしは、麹で長く醸して調味料にする。", "explanation": "ここは〈醤油〉の意味。麹で長く醸して仕込むのは醤油で、とうもろこしでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "とうもろこし", "is_correct": true, "explanation": "二メートル以上に伸び、先に花がつく植物の名前なので文に合う。"}, {"text": "水道", "is_correct": false, "explanation": "蛇口から水を出す設備で、茎が伸びるものではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、茎が伸びるものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文字を書く道具で、茎が伸びるものではない。"}], "explanations": {"とうもろこし": "二メートル以上に伸び、先に花がつく植物の名前なので文に合う。", "水道": "蛇口から水を出す設備で、茎が伸びるものではない。", "冷蔵庫": "食品を冷やす家電で、茎が伸びるものではない。", "鉛筆": "文字を書く道具で、茎が伸びるものではない。"}, "sentence_index": 6, "correct_answer": "とうもろこし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "とうもろこしは、高温で溶かして板にする。", "explanation": "ここは〈ガラス〉の意味。高温で溶かして板にするのはガラスで、とうもろこしでは合わない。"}, {"text": "とうもろこしは、発酵させてチーズを作る。", "explanation": "ここは〈牛乳〉の意味。発酵させてチーズを作るのは牛乳で、とうもろこしでは合わない。"}, {"text": "建物の骨組みは、とうもろこしを溶接して組む。", "explanation": "ここは〈鉄〉の意味。溶接して骨組みを組むのは鉄で、とうもろこしでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
