INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38606, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ジャガイモは、土の中で育つ、食べ物になる野菜です。", "primary_collocate": null, "pronunciation": "じゃがいも", "ipa": "dʑaɡaimo", "syllable_count": 4, "sentences": [{"text": "ジャガイモは土の中で育つので、掘って収穫する。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "ジャガイモは土[つち]の中[なか]で育[そだ]つので、掘[ほ]って収穫[しゅうかく]する。", "sentence_source": "generated"}, {"text": "今夜はカレーに入れるジャガイモを三つ切った。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "今夜[こんや]はカレーに入[い]れるジャガイモを三[みっ]つ切[き]った。", "sentence_source": "generated"}, {"text": "祖父の畑で、大きなジャガイモがたくさんとれた。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "祖父[そふ]の畑[はたけ]で、大[おお]きなジャガイモがたくさんとれた。", "sentence_source": "generated"}, {"text": "ジャガイモの皮をむいて、水に入れておいた。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "ジャガイモの皮[かわ]をむいて、水[みず]に入[い]れておいた。", "sentence_source": "generated"}, {"text": "母はゆでたジャガイモにバターをのせてくれた。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "母[はは]はゆでたジャガイモにバターをのせてくれた。", "sentence_source": "generated"}, {"text": "ジャガイモを油で揚げると、ポテトフライになる。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "ジャガイモを油[あぶら]で揚[あ]げると、ポテトフライになる。", "sentence_source": "generated"}, {"text": "芽が出たジャガイモは、そのまま食べないほうがいい。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "芽[め]が出[で]たジャガイモは、そのまま食[た]べないほうがいい。", "sentence_source": "generated"}, {"text": "秋になると、学校の畑でジャガイモを掘る。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "秋[あき]になると、学校[がっこう]の畑[はたけ]でジャガイモを掘[ほ]る。", "sentence_source": "generated"}, {"text": "兄は朝ごはんにジャガイモの味噌汁を作った。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "兄[あに]は朝[あさ]ごはんにジャガイモの味噌汁[みそしる]を作[つく]った。", "sentence_source": "generated"}, {"text": "店で、土のついたジャガイモが袋に入って売られていた。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "店[みせ]で、土[つち]のついたジャガイモが袋[ふくろ]に入[はい]って売[う]られていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジャガイモ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "土の中で育つ、料理に使う身近な野菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38606, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジャガイモ", "is_correct": true, "explanation": "土の中で育って掘り出す野菜の名前なので文に合う。"}, {"text": "水道", "is_correct": false, "explanation": "蛇口から水を出す設備で、土の中で育つものではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、土の中で育つものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文字を書く道具で、土の中で育つものではない。"}], "explanations": {"ジャガイモ": "土の中で育って掘り出す野菜の名前なので文に合う。", "水道": "蛇口から水を出す設備で、土の中で育つものではない。", "冷蔵庫": "食品を冷やす家電で、土の中で育つものではない。", "鉛筆": "文字を書く道具で、土の中で育つものではない。"}, "sentence_index": 0, "correct_answer": "ジャガイモ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジャガイモは、海から摘んで干してシートにする。", "explanation": "ここは〈のり〉の意味。海から摘んで干してシートにするのはのりで、ジャガイモには合わない。"}, {"text": "ジャガイモは、黄身と白身を分けて泡立てる。", "explanation": "ここは〈卵〉の意味。黄身と白身を分けて泡立てるのは卵で、ジャガイモにはその部分がない。"}, {"text": "ジャガイモは、わたと軟骨を抜いてから切る。", "explanation": "ここは〈いか〉の意味。わたと軟骨を抜いてから切るのはいかで、ジャガイモには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38606, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジャガイモ", "is_correct": true, "explanation": "芽が出た状態で食べない方がよいとされる野菜の名前なので文に合う。"}, {"text": "花火", "is_correct": false, "explanation": "夏の夜に打ち上げるもので、芽が出るものではない。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物で、芽が出るものではない。"}, {"text": "教科書", "is_correct": false, "explanation": "学校で使う本で、芽が出るものではない。"}], "explanations": {"ジャガイモ": "芽が出た状態で食べない方がよいとされる野菜の名前なので文に合う。", "花火": "夏の夜に打ち上げるもので、芽が出るものではない。", "電車": "線路を走る乗り物で、芽が出るものではない。", "教科書": "学校で使う本で、芽が出るものではない。"}, "sentence_index": 6, "correct_answer": "ジャガイモ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジャガイモは、鍋で煮詰めてキャラメルにする。", "explanation": "ここは〈砂糖〉の意味。鍋で煮詰めてキャラメルにするのは砂糖で、ジャガイモでは作れない。"}, {"text": "おにぎりは、ジャガイモで包んで持ち歩く。", "explanation": "ここは〈ラップ〉の意味。包んで持ち歩くのに使うのはラップで、ジャガイモでは包めない。"}, {"text": "ジャガイモは、お湯に溶かして冷やし固める。", "explanation": "ここは〈ゼラチン〉の意味。お湯に溶かして冷やし固めるのはゼラチンで、ジャガイモでは固まらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38606, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ジャガイモを芽には毒があるので、食べないほうがいい。", "corrected_sentence": "ジャガイモの芽には毒があるので、食べないほうがいい。", "error_description": "誤りは「ジャガイモ」に続く助詞。「芽」を修飾する所属の関係は「の」で示すので、「を」を「の」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38606, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ジャガイモに、暗い場所で保存すると長持ちする。", "corrected_sentence": "ジャガイモは、暗い場所で保存すると長持ちする。", "error_description": "誤りは「ジャガイモ」に続く助詞。「保存する」の対象を示すには「を」か主題の「は」を使うので、「に」を「は」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ジャガイモの食用部分」と、食用部分の所属を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「ジャガイモを食用部分は」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ジャガイモに食用部分は」では結び付かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「ジャガイモへ食用部分は」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ジャガイモの食用部分」と、食用部分の所属を示す。", "を": "目的語を示す助詞で、「ジャガイモを食用部分は」では文が成り立たない。", "に": "「ジャガイモに食用部分は」では結び付かず、文が成り立たない。", "へ": "方向を示す助詞で、「ジャガイモへ食用部分は」では意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
