INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ジャガイモは、ナス科の多年草で、地下の茎が肥大した塊茎を食用とします。でんぷんが豊富で、料理の材料として広く使われます。", "primary_collocate": null, "pronunciation": "じゃがいも", "ipa": "dʑaɡaimo", "syllable_count": 4, "sentences": [{"text": "ジャガイモはナス科の多年草で、地下の茎が大きくなる。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモはナス科[か]の多年草[たねんそう]で、地下[ちか]の茎[くき]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "ジャガイモの食用部分は、根ではなく茎が肥大した塊茎だ。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモの食用部分[しょくようぶぶん]は、根[ね]ではなく茎[くき]が肥大[ひだい]した塊茎[かいけい]だ。", "sentence_source": "generated"}, {"text": "ジャガイモにはでんぷんが多く、片栗粉の原料にもなる。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモにはでんぷんが多[おお]く、片栗粉[かたくりこ]の原料[げんりょう]にもなる。", "sentence_source": "generated"}, {"text": "ジャガイモは冷涼な気候を好み、北海道が主な産地だ。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモは冷涼[れいりょう]な気候[きこう]を好[この]み、北海道[ほっかいどう]が主[おも]な産地[さんち]だ。", "sentence_source": "generated"}, {"text": "光に当たったジャガイモの皮は緑色になり、毒を含む。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "光[ひかり]に当[あ]たったジャガイモの皮[かわ]は緑色[みどりいろ]になり、毒[どく]を含[ふく]む。", "sentence_source": "generated"}, {"text": "ジャガイモは多くの国で、主食や料理の材料として使われる。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモは多[おお]くの国[くに]で、主食[しゅしょく]や料理[りょうり]の材料[ざいりょう]として使[つか]われる。", "sentence_source": "generated"}, {"text": "ジャガイモは種イモを植えて増やすのが一般的だ。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモは種[たね]イモを植[う]えて増[ふ]やすのが一般的[いっぱんてき]だ。", "sentence_source": "generated"}, {"text": "ジャガイモは、肉じゃがやコロッケなど和洋の料理に広く使われる。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモは、肉[にく]じゃがやコロッケなど和洋[わよう]の料理[りょうり]に広[ひろ]く使[つか]われる。", "sentence_source": "generated"}, {"text": "ジャガイモは保存性が高く、涼しい場所なら数か月もつ。", "target_word": "ジャガイモ", "complexity_tier": "T4", "furigana": "ジャガイモは保存性[ほぞんせい]が高[たか]く、涼[すず]しい場所[ばしょ]なら数[すう]か月[げつ]もつ。", "sentence_source": "generated"}, {"text": "ジャガイモの花が咲いたあと、地中でイモが大きく育つ。", "target_word": "ジャガイモ", "complexity_tier": "T3", "furigana": "ジャガイモの花[はな]が咲[さ]いたあと、地中[ちちゅう]でイモが大[おお]きく育[そだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジャガイモ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ナス科の多年草で、でんぷん豊富な塊茎を食用にする作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7caa4d5a-6180-4932-b081-6703e518e093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジャガイモ", "is_correct": true, "explanation": "ナス科の多年草で地下の茎が大きくなる作物の名前なので文に合う。"}, {"text": "花火", "is_correct": false, "explanation": "夏の夜に打ち上げるもので、ナス科の植物ではない。"}, {"text": "電車", "is_correct": false, "explanation": "線路を走る乗り物で、ナス科の植物ではない。"}, {"text": "教科書", "is_correct": false, "explanation": "学校で使う本で、ナス科の植物ではない。"}], "explanations": {"ジャガイモ": "ナス科の多年草で地下の茎が大きくなる作物の名前なので文に合う。", "花火": "夏の夜に打ち上げるもので、ナス科の植物ではない。", "電車": "線路を走る乗り物で、ナス科の植物ではない。", "教科書": "学校で使う本で、ナス科の植物ではない。"}, "sentence_index": 0, "correct_answer": "ジャガイモ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ジャガイモは、秋に種をまいて初夏に刈り取る。", "explanation": "ここは〈麦〉の意味。秋に種をまいて初夏に刈り取るのは麦で、ジャガイモは春に植える。"}, {"text": "ジャガイモは、外側の葉を一枚ずつはがして漬ける。", "explanation": "ここは〈白菜〉の意味。外側の葉をはがして漬けるのは白菜で、ジャガイモは葉を食べない。"}, {"text": "ジャガイモは、皮をむくと薄い層が重なっている。", "explanation": "ここは〈玉ねぎ〉の意味。薄い層が重なっているのは玉ねぎで、ジャガイモの中身は層にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジャガイモ", "is_correct": true, "explanation": "種イモを植えて増やす作物の名前なので文に合う。"}, {"text": "水道", "is_correct": false, "explanation": "蛇口から水を出す設備で、種イモを植えて増やすものではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、種イモを植えて増やすものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文字を書く道具で、種イモを植えて増やすものではない。"}], "explanations": {"ジャガイモ": "種イモを植えて増やす作物の名前なので文に合う。", "水道": "蛇口から水を出す設備で、種イモを植えて増やすものではない。", "冷蔵庫": "食品を冷やす家電で、種イモを植えて増やすものではない。", "鉛筆": "文字を書く道具で、種イモを植えて増やすものではない。"}, "sentence_index": 6, "correct_answer": "ジャガイモ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジャガイモは、赤く熟れた実から順にもぐ。", "explanation": "ここは〈トマト〉の意味。赤く熟れた実から順にもぐのはトマトで、ジャガイモは地中の芋を掘る。"}, {"text": "ジャガイモは、海から川を上ってくる。", "explanation": "ここは〈うなぎ〉の意味。海から川を上ってくるのはうなぎで、ジャガイモには合わない。"}, {"text": "ジャガイモは、さやの中で育ち、乾燥させて収穫する。", "explanation": "ここは〈小豆〉の意味。さやの中で育てて乾燥させて収穫するのは小豆で、ジャガイモの芋とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ジャガイモを芋は、地中で大きく育つ。", "corrected_sentence": "ジャガイモの芋は、地中で大きく育つ。", "error_description": "誤りは「ジャガイモ」に続く助詞。「芋」を修飾する所属の関係は「の」で示すので、「を」を「の」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ジャガイモを、日光に当たると皮が緑色になる。", "corrected_sentence": "ジャガイモは、日光に当たると皮が緑色になる。", "error_description": "誤りは「ジャガイモ」に続く助詞。文の主題を示すには「は」を使うので、「を」を「は」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c3f954-b639-4f0d-89b9-8026e448dca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「取り出して」の対象である牛乳を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、牛乳が取り出す主体になってしまい不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示すため、「牛乳に取り出す」とは言えない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すため、「牛乳で取り出す」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「取り出して」の対象である牛乳を示す格助詞。", "が": "主語を示すため、牛乳が取り出す主体になってしまい不自然。", "に": "方向や相手を示すため、「牛乳に取り出す」とは言えない。", "で": "手段や場所を示すため、「牛乳で取り出す」とは言えない。"}, "error_tags": {"が": "主格（主語）", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを物の中から外に出すこと。", "primary_collocate": null, "pronunciation": "とりだす", "ipa": "toɾidasɯ", "syllable_count": 4, "sentences": [{"text": "彼はかばんから財布を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "彼(かれ)はかばんから財布(さいふ)を取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "母は冷蔵庫から牛乳を取り出して、コップに注いだ。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "母(はは)は冷蔵庫(れいぞうこ)から牛乳(ぎゅうにゅう)を取(と)り出(だ)して、コップに注(そそ)いだ。", "sentence_source": "generated"}, {"text": "箱を開けて、中のケーキを取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "箱(はこ)を開(あ)けて、中(なか)のケーキを取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "オーブンからパンを取り出すときは、手袋をする。", "target_word": "取り出す", "complexity_tier": "T3", "furigana": "オーブンからパンを取(と)り出(だ)すときは、手袋(てぶくろ)をする。", "sentence_source": "generated"}, {"text": "ポケットからハンカチを取り出して、汗をふいた。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "ポケットからハンカチを取(と)り出(だ)して、汗(あせ)をふいた。", "sentence_source": "generated"}, {"text": "洗濯が終わったら、洗濯機から服を取り出す。", "target_word": "取り出す", "complexity_tier": "T3", "furigana": "洗濯(せんたく)が終(お)わったら、洗濯機(せんたくき)から服(ふく)を取(と)り出(だ)す。", "sentence_source": "generated"}, {"text": "机の奥から古い写真を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "机(つくえ)の奥(おく)から古(ふる)い写真(しゃしん)を取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "袋を破らないように、中の薬をそっと取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "袋(ふくろ)を破(やぶ)らないように、中(なか)の薬(くすり)をそっと取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "先生は封筒から紙を取り出して、みんなに配った。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "先生(せんせい)は封筒(ふうとう)から紙(かみ)を取(と)り出(だ)して、みんなに配(くば)った。", "sentence_source": "generated"}, {"text": "電池が切れたので、時計から電池を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "電池(でんち)が切(き)れたので、時計(とけい)から電池(でんち)を取(と)り出(だ)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り出す", "label": "終止形"}, {"form": "取り出した", "label": "過去形"}, {"form": "取り出して", "label": "て形"}, {"form": "取り出さない", "label": "否定形"}, {"form": "取り出せる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "入れ物や中身の中から物を外へ出す一般的な動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り出した", "is_correct": true, "explanation": "かばんの中から財布を外に出した、という文脈に合う。"}, {"text": "煮た", "is_correct": false, "explanation": "財布を煮るのは文脈に合わない。"}, {"text": "刻んだ", "is_correct": false, "explanation": "財布を細かく刻むのは文脈に合わない。"}, {"text": "注いだ", "is_correct": false, "explanation": "液体を容器に入れる動作で、財布には使わない。"}], "explanations": {"取り出した": "かばんの中から財布を外に出した、という文脈に合う。", "煮た": "財布を煮るのは文脈に合わない。", "刻んだ": "財布を細かく刻むのは文脈に合わない。", "注いだ": "液体を容器に入れる動作で、財布には使わない。"}, "sentence_index": 0, "correct_answer": "取り出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の枠に、新しい網戸を取り出した。", "explanation": "ここは〈取り付ける〉の意味。〈取り出す〉は中から外に出すことで、網戸をはめ込む意味にはならない。"}, {"text": "雨が降り出したので、庭に干した洗濯物を急いで取り出した。", "explanation": "ここは〈取り込む〉の意味。外のものを室内へ運ぶ動作で、中から外へ出す〈取り出す〉とは合わない。"}, {"text": "古くなった壁を取り出して、部屋を広く使えるようにした。", "explanation": "ここは〈取り払う〉の意味。壁などを取り除く動作で、中身を外に出す〈取り出す〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り出した", "is_correct": true, "explanation": "机の奥から写真を外に出した、という文脈に合う。"}, {"text": "茹でた", "is_correct": false, "explanation": "写真を茹でるのは文脈に合わない。"}, {"text": "練った", "is_correct": false, "explanation": "写真を練る動作は文脈に合わない。"}, {"text": "研いだ", "is_correct": false, "explanation": "刃物などを研ぐ動作で、写真には使わない。"}], "explanations": {"取り出した": "机の奥から写真を外に出した、という文脈に合う。", "茹でた": "写真を茹でるのは文脈に合わない。", "練った": "写真を練る動作は文脈に合わない。", "研いだ": "刃物などを研ぐ動作で、写真には使わない。"}, "sentence_index": 6, "correct_answer": "取り出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店にない本を、出版社から取り出して届けてもらった。", "explanation": "ここは〈取り寄せる〉の意味。取引先から物を取り寄せることで、中から外に出す〈取り出す〉とは合わない。"}, {"text": "保護施設から子猫を取り出して、家で育てることにした。", "explanation": "ここは〈引き取る〉の意味。引き受けて自分の家に迎えることで、中から外へ出す〈取り出す〉とは合わない。"}, {"text": "みんなで話し合って、新しいルールを取り出した。", "explanation": "ここは〈取り決める〉の意味。決めることで、物を外に出す〈取り出す〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は仏壇の引き出しから、古い鍵に取り出した。", "corrected_sentence": "祖母は仏壇の引き出しから、古い鍵を取り出した。", "error_description": "「取り出す」の対象には格助詞「を」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り出して", "is_correct": true, "explanation": "て形。「取り出して、コップに注いだ」と後ろの文に続く形で、文の流れに合う。"}, {"text": "取り出す", "is_correct": false, "explanation": "終止形。後ろの「コップに注いだ」に続けるには、て形が必要。"}, {"text": "取り出した", "is_correct": false, "explanation": "過去形。動作が完了した形で、「〜して、〜した」の流れを作れない。"}, {"text": "取り出さない", "is_correct": false, "explanation": "否定形。取り出さないという意味になり、文の内容と逆になる。"}], "correct_form": "取り出して", "base_form": "取り出す", "form_label": "て形", "sentence_index": 1, "explanations": {"取り出して": "て形。「取り出して、コップに注いだ」と後ろの文に続く形で、文の流れに合う。", "取り出す": "終止形。後ろの「コップに注いだ」に続けるには、て形が必要。", "取り出した": "過去形。動作が完了した形で、「〜して、〜した」の流れを作れない。", "取り出さない": "否定形。取り出さないという意味になり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは公園の砂場から、おもちゃに取り出して遊んでいた。", "corrected_sentence": "子どもたちは公園の砂場から、おもちゃを取り出して遊んでいた。", "error_description": "「取り出す」の対象には「を」が必要。「おもちゃに」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り出した", "is_correct": true, "explanation": "過去形。中の薬を外に出したという完了の意味で、文脈に合う。"}, {"text": "取り出し", "is_correct": false, "explanation": "連用形で、文を終えることができない。"}, {"text": "取り出さ", "is_correct": false, "explanation": "未然形だけでは文を終えることができない。"}, {"text": "取り出して", "is_correct": false, "explanation": "て形で文が終わらず、「した」の文として成り立たない。"}], "correct_form": "取り出した", "base_form": "取り出す", "form_label": "過去形", "sentence_index": 7, "explanations": {"取り出した": "過去形。中の薬を外に出したという完了の意味で、文脈に合う。", "取り出し": "連用形で、文を終えることができない。", "取り出さ": "未然形だけでは文を終えることができない。", "取り出して": "て形で文が終わらず、「した」の文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
