INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「部品だけ」を取り出す対象として示す格助詞。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すため、「部品だけと取り出した」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、取り出す対象の格としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する用法で、取り出す対象を示す形にはならない。"}], "correct_answer": "を", "explanations": {"を": "「部品だけ」を取り出す対象として示す格助詞。", "と": "並列や共同を示すため、「部品だけと取り出した」とは言えない。", "へ": "方向を示すため、取り出す対象の格としては成り立たない。", "の": "名詞を修飾する用法で、取り出す対象を示す形にはならない。"}, "error_tags": {"と": "並列・共同", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物の中から、必要な物を選んで外に出すこと。", "primary_collocate": null, "pronunciation": "とりだす", "ipa": "toɾidasɯ", "syllable_count": 4, "sentences": [{"text": "本棚から必要な本だけを取り出して、机に置いた。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "本棚(ほんだな)から必要(ひつよう)な本(ほん)だけを取(と)り出(だ)して、机(つくえ)に置(お)いた。", "sentence_source": "generated"}, {"text": "工具箱の中から、合うねじを選んで取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "工具箱(こうぐばこ)の中(なか)から、合(あ)うねじを選(えら)んで取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "山積みの書類から、今日の会議の資料を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "山積(やまづ)みの書類(しょるい)から、今日(きょう)の会議(かいぎ)の資料(しりょう)を取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "箱いっぱいのカードから、好きな一枚を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "箱(はこ)いっぱいのカードから、好(す)きな一枚(いちまい)を取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "薬箱から頭痛に効く薬を探して取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "薬箱(くすりばこ)から頭痛(ずつう)に効(き)く薬(くすり)を探(さが)して取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "たくさんの鍵の中から、玄関の鍵を取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "たくさんの鍵(かぎ)の中(なか)から、玄関(げんかん)の鍵(かぎ)を取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "彼は写真の山から、旅行の一枚だけを取り出す。", "target_word": "取り出す", "complexity_tier": "T3", "furigana": "彼(かれ)は写真(しゃしん)の山(やま)から、旅行(りょこう)の一枚(いちまい)だけを取(と)り出(だ)す。", "sentence_source": "generated"}, {"text": "壊れた機械の中から、使える部品だけを取り出した。", "target_word": "取り出した", "complexity_tier": "T3", "furigana": "壊(こわ)れた機械(きかい)の中(なか)から、使(つか)える部品(ぶひん)だけを取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "衣装ケースから、冬に着る服を取り出して並べた。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "衣装(いしょう)ケースから、冬(ふゆ)に着(き)る服(ふく)を取(と)り出(だ)して並(なら)べた。", "sentence_source": "generated"}, {"text": "袋の中の豆から、悪いものだけを取り出して捨てた。", "target_word": "取り出して", "complexity_tier": "T3", "furigana": "袋(ふくろ)の中(なか)の豆(まめ)から、悪(わる)いものだけを取(と)り出(だ)して捨(す)てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り出す", "label": "終止形"}, {"form": "取り出した", "label": "過去形"}, {"form": "取り出して", "label": "て形"}, {"form": "取り出さない", "label": "否定形"}, {"form": "取り出せる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "多くの物の中から必要な物だけを選んで外へ出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り出して", "is_correct": true, "explanation": "必要な本だけを選んで外に出す、という文脈に合う。"}, {"text": "煮て", "is_correct": false, "explanation": "本を煮ることになり、文脈に合わない。"}, {"text": "刻んで", "is_correct": false, "explanation": "本を刻むのは文脈に合わない。"}, {"text": "注いで", "is_correct": false, "explanation": "液体を注ぐ動作で、本には使わない。"}], "explanations": {"取り出して": "必要な本だけを選んで外に出す、という文脈に合う。", "煮て": "本を煮ることになり、文脈に合わない。", "刻んで": "本を刻むのは文脈に合わない。", "注いで": "液体を注ぐ動作で、本には使わない。"}, "sentence_index": 0, "correct_answer": "取り出して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "話し合いの末、みんなの役割を取り出して決めた。", "explanation": "ここは〈取り決める〉の意味。役割などを決めることで、中から選んで外に出す〈取り出す〉とは合わない。"}, {"text": "予定が変わったので、頼んだ注文を取り出して取り消した。", "explanation": "ここは〈取りやめる〉の意味。注文をなかったことにする動作で、選んで外に出す〈取り出す〉とは合わない。"}, {"text": "書店にない辞書を、出版社から取り出して届けてもらった。", "explanation": "ここは〈取り寄せる〉の意味。遠くの取引先から物を取り寄せることで、選んで外に出す〈取り出す〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り出す", "is_correct": true, "explanation": "写真の山から旅行の一枚だけを選んで外に出す、という文脈に合う。"}, {"text": "茹でる", "is_correct": false, "explanation": "写真を茹でるのは文脈に合わない。"}, {"text": "練る", "is_correct": false, "explanation": "写真を練る動作は文脈に合わない。"}, {"text": "研ぐ", "is_correct": false, "explanation": "刃物などを研ぐ動作で、写真には使わない。"}], "explanations": {"取り出す": "写真の山から旅行の一枚だけを選んで外に出す、という文脈に合う。", "茹でる": "写真を茹でるのは文脈に合わない。", "練る": "写真を練る動作は文脈に合わない。", "研ぐ": "刃物などを研ぐ動作で、写真には使わない。"}, "sentence_index": 6, "correct_answer": "取り出す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古くなった納屋を取り出して、業者に頼んで壊してもらった。", "explanation": "ここは〈取り壊す〉の意味。建物を壊す動作で、中から物を外に出す〈取り出す〉とは合わない。"}, {"text": "急な雨で、干していたシーツを取り出して、家に入れた。", "explanation": "ここは〈取り込む〉の意味。外のものを室内へ入れる動作で、中から外へ出す〈取り出す〉とは方向が逆。"}, {"text": "会社は新しい制度を取り出して、来月から実施した。", "explanation": "ここは〈取り入れる〉の意味。制度や方法を採り入れることで、物を外に出す〈取り出す〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店員はレジの引き出しから千円札に取り出して渡した。", "corrected_sentence": "店員はレジの引き出しから千円札を取り出して渡した。", "error_description": "「取り出す」の対象には格助詞「を」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り出した", "is_correct": true, "explanation": "過去形。工具箱から合うねじを選んで出したという完了の意味で、文脈に合う。"}, {"text": "取り出して", "is_correct": false, "explanation": "て形。ここでは文を終える形ではなく、「した」で終わる文と合わない。"}, {"text": "取り出し", "is_correct": false, "explanation": "連用形で、文を終えることができない。"}, {"text": "取り出さ", "is_correct": false, "explanation": "未然形だけでは文を終えることができない。"}], "correct_form": "取り出した", "base_form": "取り出す", "form_label": "過去形", "sentence_index": 1, "explanations": {"取り出した": "過去形。工具箱から合うねじを選んで出したという完了の意味で、文脈に合う。", "取り出して": "て形。ここでは文を終える形ではなく、「した」で終わる文と合わない。", "取り出し": "連用形で、文を終えることができない。", "取り出さ": "未然形だけでは文を終えることができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は押し入れの奥から古い箱が取り出して、中を見た。", "corrected_sentence": "父は押し入れの奥から古い箱を取り出して、中を見た。", "error_description": "「取り出す」の対象は「箱」なので格助詞「を」が必要。「が」は主語を示し、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り出した", "is_correct": true, "explanation": "過去形。壊れた機械から部品を選んで出したという完了の意味で、文脈に合う。"}, {"text": "取り出せ", "is_correct": false, "explanation": "命令形。文末に置くと命令になり、過去の出来事を述べる文と合わない。"}, {"text": "取り出される", "is_correct": false, "explanation": "受身形。「部品だけを」の「を」と受身が合わず、この文では成り立たない。"}, {"text": "取り出そう", "is_correct": false, "explanation": "意向形で「〜しよう」の意味になる。過去の動作を述べる文と合わない。"}], "correct_form": "取り出した", "base_form": "取り出す", "form_label": "過去形", "sentence_index": 7, "explanations": {"取り出した": "過去形。壊れた機械から部品を選んで出したという完了の意味で、文脈に合う。", "取り出せ": "命令形。文末に置くと命令になり、過去の出来事を述べる文と合わない。", "取り出される": "受身形。「部品だけを」の「を」と受身が合わず、この文では成り立たない。", "取り出そう": "意向形で「〜しよう」の意味になる。過去の動作を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「成分を確かめる」の目的語を示す「を」。確かめる対象が成分であることを表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「成分が確かめる」は成分が確かめる主体になり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「成分に確かめる」は確認の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「成分と確かめる」は並列の意味になり、確認の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「成分を確かめる」の目的語を示す「を」。確かめる対象が成分であることを表す。正解。", "が": "「成分が確かめる」は成分が確かめる主体になり、不自然。", "に": "「成分に確かめる」は確認の対象を示せない。", "と": "「成分と確かめる」は並列の意味になり、確認の対象を示せない。"}, "error_tags": {"が": "主語を示す助詞", "に": "対象・相手を示す助詞", "と": "並列を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自然の成分」の「の」。自然由来という所属を表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「自然が成分だけで作られている」は自然を主語にして意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「自然へ成分」は方向を示すが、成分を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「自然を成分」は目的語を示すが、名詞の修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "「自然の成分」の「の」。自然由来という所属を表す。正解。", "が": "「自然が成分だけで作られている」は自然を主語にして意味が通らない。", "へ": "「自然へ成分」は方向を示すが、成分を修飾できない。", "を": "「自然を成分」は目的語を示すが、名詞の修飾にはならない。"}, "error_tags": {"が": "主語を示す助詞", "へ": "方向を示す助詞", "を": "目的語を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの中に入っている、もとになるもの。", "primary_collocate": null, "pronunciation": "せいぶん", "ipa": "seːbɯɴ", "syllable_count": 4, "sentences": [{"text": "この薬の成分は箱の裏に書いてある。", "target_word": "成分", "complexity_tier": "T3", "furigana": "この薬[くすり]の成分[せいぶん]は箱[はこ]の裏[うら]に書[か]いてある。", "sentence_source": "generated"}, {"text": "アレルギーがあるので、食品の成分を必ず確かめる。", "target_word": "成分", "complexity_tier": "T3", "furigana": "アレルギーがあるので、食品[しょくひん]の成分[せいぶん]を必[かなら]ず確[たし]かめる。", "sentence_source": "generated"}, {"text": "この化粧水には、肌をうるおす成分が入っている。", "target_word": "成分", "complexity_tier": "T3", "furigana": "この化粧水[けしょうすい]には、肌[はだ]をうるおす成分[せいぶん]が入[はい]っている。", "sentence_source": "generated"}, {"text": "このジュースは果汁が少なく、ほとんどの成分が砂糖と水だ。", "target_word": "成分", "complexity_tier": "T3", "furigana": "このジュースは果汁[かじゅう]が少[すく]なく、ほとんどの成分[せいぶん]が砂糖[さとう]と水[みず]だ。", "sentence_source": "generated"}, {"text": "袋の裏の成分を見ると、小麦が使われていると分かった。", "target_word": "成分", "complexity_tier": "T3", "furigana": "袋[ふくろ]の裏[うら]の成分[せいぶん]を見[み]ると、小麦[こむぎ]が使[つか]われていると分[わ]かった。", "sentence_source": "generated"}, {"text": "水の成分を調べるために、先生が実験を行った。", "target_word": "成分", "complexity_tier": "T3", "furigana": "水[みず]の成分[せいぶん]を調[しら]べるために、先生[せんせい]が実験[じっけん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "緑茶にはカフェインという成分が含まれているので、夜は飲まない。", "target_word": "成分", "complexity_tier": "T3", "furigana": "緑茶[りょくちゃ]にはカフェインという成分[せいぶん]が含[ふく]まれているので、夜[よる]は飲[の]まない。", "sentence_source": "generated"}, {"text": "この石けんは自然の成分だけで作られているから、赤ちゃんにも使える。", "target_word": "成分", "complexity_tier": "T3", "furigana": "この石[せっ]けんは自然[しぜん]の成分[せいぶん]だけで作[つく]られているから、赤[あか]ちゃんにも使[つか]える。", "sentence_source": "generated"}, {"text": "同じ名前の薬でも、会社が違えば成分が少し違うことがある。", "target_word": "成分", "complexity_tier": "T3", "furigana": "同[おな]じ名前[なまえ]の薬[くすり]でも、会社[かいしゃ]が違[ちが]えば成分[せいぶん]が少[すこ]し違[ちが]うことがある。", "sentence_source": "generated"}, {"text": "空気の成分のうち、いちばん多いのは窒素だ。", "target_word": "成分", "complexity_tier": "T3", "furigana": "空気[くうき]の成分[せいぶん]のうち、いちばん多[おお]いのは窒素[ちっそ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成分", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ingredient or component contained in a substance such as medicine, food, or air", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: うるおす (Zipf 1.41)']::text[], '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "ここは「ものの中に入っている、もとになるもの」の意味。薬の中身が箱に書かれているという文で正解。"}, {"text": "ベッド", "is_correct": false, "explanation": "「この薬のベッドは箱の裏に書いてある」は意味が通らない。"}, {"text": "風邪", "is_correct": false, "explanation": "「この薬の風邪」は成り立たない。風邪は病気で、薬の中身ではない。"}, {"text": "配達", "is_correct": false, "explanation": "「この薬の配達は箱の裏に書いてある」は不自然。配達は運ぶことで、箱に書く内容ではない。"}], "explanations": {"成分": "ここは「ものの中に入っている、もとになるもの」の意味。薬の中身が箱に書かれているという文で正解。", "ベッド": "「この薬のベッドは箱の裏に書いてある」は意味が通らない。", "風邪": "「この薬の風邪」は成り立たない。風邪は病気で、薬の中身ではない。", "配達": "「この薬の配達は箱の裏に書いてある」は不自然。配達は運ぶことで、箱に書く内容ではない。"}, "sentence_index": 0, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの成分を見守る。", "explanation": "ここは〈成長〉の意味。人の発達は成長と言い、成分は中に入っているものを指すので子どもには使わない。"}, {"text": "料理の成分を買う。", "explanation": "ここは〈材料〉の意味。料理の食材は材料と言い、成分は買うものではないので合わない。"}, {"text": "パソコンの成分が上がった。", "explanation": "ここは〈性能〉の意味。機械の能力は性能と言い、成分が上がるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "ここは「ものの中に入っている、もとになるもの」の意味。カフェインが含まれているという文で正解。"}, {"text": "窓", "is_correct": false, "explanation": "「カフェインという窓が含まれている」は意味が通らない。"}, {"text": "鍋", "is_correct": false, "explanation": "「カフェインという鍋が含まれている」は成り立たない。鍋は器具で、飲み物の中身ではない。"}, {"text": "帽子", "is_correct": false, "explanation": "「カフェインという帽子が含まれている」は不自然。帽子は身につけるもので、中身にならない。"}], "explanations": {"成分": "ここは「ものの中に入っている、もとになるもの」の意味。カフェインが含まれているという文で正解。", "窓": "「カフェインという窓が含まれている」は意味が通らない。", "鍋": "「カフェインという鍋が含まれている」は成り立たない。鍋は器具で、飲み物の中身ではない。", "帽子": "「カフェインという帽子が含まれている」は不自然。帽子は身につけるもので、中身にならない。"}, "sentence_index": 6, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んで体の成分を痛めた。", "explanation": "ここは〈部位〉の意味。体の一部は部位と言い、成分は体の部分ではないので痛めるとは言わない。"}, {"text": "この服は成分が柔らかい。", "explanation": "ここは〈素材〉の意味。服の布や糸は素材と言い、成分は布の性質を表さないので柔らかいとは言わない。"}, {"text": "彼は正直な成分だ。", "explanation": "ここは〈性分〉の意味（同じせいぶんと読む）。生まれつきの性質は性分と言い、成分とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬局で、薬の成分に聞いた。", "corrected_sentence": "薬局で、薬の成分を聞いた。", "error_description": "「聞く」の対象になる成分は「を」で示す。ここは「に」になっており、目的語を示す助詞が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38610, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このドリンクには、ビタミンという成分が含む。", "corrected_sentence": "このドリンクには、ビタミンという成分が含まれている。", "error_description": "成分は含むものではなく含まれるものなので、受け身の「含まれている」が正しい。能動の「含む」は成分を主語にできず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「薬の成分」の「の」。薬が持つ成分という所属の関係を表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「薬が成分は」では成分が主語にならず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「薬を成分は」は目的語を示す助詞で、ここでは成分を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「薬に成分は」は場所や対象を示すが、成分との所属関係を表せない。"}], "correct_answer": "の", "explanations": {"の": "「薬の成分」の「の」。薬が持つ成分という所属の関係を表す。正解。", "が": "「薬が成分は」では成分が主語にならず、文が成り立たない。", "を": "「薬を成分は」は目的語を示す助詞で、ここでは成分を修飾できない。", "に": "「薬に成分は」は場所や対象を示すが、成分との所属関係を表せない。"}, "error_tags": {"が": "主語を示す助詞", "を": "目的語を示す助詞", "に": "場所・対象を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「成分の中で」の「の」。成分の範囲を示す。正解。"}, {"text": "で", "is_correct": false, "explanation": "「成分で中で」は意味が通らない。「で」は手段や場所を示すが「中」を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "「成分へ中で」は方向を示すが、「中で」と続かない。"}, {"text": "から", "is_correct": false, "explanation": "「成分から中で」は起点を示すが、「中で」と続かない。"}], "correct_answer": "の", "explanations": {"の": "「成分の中で」の「の」。成分の範囲を示す。正解。", "で": "「成分で中で」は意味が通らない。「で」は手段や場所を示すが「中」を修飾できない。", "へ": "「成分へ中で」は方向を示すが、「中で」と続かない。", "から": "「成分から中で」は起点を示すが、「中で」と続かない。"}, "error_tags": {"で": "手段・場所を示す助詞", "へ": "方向を示す助詞", "から": "起点を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある物を構成している、もとになる物質や要素。", "primary_collocate": null, "pronunciation": "せいぶん", "ipa": "seːbɯɴ", "syllable_count": 4, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価が劇的に向上するのみならず、フィチン酸などの抗栄養因子も分解される。", "target_word": "成分", "complexity_tier": "T4", "furigana": "しかし、微生物[びせいぶつ]の営[いとな]みを経[へ]ることで、難消化性[なんしょうかせい]の成分[せいぶん]は低分子化[ていぶんしか]され、栄養価[えいようか]が劇的[げきてき]に向上[こうじょう]するのみならず、フィチン酸[さん]などの抗栄養[こうえいよう]因子[いんし]も分解[ぶんかい]される。", "sentence_source": "mined"}, {"text": "薬の成分は、箱の裏に書いてある。", "target_word": "成分", "complexity_tier": "T3", "furigana": "薬[くすり]の成分[せいぶん]は、箱[はこ]の裏[うら]に書[か]いてある。", "sentence_source": "generated"}, {"text": "アレルギーがあるので、食品の成分を必ず確認する。", "target_word": "成分", "complexity_tier": "T3", "furigana": "アレルギーがあるので、食品[しょくひん]の成分[せいぶん]を必[かなら]ず確認[かくにん]する。", "sentence_source": "generated"}, {"text": "この化粧水には、肌に優しい成分が使われている。", "target_word": "成分", "complexity_tier": "T3", "furigana": "この化粧水[けしょうすい]には、肌[はだ]に優[やさ]しい成分[せいぶん]が使[つか]われている。", "sentence_source": "generated"}, {"text": "水の成分は、水素と酸素である。", "target_word": "成分", "complexity_tier": "T3", "furigana": "水[みず]の成分[せいぶん]は、水素[すいそ]と酸素[さんそ]である。", "sentence_source": "generated"}, {"text": "研究室で、温泉水に含まれる成分を調べた。", "target_word": "成分", "complexity_tier": "T3", "furigana": "研究室[けんきゅうしつ]で、温泉水[おんせんすい]に含[ふく]まれる成分[せいぶん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "この洗剤は、自然由来の成分だけで作られている。", "target_word": "成分", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は、自然[しぜん]由来[ゆらい]の成分[せいぶん]だけで作[つく]られている。", "sentence_source": "generated"}, {"text": "牛乳に含まれる成分の中で、カルシウムは骨に大切だ。", "target_word": "成分", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]に含[ふく]まれる成分[せいぶん]の中[なか]で、カルシウムは骨[ほね]に大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "空気の成分の約八割は、窒素である。", "target_word": "成分", "complexity_tier": "T3", "furigana": "空気[くうき]の成分[せいぶん]の約[やく]八割[はちわり]は、窒素[ちっそ]である。", "sentence_source": "generated"}, {"text": "お茶の苦みは、カテキンという成分によるものだ。", "target_word": "成分", "complexity_tier": "T3", "furigana": "お茶[ちゃ]の苦[にが]みは、カテキンという成分[せいぶん]によるものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成分", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を構成するもとの物質や要素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: フィチン (Zipf 1.72)']::text[], '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "ここは「ある物を構成するもとの物質」の意味。難消化性の物質が低分子化される文で正解。"}, {"text": "気温", "is_correct": false, "explanation": "「難消化性の気温は」は意味が通らない。気温は空気の温度で、食品の構成要素ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "「難消化性の眠気は」は不自然。眠気は体の状態で、食品の構成要素ではない。"}, {"text": "天井", "is_correct": false, "explanation": "「難消化性の天井は」は成り立たない。天井は建物の部位で、食品には関係しない。"}], "explanations": {"成分": "ここは「ある物を構成するもとの物質」の意味。難消化性の物質が低分子化される文で正解。", "気温": "「難消化性の気温は」は意味が通らない。気温は空気の温度で、食品の構成要素ではない。", "眠気": "「難消化性の眠気は」は不自然。眠気は体の状態で、食品の構成要素ではない。", "天井": "「難消化性の天井は」は成り立たない。天井は建物の部位で、食品には関係しない。"}, "sentence_index": 0, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は成分が新鮮で、値段も手頃だ。", "explanation": "ここは〈材料〉の意味。料理の食材は材料と言い、成分は物質の要素を指すので「新鮮な成分」とは言わない。"}, {"text": "車の成分が壊れた。", "explanation": "ここは〈部品〉の意味。機械の一部は部品と言い、成分は壊れるものではないので合わない。"}, {"text": "子どもの成分を見守る。", "explanation": "ここは〈成長〉の意味。人の発達は成長と言い、成分は物質の要素なので子どもには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "ここは「洗剤を作るもとの物質」の意味。自然由来の成分で作られるという文で正解。"}, {"text": "季節", "is_correct": false, "explanation": "「自然由来の季節だけで作られている」は意味が通らない。季節は物の構成要素ではない。"}, {"text": "乗客", "is_correct": false, "explanation": "「自然由来の乗客」は不自然。乗客は人で、洗剤の構成要素ではない。"}, {"text": "価格", "is_correct": false, "explanation": "「自然由来の価格だけで作られている」は成り立たない。価格は値段で、材料にはならない。"}], "explanations": {"成分": "ここは「洗剤を作るもとの物質」の意味。自然由来の成分で作られるという文で正解。", "季節": "「自然由来の季節だけで作られている」は意味が通らない。季節は物の構成要素ではない。", "乗客": "「自然由来の乗客」は不自然。乗客は人で、洗剤の構成要素ではない。", "価格": "「自然由来の価格だけで作られている」は成り立たない。価格は値段で、材料にはならない。"}, "sentence_index": 6, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んで体の成分を痛めた。", "explanation": "ここは〈部位〉の意味。体の一部は部位と言い、成分は体の部分ではないので痛めるとは言わない。"}, {"text": "研究の成分を発表した。", "explanation": "ここは〈成果〉の意味。研究の結果は成果と言い、成分は発表の対象にはならない。"}, {"text": "パソコンの成分が上がった。", "explanation": "ここは〈性能〉の意味。機械の能力は性能と言い、成分が上がるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食品の成分に表示する義務がある。", "corrected_sentence": "食品の成分を表示する義務がある。", "error_description": "「表示する」の目的語は「を」で示す。ここは「に」になっており、目的語を示す助詞が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この石けんには、肌に優しい成分が使っている。", "corrected_sentence": "この石けんには、肌に優しい成分が使われている。", "error_description": "成分は使われるものなので、受け身の「使われている」が正しい。能動の「使っている」は成分を主語にできず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾く", "is_correct": true, "explanation": "〈湿る〉の対義語。水分がなくなり、ぬれた感じがなくなる意味。"}, {"text": "凍る", "is_correct": false, "explanation": "水が固まる変化で、〈湿る〉の対義語ではない。"}, {"text": "焦げる", "is_correct": false, "explanation": "熱で黒くなる変化で、〈湿る〉の対義語ではない。"}, {"text": "膨らむ", "is_correct": false, "explanation": "体積が増える変化で、〈湿る〉の対義語ではない。"}], "correct_answer": "乾く", "explanations": {"乾く": "〈湿る〉の対義語。水分がなくなり、ぬれた感じがなくなる意味。", "凍る": "水が固まる変化で、〈湿る〉の対義語ではない。", "焦げる": "熱で黒くなる変化で、〈湿る〉の対義語ではない。", "膨らむ": "体積が増える変化で、〈湿る〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾く", "is_correct": true, "explanation": "〈湿る〉の対義語。水分がなくなり、ぬれた感じがなくなる意味。"}, {"text": "溶ける", "is_correct": false, "explanation": "固体が熱で液体になる変化で、〈湿る〉の対義語ではない。"}, {"text": "割れる", "is_correct": false, "explanation": "物が裂けたり砕けたりする変化で、〈湿る〉の対義語ではない。"}, {"text": "縮む", "is_correct": false, "explanation": "長さや大きさが小さくなる変化で、〈湿る〉の対義語ではない。"}], "correct_answer": "乾く", "explanations": {"乾く": "〈湿る〉の対義語。水分がなくなり、ぬれた感じがなくなる意味。", "溶ける": "固体が熱で液体になる変化で、〈湿る〉の対義語ではない。", "割れる": "物が裂けたり砕けたりする変化で、〈湿る〉の対義語ではない。", "縮む": "長さや大きさが小さくなる変化で、〈湿る〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "水や空気の水分で、物がちょっとぬれたような感じになること。", "primary_collocate": null, "pronunciation": "しめる", "ipa": "ɕimeɾɯ", "syllable_count": 3, "sentences": [{"text": "洗濯物が乾かず、夜になっても湿ったままだ。", "target_word": "湿った", "complexity_tier": "T3", "furigana": "洗濯物(せんたくもの)が乾(かわ)かず、夜(よる)になっても湿(しめ)ったままだ。", "sentence_source": "generated"}, {"text": "窓を開けて寝たら、朝には布団が湿っていた。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "窓(まど)を開(あ)けて寝(ね)たら、朝(あさ)には布団(ふとん)が湿(しめ)っていた。", "sentence_source": "generated"}, {"text": "海苔は空気に触れると、すぐ湿ってしまう。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "海苔(のり)は空気(くうき)に触(ふ)れると、すぐ湿(しめ)ってしまう。", "sentence_source": "generated"}, {"text": "雨上がりで、庭の土が少し湿っている。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "雨上(あめあ)がりで、庭(にわ)の土(つち)が少(すこ)し湿(しめ)っている。", "sentence_source": "generated"}, {"text": "汗で背中のシャツが湿ってきた。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "汗(あせ)で背中(せなか)のシャツが湿(しめ)ってきた。", "sentence_source": "generated"}, {"text": "湿ってしまったマッチは、火がつかない。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "湿(しめ)ってしまったマッチは、火(ひ)がつかない。", "sentence_source": "generated"}, {"text": "お風呂の湯気で、洗面所のタオルが湿る。", "target_word": "湿る", "complexity_tier": "T3", "furigana": "お風呂(ふろ)の湯気(ゆげ)で、洗面所(せんめんじょ)のタオルが湿(しめ)る。", "sentence_source": "generated"}, {"text": "霧が出た朝は、道ばたの草まで湿っていた。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "霧(きり)が出(で)た朝(あさ)は、道(みち)ばたの草(くさ)まで湿(しめ)っていた。", "sentence_source": "generated"}, {"text": "せんべいが湿ると、ぱりっとした音がしなくなる。", "target_word": "湿る", "complexity_tier": "T3", "furigana": "せんべいが湿(しめ)ると、ぱりっとした音(おと)がしなくなる。", "sentence_source": "generated"}, {"text": "梅雨は押し入れの中の服まで湿る。", "target_word": "湿る", "complexity_tier": "T3", "furigana": "梅雨(つゆ)は押(お)し入(い)れの中(なか)の服(ふく)まで湿(しめ)る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湿る", "label": "終止形"}, {"form": "湿った", "label": "過去形"}, {"form": "湿って", "label": "て形"}, {"form": "湿らない", "label": "否定形"}, {"form": "湿れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "水分を受けて物が少しぬれた感じに変わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿った", "is_correct": true, "explanation": "洗濯物がぬれた感じのまま乾かない、という文脈に合う。"}, {"text": "乾いた", "is_correct": false, "explanation": "乾かないという文脈と逆で、ぬれた感じを表さない。"}, {"text": "膨らんだ", "is_correct": false, "explanation": "布が膨らむ意味で、ぬれた状態を表さない。"}, {"text": "錆びた", "is_correct": false, "explanation": "金属が錆びる変化で、洗濯物には使わない。"}], "explanations": {"湿った": "洗濯物がぬれた感じのまま乾かない、という文脈に合う。", "乾いた": "乾かないという文脈と逆で、ぬれた感じを表さない。", "膨らんだ": "布が膨らむ意味で、ぬれた状態を表さない。", "錆びた": "金属が錆びる変化で、洗濯物には使わない。"}, "sentence_index": 0, "correct_answer": "湿った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "霧で遠くの山並みが湿った。", "explanation": "ここは〈煙る〉の意味。霧で景色がぼんやりかすむ様子を表し、水分でぬれた感じの〈湿る〉とは合わない。"}, {"text": "大雨で、傘を忘れた私の服がびっしょり湿った。", "explanation": "ここは〈濡れる〉の場面。大量の水でびしょ濡れになる時は〈濡れる〉を使い、少しぬれた感じの〈湿る〉とは合わない。"}, {"text": "寒い朝、川の水面が一面湿って、動かなくなった。", "explanation": "ここは〈凍る〉の意味。水が固まる変化で、水分でぬれた感じを表す〈湿る〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿る", "is_correct": true, "explanation": "湯気で洗面所のタオルが水分を受けてぬれる、という文脈に合う。"}, {"text": "焦げる", "is_correct": false, "explanation": "湯気で焦げることはなく、文脈に合わない。"}, {"text": "割れる", "is_correct": false, "explanation": "タオルが割れるという意味にはならない。"}, {"text": "溶ける", "is_correct": false, "explanation": "湯気で溶けることは文脈に合わない。"}], "explanations": {"湿る": "湯気で洗面所のタオルが水分を受けてぬれる、という文脈に合う。", "焦げる": "湯気で焦げることはなく、文脈に合わない。", "割れる": "タオルが割れるという意味にはならない。", "溶ける": "湯気で溶けることは文脈に合わない。"}, "sentence_index": 6, "correct_answer": "湿る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "トーストを焼きすぎて、パンの表面が湿った。", "explanation": "ここは〈焦げる〉の意味。焼きすぎた表面は黒くなる変化で、ぬれた感じの〈湿る〉とは合わない。"}, {"text": "夏の間に置いた肉が、とうとう湿ってしまった。", "explanation": "ここは〈腐る〉の意味。食べ物が傷んで悪くなる変化で、ぬれた感じの〈湿る〉とは合わない。"}, {"text": "真夏の車内でチョコレートが湿った。", "explanation": "ここは〈溶ける〉の意味。熱で固体が柔らかくなる変化で、〈湿る〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降ったので、屋根の下の床をまだ湿っている。", "corrected_sentence": "雨が降ったので、屋根の下の床がまだ湿っている。", "error_description": "「湿る」は自動詞なので目的語「を」は取れない。主語には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "湿って", "is_correct": true, "explanation": "て形。「湿っていた」の一部として使われる形。"}, {"text": "湿った", "is_correct": false, "explanation": "過去形。「湿っていた」の一部にはならず、ここでは形が合わない。"}, {"text": "湿らない", "is_correct": false, "explanation": "否定形。ぬれていないという意味になり、文の内容と逆になる。"}, {"text": "湿れば", "is_correct": false, "explanation": "仮定形。「〜ば」は仮定を表し、ここでは文が続かない。"}], "correct_form": "湿って", "base_form": "湿る", "form_label": "て形", "sentence_index": 1, "explanations": {"湿って": "て形。「湿っていた」の一部として使われる形。", "湿った": "過去形。「湿っていた」の一部にはならず、ここでは形が合わない。", "湿らない": "否定形。ぬれていないという意味になり、文の内容と逆になる。", "湿れば": "仮定形。「〜ば」は仮定を表し、ここでは文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝の散歩で、草の葉がまだ湿らせていた。", "corrected_sentence": "朝の散歩で、草の葉がまだ湿っていた。", "error_description": "「湿る」は自動詞で、「湿らせる」は他動詞。「草の葉が湿らせていた」は目的語がなく、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "湿って", "is_correct": true, "explanation": "て形。「湿っていた」の一部として使われる形。"}, {"text": "湿る", "is_correct": false, "explanation": "終止形。「湿っていた」の形になっておらず、ここでは続かない。"}, {"text": "湿ろう", "is_correct": false, "explanation": "意志形。「湿ろう」という意味になり、文の内容と合わない。"}, {"text": "湿らず", "is_correct": false, "explanation": "否定形（文語的）。ぬれていないという意味になり、文と逆になる。"}], "correct_form": "湿って", "base_form": "湿る", "form_label": "て形", "sentence_index": 7, "explanations": {"湿って": "て形。「湿っていた」の一部として使われる形。", "湿る": "終止形。「湿っていた」の形になっておらず、ここでは続かない。", "湿ろう": "意志形。「湿ろう」という意味になり、文の内容と合わない。", "湿らず": "否定形（文語的）。ぬれていないという意味になり、文と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
