INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38613, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "空気中の水分を多く含んで、少しぬれている状態。", "primary_collocate": null, "pronunciation": "しめる", "ipa": "ɕimeɾɯ", "syllable_count": 3, "sentences": [{"text": "湿った空気が流れ込んで、今夜は雨になりそうだ。", "target_word": "湿った", "complexity_tier": "T3", "furigana": "湿(しめ)った空気(くうき)が流(なが)れ込(こ)んで、今夜(こんや)は雨(あめ)になりそうだ。", "sentence_source": "generated"}, {"text": "地下室は風が通らないので、いつも湿っている。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "地下室(ちかしつ)は風(かぜ)が通(とお)らないので、いつも湿(しめ)っている。", "sentence_source": "generated"}, {"text": "湿った風が吹いて、肌がべたべたする。", "target_word": "湿った", "complexity_tier": "T3", "furigana": "湿(しめ)った風(かぜ)が吹(ふ)いて、肌(はだ)がべたべたする。", "sentence_source": "generated"}, {"text": "霧の朝は、木のベンチも湿っている。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "霧(きり)の朝(あさ)は、木(き)のベンチも湿(しめ)っている。", "sentence_source": "generated"}, {"text": "湿った落ち葉の上を歩くと、音がしない。", "target_word": "湿った", "complexity_tier": "T3", "furigana": "湿(しめ)った落(お)ち葉(ば)の上(うえ)を歩(ある)くと、音(おと)がしない。", "sentence_source": "generated"}, {"text": "梅雨になると、この部屋の畳はいつも湿っている。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "梅雨(つゆ)になると、この部屋(へや)の畳(たたみ)はいつも湿(しめ)っている。", "sentence_source": "generated"}, {"text": "谷の湿った空気の中で、こけがよく育つ。", "target_word": "湿った", "complexity_tier": "T3", "furigana": "谷(たに)の湿(しめ)った空気(くうき)の中(なか)で、こけがよく育(そだ)つ。", "sentence_source": "generated"}, {"text": "雨が続いて、押し入れの中が湿っている。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "雨(あめ)が続(つづ)いて、押(お)し入(い)れの中(なか)が湿(しめ)っている。", "sentence_source": "generated"}, {"text": "洞窟の中は暗くて、壁が湿っていた。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "洞窟(どうくつ)の中(なか)は暗(くら)くて、壁(かべ)が湿(しめ)っていた。", "sentence_source": "generated"}, {"text": "雨の後は空気が湿って、洗濯物がなかなか乾かない。", "target_word": "湿って", "complexity_tier": "T3", "furigana": "雨(あめ)の後(あと)は空気(くうき)が湿(しめ)って、洗濯物(せんたくもの)がなかなか乾(かわ)かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湿る", "label": "終止形"}, {"form": "湿った", "label": "過去形・連体形"}, {"form": "湿って", "label": "て形"}, {"form": "湿らない", "label": "否定形"}, {"form": "湿れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "空気中の水分を多く含み、少しぬれている状態にある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿った", "is_correct": true, "explanation": "湿った空気が流れ込んで雨になりそう、という文脈に合う。"}, {"text": "錆びた", "is_correct": false, "explanation": "空気が錆びることはなく、文脈に合わない。"}, {"text": "焦げた", "is_correct": false, "explanation": "空気が焦げるという意味にはならず、文脈に合わない。"}, {"text": "溶けた", "is_correct": false, "explanation": "空気が溶けるとは言わず、文脈に合わない。"}], "explanations": {"湿った": "湿った空気が流れ込んで雨になりそう、という文脈に合う。", "錆びた": "空気が錆びることはなく、文脈に合わない。", "焦げた": "空気が焦げるという意味にはならず、文脈に合わない。", "溶けた": "空気が溶けるとは言わず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "湿った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の煙で、遠くの景色が湿った。", "explanation": "ここは〈煙る〉の意味。煙で景色がぼやける様子を表し、水分を含む〈湿る〉とは合わない。"}, {"text": "真夏の車内で、チョコレートが湿った。", "explanation": "ここは〈溶ける〉の意味。熱で柔らかくなる変化で、〈湿る〉とは合わない。"}, {"text": "冷蔵庫の中で、食べ残しの肉が湿った。", "explanation": "ここは〈腐る〉の意味。食べ物が傷んでいく変化で、ぬれた感じの〈湿る〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿った", "is_correct": true, "explanation": "谷の湿った空気の中でこけが育つ、という文脈に合う。"}, {"text": "凍った", "is_correct": false, "explanation": "空気が凍るという状態は、こけが育つ文脈に合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "空気が割れるという表現にはならない。"}, {"text": "膨らんだ", "is_correct": false, "explanation": "空気が膨らむ変化は、谷の環境を表す文脈に合わない。"}], "explanations": {"湿った": "谷の湿った空気の中でこけが育つ、という文脈に合う。", "凍った": "空気が凍るという状態は、こけが育つ文脈に合わない。", "割れた": "空気が割れるという表現にはならない。", "膨らんだ": "空気が膨らむ変化は、谷の環境を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "湿った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日なたに置いたろうそくが、すっかり湿った。", "explanation": "ここは〈溶ける〉の意味。熱で固体が柔らかく液状になる変化で、〈湿る〉とは合わない。"}, {"text": "焼きすぎた肉の端が湿った。", "explanation": "ここは〈焦げる〉の意味。焼きすぎて黒くなる変化で、ぬれた感じの〈湿る〉とは合わない。"}, {"text": "冷凍庫に入れた肉が、すっかり湿った。", "explanation": "ここは〈凍る〉の意味。水分が固まる変化で、〈湿る〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海辺の町は風が強く、空気をいつも湿っている。", "corrected_sentence": "海辺の町は風が強く、空気がいつも湿っている。", "error_description": "「湿っている」の主語「空気」には「が」が必要。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "湿って", "is_correct": true, "explanation": "て形。「湿っている」の一部として使われる形。"}, {"text": "湿った", "is_correct": false, "explanation": "過去形。「湿っている」の一部にはならず、ここでは形が合わない。"}, {"text": "湿らない", "is_correct": false, "explanation": "否定形。湿っていないという意味になり、文の内容と逆になる。"}, {"text": "湿る", "is_correct": false, "explanation": "終止形。「湿っている」の形にならず、文が続かない。"}], "correct_form": "湿って", "base_form": "湿る", "form_label": "て形", "sentence_index": 1, "explanations": {"湿って": "て形。「湿っている」の一部として使われる形。", "湿った": "過去形。「湿っている」の一部にはならず、ここでは形が合わない。", "湿らない": "否定形。湿っていないという意味になり、文の内容と逆になる。", "湿る": "終止形。「湿っている」の形にならず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の中の沢は、いつも空気が湿れている。", "corrected_sentence": "山の中の沢は、いつも空気が湿っている。", "error_description": "「湿る」のて形は「湿って」なので、「湿れている」は活用の誤り。正しくは「湿っている」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "湿って", "is_correct": true, "explanation": "て形。「湿っている」の一部として使われる形。"}, {"text": "湿る", "is_correct": false, "explanation": "終止形。「〜ている」に続く形になっておらず、ここでは文が続かない。"}, {"text": "湿ろう", "is_correct": false, "explanation": "意志形。「湿ろう」という意味になり、文の内容と合わない。"}, {"text": "湿らず", "is_correct": false, "explanation": "否定形（文語的）。湿っていないという意味になり、文と逆になる。"}], "correct_form": "湿って", "base_form": "湿る", "form_label": "て形", "sentence_index": 7, "explanations": {"湿って": "て形。「湿っている」の一部として使われる形。", "湿る": "終止形。「〜ている」に続く形になっておらず、ここでは文が続かない。", "湿ろう": "意志形。「湿ろう」という意味になり、文の内容と合わない。", "湿らず": "否定形（文語的）。湿っていないという意味になり、文と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38614, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「寄付した」の目的語を示し、「財産の全て」を寄付したという文意が通る。"}, {"text": "が", "is_correct": false, "explanation": "「全てが」は主語になり、「寄付した」の動作主が物事になってしまうため不自然。"}, {"text": "で", "is_correct": false, "explanation": "「全てで」は手段の意味になるが、「全て」を手段として寄付するという表現は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」になり、「全てより寄付した」は比べる相手がなく意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「寄付した」の目的語を示し、「財産の全て」を寄付したという文意が通る。", "が": "「全てが」は主語になり、「寄付した」の動作主が物事になってしまうため不自然。", "で": "「全てで」は手段の意味になるが、「全て」を手段として寄付するという表現は不自然。", "より": "比較の「より」になり、「全てより寄付した」は比べる相手がなく意味が通らない。"}, "error_tags": {"が": "subject_marker", "で": "means_or_location", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一部", "is_correct": true, "explanation": "「全て」の対義語。全体のうちの一部を指し、全部と反対の関係にある。"}, {"text": "半分", "is_correct": false, "explanation": "部分を表すが、「全て」の対義語として辞書に挙げられる語ではない。"}, {"text": "本体", "is_correct": false, "explanation": "中心となるものを指し、「全て」と反対の関係にはない。"}, {"text": "始まり", "is_correct": false, "explanation": "起点を指す語で、「全て」の反対語ではない。"}], "correct_answer": "一部", "explanations": {"一部": "「全て」の対義語。全体のうちの一部を指し、全部と反対の関係にある。", "半分": "部分を表すが、「全て」の対義語として辞書に挙げられる語ではない。", "本体": "中心となるものを指し、「全て」と反対の関係にはない。", "始まり": "起点を指す語で、「全て」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.gen