INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38614, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「全て」は、「ぜんぶ」という意味です。", "primary_collocate": null, "pronunciation": "すべて", "ipa": "sɯbete", "syllable_count": 3, "sentences": [{"text": "今日の宿題は全て終わった。", "target_word": "全て", "complexity_tier": "T3", "furigana": "今日(きょう)の宿題(しゅくだい)は全(すべ)て終(お)わった。", "sentence_source": "generated"}, {"text": "彼は財産の全てを寄付した。", "target_word": "全て", "complexity_tier": "T3", "furigana": "彼(かれ)は財産(ざいさん)の全(すべ)てを寄付(きふ)した。", "sentence_source": "generated"}, {"text": "この数日間の出来事は、全てが夢のようだった。", "target_word": "全て", "complexity_tier": "T3", "furigana": "この数日間(すうじつかん)の出来事(できごと)は、全(すべ)てが夢(ゆめ)のようだった。", "sentence_source": "generated"}, {"text": "机の上の書類は全て私のものだ。", "target_word": "全て", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)の書類(しょるい)は全(すべ)て私(わたし)のものだ。", "sentence_source": "generated"}, {"text": "試験の問題は全て易しかった。", "target_word": "全て", "complexity_tier": "T3", "furigana": "試験(しけん)の問題(もんだい)は全(すべ)て易(やさ)しかった。", "sentence_source": "generated"}, {"text": "警察に、知っていることを全て話した。", "target_word": "全て", "complexity_tier": "T3", "furigana": "警察(けいさつ)に、知(し)っていることを全(すべ)て話(はな)した。", "sentence_source": "generated"}, {"text": "彼女の言うことは全て正しい。", "target_word": "全て", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の言(い)うことは全(すべ)て正(ただ)しい。", "sentence_source": "generated"}, {"text": "今回の失敗の責任は全て私にある。", "target_word": "全て", "complexity_tier": "T3", "furigana": "今回(こんかい)の失敗(しっぱい)の責任(せきにん)は全(すべ)て私(わたし)にある。", "sentence_source": "generated"}, {"text": "旅行の費用は全て会社が払う。", "target_word": "全て", "complexity_tier": "T3", "furigana": "旅行(りょこう)の費用(ひよう)は全(すべ)て会社(かいしゃ)が払(はら)う。", "sentence_source": "generated"}, {"text": "疲れたので、全てを忘れてゆっくり休みたい。", "target_word": "全て", "complexity_tier": "T3", "furigana": "疲(つか)れたので、全(すべ)てを忘(わす)れてゆっくり休(やす)みたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全て", "label": "基本形"}, {"form": "全ての", "label": "連体形"}, {"form": "全てが", "label": "主語形"}, {"form": "全てを", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "ある範囲のものごと全体、ぜんぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全て", "is_correct": true, "explanation": "「全て」は「ぜんぶ」の意味で、「今日の宿題は＿終わった」に入ると「宿題のすべてが終わった」と文意が通る。"}, {"text": "教科書", "is_correct": false, "explanation": "名詞の「教科書」は「終わった」を修飾できず、「宿題は教科書終わった」は意味が通らない。"}, {"text": "問題集", "is_correct": false, "explanation": "宿題に関係する名詞だが、「宿題は問題集終わった」は文として成り立たない。"}, {"text": "授業", "is_correct": false, "explanation": "学校の場面の名詞だが、「宿題は授業終わった」は意味が通らず、空欄に入らない。"}], "explanations": {"全て": "「全て」は「ぜんぶ」の意味で、「今日の宿題は＿終わった」に入ると「宿題のすべてが終わった」と文意が通る。", "教科書": "名詞の「教科書」は「終わった」を修飾できず、「宿題は教科書終わった」は意味が通らない。", "問題集": "宿題に関係する名詞だが、「宿題は問題集終わった」は文として成り立たない。", "授業": "学校の場面の名詞だが、「宿題は授業終わった」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "全て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は全て寒かった。", "explanation": "ここは〈とても〉の意味。「全て」は残らず全部を表すため、程度を強める〈とても〉の代わりにはならない。"}, {"text": "クラスの全てが参加した。", "explanation": "ここは〈全員〉の意味。「全て」は物事に使い、人の集まりには「全員」を使う。"}, {"text": "チームは全てで試合に臨んだ。", "explanation": "ここは〈全力〉の意味。「全て」は「全力で」の意味にならず、「全てで」は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全て", "is_correct": true, "explanation": "「彼女の言うことのすべてが正しい」の意味で、空欄に入ると文意が通る。"}, {"text": "意見", "is_correct": false, "explanation": "「彼女の言うことは意見正しい」となり、修飾の形にならず意味が通らない。"}, {"text": "態度", "is_correct": false, "explanation": "「彼女の言うことは態度正しい」となり、「正しい」にかからず文が成り立たない。"}, {"text": "性格", "is_correct": false, "explanation": "人物を表す名詞だが、「彼女の言うことは性格正しい」は意味が通らない。"}], "explanations": {"全て": "「彼女の言うことのすべてが正しい」の意味で、空欄に入ると文意が通る。", "意見": "「彼女の言うことは意見正しい」となり、修飾の形にならず意味が通らない。", "態度": "「彼女の言うことは態度正しい」となり、「正しい」にかからず文が成り立たない。", "性格": "人物を表す名詞だが、「彼女の言うことは性格正しい」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "全て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の練習で、全てに汗をかいた。", "explanation": "ここは〈全身〉の意味。体全体に汗をかく表現で、「全て」は体の部分を表す語として使わない。"}, {"text": "全てから応援が届いた。", "explanation": "ここは〈全国〉の意味。「全て」は地域の広がりを表さないため、「全国から」の代わりにはならない。"}, {"text": "彼は全て頭がいい。", "explanation": "ここは〈とても〉の意味。「全て」は残らず全部の意味で、程度を強める〈とても〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
