INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38615, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「全て」は、数えられるものや、数えられないものの、残らず全部を指す言葉です。", "primary_collocate": null, "pronunciation": "すべて", "ipa": "sɯbete", "syllable_count": 3, "sentences": [{"text": "おなかがすいていたので、皿の上の料理を全て食べた。", "target_word": "全て", "complexity_tier": "T3", "furigana": "おなかがすいていたので、皿(さら)の上(うえ)の料理(りょうり)を全(すべ)て食(た)べた。", "sentence_source": "generated"}, {"text": "箱の中のりんごは全て傷んでいた。", "target_word": "全て", "complexity_tier": "T3", "furigana": "箱(はこ)の中(なか)のりんごは全(すべ)て傷(いた)んでいた。", "sentence_source": "generated"}, {"text": "そうじのために、池の水が全て抜かれた。", "target_word": "全て", "complexity_tier": "T3", "furigana": "そうじのために、池(いけ)の水(みず)が全(すべ)て抜(ぬ)かれた。", "sentence_source": "generated"}, {"text": "買い物で、持っているお金を全て使ってしまった。", "target_word": "全て", "complexity_tier": "T3", "furigana": "買(か)い物(もの)で、持(も)っているお金(かね)を全(すべ)て使(つか)ってしまった。", "sentence_source": "generated"}, {"text": "部屋の電気を全て消して、寝た。", "target_word": "全て", "complexity_tier": "T3", "furigana": "部屋(へや)の電気(でんき)を全(すべ)て消(け)して、寝(ね)た。", "sentence_source": "generated"}, {"text": "先月買った本は、全て読み終えた。", "target_word": "全て", "complexity_tier": "T3", "furigana": "先月(せんげつ)買(か)った本(ほん)は、全(すべ)て読(よ)み終(お)えた。", "sentence_source": "generated"}, {"text": "春になって、山の雪が全てとけて川になった。", "target_word": "全て", "complexity_tier": "T3", "furigana": "春(はる)になって、山(やま)の雪(ゆき)が全(すべ)てとけて川(かわ)になった。", "sentence_source": "generated"}, {"text": "三百人の生徒の名前を全て覚えるのは大変だ。", "target_word": "全て", "complexity_tier": "T3", "furigana": "三百人(さんびゃくにん)の生徒(せいと)の名前(なまえ)を全(すべ)て覚(おぼ)えるのは大変(たいへん)だ。", "sentence_source": "generated"}, {"text": "試験前は、残った時間を全て勉強に使った。", "target_word": "全て", "complexity_tier": "T3", "furigana": "試験前(しけんまえ)は、残(のこ)った時間(じかん)を全(すべ)て勉強(べんきょう)に使(つか)った。", "sentence_source": "generated"}, {"text": "日曜日なので、駅前の店は全て閉まっていた。", "target_word": "全て", "complexity_tier": "T3", "furigana": "日曜日(にちようび)なので、駅前(えきまえ)の店(みせ)は全(すべ)て閉(し)まっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全て", "label": "基本形"}, {"form": "全ての", "label": "連体形"}, {"form": "全てを", "label": "目的語形"}, {"form": "全てが", "label": "主語形"}], "register": "neutral", "sense_fingerprint": "数えられる物も数えられない物も、残らず全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全て", "is_correct": true, "explanation": "「料理を全て食べた」となり、残らず食べたという意味で文が通る。"}, {"text": "皿", "is_correct": false, "explanation": "料理の器を表す名詞で、「料理を皿食べた」は意味が通らない。"}, {"text": "箸", "is_correct": false, "explanation": "食事道具の名詞だが、「料理を箸食べた」は文として成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "台所の場面にはあるが、「料理を窓食べた」は意味が通らない。"}], "explanations": {"全て": "「料理を全て食べた」となり、残らず食べたという意味で文が通る。", "皿": "料理の器を表す名詞で、「料理を皿食べた」は意味が通らない。", "箸": "食事道具の名詞だが、「料理を箸食べた」は文として成り立たない。", "窓": "台所の場面にはあるが、「料理を窓食べた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "全て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は全て広い。", "explanation": "ここは〈とても〉の意味。「全て」は残らず全部の意味で、程度を強める〈とても〉の代わりにはならない。"}, {"text": "全てから応援が届いた。", "explanation": "ここは〈全国〉の意味。「全て」は地域の広がりを表さないため、「全国から」の代わりにはならない。"}, {"text": "寒さで全てがすくんだ。", "explanation": "ここは〈全身〉の意味。体がこわばる様子は「全身」で表し、「全て」は体全体を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全て", "is_correct": true, "explanation": "「雪が全てとけて」となり、山の雪のすべてがとけたという意味で文が通る。"}, {"text": "春", "is_correct": false, "explanation": "季節の名詞だが、「雪が春とけて」は意味が通らない。"}, {"text": "水", "is_correct": false, "explanation": "雪がとけた結果の物質だが、「雪が水とけて」は文として成り立たない。"}, {"text": "霧", "is_correct": false, "explanation": "自然現象の名詞だが、「雪が霧とけて」は意味が通らない。"}], "explanations": {"全て": "「雪が全てとけて」となり、山の雪のすべてがとけたという意味で文が通る。", "春": "季節の名詞だが、「雪が春とけて」は意味が通らない。", "水": "雪がとけた結果の物質だが、「雪が水とけて」は文として成り立たない。", "霧": "自然現象の名詞だが、「雪が霧とけて」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "全て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "選手は全てで走り抜けた。", "explanation": "ここは〈全力〉の意味。「全て」は全力の意味にならず、「全てで走る」は不自然。"}, {"text": "お金は全てで十円だった。", "explanation": "ここは〈合計〉の意味。「全て」は残らず全部を表し、金額の合計を示すには「全部で」の形が必要で、「全てで」だけでは合計の意味にならない。"}, {"text": "店員の全てが休みだった。", "explanation": "ここは〈全員〉の意味。人の集まりには「全員」を使い、「全て」は人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の夜、窓ガラスは全てを割れていた。", "corrected_sentence": "台風の夜、窓ガラスは全て割れていた。", "error_description": "誤りは「全てを」の「を」。「割れていた」は自動詞なので目的語を取らない。「全て」は直接「割れていた」にかかるため、「を」は不要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日の図書館は全ての閉まっていた。", "corrected_sentence": "雨の日の図書館は全て閉まっていた。", "error_description": "誤りは「全ての」の「の」。「全ての」は名詞を修飾する形で、動詞「閉まっていた」を修飾できない。ここは副詞的に「全て」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
