INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38616, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "すぐに、という意味です。", "primary_collocate": null, "pronunciation": "すぐ", "ipa": "sɯɡɯ", "syllable_count": 2, "sentences": [{"text": "電話が鳴ったので、直ぐに出ました。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "電話[でんわ]が鳴[な]ったので、直[す]ぐに出[で]ました。", "sentence_source": "generated"}, {"text": "駅に着いたら、直ぐに連絡してください。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "駅[えき]に着[つ]いたら、直[す]ぐに連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "雨が降り出したから、直ぐ傘をさした。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]り出[だ]したから、直[す]ぐ傘[かさ]をさした。", "sentence_source": "generated"}, {"text": "先生に呼ばれて、直ぐ職員室へ行きました。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "先生[せんせい]に呼[よ]ばれて、直[す]ぐ職員室[しょくいんしつ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "宿題は帰ったら直ぐに始めるつもりです。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]は帰[かえ]ったら直[す]ぐに始[はじ]めるつもりです。", "sentence_source": "generated"}, {"text": "彼は名前を聞くと、直ぐに思い出した。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "彼[かれ]は名前[なまえ]を聞[き]くと、直[す]ぐに思[おも]い出[だ]した。", "sentence_source": "generated"}, {"text": "薬を飲んだら、直ぐに熱が下がった。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、直[す]ぐに熱[ねつ]が下[さ]がった。", "sentence_source": "generated"}, {"text": "メールを読んだ後、直ぐに返事を書きました。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "メールを読[よ]んだ後[あと]、直[す]ぐに返事[へんじ]を書[か]きました。", "sentence_source": "generated"}, {"text": "注文した料理は直ぐに運ばれてきた。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]した料理[りょうり]は直[す]ぐに運[はこ]ばれてきた。", "sentence_source": "generated"}, {"text": "危ないので、直ぐ逃げてください。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "危[あぶ]ないので、直[す]ぐ逃[に]げてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直ぐ", "label": "基本形"}, {"form": "直ぐに", "label": "に形"}], "register": "neutral", "sense_fingerprint": "adverb: immediately, without delay after a trigger", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直ぐ", "is_correct": true, "explanation": "「直ぐに出ました」となり、電話が鳴ってすぐに出たという意味で文が通る。"}, {"text": "必ず", "is_correct": false, "explanation": "確実さを表す副詞だが、「直ぐ」の位置に入れると「必ずに出ました」は意味が通らない。"}, {"text": "まず", "is_correct": false, "explanation": "順序を表す副詞だが、「まずに出ました」は文として成り立たない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "速さを表す副詞だが、「ゆっくりに出ました」は意味が通らない。"}], "explanations": {"直ぐ": "「直ぐに出ました」となり、電話が鳴ってすぐに出たという意味で文が通る。", "必ず": "確実さを表す副詞だが、「直ぐ」の位置に入れると「必ずに出ました」は意味が通らない。", "まず": "順序を表す副詞だが、「まずに出ました」は文として成り立たない。", "ゆっくり": "速さを表す副詞だが、「ゆっくりに出ました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "直ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜道を直ぐ歩いた。", "explanation": "ここは〈ゆっくり〉の意味。「直ぐ」は時間が短いことを表すため、歩く速さを表す〈ゆっくり〉の代わりにはならない。"}, {"text": "彼女は直ぐに夢を追い続けた。", "explanation": "ここは〈長い間〉の意味。「直ぐに」は時間が近いことを表すため、長く続けた「追い続けた」とは合わない。"}, {"text": "試験は直ぐに三時間続いた。", "explanation": "ここは〈しばらく〉の意味。「直ぐに」は時間の近さを表すので、三時間にわたる経過を表す〈しばらく〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直ぐ", "is_correct": true, "explanation": "「薬を飲んだら、直ぐに熱が下がった」となり、飲んですぐ熱が下がったという意味で文が通る。"}, {"text": "少し", "is_correct": false, "explanation": "程度を表す副詞だが、「少しに熱が下がった」は文として成り立たない。"}, {"text": "大体", "is_correct": false, "explanation": "おおよそを表す副詞だが、「大体に熱が下がった」は意味が通らない。"}, {"text": "いつも", "is_correct": false, "explanation": "頻度を表す副詞だが、「いつもに熱が下がった」は文として成り立たない。"}], "explanations": {"直ぐ": "「薬を飲んだら、直ぐに熱が下がった」となり、飲んですぐ熱が下がったという意味で文が通る。", "少し": "程度を表す副詞だが、「少しに熱が下がった」は文として成り立たない。", "大体": "おおよそを表す副詞だが、「大体に熱が下がった」は意味が通らない。", "いつも": "頻度を表す副詞だが、「いつもに熱が下がった」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "直ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一時間も直ぐに待った。", "explanation": "ここは〈じっくり〉の意味。「直ぐに」は時間が近いことを表すため、時間をかけて待つ〈じっくり〉の代わりにはならない。"}, {"text": "ずっと前から直ぐに住んでいた。", "explanation": "ここは〈以前から〉の意味。「直ぐに」は時間の近さを表すため、長い期間を指す〈以前から〉の代わりにはならない。"}, {"text": "少しずつ直ぐに進んだ。", "explanation": "ここは〈徐々に〉の意味。「直ぐに」は即時性を表すため、段階を踏んで進む〈徐々に〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベルが鳴ったので、直ぐを出た。", "corrected_sentence": "ベルが鳴ったので、直ぐに出た。", "error_description": "誤りは「直ぐを」の「を」。「直ぐ」は副詞なので目的格の「を」は付かず、「直ぐに出た」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "メールを読んだら、直ぐな返事を書いた。", "corrected_sentence": "メールを読んだら、直ぐに返事を書いた。", "error_description": "誤りは「直ぐな」の「な」。「直ぐ」は形容動詞の語幹ではないので「な」は付かない。ここは動詞「書いた」を修飾するため「直ぐに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
