INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38617, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "物事が行われるまでの時間が短いさま。すぐに。", "primary_collocate": null, "pronunciation": "すぐ", "ipa": "sɯɡɯ", "syllable_count": 2, "sentences": [{"text": "電車は直ぐ来ますから、ここで待ちましょう。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は直[す]ぐ来[き]ますから、ここで待[ま]ちましょう。", "sentence_source": "generated"}, {"text": "春休みが終わって、直ぐ新学期が始まる。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "春休[はるやす]みが終[お]わって、直[す]ぐ新学期[しんがっき]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "母は直ぐ帰ってくると言って出かけた。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "母[はは]は直[す]ぐ帰[かえ]ってくると言[い]って出[で]かけた。", "sentence_source": "generated"}, {"text": "食事の用意は直ぐできますよ。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "食事[しょくじ]の用意[ようい]は直[す]ぐできますよ。", "sentence_source": "generated"}, {"text": "もう直ぐ夏休みが始まります。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "もう直[す]ぐ夏休[なつやす]みが始[はじ]まります。", "sentence_source": "generated"}, {"text": "直ぐ終わる仕事なので、手伝わなくていいです。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "直[す]ぐ終[お]わる仕事[しごと]なので、手伝[てつだ]わなくていいです。", "sentence_source": "generated"}, {"text": "授業が終わって直ぐ、友達と図書館へ行った。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わって直[す]ぐ、友達[ともだち]と図書館[としょかん]へ行[い]った。", "sentence_source": "generated"}, {"text": "会議はもう直ぐ終わるはずだ。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "会議[かいぎ]はもう直[す]ぐ終[お]わるはずだ。", "sentence_source": "generated"}, {"text": "直ぐ戻りますので、少々お待ちください。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "直[す]ぐ戻[もど]りますので、少々[しょうしょう]お待[ま]ちください。", "sentence_source": "generated"}, {"text": "引っ越してから直ぐ、新しい友達ができた。", "target_word": "直ぐ", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから直[す]ぐ、新[あたら]しい友達[ともだち]ができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直ぐ", "label": "基本形"}, {"form": "直ぐに", "label": "に形"}, {"form": "もう直ぐ", "label": "もう付き形"}], "register": "neutral", "sense_fingerprint": "adverb: soon, only a short time until something happens", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38617, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直ぐ", "is_correct": true, "explanation": "「電車は直ぐ来ますから」となり、間もなく来るという意味で文が通る。"}, {"text": "ぐるぐる", "is_correct": false, "explanation": "回る様子を表す擬態語で、「電車はぐるぐる来ますから」は意味が通らない。"}, {"text": "ぴょんぴょん", "is_correct": false, "explanation": "跳ねる様子を表す擬態語で、「電車はぴょんぴょん来ますから」は成り立たない。"}, {"text": "きらきら", "is_correct": false, "explanation": "光る様子を表す擬態語で、「電車はきらきら来ますから」は意味が通らない。"}], "explanations": {"直ぐ": "「電車は直ぐ来ますから」となり、間もなく来るという意味で文が通る。", "ぐるぐる": "回る様子を表す擬態語で、「電車はぐるぐる来ますから」は意味が通らない。", "ぴょんぴょん": "跳ねる様子を表す擬態語で、「電車はぴょんぴょん来ますから」は成り立たない。", "きらきら": "光る様子を表す擬態語で、「電車はきらきら来ますから」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "直ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は一時間後に直ぐ始まる。", "explanation": "ここは〈のちほど〉の意味。「直ぐ」は時間の近さを表すので、一時間後という先の時点を指す〈のちほど〉の代わりにはならない。"}, {"text": "その計画は直ぐ実行されるまで何年もかかった。", "explanation": "ここは〈ようやく〉の意味。「直ぐ」は時間の近さを表すため、長い年月を経た結果を表す〈ようやく〉の代わりにはならない。"}, {"text": "電車は一時間に直ぐ一本しか来ない。", "explanation": "ここは〈たまに〉の意味。「直ぐ」は間近の時間を指すため、間隔をあけて現れる〈たまに〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38617, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直ぐ", "is_correct": true, "explanation": "「授業が終わって直ぐ、友達と図書館へ行った」となり、終わってすぐ行ったという意味で文が通る。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "柔らかく浮く様子を表す擬態語で、「授業が終わってふわふわ」は意味が通らない。"}, {"text": "ごろごろ", "is_correct": false, "explanation": "転がる様子を表す擬態語で、「授業が終わってごろごろ」は文として成り立たない。"}, {"text": "にこにこ", "is_correct": false, "explanation": "笑顔の様子を表す擬態語で、「授業が終わってにこにこ」は意味が通らない。"}], "explanations": {"直ぐ": "「授業が終わって直ぐ、友達と図書館へ行った」となり、終わってすぐ行ったという意味で文が通る。", "ふわふわ": "柔らかく浮く様子を表す擬態語で、「授業が終わってふわふわ」は意味が通らない。", "ごろごろ": "転がる様子を表す擬態語で、「授業が終わってごろごろ」は文として成り立たない。", "にこにこ": "笑顔の様子を表す擬態語で、「授業が終わってにこにこ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "直ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三年前に直ぐ引っ越した。", "explanation": "ここは〈さっき〉の意味。「直ぐ」は時間の近さを表すため、過去の一点を指す〈さっき〉の代わりにはならない。"}, {"text": "長い間、直ぐ待つことになった。", "explanation": "ここは〈じっくり〉の意味。「直ぐ」は時間が近いことを表すため、時間をかけて待つ〈じっくり〉の代わりにはならない。"}, {"text": "雨が直ぐ三日間続いた。", "explanation": "ここは〈ずっと〉の意味。「直ぐ」は間近の時間を指すため、三日間続く経過を表す〈ずっと〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38617, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスは直ぐな来ますから、ここで待ちましょう。", "corrected_sentence": "バスは直ぐ来ますから、ここで待ちましょう。", "error_description": "誤りは「直ぐな」の「な」。「直ぐ」は副詞なので、動詞「来ます」の前には「な」を付けず、そのまま「直ぐ来ます」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38617, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新学期は直ぐを始まる。", "corrected_sentence": "新学期は直ぐ始まる。", "error_description": "誤りは「直ぐを」の「を」。「直ぐ」は副詞なので「を」は付かず、「始まる」は自動詞なので目的語も取らない。「直ぐ始まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「法律の分野で働く」の〈で〉。働く場所や活動の範囲を示す〈で〉。"}, {"text": "を", "is_correct": false, "explanation": "「分野を働く」は成り立たない。〈を〉は動作の対象を示すが、「働く」は対象を取らない。"}, {"text": "に", "is_correct": false, "explanation": "「分野に働く」は不自然。「働く」は場所を表す〈で〉を取るので、〈に〉は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「分野へ働く」は方向を示す〈へ〉が合わず、働く場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "「法律の分野で働く」の〈で〉。働く場所や活動の範囲を示す〈で〉。", "を": "「分野を働く」は成り立たない。〈を〉は動作の対象を示すが、「働く」は対象を取らない。", "に": "「分野に働く」は不自然。「働く」は場所を表す〈で〉を取るので、〈に〉は合わない。", "へ": "「分野へ働く」は方向を示す〈へ〉が合わず、働く場所を表せない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「分野」とは、学問や仕事などで分けられた一つの範囲のことです。", "primary_collocate": null, "pronunciation": "ぶんや", "ipa": "bɯɴja", "syllable_count": 3, "sentences": [{"text": "大学では、自分が学びたい分野を選んで専攻を決める。", "target_word": "分野", "complexity_tier": "T3", "furigana": "大学[だいがく]では、自分[じぶん]が学[まな]びたい分野[ぶんや]を選[えら]んで専攻[せんこう]を決[き]める。", "sentence_source": "generated"}, {"text": "法律の分野で働くために、彼は毎日勉強している。", "target_word": "分野", "complexity_tier": "T3", "furigana": "法律[ほうりつ]の分野[ぶんや]で働[はたら]くために、彼[かれ]は毎日[まいにち]勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "この雑誌は、科学のさまざまな分野の話題を取り上げている。", "target_word": "分野", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は、科学[かがく]のさまざまな分野[ぶんや]の話題[わだい]を取[と]り上[あ]げている。", "sentence_source": "generated"}, {"text": "私は数学が好きだが、文学の分野はあまり得意ではない。", "target_word": "分野", "complexity_tier": "T3", "furigana": "私[わたし]は数学[すうがく]が好[す]きだが、文学[ぶんがく]の分野[ぶんや]はあまり得意[とくい]ではない。", "sentence_source": "generated"}, {"text": "同じ会社でも、営業と開発では分野が違うので仕事の内容も大きく異なる。", "target_word": "分野", "complexity_tier": "T3", "furigana": "同[おな]じ会社[かいしゃ]でも、営業[えいぎょう]と開発[かいはつ]では分野[ぶんや]が違[ちが]うので仕事[しごと]の内容[ないよう]も大[おお]きく異[こと]なる。", "sentence_source": "generated"}, {"text": "新しい分野に挑戦するのは不安だが、やりがいもある。", "target_word": "分野", "complexity_tier": "T3", "furigana": "新[あたら]しい分野[ぶんや]に挑戦[ちょうせん]するのは不安[ふあん]だが、やりがいもある。", "sentence_source": "generated"}, {"text": "彼女は教育の分野で長年活躍し、多くの賞を受けた。", "target_word": "分野", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は教育[きょういく]の分野[ぶんや]で長年[ながねん]活躍[かつやく]し、多[おお]くの賞[しょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "図書館の本は、分野ごとに棚が分けられている。", "target_word": "分野", "complexity_tier": "T3", "furigana": "図書館[としょかん]の本[ほん]は、分野[ぶんや]ごとに棚[たな]が分[わ]けられている。", "sentence_source": "generated"}, {"text": "専門の分野以外のことは、私にはよくわかりません。", "target_word": "分野", "complexity_tier": "T3", "furigana": "専門[せんもん]の分野[ぶんや]以外[いがい]のことは、私[わたし]にはよくわかりません。", "sentence_source": "generated"}, {"text": "スポーツの分野では、若い選手がどんどん記録を更新している。", "target_word": "分野", "complexity_tier": "T3", "furigana": "スポーツの分野[ぶんや]では、若[わか]い選手[せんしゅ]がどんどん記録[きろく]を更新[こうしん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分野", "label": "基本形"}], "register": "中立", "sense_fingerprint": "学問や仕事などで区分けされた一つの範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分野", "is_correct": true, "explanation": "「学びたい分野を選んで」は、学ぶ領域を選ぶという意味で、専攻を決める文脈に合う。"}, {"text": "距離", "is_correct": false, "explanation": "「学びたい距離を選んで」は成り立たない。距離は学ぶ対象にならない。"}, {"text": "音量", "is_correct": false, "explanation": "「学びたい音量を選んで」は不自然。音量は学ぶ対象ではなく、専攻とも関係がない。"}, {"text": "体重", "is_correct": false, "explanation": "「学びたい体重を選んで」は成り立たない。体重は専攻の対象にならない。"}], "explanations": {"分野": "「学びたい分野を選んで」は、学ぶ領域を選ぶという意味で、専攻を決める文脈に合う。", "距離": "「学びたい距離を選んで」は成り立たない。距離は学ぶ対象にならない。", "音量": "「学びたい音量を選んで」は不自然。音量は学ぶ対象ではなく、専攻とも関係がない。", "体重": "「学びたい体重を選んで」は成り立たない。体重は専攻の対象にならない。"}, "sentence_index": 0, "correct_answer": "分野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝ジョギングをして、分野を鍛えている。", "explanation": "〈体を鍛える〉の代わりに〈分野〉を置いた誤用。鍛えるのは体や力で、学問や仕事の範囲は鍛えない。"}, {"text": "この絵は分野がとても鮮やかで、見る人の目を引く。", "explanation": "〈色が鮮やか〉の代わりに〈分野〉を置いた誤用。鮮やかなのは色や絵で、範囲を指す分野には使わない。"}, {"text": "この布は分野を半分に折って、きれいにしまった。", "explanation": "〈布を半分に折る〉の代わりに〈分野〉を置いた誤用。折るのは布や紙で、範囲を指す分野は折れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分野", "is_correct": true, "explanation": "「教育の分野で長年活躍し」は、教育という領域で活動したという意味で、文の意味に合う。"}, {"text": "対象", "is_correct": false, "explanation": "「教育の対象で長年活躍し」は不自然。対象は働きかける相手を指し、活躍する場を表さない。"}, {"text": "機械", "is_correct": false, "explanation": "「教育の機械で長年活躍し」は成り立たない。機械は活躍する領域を表さない。"}, {"text": "言語", "is_correct": false, "explanation": "「教育の言語で長年活躍し」は不自然。言語は活動の領域を指す語ではない。"}], "explanations": {"分野": "「教育の分野で長年活躍し」は、教育という領域で活動したという意味で、文の意味に合う。", "対象": "「教育の対象で長年活躍し」は不自然。対象は働きかける相手を指し、活躍する場を表さない。", "機械": "「教育の機械で長年活躍し」は成り立たない。機械は活躍する領域を表さない。", "言語": "「教育の言語で長年活躍し」は不自然。言語は活動の領域を指す語ではない。"}, "sentence_index": 6, "correct_answer": "分野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学芸会で、子どもたちが分野を大きな声で歌った。", "explanation": "〈歌を歌う〉の代わりに〈分野〉を置いた誤用。歌うのは歌や曲で、学問や仕事の範囲は歌えない。"}, {"text": "朝から分野が降っていた。", "explanation": "〈雨が降る〉の代わりに〈分野〉を置いた誤用。降るのは雨や雪などで、範囲を指す分野は降らない。"}, {"text": "テストの結果で、分野がぐっと上がった。", "explanation": "〈点数が上がる〉の代わりに〈分野〉を置いた誤用。上がるのは点数や値段などの数値で、分野は上がらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学では、興味のある分野に専攻する学生が多い。", "corrected_sentence": "大学では、興味のある分野を専攻する学生が多い。", "error_description": "「専攻する」は目的語に「を」を取る。「に」にすると文がつながらず、正しくは「分野を専攻する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38618, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この分野で詳しい人を紹介してもらった。", "corrected_sentence": "この分野に詳しい人を紹介してもらった。", "error_description": "「～に詳しい」は「に」を取る。「で」にすると意味がつながらず、正しくは「分野に詳しい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「医学の分野で知られた」の〈で〉。活動や知名度の範囲を示す場所の〈で〉。"}, {"text": "を", "is_correct": false, "explanation": "「分野を知られた」は成り立たない。〈を〉は動作の対象を示すが、「知られる」は対象を取らない。"}, {"text": "へ", "is_correct": false, "explanation": "「分野へ知られた」は方向を示す〈へ〉が合わず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「分野と知られた」は相手や共同を示す〈と〉が合わず、文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「医学の分野で知られた」の〈で〉。活動や知名度の範囲を示す場所の〈で〉。", "を": "「分野を知られた」は成り立たない。〈を〉は動作の対象を示すが、「知られる」は対象を取らない。", "へ": "「分野へ知られた」は方向を示す〈へ〉が合わず、不自然。", "と": "「分野と知られた」は相手や共同を示す〈と〉が合わず、文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「分野に進んだ」の〈に〉。進む先や到達点を示す〈に〉。"}, {"text": "と", "is_correct": false, "explanation": "「分野と進んだ」は相手や共同を示す〈と〉が合わず、意味がつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「分野の進んだ」は名詞と動詞がつながらず、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「分野より進んだ」は比較を示す〈より〉が合わず、進んだ先を表せない。"}], "correct_answer": "に", "explanations": {"に": "「分野に進んだ」の〈に〉。進む先や到達点を示す〈に〉。", "と": "「分野と進んだ」は相手や共同を示す〈と〉が合わず、意味がつながらない。", "の": "「分野の進んだ」は名詞と動詞がつながらず、文として成り立たない。", "より": "「分野より進んだ」は比較を示す〈より〉が合わず、進んだ先を表せない。"}, "error_tags": {"と": "相手", "の": "所属", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄や活動を種類や性質によって分けたときの範囲。領域。", "primary_collocate": null, "pronunciation": "ぶんや", "ipa": "bɯɴja", "syllable_count": 3, "sentences": [{"text": "近年、パラメトリックデザインの理論は、都市主義の分野において重要な基盤となりつつあります。", "target_word": "分野", "complexity_tier": "T4", "furigana": "近年[きんねん]、パラメトリックデザインの理論[りろん]は、都市主義[としゅぎ]の分野[ぶんや]において重要[じゅうよう]な基盤[きばん]となりつつあります。", "sentence_source": "mined"}, {"text": "彼女は医学の分野で世界的に知られた研究者だ。", "target_word": "分野", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は医学[いがく]の分野[ぶんや]で世界的[せかいてき]に知[し]られた研究者[けんきゅうしゃ]だ。", "sentence_source": "generated"}, {"text": "この分野に興味がある人は、まず入門書から読むといい。", "target_word": "分野", "complexity_tier": "T3", "furigana": "この分野[ぶんや]に興味[きょうみ]がある人[ひと]は、まず入門書[にゅうもんしょ]から読[よ]むといい。", "sentence_source": "generated"}, {"text": "私の専門はコンピューターの分野で、毎日新しい技術を学んでいる。", "target_word": "分野", "complexity_tier": "T3", "furigana": "私[わたし]の専門[せんもん]はコンピューターの分野[ぶんや]で、毎日[まいにち]新[あたら]しい技術[ぎじゅつ]を学[まな]んでいる。", "sentence_source": "generated"}, {"text": "料理の分野では、彼に勝てる人はなかなかいない。", "target_word": "分野", "complexity_tier": "T3", "furigana": "料理[りょうり]の分野[ぶんや]では、彼[かれ]に勝[か]てる人[ひと]はなかなかいない。", "sentence_source": "generated"}, {"text": "学校では、自分が得意な分野を伸ばすことも大切にしている。", "target_word": "分野", "complexity_tier": "T3", "furigana": "学校[がっこう]では、自分[じぶん]が得意[とくい]な分野[ぶんや]を伸[の]ばすことも大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "AIの分野は進歩が速く、去年の知識はもう古くなってしまう。", "target_word": "分野", "complexity_tier": "T3", "furigana": "AIの分野[ぶんや]は進歩[しんぽ]が速[はや]く、去年[きょねん]の知識[ちしき]はもう古[ふる]くなってしまう。", "sentence_source": "generated"}, {"text": "兄とは違う分野に進んだが、今も仕事の相談をし合っている。", "target_word": "分野", "complexity_tier": "T3", "furigana": "兄[あに]とは違[ちが]う分野[ぶんや]に進[すす]んだが、今[いま]も仕事[しごと]の相談[そうだん]をし合[あ]っている。", "sentence_source": "generated"}, {"text": "環境問題は一つの分野だけでは解決できないので、多くの専門家が協力している。", "target_word": "分野", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]は一[ひと]つの分野[ぶんや]だけでは解決[かいけつ]できないので、多[おお]くの専門家[せんもんか]が協力[きょうりょく]している。", "sentence_source": "generated"}, {"text": "彼は音楽だけでなく、美術の分野でも才能を見せた。", "target_word": "分野", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]だけでなく、美術[びじゅつ]の分野[ぶんや]でも才能[さいのう]を見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分野", "label": "基本形"}], "register": "中立", "sense_fingerprint": "学問・仕事・活動を種類で区切ったときの一つの領域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分野", "is_correct": true, "explanation": "「都市主義の分野において」は、都市主義という領域の範囲を指し、文の意味に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「都市主義の年齢において」は言えない。年齢は人の歳を指し、学問や領域の範囲には当たらない。"}, {"text": "期限", "is_correct": false, "explanation": "「都市主義の期限において」は成り立たない。期限は締め切りを指し、領域を表さない。"}, {"text": "感想", "is_correct": false, "explanation": "「都市主義の感想において」は不自然。感想は受けた印象を指し、学問の範囲を表さない。"}], "explanations": {"分野": "「都市主義の分野において」は、都市主義という領域の範囲を指し、文の意味に合う。", "年齢": "「都市主義の年齢において」は言えない。年齢は人の歳を指し、学問や領域の範囲には当たらない。", "期限": "「都市主義の期限において」は成り立たない。期限は締め切りを指し、領域を表さない。", "感想": "「都市主義の感想において」は不自然。感想は受けた印象を指し、学問の範囲を表さない。"}, "sentence_index": 0, "correct_answer": "分野"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は分野を重ねて、とても大人びて見えた。", "explanation": "〈年齢を重ねる〉の代わりに〈分野〉を置いた誤用。分野は学問や仕事の範囲で、積み重ねる対象ではない。"}, {"text": "この料理は分野が濃くて、食べやすい。", "explanation": "〈味が濃い〉の代わりに〈分野〉を置いた誤用。濃いのは味や色の性質で、学問の範囲には使わない。"}, {"text": "寒いので、部屋の分野を開けて換気した。", "explanation": "〈窓を開ける〉の意味で使う誤用。窓のように開けて空気を通す物ではないので、分野は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分野", "is_correct": true, "explanation": "「AIの分野は進歩が速く」は、AIという領域について述べる主語として文の意味に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「AIの温度は進歩が速く」は成り立たない。温度は進歩するものではない。"}, {"text": "理由", "is_correct": false, "explanation": "「AIの理由は進歩が速く」は意味がつながらない。理由は説明の根拠を指し、進歩の速さを述べる主語にならない。"}, {"text": "距離", "is_correct": false, "explanation": "「AIの距離は進歩が速く」は不自然。距離は進歩の速さを述べる主語になりにくい。"}], "explanations": {"分野": "「AIの分野は進歩が速く」は、AIという領域について述べる主語として文の意味に合う。", "温度": "「AIの温度は進歩が速く」は成り立たない。温度は進歩するものではない。", "理由": "「AIの理由は進歩が速く」は意味がつながらない。理由は説明の根拠を指し、進歩の速さを述べる主語にならない。", "距離": "「AIの距離は進歩が速く」は不自然。距離は進歩の速さを述べる主語になりにくい。"}, "sentence_index": 6, "correct_answer": "分野"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後になって、分野がすっかり晴れてきた。", "explanation": "〈空が晴れる〉の代わりに〈分野〉を置いた誤用。晴れるのは空や天気で、学問の範囲は晴れない。"}, {"text": "大きな鍋の分野を強火で沸かした。", "explanation": "〈鍋の湯を沸かす〉の代わりに〈分野〉を置いた誤用。沸かすのは液体で、範囲を指す分野は沸かせない。"}, {"text": "セーターの分野がほどけてしまった。", "explanation": "〈糸がほどける〉の代わりに〈分野〉を置いた誤用。ほどけるのは糸などの細長い物で、分野はほどけない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は音楽の分野に活躍している。", "corrected_sentence": "彼女は音楽の分野で活躍している。", "error_description": "「活躍する」は場所を表す「で」を取る。「に」にすると不自然になり、正しくは「分野で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38619, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この分野が専門家に相談した。", "corrected_sentence": "この分野の専門家に相談した。", "error_description": "「分野が」と〈が〉を付けると分野が主語になり、「相談した」と合わない。分野は相談できないので文が成り立たない。正しくは「分野の専門家」と〈の〉でつなぎ、その専門家に相談する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
