INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38620, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "分子は、ものをつくる、とても小さなつぶです。", "primary_collocate": null, "pronunciation": "ぶんし", "ipa": "bɯɴɕi", "syllable_count": 3, "sentences": [{"text": "ものはすべて、とても小さな分子が集まってできている。", "target_word": "分子", "complexity_tier": "T3", "furigana": "ものはすべて、とても小[ちい]さな分子[ぶんし]が集[あつ]まってできている。", "sentence_source": "generated"}, {"text": "水の分子は小さすぎて、目では見えない。", "target_word": "分子", "complexity_tier": "T3", "furigana": "水[みず]の分子[ぶんし]は小[ちい]さすぎて、目[め]では見[み]えない。", "sentence_source": "generated"}, {"text": "氷になると、分子の動きがゆっくりになる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "氷[こおり]になると、分子[ぶんし]の動[うご]きがゆっくりになる。", "sentence_source": "generated"}, {"text": "先生は、分子の模型を使って説明してくれた。", "target_word": "分子", "complexity_tier": "T3", "furigana": "先生[せんせい]は、分子[ぶんし]の模型[もけい]を使[つか]って説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "分子がたくさん集まると、一つのかたまりになる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "分子[ぶんし]がたくさん集[あつ]まると、一[ひと]つのかたまりになる。", "sentence_source": "generated"}, {"text": "お湯の中では、分子が元気よく動き回っている。", "target_word": "分子", "complexity_tier": "T3", "furigana": "お湯[ゆ]の中[なか]では、分子[ぶんし]が元気[げんき]よく動[うご]き回[まわ]っている。", "sentence_source": "generated"}, {"text": "空気の分子が風船の中に入っているので、風船はふくらむ。", "target_word": "分子", "complexity_tier": "T3", "furigana": "空気[くうき]の分子[ぶんし]が風船[ふうせん]の中[なか]に入[はい]っているので、風船[ふうせん]はふくらむ。", "sentence_source": "generated"}, {"text": "においがするのは、分子が鼻まで飛んでくるからだ。", "target_word": "分子", "complexity_tier": "T3", "furigana": "においがするのは、分子[ぶんし]が鼻[はな]まで飛[と]んでくるからだ。", "sentence_source": "generated"}, {"text": "砂糖の分子は水に混ざって、見えなくなる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "砂糖[さとう]の分子[ぶんし]は水[みず]に混[ま]ざって、見[み]えなくなる。", "sentence_source": "generated"}, {"text": "普通の顕微鏡では、分子の一つ一つは見えない。", "target_word": "分子", "complexity_tier": "T3", "furigana": "普通[ふつう]の顕微鏡[けんびきょう]では、分子[ぶんし]の一[ひと]つ一[ひと]つは見[み]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "molecule explained simply: a very tiny particle that things are made of", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38620, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "ものをつくる、とても小さなつぶ。小さなつぶが集まってものができる、という文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "人が歌う旋律で、ものを作る小さなつぶとしては成り立たないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "見え方の性質で、ものを構成する小さなつぶとは言わないので合わない。"}, {"text": "音", "is_correct": false, "explanation": "聞こえる響きで、ものを構成するつぶとしては成り立たないので合わない。"}], "explanations": {"分子": "ものをつくる、とても小さなつぶ。小さなつぶが集まってものができる、という文に合う。", "歌": "人が歌う旋律で、ものを作る小さなつぶとしては成り立たないので合わない。", "色": "見え方の性質で、ものを構成する小さなつぶとは言わないので合わない。", "音": "聞こえる響きで、ものを構成するつぶとしては成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "光子は、光を運ぶ分子の一種だ。", "explanation": "ここは〈粒子〉の意味。光子は粒子の一種で、ものをつくる分子とは言わないので合わない。"}, {"text": "分子は、分裂して二つに増える。", "explanation": "ここは〈細胞〉の意味。細胞は分裂して二つに増えるが、分子は分裂して増えないので合わない。"}, {"text": "鉄は、磁石にくっつく分子だ。", "explanation": "ここは〈元素〉の意味。鉄は元素で、分子とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38620, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "空気を作る小さなつぶで、風船の中に入るものとして文に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "『一本』『一つ』で数える道具で、空気の成分にはならないので合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "身につける装飾品で、空気の中に入るものではないので合わない。"}, {"text": "切手", "is_correct": false, "explanation": "紙の郵便物で、風船の中に入る空気の成分ではないので合わない。"}], "explanations": {"分子": "空気を作る小さなつぶで、風船の中に入るものとして文に合う。", "鍵": "『一本』『一つ』で数える道具で、空気の成分にはならないので合わない。", "指輪": "身につける装飾品で、空気の中に入るものではないので合わない。", "切手": "紙の郵便物で、風船の中に入る空気の成分ではないので合わない。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分子は、普通の顕微鏡で一つ一つ見ることができる。", "explanation": "ここは〈細菌〉の意味。普通の顕微鏡で一つずつ見えるのは細菌で、分子は見えないので合わない。"}, {"text": "分子は、周期表の中で番号順に並んでいる。", "explanation": "ここは〈元素〉の意味。分子は元素が結びついた粒で、周期表の番号順には並ばないので合わない。"}, {"text": "分子は、宿主の細胞の中で数を増やす。", "explanation": "ここは〈ウイルス〉の意味。ウイルスは宿主の細胞の中で増えるが、分子はそうしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38620, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分子に組み合わせると、いろいろなものができる。", "corrected_sentence": "分子を組み合わせると、いろいろなものができる。", "error_description": "誤: 分子に / 正: 分子を。『組み合わせる』は分子を目的語に取るので『を』が必要。『に』では対象が立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38620, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分子は、熱を受けると速く動き回らせる。", "corrected_sentence": "分子は、熱を受けると速く動き回る。", "error_description": "誤: 動き回らせる / 正: 動き回る。分子が自分で動くので自動詞『動き回る』が正しい。『〜らせる』は使役で、動かす主体がいないので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
