INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38621, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "分子とは、物質を構成する最小の単位で、化学的な性質を持つ粒子のこと。", "primary_collocate": null, "pronunciation": "ぶんし", "ipa": "bɯɴɕi", "syllable_count": 3, "sentences": [{"text": "香水の分子は、空気中へ少しずつ散っていく。", "target_word": "分子", "complexity_tier": "T5", "furigana": "香水[こうすい]の分子[ぶんし]は、空気中[くうきちゅう]へ少[すこ]しずつ散[ち]っていく。", "sentence_source": "generated"}, {"text": "水の分子は、酸素原子一つと水素原子二つでできている。", "target_word": "分子", "complexity_tier": "T3", "furigana": "水[みず]の分子[ぶんし]は、酸素原子[さんそげんし]一[ひと]つと水素原子[すいそげんし]二[ふた]つでできている。", "sentence_source": "generated"}, {"text": "温度が上がると、分子の動きが速くなる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "温度[おんど]が上[あ]がると、分子[ぶんし]の動[うご]きが速[はや]くなる。", "sentence_source": "generated"}, {"text": "分子が大きいほど、体に吸収されにくい。", "target_word": "分子", "complexity_tier": "T3", "furigana": "分子[ぶんし]が大[おお]きいほど、体[からだ]に吸収[きゅうしゅう]されにくい。", "sentence_source": "generated"}, {"text": "酸素は二つの原子が結びついた分子として空気中に存在する。", "target_word": "分子", "complexity_tier": "T3", "furigana": "酸素[さんそ]は二[ふた]つの原子[げんし]が結[むす]びついた分子[ぶんし]として空気中[くうきちゅう]に存在[そんざい]する。", "sentence_source": "generated"}, {"text": "この研究室では、タンパク質の分子の形を調べている。", "target_word": "分子", "complexity_tier": "T3", "furigana": "この研究室[けんきゅうしつ]では、タンパク質[しつ]の分子[ぶんし]の形[かたち]を調[しら]べている。", "sentence_source": "generated"}, {"text": "香りが遠くまで届くのは、においの分子が空気中を広がるからだ。", "target_word": "分子", "complexity_tier": "T3", "furigana": "香[かお]りが遠[とお]くまで届[とど]くのは、においの分子[ぶんし]が空気中[くうきちゅう]を広[ひろ]がるからだ。", "sentence_source": "generated"}, {"text": "砂糖の分子は水の中でばらばらに散らばって、見えなくなる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "砂糖[さとう]の分子[ぶんし]は水[みず]の中[なか]でばらばらに散[ち]らばって、見[み]えなくなる。", "sentence_source": "generated"}, {"text": "分子の構造を知れば、薬が効く理由を説明できる。", "target_word": "分子", "complexity_tier": "T3", "furigana": "分子[ぶんし]の構造[こうぞう]を知[し]れば、薬[くすり]が効[き]く理由[りゆう]を説明[せつめい]できる。", "sentence_source": "generated"}, {"text": "氷が溶けても、水の分子そのものは変わらない。", "target_word": "分子", "complexity_tier": "T3", "furigana": "氷[こおり]が溶[と]けても、水[みず]の分子[ぶんし]そのものは変[か]わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子", "label": "基本形"}], "register": "technical", "sense_fingerprint": "molecule: smallest unit of a substance that keeps its chemical properties", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38621, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "香りの成分となる粒で、空気中へ散っていく主体になる。文の意味に合う。"}, {"text": "電子", "is_correct": false, "explanation": "原子の中の粒子で、香水の成分が空気中へ散るとは言えないので合わない。"}, {"text": "核", "is_correct": false, "explanation": "原子の中心部分で、香水が空気中へ散る主体にはならないので合わない。"}, {"text": "鉱物", "is_correct": false, "explanation": "自然にできる固体で、香水が空気中へ散るとは言わないので合わない。"}], "explanations": {"分子": "香りの成分となる粒で、空気中へ散っていく主体になる。文の意味に合う。", "電子": "原子の中の粒子で、香水の成分が空気中へ散るとは言えないので合わない。", "核": "原子の中心部分で、香水が空気中へ散る主体にはならないので合わない。", "鉱物": "自然にできる固体で、香水が空気中へ散るとは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電子は、マイナスの電気をもつ分子だ。", "explanation": "ここは〈粒子〉の意味。電子は粒子の一種で、分子とは言わないので合わない。"}, {"text": "分子は、核と細胞膜に囲まれている。", "explanation": "ここは〈細胞〉の意味。核と細胞膜で囲まれるのは細胞で、分子には当てはまらないので合わない。"}, {"text": "分子は、熱を加えると死んでしまう。", "explanation": "ここは〈細菌〉の意味。細菌は生き物なので熱で死ぬが、分子は生き物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38621, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "においを運ぶ粒子で、空気中を広がる主体になる。文の意味に合う。"}, {"text": "声", "is_correct": false, "explanation": "人や動物が発する音で、においが空気中を広がる主体としては成り立たないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "見た目の性質で、においが空気中を広がる主体としては合わないので文に合わない。"}, {"text": "光", "is_correct": false, "explanation": "光は空気中を進むが、においの成分ではないので『においの光が広がる』は合わない。"}], "explanations": {"分子": "においを運ぶ粒子で、空気中を広がる主体になる。文の意味に合う。", "声": "人や動物が発する音で、においが空気中を広がる主体としては成り立たないので合わない。", "色": "見た目の性質で、においが空気中を広がる主体としては合わないので文に合わない。", "光": "光は空気中を進むが、においの成分ではないので『においの光が広がる』は合わない。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分子は、周期表の決まった場所に並んでいる。", "explanation": "ここは〈元素〉の意味。分子は元素が結びついた粒なので、周期表の決まった場所には並ばないので合わない。"}, {"text": "分子は、細胞の中に入り込んで、自分のコピーをつくる。", "explanation": "ここは〈ウイルス〉の意味。ウイルスは細胞に入り込んで増えるが、分子はそのような増え方をしないので合わない。"}, {"text": "分子は、陽子と中性子からできている。", "explanation": "ここは〈原子〉の意味。分子は原子が結びついたもので、陽子と中性子からできているとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38621, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分子に熱すると、分子同士の間隔が広がる。", "corrected_sentence": "分子を熱すると、分子同士の間隔が広がる。", "error_description": "誤: 分子に / 正: 分子を。『熱する』は対象を『を』で示す。『に』では熱する対象が立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38621, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分子は、温度が上がると速く動かす。", "corrected_sentence": "分子は、温度が上がると速く動く。", "error_description": "誤: 動かす / 正: 動く。分子が自分で動くので自動詞の『動く』が正しい。『動かす』は他動詞で、動かす対象（〜を）が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「酸素と化合」の「と」。化合の相手を示す格助詞で、ここで正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。化合は相手を「と」で示すので、ここでは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。化合の相手は方向ではないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示す。化合の相手を示すには使えない。"}], "correct_answer": "と", "explanations": {"と": "「酸素と化合」の「と」。化合の相手を示す格助詞で、ここで正しい。", "を": "「を」は目的語を示す。化合は相手を「と」で示すので、ここでは合わない。", "へ": "「へ」は方向を示す。化合の相手は方向ではないので合わない。", "より": "「より」は比較や起点を示す。化合の相手を示すには使えない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になる現象で、化合の対義語ではない。"}, {"text": "沈殿", "is_correct": false, "explanation": "溶けた物質が底に沈む現象で、化合の対義語ではない。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固体になる現象で、化合の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。", "蒸発": "液体が気体になる現象で、化合の対義語ではない。", "沈殿": "溶けた物質が底に沈む現象で、化合の対義語ではない。", "凝固": "液体が固体になる現象で、化合の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。"}, {"text": "融合", "is_correct": false, "explanation": "二つのものが一つになる意味で、化合の対義語ではない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分が抜ける現象で、化合の対義語ではない。"}, {"text": "結晶", "is_correct": false, "explanation": "規則正しい固体の形ができる現象で、化合の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。", "融合": "二つのものが一つになる意味で、化合の対義語ではない。", "乾燥": "水分が抜ける現象で、化合の対義語ではない。", "結晶": "規則正しい固体の形ができる現象で、化合の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上のものがくっついて新しいものになること。", "primary_collocate": null, "pronunciation": "かごう", "ipa": "kaɡoː", "syllable_count": 3, "sentences": [{"text": "二つの物質が化合して、まったく新しいものになった。", "target_word": "化合", "complexity_tier": "T3", "furigana": "二[ふた]つの物質[ぶっしつ]が化合[かごう]して、まったく新[あたら]しいものになった。", "sentence_source": "generated"}, {"text": "鉄は空気中の酸素と化合して、さびになる。", "target_word": "化合", "complexity_tier": "T3", "furigana": "鉄[てつ]は空気中[くうきちゅう]の酸素[さんそ]と化合[かごう]して、さびになる。", "sentence_source": "generated"}, {"text": "ナトリウムと塩素が化合すると、塩ができる。", "target_word": "化合", "complexity_tier": "T3", "furigana": "ナトリウムと塩素[えんそ]が化合[かごう]すると、塩[しお]ができる。", "sentence_source": "generated"}, {"text": "化合した後の物は、元の姿とは全然違う。", "target_word": "化合", "complexity_tier": "T3", "furigana": "化合[かごう]した後[あと]の物[もの]は、元[もと]の姿[すがた]とは全然[ぜんぜん]違[ちが]う。", "sentence_source": "generated"}, {"text": "二つのものが化合する様子を、実験で見た。", "target_word": "化合", "complexity_tier": "T3", "furigana": "二[ふた]つのものが化合[かごう]する様子[ようす]を、実験[じっけん]で見[み]た。", "sentence_source": "generated"}, {"text": "熱を加えないと、この二つは化合しない。", "target_word": "化合", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えないと、この二[ふた]つは化合[かごう]しない。", "sentence_source": "generated"}, {"text": "炭素が酸素と化合して、二酸化炭素ができた。", "target_word": "化合", "complexity_tier": "T3", "furigana": "炭素[たんそ]が酸素[さんそ]と化合[かごう]して、二酸化炭素[にさんかたんそ]ができた。", "sentence_source": "generated"}, {"text": "化合は、新しいものが生まれる変化の一つだ。", "target_word": "化合", "complexity_tier": "T3", "furigana": "化合[かごう]は、新[あたら]しいものが生[う]まれる変化[へんか]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "銅と硫黄が化合して、黒い粉になった。", "target_word": "化合", "complexity_tier": "T3", "furigana": "銅[どう]と硫黄[いおう]が化合[かごう]して、黒[くろ]い粉[こな]になった。", "sentence_source": "generated"}, {"text": "先生は、くっついて新しいものになることを化合と言った。", "target_word": "化合", "complexity_tier": "T3", "furigana": "先生[せんせい]は、くっついて新[あたら]しいものになることを化合[かごう]と言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "化合", "label": "基本形"}, {"form": "化合する", "label": "辞書形"}, {"form": "化合して", "label": "て形"}, {"form": "化合した", "label": "た形"}], "register": "neutral", "sense_fingerprint": "noun (suru): two or more things join and become a new thing", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化合", "is_correct": true, "explanation": "二つのものがくっついて新しいものになる意味に合う。「二つの物質が化合して」として自然。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になって消える現象で、新しいものはできない。ここでは意味が合わない。"}, {"text": "溶解", "is_correct": false, "explanation": "溶けて全体に広がるだけで、新しいものはできない。結びついて新しいものになる意味には合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固体になることで、二つの物質が結びつく意味には合わない。"}], "explanations": {"化合": "二つのものがくっついて新しいものになる意味に合う。「二つの物質が化合して」として自然。", "蒸発": "液体が気体になって消える現象で、新しいものはできない。ここでは意味が合わない。", "溶解": "溶けて全体に広がるだけで、新しいものはできない。結びついて新しいものになる意味には合わない。", "凝固": "液体が固体になることで、二つの物質が結びつく意味には合わない。"}, "sentence_index": 0, "correct_answer": "化合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は二人の意見を化合させて、新しい案を作った。", "explanation": "ここは〈統合〉の意味。化合は物質が化学的に結びつくことで、意見には使わない。"}, {"text": "この二つの液体を化合させて、おいしい飲み物にした。", "explanation": "ここは〈混合〉の意味。ただ混ぜるだけで新しい物質ができない場合は、化合とは言わない。"}, {"text": "氷を化合させて、水にした。", "explanation": "ここは〈融解〉の意味。氷を溶かすことは化学反応ではないので、化合は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化合", "is_correct": true, "explanation": "炭素と酸素が結びつく意味に合い、「酸素と化合して」として自然。"}, {"text": "融解", "is_correct": false, "explanation": "固体が溶けて液体になることで、酸素と結びつく意味にはならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分が抜けて乾くことで、結びつく意味には合わない。"}, {"text": "結晶", "is_correct": false, "explanation": "規則正しい固体の形ができることで、ここでは化合の意味にはならない。"}], "explanations": {"化合": "炭素と酸素が結びつく意味に合い、「酸素と化合して」として自然。", "融解": "固体が溶けて液体になることで、酸素と結びつく意味にはならない。", "乾燥": "水分が抜けて乾くことで、結びつく意味には合わない。", "結晶": "規則正しい固体の形ができることで、ここでは化合の意味にはならない。"}, "sentence_index": 6, "correct_answer": "化合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの会社は化合して、業界最大の企業になった。", "explanation": "ここは〈合併〉の意味。会社の統合には化合を使わず、化学的に結びつく場合にだけ使う。"}, {"text": "二枚の写真を化合させて、一枚の絵にした。", "explanation": "ここは〈合成〉の意味。写真や絵を組み合わせることには化合は使わない。"}, {"text": "砂糖を水に化合させて、甘い液を作った。", "explanation": "ここは〈溶解〉の意味。砂糖が水に溶けるだけで新しい物質はできないので、化合は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄は湿った空気の中で酸素を化合して、さびになる。", "corrected_sentence": "鉄は湿った空気の中で酸素と化合して、さびになる。", "error_description": "「化合」は「〜と化合する」の形で、相手を「と」で示す。「酸素を化合」は誤りで、正しくは「酸素と化合して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験管の中で、炭素が酸素と化合しで、二酸化炭素が生じた。", "corrected_sentence": "試験管の中で、炭素が酸素と化合して、二酸化炭素が生じた。", "error_description": "「化合して」の「て」は清音。「化合しで」は濁音化した誤った活用形で、正しくは「化合して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固体になる現象で、化合の対義語ではない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分が抜ける現象で、化合の対義語ではない。"}, {"text": "結晶", "is_correct": false, "explanation": "規則正しい固体の形ができる現象で、化合の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。", "凝固": "液体が固体になる現象で、化合の対義語ではない。", "乾燥": "水分が抜ける現象で、化合の対義語ではない。", "結晶": "規則正しい固体の形ができる現象で、化合の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「化合の反応式」の「の」。化合が反応式を修飾する格助詞で、ここで正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。反応式を修飾する形では使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示す。化合を反応式の修飾に使う形では合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。化合を反応式の修飾に使う形では合わない。"}], "correct_answer": "の", "explanations": {"の": "「化合の反応式」の「の」。化合が反応式を修飾する格助詞で、ここで正しい。", "が": "「が」は主語を示す。反応式を修飾する形では使えない。", "に": "「に」は位置や相手を示す。化合を反応式の修飾に使う形では合わない。", "から": "「から」は起点を示す。化合を反応式の修飾に使う形では合わない。"}, "error_tags": {"が": "主語", "に": "位置", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。"}, {"text": "合成", "is_correct": false, "explanation": "複数のものを組み合わせる意味で、化合と近いが対義語ではない。"}, {"text": "溶解", "is_correct": false, "explanation": "固体が液体に溶ける現象で、化合の対義語ではない。"}, {"text": "増殖", "is_correct": false, "explanation": "生物が増える現象で、化合の対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "化合の対義語。結びついたものを元の成分に分けることで、化合と反対の関係にある。", "合成": "複数のものを組み合わせる意味で、化合と近いが対義語ではない。", "溶解": "固体が液体に溶ける現象で、化合の対義語ではない。", "増殖": "生物が増える現象で、化合の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "異なる元素や物質が化学反応により結合し、新しい物質を生成すること。", "primary_collocate": null, "pronunciation": "かごう", "ipa": "kaɡoː", "syllable_count": 3, "sentences": [{"text": "水素と酸素が化合して、水ができる。", "target_word": "化合", "complexity_tier": "T3", "furigana": "水素[すいそ]と酸素[さんそ]が化合[かごう]して、水[みず]ができる。", "sentence_source": "generated"}, {"text": "マグネシウムを燃やすと、酸素と化合して白い粉になる。", "target_word": "化合", "complexity_tier": "T3", "furigana": "マグネシウムを燃[も]やすと、酸素[さんそ]と化合[かごう]して白[しろ]い粉[こな]になる。", "sentence_source": "generated"}, {"text": "異なる元素が化合するとき、熱が出ることがある。", "target_word": "化合", "complexity_tier": "T3", "furigana": "異[こと]なる元素[げんそ]が化合[かごう]するとき、熱[ねつ]が出[で]ることがある。", "sentence_source": "generated"}, {"text": "この実験では、鉄と硫黄の化合を観察する。", "target_word": "化合", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、鉄[てつ]と硫黄[いおう]の化合[かごう]を観察[かんさつ]する。", "sentence_source": "generated"}, {"text": "化合によって生じた物質は、元の元素とは性質が違う。", "target_word": "化合", "complexity_tier": "T3", "furigana": "化合[かごう]によって生[しょう]じた物質[ぶっしつ]は、元[もと]の元素[げんそ]とは性質[せいしつ]が違[ちが]う。", "sentence_source": "generated"}, {"text": "窒素と水素が化合して、アンモニアが作られる。", "target_word": "化合", "complexity_tier": "T3", "furigana": "窒素[ちっそ]と水素[すいそ]が化合[かごう]して、アンモニアが作[つく]られる。", "sentence_source": "generated"}, {"text": "試験管の中で二つの物質が化合し、色が変わった。", "target_word": "化合", "complexity_tier": "T3", "furigana": "試験管[しけんかん]の中[なか]で二[ふた]つの物質[ぶっしつ]が化合[かごう]し、色[いろ]が変[か]わった。", "sentence_source": "generated"}, {"text": "化合の反応式を、ノートに書いてください。", "target_word": "化合", "complexity_tier": "T3", "furigana": "化合[かごう]の反応式[はんのうしき]を、ノートに書[か]いてください。", "sentence_source": "generated"}, {"text": "銀は硫黄と化合して、黒く変色する。", "target_word": "化合", "complexity_tier": "T3", "furigana": "銀[ぎん]は硫黄[いおう]と化合[かごう]して、黒[くろ]く変色[へんしょく]する。", "sentence_source": "generated"}, {"text": "触媒を使うと、化合が速く進む。", "target_word": "化合", "complexity_tier": "T3", "furigana": "触媒[しょくばい]を使[つか]うと、化合[かごう]が速[はや]く進[すす]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "化合", "label": "基本形"}, {"form": "化合する", "label": "辞書形"}, {"form": "化合して", "label": "て形"}, {"form": "化合し", "label": "連用形"}], "register": "technical", "sense_fingerprint": "chemistry noun (suru): different elements or substances bond by chemical reaction to form a new substance", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51f6fef-c8e6-47e0-b90a-e6b98643ce9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化合", "is_correct": true, "explanation": "異なる元素が化学反応で結びつく意味。水素と酸素が結びついて水ができることに合う。"}, {"text": "沈殿", "is_correct": false, "explanation": "溶けた物質が固体となって沈むことで、水素と酸素の結びつきには合わない。"}, {"text": "融解", "is_correct": false, "explanation": "固体が熱で溶けることで、水素と酸素が結びつく意味にはならない。"}, {"text": "蒸発", "is_correct": false, "explanation": "液体が気体になって消えることで、水ができる意味とは合わない。"}], "explanations": {"化合": "異なる元素が化学反応で結びつく意味。水素と酸素が結びついて水ができることに合う。", "沈殿": "溶けた物質が固体となって沈むことで、水素と酸素の結びつきには合わない。", "融解": "固体が熱で溶けることで、水素と酸素が結びつく意味にはならない。", "蒸発": "液体が気体になって消えることで、水ができる意味とは合わない。"}, "sentence_index": 0, "correct_answer": "化合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この二つの溶液を化合させて、ただ混ぜ合わせて飲み物にした。", "explanation": "ここは〈混合〉の意味。ただ混ぜるだけで新しい物質ができない場合は、化合とは言わない。"}, {"text": "水を化合させて、水素と酸素に分けた。", "explanation": "ここは〈分解〉の意味。化合は複数のものが結びつくことで、分けることではない。"}, {"text": "鉄を熱して化合させ、液体にした。", "explanation": "ここは〈融解〉の意味。固体が熱で溶けて液体になることで、新しい物質はできないので化合は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化合", "is_correct": true, "explanation": "二つの物質が化学的に結びつく意味に合い、ここで正しい。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物の働きで物質が変わることで、化学的な結合の意味ではない。"}, {"text": "増殖", "is_correct": false, "explanation": "生物が増えることで、物質には使わない。"}, {"text": "発芽", "is_correct": false, "explanation": "種子から芽が出ることで、物質の化学的結合には使わない。"}], "explanations": {"化合": "二つの物質が化学的に結びつく意味に合い、ここで正しい。", "発酵": "微生物の働きで物質が変わることで、化学的な結合の意味ではない。", "増殖": "生物が増えることで、物質には使わない。", "発芽": "種子から芽が出ることで、物質の化学的結合には使わない。"}, "sentence_index": 6, "correct_answer": "化合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂糖を水に化合させて、甘い液を作った。", "explanation": "ここは〈溶解〉の意味。砂糖が水に溶けるだけで新しい物質はできないので、化合は合わない。"}, {"text": "この液を化合させて、そのまま冷やした。", "explanation": "ここは〈冷却〉の意味。温度を下げるだけで物質は変わらないので、化合は合わない。"}, {"text": "この液を化合させて、不純物を取り除いた。", "explanation": "ここは〈濾過〉の意味。固体と液体を分けるだけで新しい物質はできないので、化合は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マグネシウムは酸素を化合して、酸化マグネシウムができる。", "corrected_sentence": "マグネシウムは酸素と化合して、酸化マグネシウムができる。", "error_description": "「化合」は相手を「と」で示す。「酸素を化合」は誤りで、正しくは「酸素と化合して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38623, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験管の中で、二つの物質が化合しで、液の色が変わった。", "corrected_sentence": "試験管の中で、二つの物質が化合して、液の色が変わった。", "error_description": "「化合して」の「て」は清音。「化合しで」は濁音化した誤った形で、正しくは「化合して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b7ec05-0f6e-46b9-b377-310b22b1ecb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「囲まれる」の行為者を示し、海洋が三方を囲む形になる。"}, {"text": "を", "is_correct": false, "explanation": "「三方を」で目的語がすでにあり、二つ目の〈を〉は置けない。"}, {"text": "と", "is_correct": false, "explanation": "「〜と囲まれる」とは言わない。囲む相手を示すには〈に〉を使う。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉で、「海洋より囲まれて」は受身の行為者にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「囲まれる」の行為者を示し、海洋が三方を囲む形になる。", "を": "「三方を」で目的語がすでにあり、二つ目の〈を〉は置けない。", "と": "「〜と囲まれる」とは言わない。囲む相手を示すには〈に〉を使う。", "より": "比較の〈より〉で、「海洋より囲まれて」は受身の行為者にならない。"}, "error_tags": {"を": "二重の目的語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「海洋」を文の主題として示す（〜は）。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す〈で〉では、「海洋で広いが」と述語がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す〈へ〉は、「海洋へ広いが」と形容詞にかからない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す〈から〉は、「海洋から広いが」と文の中心にならない。"}], "correct_answer": "は", "explanations": {"は": "正解。「海洋」を文の主題として示す（〜は）。", "で": "場所や手段を示す〈で〉では、「海洋で広いが」と述語がつながらない。", "へ": "方向を示す〈へ〉は、「海洋へ広いが」と形容詞にかからない。", "から": "起点を示す〈から〉は、「海洋から広いが」と文の中心にならない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "海（うみ）のことです。", "primary_collocate": null, "pronunciation": "かいよう", "ipa": "kaijoː", "syllable_count": 4, "sentences": [{"text": "海洋の深いところには、まだ知られていない生き物がたくさんいる。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]の深[ふか]いところには、まだ知[し]られていない生[い]き物[もの]がたくさんいる。", "sentence_source": "generated"}, {"text": "この国は三方を海洋に囲まれていて、魚料理が有名だ。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "この国[くに]は三方[さんぽう]を海洋[かいよう]に囲[かこ]まれていて、魚料理[さかなりょうり]が有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "海洋を調べる船が、昨日、港から出発した。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]を調[しら]べる船[ふね]が、昨日[きのう]、港[みなと]から出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "海洋が汚れると、魚も貝も生きていけなくなる。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]が汚[よご]れると、魚[さかな]も貝[かい]も生[い]きていけなくなる。", "sentence_source": "generated"}, {"text": "子どものころ、広い海洋を見て、地球の大きさを感じた。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "子[こ]どものころ、広[ひろ]い海洋[かいよう]を見[み]て、地球[ちきゅう]の大[おお]きさを感[かん]じた。", "sentence_source": "generated"}, {"text": "海洋の天気は変わりやすいので、船の旅には注意が必要だ。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]の天気[てんき]は変[か]わりやすいので、船[ふね]の旅[たび]には注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "研究者たちは、海洋に住む小さな生き物を毎日観察している。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、海洋[かいよう]に住[す]む小[ちい]さな生[い]き物[もの]を毎日[まいにち]観察[かんさつ]している。", "sentence_source": "generated"}, {"text": "海洋は広いが、人間が行ったことのある場所はごく一部だ。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]は広[ひろ]いが、人間[にんげん]が行[い]ったことのある場所[ばしょ]はごく一部[いちぶ]だ。", "sentence_source": "generated"}, {"text": "彼は海洋の生き物を研究していて、休みのたびに船で沖へ出かける。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "彼[かれ]は海洋[かいよう]の生[い]き物[もの]を研究[けんきゅう]していて、休[やす]みのたびに船[ふね]で沖[おき]へ出[で]かける。", "sentence_source": "generated"}, {"text": "海洋を守るために、私たちはプラスチックの使用を減らしている。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]を守[まも]るために、私[わたし]たちはプラスチックの使用[しよう]を減[へ]らしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "海洋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "海のこと。広い海全体を指す言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正解。海全体を指す名詞で、「〜の深いところ」と続けられる。"}, {"text": "機嫌", "is_correct": false, "explanation": "気分を表す名詞で、「機嫌の深いところ」と場所を表す語として続かない。"}, {"text": "方角", "is_correct": false, "explanation": "向きを表す名詞で、深さのある場所を示す語にはならない。"}, {"text": "勝負", "is_correct": false, "explanation": "争いを表す名詞で、生き物がいる深い場所には結びつかない。"}], "explanations": {"海洋": "正解。海全体を指す名詞で、「〜の深いところ」と続けられる。", "機嫌": "気分を表す名詞で、「機嫌の深いところ」と場所を表す語として続かない。", "方角": "向きを表す名詞で、深さのある場所を示す語にはならない。", "勝負": "争いを表す名詞で、生き物がいる深い場所には結びつかない。"}, "sentence_index": 0, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨のあと、道の海洋をよけて歩いた。", "explanation": "ここは〈水たまり〉の意味。海洋は広い海の水のことで、道にできた小さな水たまりには使わない。"}, {"text": "庭の海洋に、金魚が泳いでいる。", "explanation": "ここは〈池〉の意味。海洋は広い海のことで、庭先の小さな池には使わない。"}, {"text": "夕方、海洋を歩くと、貝殻が足にあたる。", "explanation": "ここは〈海岸〉の意味。海洋は海そのものを指すので、陸との境の浜を歩く場所には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正解。「海洋に住む」と場所を示し、生き物が暮らす広い海を指す。"}, {"text": "議論", "is_correct": false, "explanation": "話し合いを表す名詞で、生き物が住む場所にはならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控える気持ちを表す名詞で、住む場所を示す語として続かない。"}, {"text": "退屈", "is_correct": false, "explanation": "気持ちを表す名詞で、生き物が住む場所にはならない。"}], "explanations": {"海洋": "正解。「海洋に住む」と場所を示し、生き物が暮らす広い海を指す。", "議論": "話し合いを表す名詞で、生き物が住む場所にはならない。", "遠慮": "控える気持ちを表す名詞で、住む場所を示す語として続かない。", "退屈": "気持ちを表す名詞で、生き物が住む場所にはならない。"}, "sentence_index": 6, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見渡すかぎりの海洋を、ラクダの列がゆっくり進む。", "explanation": "ここは〈砂漠〉の意味。海洋は水をたたえた海を指すので、乾いた砂の大地には使わない。"}, {"text": "雪の海洋に登って、景色を楽しんだ。", "explanation": "ここは〈山〉の意味。海洋は広い海で、登って景色を眺める対象にはならない。"}, {"text": "子どもが海洋に絵を描いている。", "explanation": "ここは〈地面〉の意味。海洋は海そのものなので、絵を描く平面としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究船は海洋に調べるために、昨日港を出た。", "corrected_sentence": "研究船は海洋を調べるために、昨日港を出た。", "error_description": "「調べる」の対象は〈を〉で示す。〈に〉は誤り。正しくは「海洋を調べる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究チームは、海洋を住む小さな生き物を毎年調べている。", "corrected_sentence": "研究チームは、海洋に住む小さな生き物を毎年調べている。", "error_description": "「住む」は場所を〈に〉で示す。〈を〉は誤り。正しくは「海洋に住む」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「海洋の水」と、水がどこに属するかを示す。"}, {"text": "を", "is_correct": false, "explanation": "「海洋を水は」と目的語を作ると、文の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す〈へ〉は、「海洋へ水は」と所属の関係を作れない。"}, {"text": "が", "is_correct": false, "explanation": "「海洋が水は」と主語が二つ並び、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「海洋の水」と、水がどこに属するかを示す。", "を": "「海洋を水は」と目的語を作ると、文の関係が成り立たない。", "へ": "方向を示す〈へ〉は、「海洋へ水は」と所属の関係を作れない。", "が": "「海洋が水は」と主語が二つ並び、文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語の重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「海洋」を文の主題として示す（〜は）。"}, {"text": "を", "is_correct": false, "explanation": "「占める」の目的語（面積）がすでにあり、〈を〉を重ねると成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す〈から〉では、「海洋から広い面積を占める」と文の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す〈と〉では、「海洋と大陸より」と比べる文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「海洋」を文の主題として示す（〜は）。", "を": "「占める」の目的語（面積）がすでにあり、〈を〉を重ねると成り立たない。", "から": "起点を示す〈から〉では、「海洋から広い面積を占める」と文の主語にならない。", "と": "並列を示す〈と〉では、「海洋と大陸より」と比べる文が成り立たない。"}, "error_tags": {"を": "目的語の重複", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球の表面の大部分を占める、塩分を含んだ大きな水の塊。", "primary_collocate": null, "pronunciation": "かいよう", "ipa": "kaijoː", "syllable_count": 4, "sentences": [{"text": "地球の表面の約七割は海洋でおおわれている。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の表面[ひょうめん]の約[やく]七割[ななわり]は海洋[かいよう]でおおわれている。", "sentence_source": "generated"}, {"text": "海洋の水は塩分を含んでいるので、そのままでは飲めない。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]の水[みず]は塩分[えんぶん]を含[ふく]んでいるので、そのままでは飲[の]めない。", "sentence_source": "generated"}, {"text": "太平洋や大西洋のような海洋は、地球でもっとも大きな水のかたまりだ。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "太平洋[たいへいよう]や大西洋[たいせいよう]のような海洋[かいよう]は、地球[ちきゅう]でもっとも大[おお]きな水[みず]のかたまりだ。", "sentence_source": "generated"}, {"text": "海洋があるおかげで、地球の気温は急に変わらない。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]があるおかげで、地球[ちきゅう]の気温[きおん]は急[きゅう]に変[か]わらない。", "sentence_source": "generated"}, {"text": "宇宙から見ると、地球は海洋が広がる青い星だ。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]から見[み]ると、地球[ちきゅう]は海洋[かいよう]が広[ひろ]がる青[あお]い星[ほし]だ。", "sentence_source": "generated"}, {"text": "海洋の水は蒸発して雲になり、やがて雨として地上に降る。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]の水[みず]は蒸発[じょうはつ]して雲[くも]になり、やがて雨[あめ]として地上[ちじょう]に降[ふ]る。", "sentence_source": "generated"}, {"text": "月には水がないが、地球には広い海洋がある。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "月[つき]には水[みず]がないが、地球[ちきゅう]には広[ひろ]い海洋[かいよう]がある。", "sentence_source": "generated"}, {"text": "海洋は大陸よりずっと広い面積を占めている。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "海洋[かいよう]は大陸[たいりく]よりずっと広[ひろ]い面積[めんせき]を占[し]めている。", "sentence_source": "generated"}, {"text": "地球温暖化によって、海洋の水の量が少しずつ増えている。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "地球温暖化[ちきゅうおんだんか]によって、海洋[かいよう]の水[みず]の量[りょう]が少[すこ]しずつ増[ふ]えている。", "sentence_source": "generated"}, {"text": "先生は、海洋がどのようにできたかを、図を使って説明した。", "target_word": "海洋", "complexity_tier": "T3", "furigana": "先生[せんせい]は、海洋[かいよう]がどのようにできたかを、図[ず]を使[つか]って説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "海洋", "label": "基本形"}], "register": "formal", "sense_fingerprint": "地球の表面の大部分を占める塩水の大きな広がり（地球科学的な意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正解。地球表面の約七割を覆う、塩分を含んだ大きな水の塊を指す。"}, {"text": "陸地", "is_correct": false, "explanation": "陸地は地球表面の約三割で、七割を覆う対象ではない。"}, {"text": "山脈", "is_correct": false, "explanation": "山脈は山の連なりで、地表の大部分を覆う語ではない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は乾いた陸地で、地表の七割を覆うものではない。"}], "explanations": {"海洋": "正解。地球表面の約七割を覆う、塩分を含んだ大きな水の塊を指す。", "陸地": "陸地は地球表面の約三割で、七割を覆う対象ではない。", "山脈": "山脈は山の連なりで、地表の大部分を覆う語ではない。", "砂漠": "砂漠は乾いた陸地で、地表の七割を覆うものではない。"}, "sentence_index": 0, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の上では海洋が薄く、息切れしやすい。", "explanation": "ここは〈空気〉の意味。海洋は地表の水の広がりで、薄い気体の性質には使わない。"}, {"text": "海洋の水は山から海へ流れる。", "explanation": "ここは〈川〉の意味。海洋は流れ込む先の海そのもので、山から流れ出す水の出発点には使わない。"}, {"text": "海洋が溶けて、海面が少し上がった。", "explanation": "ここは〈氷河〉の意味。海洋は塩水の広がりで、溶けて海面を上げる氷の塊には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": true, "explanation": "正解。「月にはない」と対比して「地球には広い海洋がある」とつながる。"}, {"text": "祝日", "is_correct": false, "explanation": "暦に定められた休みの日で、月の話の対象にはならない。"}, {"text": "教室", "is_correct": false, "explanation": "学校の部屋で、月と地球を比べる文脈に合わない。"}, {"text": "交番", "is_correct": false, "explanation": "警察の施設で、月と地球を比べる文脈とは無関係。"}], "explanations": {"海洋": "正解。「月にはない」と対比して「地球には広い海洋がある」とつながる。", "祝日": "暦に定められた休みの日で、月の話の対象にはならない。", "教室": "学校の部屋で、月と地球を比べる文脈に合わない。", "交番": "警察の施設で、月と地球を比べる文脈とは無関係。"}, "sentence_index": 6, "correct_answer": "海洋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上空の海洋は、風で形を変えながら流れていく。", "explanation": "ここは〈雲〉の意味。海洋は地表の塩水の広がりで、空に浮かぶ雲には使わない。"}, {"text": "海洋は地球の周りを回っている。", "explanation": "ここは〈月〉の意味。海洋は地表の水なので、地球の周りを回る天体には使わない。"}, {"text": "海洋は地球より表面温度が高い惑星だ。", "explanation": "ここは〈金星〉の意味。海洋は惑星ではなく、惑星の表面にある水の広がりを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宇宙から眺めると、地球は海洋を広がる青い星に見える。", "corrected_sentence": "宇宙から眺めると、地球は海洋が広がる青い星に見える。", "error_description": "「広がる」は自動詞で、主語を〈が〉で示す。〈を〉は誤り。正しくは「海洋が広がる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38627, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月にはまだ人が住んでいないが、地球には広い海洋をある。", "corrected_sentence": "月にはまだ人が住んでいないが、地球には広い海洋がある。", "error_description": "「ある」は存在を表し、主語を〈が〉で示す。〈を〉は誤り。正しくは「広い海洋がある」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。〈生体〉と〈反応〉をつないで「生体の反応」という名詞句を作る。"}, {"text": "を", "is_correct": false, "explanation": "「生体を反応を」となり目的語が二つ並んで不自然。文の構造に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「生体に反応を調べる」は対象を表す格が合わず、不自然な文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「生体へ反応を調べる」は方向の意味になり、文の内容に合わない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。〈生体〉と〈反応〉をつないで「生体の反応」という名詞句を作る。", "を": "「生体を反応を」となり目的語が二つ並んで不自然。文の構造に合わない。", "に": "「生体に反応を調べる」は対象を表す格が合わず、不自然な文になる。", "へ": "「生体へ反応を調べる」は方向の意味になり、文の内容に合わない。"}, "error_tags": {"を": "目的語の格", "に": "与格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「生体が出す」で〈生体〉が動詞〈出す〉の主語であることを示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「生体を出す」は〈生体〉を〈出す〉の目的語にすることになり、〈出す〉の対象は電気なので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「生体と出す」は並列や共同の意味になり、電気を出す主体を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「生体より出す」は比較の意味になり、〈出す〉の主語の位置には収まらない。"}], "correct_answer": "が", "explanations": {"が": "「生体が出す」で〈生体〉が動詞〈出す〉の主語であることを示す格助詞。", "を": "「生体を出す」は〈生体〉を〈出す〉の目的語にすることになり、〈出す〉の対象は電気なので不自然。", "と": "「生体と出す」は並列や共同の意味になり、電気を出す主体を示せない。", "より": "「生体より出す」は比較の意味になり、〈出す〉の主語の位置には収まらない。"}, "error_tags": {"を": "目的語の格", "と": "並列・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きているもののこと。いきもの。", "primary_collocate": null, "pronunciation": "せいたい", "ipa": "seːtai", "syllable_count": 4, "sentences": [{"text": "生体は、外の温度が変わっても体温を一定に保とうとする。", "target_word": "生体", "complexity_tier": "T3", "furigana": "生体[せいたい]は、外[そと]の温度[おんど]が変[か]わっても体温[たいおん]を一定[いってい]に保[たも]とうとする。", "sentence_source": "generated"}, {"text": "医者は、生体の反応を調べるために検査をした。", "target_word": "生体", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、生体[せいたい]の反応[はんのう]を調[しら]べるために検査[けんさ]をした。", "sentence_source": "generated"}, {"text": "死んだ細胞と生体の細胞では、動きがまったく違う。", "target_word": "生体", "complexity_tier": "T3", "furigana": "死[し]んだ細胞[さいぼう]と生体[せいたい]の細胞[さいぼう]では、動[うご]きがまったく違[ちが]う。", "sentence_source": "generated"}, {"text": "この薬は、生体に害がないか確かめてから使う。", "target_word": "生体", "complexity_tier": "T3", "furigana": "この薬[くすり]は、生体[せいたい]に害[がい]がないか確[たし]かめてから使[つか]う。", "sentence_source": "generated"}, {"text": "生体から取った血液を、研究室で調べた。", "target_word": "生体", "complexity_tier": "T3", "furigana": "生体[せいたい]から取[と]った血液[けつえき]を、研究室[けんきゅうしつ]で調[しら]べた。", "sentence_source": "generated"}, {"text": "生体の中では、毎日たくさんの細胞が入れかわっている。", "target_word": "生体", "complexity_tier": "T3", "furigana": "生体[せいたい]の中[なか]では、毎日[まいにち]たくさんの細胞[さいぼう]が入[い]れかわっている。", "sentence_source": "generated"}, {"text": "人工の材料が生体になじむかどうかが、大切な問題だ。", "target_word": "生体", "complexity_tier": "T3", "furigana": "人工[じんこう]の材料[ざいりょう]が生体[せいたい]になじむかどうかが、大切[たいせつ]な問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "生体が出す小さな電気を測る機械が、病院にある。", "target_word": "生体", "complexity_tier": "T3", "furigana": "生体[せいたい]が出[だ]す小[ちい]さな電気[でんき]を測[はか]る機械[きかい]が、病院[びょういん]にある。", "sentence_source": "generated"}, {"text": "標本ではなく生体を観察すると、動物の動き方がよくわかる。", "target_word": "生体", "complexity_tier": "T3", "furigana": "標本[ひょうほん]ではなく生体[せいたい]を観察[かんさつ]すると、動物[どうぶつ]の動[うご]き方[かた]がよくわかる。", "sentence_source": "generated"}, {"text": "生体は、食べ物からエネルギーを取り入れて生きている。", "target_word": "生体", "complexity_tier": "T3", "furigana": "生体[せいたい]は、食[た]べ物[もの]からエネルギーを取[と]り入[い]れて生[い]きている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生体", "label": "基本形"}, {"form": "生体の", "label": "連体格"}, {"form": "生体に", "label": "与格"}, {"form": "生体から", "label": "起点"}], "register": "学術", "sense_fingerprint": "生きている体・生物そのもの（死んだものや標本と区別される）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生体", "is_correct": true, "explanation": "「生体は」が主語になり、生きている体が外気の変化に応じて体温を保つ、という文脈に合う。"}, {"text": "標本", "is_correct": false, "explanation": "標本は死んだものや保存された試料を指すので、体温を保とうとする主語にはならない。"}, {"text": "建物", "is_correct": false, "explanation": "建物は体温を持たないので、体温を一定に保とうとする主語として文脈に合わない。"}, {"text": "薬品", "is_correct": false, "explanation": "薬品は体温を保つ主体ではないので、この文の主語として意味が通らない。"}], "explanations": {"生体": "「生体は」が主語になり、生きている体が外気の変化に応じて体温を保つ、という文脈に合う。", "標本": "標本は死んだものや保存された試料を指すので、体温を保とうとする主語にはならない。", "建物": "建物は体温を持たないので、体温を一定に保とうとする主語として文脈に合わない。", "薬品": "薬品は体温を保つ主体ではないので、この文の主語として意味が通らない。"}, "sentence_index": 0, "correct_answer": "生体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この端末は生体で本人かどうかを確かめる。", "explanation": "〈生体〉は〈生きているもの〉の意味。指紋や顔で本人を確かめる仕組みは〈生体認証〉と言い、〈生体〉だけでは認証の意味にはならない。"}, {"text": "大きな手術の末、彼は生体を取りとめた。", "explanation": "ここは〈命〉を〈取りとめる〉という決まった言い方で、〈生命〉の意味。〈生体〉は生き物の体のことなので、この言い方には使わない。"}, {"text": "亡くなった犬の生体を庭に埋めた。", "explanation": "〈生体〉は生きている体の意味で、亡くなった犬には〈死体〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生体", "is_correct": true, "explanation": "人工の材料と組織の適合が問題になる文脈で、なじむ相手は生きている体である〈生体〉。"}, {"text": "天気", "is_correct": false, "explanation": "天気は材料がなじむ相手にはならず、医療的な適合の問題という文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は人工材料がなじむ対象ではなく、この文脈では意味が通らない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は人工材料がなじむ対象として文脈に合わず、大切な問題という文意にも合わない。"}], "explanations": {"生体": "人工の材料と組織の適合が問題になる文脈で、なじむ相手は生きている体である〈生体〉。", "天気": "天気は材料がなじむ相手にはならず、医療的な適合の問題という文脈に合わない。", "教科書": "教科書は人工材料がなじむ対象ではなく、この文脈では意味が通らない。", "電車": "電車は人工材料がなじむ対象として文脈に合わず、大切な問題という文意にも合わない。"}, "sentence_index": 6, "correct_answer": "生体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この生体は、古い部品を取り替えれば長く使える。", "explanation": "元の文は〈機械〉の話。〈生体〉は生きている体で、部品を交換して使うものではない。"}, {"text": "明日の生体は、午後から雨になるらしい。", "explanation": "元の文は〈天気〉の話。〈生体〉は生き物の体を指し、天候には使わない。"}, {"text": "この鳥は、冬になると南へ移動する生体をもつ。", "explanation": "〈生態〉は暮らし方や習性の意味。〈生体〉は身体そのものを指すので、習性には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究室では、生体から薬を投与して反応を見る。", "corrected_sentence": "研究室では、生体に薬を投与して反応を見る。", "error_description": "〈生体〉に続く格助詞の誤り。〈投与する〉は受け手に「に」を取るので「から」は誤り。正しくは「生体に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生体な細胞は、数日で入れかわる。", "corrected_sentence": "生体の細胞は、数日で入れかわる。", "error_description": "名詞〈生体〉には連体助詞「の」が必要。「な」は形容動詞の語尾で、名詞には付かないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を表すので、「触媒と一緒にきれいにされる」となり手段の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、比べる相手がないので文が成り立たない。"}, {"text": "で", "is_correct": true, "explanation": "「触媒で」は手段を表し、「触媒によってきれいにされる」という文脈に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すので、「触媒へきれいにされる」では手段を示せない。"}], "correct_answer": "で", "explanations": {"と": "「と」は並列・共同を表すので、「触媒と一緒にきれいにされる」となり手段の意味にならない。", "より": "「より」は比較を表し、比べる相手がないので文が成り立たない。", "で": "「触媒で」は手段を表し、「触媒によってきれいにされる」という文脈に合う。", "へ": "「へ」は向かう先を表すので、「触媒へきれいにされる」では手段を示せない。"}, "error_tags": {"と": "並列・共同", "より": "比較", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「に」は用途を表し「触媒に使う」とは言えるが、この文では使うもの（目的語）が示されず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「触媒から何度も使っている」では意味が通らない。"}, {"text": "を", "is_correct": true, "explanation": "「を」は「使う」の目的語を示し、「高価な触媒を何度も使っている」で文が成り立つ。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、動詞「使う」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"に": "「に」は用途を表し「触媒に使う」とは言えるが、この文では使うもの（目的語）が示されず、文が成り立たない。", "から": "「から」は起点を表し、「触媒から何度も使っている」では意味が通らない。", "を": "「を」は「使う」の目的語を示し、「高価な触媒を何度も使っている」で文が成り立つ。", "の": "「の」は名詞どうしをつなぐ助詞で、動詞「使う」の目的語にはならない。"}, "error_tags": {"に": "着点", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "化学反応を起こすのを助けるもの。", "primary_collocate": null, "pronunciation": "しょくばい", "ipa": "ɕokɯbai", "syllable_count": 4, "sentences": [{"text": "この実験では、反応を早めるために触媒を加える。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、反応[はんのう]を早[はや]めるために触媒[しょくばい]を加[くわ]える。", "sentence_source": "generated"}, {"text": "車の排気ガスは、触媒でできるだけきれいにされる。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "車[くるま]の排気[はいき]ガスは、触媒[しょくばい]でできるだけきれいにされる。", "sentence_source": "generated"}, {"text": "触媒は、反応のあとも変わらずに残る。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]は、反応[はんのう]のあとも変[か]わらずに残[のこ]る。", "sentence_source": "generated"}, {"text": "白金は、よく使われる触媒の一つだ。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "白金[はっきん]は、よく使[つか]われる触媒[しょくばい]の一つ[ひとつ]だ。", "sentence_source": "generated"}, {"text": "触媒がないと、この反応はとてもゆっくり進む。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]がないと、この反応[はんのう]はとてもゆっくり進[すす]む。", "sentence_source": "generated"}, {"text": "先生は、触媒の働きを図で説明してくれた。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "先生[せんせい]は、触媒[しょくばい]の働[はたら]きを図[ず]で説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "触媒を入れすぎても、反応が速くなるとは限らない。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]を入[い]れすぎても、反応[はんのう]が速[はや]くなるとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "工場では、高価な触媒を何度も使っている。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、高価[こうか]な触媒[しょくばい]を何度[なんど]も使[つか]っている。", "sentence_source": "generated"}, {"text": "体の中の酵素も、一種の触媒と考えられる。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "体[からだ]の中[なか]の酵素[こうそ]も、一種[いっしゅ]の触媒[しょくばい]と考[かんが]えられる。", "sentence_source": "generated"}, {"text": "触媒の力で、少ない熱でも反応が起こった。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]の力[ちから]で、少[すく]ない熱[ねつ]でも反応[はんのう]が起[お]こった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触媒", "label": "基本形"}, {"form": "触媒の", "label": "連体形"}], "register": "technical", "sense_fingerprint": "化学反応を助けるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反応速度", "is_correct": false, "explanation": "速さを表す語で、加えて使うものではないので「加える」と合わない。"}, {"text": "触媒", "is_correct": true, "explanation": "反応を速めるために加えるものは触媒。"}, {"text": "結論", "is_correct": false, "explanation": "物事の結論を表す語で、化学反応に加えるものではない。"}, {"text": "比重", "is_correct": false, "explanation": "物質の重さの比を表す語で、加える対象にならない。"}], "explanations": {"反応速度": "速さを表す語で、加えて使うものではないので「加える」と合わない。", "触媒": "反応を速めるために加えるものは触媒。", "結論": "物事の結論を表す語で、化学反応に加えるものではない。", "比重": "物質の重さの比を表す語で、加える対象にならない。"}, "sentence_index": 0, "correct_answer": "触媒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パンは、小麦粉を触媒にして作られる。", "explanation": "ここは〈原料〉の意味。触媒は反応の前後で変わらず、材料として使い切るものではないので合わない。"}, {"text": "音を伝える触媒として、空気が使われる。", "explanation": "ここは〈媒体〉の意味。触媒は化学反応を助ける物質で、音を運ぶ役目には合わない。"}, {"text": "食塩を溶かす触媒は、水だ。", "explanation": "ここは〈溶媒〉の意味。触媒は反応を速める物質で、物を溶かす液体としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手順", "is_correct": false, "explanation": "作業の順番を表す語で、入れすぎるものではない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、物として入れることはできない。"}, {"text": "触媒", "is_correct": true, "explanation": "反応の速さに関わり、入れすぎても速くなるとは限らないと述べられるのは触媒。"}, {"text": "溶解度", "is_correct": false, "explanation": "物質が溶ける程度を表す語で、入れるものではない。"}], "explanations": {"手順": "作業の順番を表す語で、入れすぎるものではない。", "気温": "空気の温度を表す語で、物として入れることはできない。", "触媒": "反応の速さに関わり、入れすぎても速くなるとは限らないと述べられるのは触媒。", "溶解度": "物質が溶ける程度を表す語で、入れるものではない。"}, "sentence_index": 6, "correct_answer": "触媒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体に必要な触媒を、毎日とるようにしている。", "explanation": "ここは〈栄養素〉の意味。触媒は体に取り込んで栄養にするものではないので合わない。"}, {"text": "植物から取った触媒で、布を染めてある。", "explanation": "ここは〈染料〉の意味。触媒は反応を速める物質で、布に色をつける働きは持たないので合わない。"}, {"text": "床のごみを、触媒で吸い取った。", "explanation": "ここは〈掃除機〉の意味。触媒は吸い取る道具ではないので、ごみを集める文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場では、新しい触媒で使って反応を速めている。", "corrected_sentence": "工場では、新しい触媒を使って反応を速めている。", "error_description": "「使う」の目的語には「を」が必要。「触媒で使う」は文として成り立たない。正しくは「触媒を使って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、触媒の働くをわかりやすく説明した。", "corrected_sentence": "先生は、触媒の働きをわかりやすく説明した。", "error_description": "「〜の働き」は名詞。「働く」は動詞の終止形で、「触媒の」の後には名詞「働き」が続く。「働くを」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここに置くと「この触媒を、〜だけを起こしやすくする」と目的語が重なる。"}, {"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「この触媒は」と文の話題を立てている。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「この触媒へ」では主題にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、比べる対象がないので文が成り立たない。"}], "correct_answer": "は", "explanations": {"を": "「を」は目的語を示すが、ここに置くと「この触媒を、〜だけを起こしやすくする」と目的語が重なる。", "は": "主題を示す「は」。「この触媒は」と文の話題を立てている。", "へ": "「へ」は方向を表し、「この触媒へ」では主題にならない。", "より": "「より」は比較を表し、比べる対象がないので文が成り立たない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を表し、「この触媒と使われている」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を表し、「この触媒の使われている」と続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「この触媒から使われている」は意味が通らない。"}, {"text": "が", "is_correct": true, "explanation": "主語を示す「が」。「この触媒が使われている」で受身の主語になる。"}], "correct_answer": "が", "explanations": {"と": "「と」は並列・共同を表し、「この触媒と使われている」では文が成り立たない。", "の": "「の」は連体修飾を表し、「この触媒の使われている」と続かない。", "から": "「から」は起点を表し、「この触媒から使われている」は意味が通らない。", "が": "主語を示す「が」。「この触媒が使われている」で受身の主語になる。"}, "error_tags": {"と": "並列・共同", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "化学反応を速めたり、特定の反応を起こしやすくする物質。", "primary_collocate": null, "pronunciation": "しょくばい", "ipa": "ɕokɯbai", "syllable_count": 4, "sentences": [{"text": "触媒を使えば、水素と酸素から水を作りやすくなる。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]を使[つか]えば、水素[すいそ]と酸素[さんそ]から水[みず]を作[つく]りやすくなる。", "sentence_source": "generated"}, {"text": "この触媒は、特定の反応だけを起こしやすくする。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "この触媒[しょくばい]は、特定[とくてい]の反応[はんのう]だけを起[お]こしやすくする。", "sentence_source": "generated"}, {"text": "新しい触媒の開発で、製造にかかる時間が短くなった。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "新[あたら]しい触媒[しょくばい]の開発[かいはつ]で、製造[せいぞう]にかかる時間[じかん]が短[みじか]くなった。", "sentence_source": "generated"}, {"text": "触媒の表面に気体がくっついて、反応が進む。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]の表面[ひょうめん]に気体[きたい]がくっついて、反応[はんのう]が進[すす]む。", "sentence_source": "generated"}, {"text": "触媒が古くなると、反応を速める力が弱くなる。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]が古[ふる]くなると、反応[はんのう]を速[はや]める力[ちから]が弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "粉末の触媒を使うと、反応物どうしが接する面積が増えて、反応が速まる。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "粉末[ふんまつ]の 触媒[しょくばい]を 使[つか]うと、反応物[はんのうぶつ]どうしが 接[せっ]する 面積[めんせき]が 増[ふ]えて、反応[はんのう]が 速[はや]まる。", "sentence_source": "generated"}, {"text": "研究者は、安くて強い触媒を探している。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、安[やす]くて強[つよ]い触媒[しょくばい]を探[さが]している。", "sentence_source": "generated"}, {"text": "プラスチックの製造に、この触媒が使われている。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "プラスチックの製造[せいぞう]に、この触媒[しょくばい]が使[つか]われている。", "sentence_source": "generated"}, {"text": "触媒を選ぶ作業は、実験でいちばん大切な段階だ。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "触媒[しょくばい]を選[えら]ぶ作業[さぎょう]は、実験[じっけん]でいちばん大切[たいせつ]な段階[だんかい]だ。", "sentence_source": "generated"}, {"text": "反応が遅いときは、別の触媒に変えてみるといい。", "target_word": "触媒", "complexity_tier": "T3", "furigana": "反応[はんのう]が遅[おそ]いときは、別[べつ]の触媒[しょくばい]に変[か]えてみるといい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触媒", "label": "基本形"}, {"form": "触媒の", "label": "連体形"}], "register": "technical", "sense_fingerprint": "反応を速めたり特定の反応を起こしやすくする物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T4: contains vocabulary far above tier T4: 速まる (Zipf 1.17)']::text[], '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比重", "is_correct": false, "explanation": "物の重さの比を表す語で、水を作るために使う対象にならない。"}, {"text": "結論", "is_correct": false, "explanation": "判断の結果を表す語で、反応に使う物ではない。"}, {"text": "触媒", "is_correct": true, "explanation": "水素と酸素から水を作る反応を助けるのは触媒なので、ここで使うものとして合う。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、水を作るために使う道具にはならない。"}], "explanations": {"比重": "物の重さの比を表す語で、水を作るために使う対象にならない。", "結論": "判断の結果を表す語で、反応に使う物ではない。", "触媒": "水素と酸素から水を作る反応を助けるのは触媒なので、ここで使うものとして合う。", "気温": "空気の温度を表す語で、水を作るために使う道具にはならない。"}, "sentence_index": 0, "correct_answer": "触媒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "機械の摩擦を減らすために、触媒を塗った。", "explanation": "ここは〈潤滑油〉の意味。触媒は摩擦を減らす働きを持たないので、塗って滑らせる役目には合わない。"}, {"text": "犯人を示す触媒が、現場から見つかった。", "explanation": "ここは〈証拠〉の意味。触媒は反応を助ける物質で、犯人を示す証拠にはならないので合わない。"}, {"text": "病気を治すために、触媒を毎日飲んだ。", "explanation": "ここは〈薬〉の意味。触媒は反応を助ける物質で、飲んで病気を治すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溶解度", "is_correct": false, "explanation": "物質が溶ける程度を表す語で、探す対象の物ではない。"}, {"text": "反応速度", "is_correct": false, "explanation": "反応の速さを表す語で、探して手に入れる物ではない。"}, {"text": "比熱", "is_correct": false, "explanation": "物質の温まりにくさを表す値で、探す対象の物ではない。"}, {"text": "触媒", "is_correct": true, "explanation": "安くて強い、反応を助ける物質として探されるのは触媒。"}], "explanations": {"溶解度": "物質が溶ける程度を表す語で、探す対象の物ではない。", "反応速度": "反応の速さを表す語で、探して手に入れる物ではない。", "比熱": "物質の温まりにくさを表す値で、探す対象の物ではない。", "触媒": "安くて強い、反応を助ける物質として探されるのは触媒。"}, "sentence_index": 6, "correct_answer": "触媒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その温度を、触媒で測った。", "explanation": "ここは〈測定器〉の意味。触媒は反応を助ける物質で、温度を測る道具にはならないので合わない。"}, {"text": "車はガソリンを触媒にして走る。", "explanation": "ここは〈燃料〉の意味。触媒は反応の前後で変わらず、燃やして動力にするものではないので合わない。"}, {"text": "カレーに触媒を入れて、味を整えた。", "explanation": "ここは〈調味料〉の意味。触媒は化学反応を速める物質で、料理の味を整える役目は持たないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "触媒が使うと、反応の時間が短くなる。", "corrected_sentence": "触媒を使うと、反応の時間が短くなる。", "error_description": "「使う」の目的語は「を」。「触媒が使う」では触媒が使う主体になり、意味が通らない。正しくは「触媒を使うと」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38631, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "触媒が少なくと、反応は遅くなる。", "corrected_sentence": "触媒が少ないと、反応は遅くなる。", "error_description": "「少ない」は形容詞で、「少ないと」の形が正しい。「少なくと」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
