INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「使う」の対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は道具や手段を示し、「安い素材で使った」では使う対象が消える。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は相手や並列を示し、「素材と使った」では使う対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示し、「素材から使った」では使う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「使う」の対象を示す。", "で": "〈で〉は道具や手段を示し、「安い素材で使った」では使う対象が消える。", "と": "〈と〉は相手や並列を示し、「素材と使った」では使う対象にならない。", "から": "〈から〉は起点を示し、「素材から使った」では使う対象を示せない。"}, "error_tags": {"で": "手段", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをつくるもとになるものです。", "primary_collocate": null, "pronunciation": "そざい", "ipa": "sozai", "syllable_count": 3, "sentences": [{"text": "この店のバッグは、天然の素材だけで作られている。", "target_word": "素材", "complexity_tier": "T3", "furigana": "この店[みせ]のバッグは、天然[てんねん]の素材[そざい]だけで作[つく]られている。", "sentence_source": "generated"}, {"text": "料理の味は、素材の新鮮さで決まると言われる。", "target_word": "素材", "complexity_tier": "T3", "furigana": "料理[りょうり]の味[あじ]は、素材[そざい]の新鮮[しんせん]さで決[き]まると言[い]われる。", "sentence_source": "generated"}, {"text": "木は昔から家を建てるための大切な素材だった。", "target_word": "素材", "complexity_tier": "T3", "furigana": "木[き]は昔[むかし]から家[いえ]を建[た]てるための大切[たいせつ]な素材[そざい]だった。", "sentence_source": "generated"}, {"text": "映画を作るために、監督は古い写真を素材として集めた。", "target_word": "素材", "complexity_tier": "T3", "furigana": "映画[えいが]を作[つく]るために、監督[かんとく]は古[ふる]い写真[しゃしん]を素材[そざい]として集[あつ]めた。", "sentence_source": "generated"}, {"text": "この服は軽くて丈夫な素材なので、旅行に向いている。", "target_word": "素材", "complexity_tier": "T3", "furigana": "この服[ふく]は軽[かる]くて丈夫[じょうぶ]な素材[そざい]なので、旅行[りょこう]に向[む]いている。", "sentence_source": "generated"}, {"text": "彼女は素材を生かした、シンプルな料理を得意としている。", "target_word": "素材", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は素材[そざい]を生[い]かした、シンプルな料理[りょうり]を得意[とくい]としている。", "sentence_source": "generated"}, {"text": "プラスチックに代わる新しい素材を、会社が開発している。", "target_word": "素材", "complexity_tier": "T3", "furigana": "プラスチックに代[か]わる新[あたら]しい素材[そざい]を、会社[かいしゃ]が開発[かいはつ]している。", "sentence_source": "generated"}, {"text": "安い素材を使ったため、そのおもちゃはすぐに壊れた。", "target_word": "素材", "complexity_tier": "T3", "furigana": "安[やす]い素材[そざい]を使[つか]ったため、そのおもちゃはすぐに壊[こわ]れた。", "sentence_source": "generated"}, {"text": "作文の素材を探して、一日中町を歩き回った。", "target_word": "素材", "complexity_tier": "T3", "furigana": "作文[さくぶん]の素材[そざい]を探[さが]して、一日中[いちにちじゅう]町[まち]を歩[ある]き回[まわ]った。", "sentence_source": "generated"}, {"text": "紙という素材は、折ったり切ったりしやすいので工作に便利だ。", "target_word": "素材", "complexity_tier": "T3", "furigana": "紙[かみ]という素材[そざい]は、折[お]ったり切[き]ったりしやすいので工作[こうさく]に便利[べんり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "素材", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物や作品を作るときの元になる材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "素材", "is_correct": true, "explanation": "正解。物を作るもとになる材料で、「天然の素材だけで」と続く。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、物を作る材料にはならない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを表す語で、物を作る材料としては使えない。"}, {"text": "学問", "is_correct": false, "explanation": "知識の体系を表す語で、物を作る材料にはならない。"}], "explanations": {"素材": "正解。物を作るもとになる材料で、「天然の素材だけで」と続く。", "天気": "空模様を表す語で、物を作る材料にはならない。", "感情": "心の動きを表す語で、物を作る材料としては使えない。", "学問": "知識の体系を表す語で、物を作る材料にはならない。"}, "sentence_index": 0, "correct_answer": "素材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの新人は素材がいいと、監督は言った。", "explanation": "ここは〈素質・才能〉の意味で、物の材料を指すこの語義とは別。"}, {"text": "化粧を落とすと、彼女の素材はとても若く見えた。", "explanation": "ここは〈素顔〉の意味。素材は物の材料を指すので、化粧をしていない顔には使わない。"}, {"text": "作家は素材を三日で書き上げた。", "explanation": "ここは〈原稿〉の意味。素材は物をつくるもとになる材料で、書き上げた文章そのものは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "素材", "is_correct": true, "explanation": "正解。新しく開発される物の材料として「新しい素材を」と続く。"}, {"text": "郷愁", "is_correct": false, "explanation": "懐かしい思いを表す語で、開発の対象にはならない。"}, {"text": "作法", "is_correct": false, "explanation": "行儀の決まりを表す語で、新しく開発する対象とは合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている時の息づかいを表す語で、開発の対象にはならない。"}], "explanations": {"素材": "正解。新しく開発される物の材料として「新しい素材を」と続く。", "郷愁": "懐かしい思いを表す語で、開発の対象にはならない。", "作法": "行儀の決まりを表す語で、新しく開発する対象とは合わない。", "寝息": "眠っている時の息づかいを表す語で、開発の対象にはならない。"}, "sentence_index": 6, "correct_answer": "素材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で素材を買って、電車で読んだ。", "explanation": "ここは〈雑誌〉の意味。素材は物をつくるもとになる材料で、読み物には使わない。"}, {"text": "侍は素材を腰に差して歩いた。", "explanation": "ここは〈刀〉の意味。素材は作るもとで、腰に差す武器を指さない。"}, {"text": "彼女は素材を左手の薬指にはめた。", "explanation": "ここは〈指輪〉の意味。素材は作るもとになる材料で、身につける装飾品を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は、新鮮な素材に選ぶことで有名だ。", "corrected_sentence": "この店は、新鮮な素材を選ぶことで有名だ。", "error_description": "「選ぶ」の対象は〈を〉で示す。〈に〉は誤り。正しくは「新鮮な素材を選ぶ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の家具は、木の素材を作られている。", "corrected_sentence": "この店の家具は、木の素材で作られている。", "error_description": "「作られる」の材料は〈で〉で示す。〈を〉は誤り。正しくは「木の素材で作られている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「代謝が悪くなって」で、代謝が悪くなるという主語の形になる。"}, {"text": "に", "is_correct": false, "explanation": "「代謝に悪くなって」は成り立たず、空欄に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「代謝で悪くなって」は手段の意味になり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「代謝と悪くなって」は並列の形になり、文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「代謝が悪くなって」で、代謝が悪くなるという主語の形になる。", "に": "「代謝に悪くなって」は成り立たず、空欄に合わない。", "で": "「代謝で悪くなって」は手段の意味になり、文の意味が通らない。", "と": "「代謝と悪くなって」は並列の形になり、文として成り立たない。"}, "error_tags": {"に": "帰着点", "で": "手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「代謝を上げるために」で、上げる対象の代謝を目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "「代謝が上げるために」は他動詞「上げる」の主語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「代謝へ上げるために」は方向の意味になり、代謝を高める文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「代謝より上げるために」は比較の意味になり、文の内容と合わない。"}], "correct_answer": "を", "explanations": {"を": "「代謝を上げるために」で、上げる対象の代謝を目的語として示す。", "が": "「代謝が上げるために」は他動詞「上げる」の主語にならず、文が成り立たない。", "へ": "「代謝へ上げるために」は方向の意味になり、代謝を高める文として不自然。", "より": "「代謝より上げるために」は比較の意味になり、文の内容と合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体の中で、いらなくなったものを新しいものに変えること。", "primary_collocate": null, "pronunciation": "たいしゃ", "ipa": "taiɕa", "syllable_count": 3, "sentences": [{"text": "毎日運動すると、体の代謝がよくなる。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "毎日[まいにち]運動[うんどう]すると、体[からだ]の代謝[たいしゃ]がよくなる。", "sentence_source": "generated"}, {"text": "年をとると、代謝が悪くなって太りやすくなる。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "年[とし]をとると、代謝[たいしゃ]が悪[わる]くなって太[ふと]りやすくなる。", "sentence_source": "generated"}, {"text": "お風呂に入って体が温まると、代謝が上がる。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "お風呂[ふろ]に入[はい]って体[からだ]が温[あたた]まると、代謝[たいしゃ]が上[あ]がる。", "sentence_source": "generated"}, {"text": "水をたくさん飲むと、代謝を助けると言われている。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "水[みず]をたくさん飲[の]むと、代謝[たいしゃ]を助[たす]けると言[い]われている。", "sentence_source": "generated"}, {"text": "朝ごはんを食べないと、体の代謝が下がってしまう。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べないと、体[からだ]の代謝[たいしゃ]が下[さ]がってしまう。", "sentence_source": "generated"}, {"text": "子どもは代謝が活発なので、すぐにおなかがすく。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "子[こ]どもは代謝[たいしゃ]が活発[かっぱつ]なので、すぐにおなかがすく。", "sentence_source": "generated"}, {"text": "代謝がいい人は、冬でも手足があまり冷たくならない。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "代謝[たいしゃ]がいい人[ひと]は、冬[ふゆ]でも手足[てあし]があまり冷[つめ]たくならない。", "sentence_source": "generated"}, {"text": "母は代謝を上げるために、毎朝ストレッチをしている。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "母[はは]は代謝[たいしゃ]を上[あ]げるために、毎朝[まいあさ]ストレッチをしている。", "sentence_source": "generated"}, {"text": "体の代謝が悪いと、疲れがなかなかとれない。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "体[からだ]の代謝[たいしゃ]が悪[わる]いと、疲[つか]れがなかなかとれない。", "sentence_source": "generated"}, {"text": "辛いものを食べると汗が出るのは、代謝が高まるからだ。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "辛[から]いものを食[た]べると汗[あせ]が出[で]るのは、代謝[たいしゃ]が高[たか]まるからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "代謝", "label": "基本形"}, {"form": "代謝する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "体の中で古いものや不要なものを新しいものに入れ替える働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代謝", "is_correct": true, "explanation": "「体の代謝がよくなる」で、体内の古いものを入れ替える働きを指す。"}, {"text": "天気", "is_correct": false, "explanation": "「体の天気がよくなる」は意味をなさず、空欄に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "「体の名前がよくなる」は文として成り立たない。"}, {"text": "文字", "is_correct": false, "explanation": "「体の文字がよくなる」は意味が通らず、空欄に合わない。"}], "explanations": {"代謝": "「体の代謝がよくなる」で、体内の古いものを入れ替える働きを指す。", "天気": "「体の天気がよくなる」は意味をなさず、空欄に合わない。", "名前": "「体の名前がよくなる」は文として成り立たない。", "文字": "「体の文字がよくなる」は意味が通らず、空欄に合わない。"}, "sentence_index": 0, "correct_answer": "代謝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くなった電池を代謝して、新しいものを買った。", "explanation": "ここは〈交換〉の場面。代謝は体内での入れ替えを指し、電池には使わないので合わない。"}, {"text": "よく寝ると、部屋の空気が代謝して新鮮になる。", "explanation": "ここは〈換気〉の場面。代謝は体の中で古いものを新しいものに変えることで、部屋の空気を入れ替える場面には使わない。"}, {"text": "大きな音で、窓ガラスが代謝して割れた。", "explanation": "ここは〈破損〉の場面。代謝は体の中で古いものを新しいものに変えることで、窓ガラスが壊れる出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代謝", "is_correct": true, "explanation": "「代謝がいい人」で、体の中で古いものを新しいものに変える働きが良いことを指す。"}, {"text": "名刺", "is_correct": false, "explanation": "「名刺がいい人」は意味が通らず、空欄に合わない。"}, {"text": "教室", "is_correct": false, "explanation": "「教室がいい人」は成り立たず、体の働きを表す文に合わない。"}, {"text": "地図", "is_correct": false, "explanation": "「地図がいい人」は文脈に合わず、体の働きの説明にならない。"}], "explanations": {"代謝": "「代謝がいい人」で、体の中で古いものを新しいものに変える働きが良いことを指す。", "名刺": "「名刺がいい人」は意味が通らず、空欄に合わない。", "教室": "「教室がいい人」は成り立たず、体の働きを表す文に合わない。", "地図": "「地図がいい人」は文脈に合わず、体の働きの説明にならない。"}, "sentence_index": 6, "correct_answer": "代謝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯機を毎日回すと、内部のパーツが代謝して新しくなる。", "explanation": "ここは〈部品の取り替え〉の意味。代謝は体の中の入れ替えを指し、機械の部品を取り替えることには使わない。"}, {"text": "ガラスのコップは、使うほどに代謝して丈夫になる。", "explanation": "ここは〈強化〉の場面。代謝は体の中で古いものを新しいものに変えることで、ガラスを強くする加工には使わない。"}, {"text": "鍋を火にかけると、中身が代謝して熱くなる。", "explanation": "ここは〈加熱〉の場面。代謝は体内の入れ替えを指し、熱を加える変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜ふかしすると、体の代謝を悪くなる。", "corrected_sentence": "夜ふかしすると、体の代謝が悪くなる。", "error_description": "「悪くなる」は主語を「が」で示す。代謝の後に「を」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お風呂に入ると、代謝が高める。", "corrected_sentence": "お風呂に入ると、代謝が高まる。", "error_description": "「高める」は他動詞で目的語に「を」を取る。代謝は自ら高まるので、自動詞「高まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「代謝が上がる」で、代謝を主語とする自動詞の文になる。"}, {"text": "を", "is_correct": false, "explanation": "「代謝を上がって」は他動詞の形になるが、「上がる」は自動詞なので成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「代謝で上がって」は手段の意味になり、体の変化を表す文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「代謝と上がって」は並列の形で、代謝が上がるという意味にならない。"}], "correct_answer": "が", "explanations": {"が": "「代謝が上がる」で、代謝を主語とする自動詞の文になる。", "を": "「代謝を上がって」は他動詞の形になるが、「上がる」は自動詞なので成り立たない。", "で": "「代謝で上がって」は手段の意味になり、体の変化を表す文として不自然。", "と": "「代謝と上がって」は並列の形で、代謝が上がるという意味にならない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「代謝に悪い影響が出る」で、代謝が受ける対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「代謝を悪い影響が出る」は目的語の「を」が合わず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「代謝より悪い影響」は比較の意味になり、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」で、体の働きを手段として示す文にならず、影響の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「代謝に悪い影響が出る」で、代謝が受ける対象を示す。", "を": "「代謝を悪い影響が出る」は目的語の「を」が合わず、文が成り立たない。", "より": "「代謝より悪い影響」は比較の意味になり、文の意味が通らない。", "で": "手段の「で」で、体の働きを手段として示す文にならず、影響の対象を示せない。"}, "error_tags": {"を": "目的語の誤り", "より": "比較の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物が体内で、栄養をエネルギーや体を作る材料に変えたり、不要なものを分解したりする一連の化学反応。", "primary_collocate": null, "pronunciation": "たいしゃ", "ipa": "taiɕa", "syllable_count": 3, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "代謝", "complexity_tier": "T5", "furigana": "微生物[びせいぶつ]の代謝[たいしゃ]作用[さよう]である発酵[はっこう]は、単[たん]なる保存[ほぞん]技法[ぎほう]の域[いき]を超[こ]え、主食[しゅしょく]の持[も]つ潜在[せんざい]能力[のうりょく]を飛躍的[ひやくてき]に拡張[かくちょう]する化学的[かがくてき]芸術[げいじゅつ]である。", "sentence_source": "mined"}, {"text": "運動を続けると、体の代謝が上がって、汗をかきやすくなる。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けると、体[からだ]の代謝[たいしゃ]が上[あ]がって、汗[あせ]をかきやすくなる。", "sentence_source": "generated"}, {"text": "年を取ると代謝が落ちるので、若いころと同じ量を食べると太りやすい。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると代謝[たいしゃ]が落[お]ちるので、若[わか]いころと同[おな]じ量[りょう]を食[た]べると太[ふと]りやすい。", "sentence_source": "generated"}, {"text": "代謝がよくないと、体の中のいらないものがうまく外に出ない。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "代謝[たいしゃ]がよくないと、体[からだ]の中[なか]のいらないものがうまく外[そと]に出[で]ない。", "sentence_source": "generated"}, {"text": "肝臓は、体に入った薬を分解するなど、代謝の中心的な役割を果たす器官である。", "target_word": "代謝", "complexity_tier": "T4", "furigana": "肝臓[かんぞう]は、体[からだ]に入[はい]った薬[くすり]を分解[ぶんかい]するなど、代謝[たいしゃ]の中心的[ちゅうしんてき]な役割[やくわり]を果[は]たす器官[きかん]である。", "sentence_source": "generated"}, {"text": "寒い朝は体が冷えて代謝が下がるため、温かい飲み物を飲むとよい。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は体[からだ]が冷[ひ]えて代謝[たいしゃ]が下[さ]がるため、温[あたた]かい飲[の]み物[もの]を飲[の]むとよい。", "sentence_source": "generated"}, {"text": "植物も動物も、生きているかぎり絶えず代謝を行っている。", "target_word": "代謝", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]も動物[どうぶつ]も、生[い]きているかぎり絶[た]えず代謝[たいしゃ]を行[おこな]っている。", "sentence_source": "generated"}, {"text": "睡眠が足りないと、ホルモンの働きが乱れて代謝に悪い影響が出る。", "target_word": "代謝", "complexity_tier": "T4", "furigana": "睡眠[すいみん]が足[た]りないと、ホルモンの働[はたら]きが乱[みだ]れて代謝[たいしゃ]に悪[わる]い影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "冬眠中の動物は、代謝を大きく落としてエネルギーの消費を抑える。", "target_word": "代謝", "complexity_tier": "T4", "furigana": "冬眠中[とうみんちゅう]の動物[どうぶつ]は、代謝[たいしゃ]を大[おお]きく落[お]としてエネルギーの消費[しょうひ]を抑[おさ]える。", "sentence_source": "generated"}, {"text": "医師は、糖の代謝に異常がないかを調べるために血液検査を勧めた。", "target_word": "代謝", "complexity_tier": "T4", "furigana": "医師[いし]は、糖[とう]の代謝[たいしゃ]に異常[いじょう]がないかを調[しら]べるために血液[けつえき]検査[けんさ]を勧[すす]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "代謝", "label": "基本形"}, {"form": "代謝する", "label": "サ変動詞"}], "register": "technical", "sense_fingerprint": "生物の体内で栄養を変換し不要物を分解する化学反応の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代謝", "is_correct": true, "explanation": "「微生物の代謝作用」は、生体内の化学変換を指す。発酵の説明に合う。"}, {"text": "免疫", "is_correct": false, "explanation": "免疫は病原体への防御機能のことで、微生物の化学変換には使わないので、空欄に合わない。"}, {"text": "循環", "is_correct": false, "explanation": "循環は血液などが巡ることを指す。「微生物の循環作用」とは言わないので合わない。"}, {"text": "排泄", "is_correct": false, "explanation": "排泄は体外に出すことを指す。化学変換を表す「作用」とは結びつかないので合わない。"}], "explanations": {"代謝": "「微生物の代謝作用」は、生体内の化学変換を指す。発酵の説明に合う。", "免疫": "免疫は病原体への防御機能のことで、微生物の化学変換には使わないので、空欄に合わない。", "循環": "循環は血液などが巡ることを指す。「微生物の循環作用」とは言わないので合わない。", "排泄": "排泄は体外に出すことを指す。化学変換を表す「作用」とは結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "代謝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂糖はお湯に入れると代謝して、すぐになくなる。", "explanation": "ここは〈溶解〉の場面。代謝は生物の体内の化学反応を指すので、砂糖が溶けることには使わない。"}, {"text": "雪は気温が上がると代謝して、すぐに消える。", "explanation": "ここは〈融解〉の場面。代謝は生体内の化学反応を指すので、雪が解けることには使わない。"}, {"text": "お湯を沸かし続けると、水が代謝して空気中に消えていく。", "explanation": "ここは〈蒸発〉の場面。代謝は生物の体内の変化を指すので、水が蒸発することには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代謝", "is_correct": true, "explanation": "「生きているかぎり絶えず代謝を行っている」で、生体内の化学反応を指す。"}, {"text": "感動", "is_correct": false, "explanation": "「感動を行う」は不自然で、体内の化学反応の文脈には合わない。"}, {"text": "恋愛", "is_correct": false, "explanation": "「恋愛を行う」は不自然で、生命活動の文脈には合わない。"}, {"text": "失恋", "is_correct": false, "explanation": "「失恋を行う」は成り立たず、生物の化学反応を述べる文に合わない。"}], "explanations": {"代謝": "「生きているかぎり絶えず代謝を行っている」で、生体内の化学反応を指す。", "感動": "「感動を行う」は不自然で、体内の化学反応の文脈には合わない。", "恋愛": "「恋愛を行う」は不自然で、生命活動の文脈には合わない。", "失恋": "「失恋を行う」は成り立たず、生物の化学反応を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "代謝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の車輪を代謝して、速く走れるようにした。", "explanation": "ここは〈改良〉の意味。代謝は生体内の化学反応を指すので、機械の性能を上げる改良には使わない。"}, {"text": "パソコンは長く使うと、内部の代謝が起きて動作が遅くなる。", "explanation": "ここは〈劣化〉の意味。代謝は体内の化学反応を指すので、機械の劣化には使わない。"}, {"text": "古い紙幣を代謝して、新札に入れ替えた。", "explanation": "ここは〈交換〉の意味。代謝は生体内の物質の変化を指し、紙幣の取り替えには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝不足が続くと、体の代謝を下がって、疲れが取れにくくなる。", "corrected_sentence": "寝不足が続くと、体の代謝が下がって、疲れが取れにくくなる。", "error_description": "「下がる」は自動詞なので、主語の代謝には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "辛い料理を食べると、代謝が高める。", "corrected_sentence": "辛い料理を食べると、代謝が高まる。", "error_description": "「高める」は他動詞で目的語に「を」を取る。代謝は自ら高まるので、自動詞「高まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "正解。一つにまとまったものを二つ以上に離すことで、結合の対義語になる。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ることを表す語で、つなげる・離すという対になる関係ではない。"}, {"text": "郷愁", "is_correct": false, "explanation": "故郷などを懐かしむ気持ちを表す語で、結合と対になる語ではない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様や気象の状態を表す語で、物のつながりとは関係がない。"}], "correct_answer": "分離", "explanations": {"分離": "正解。一つにまとまったものを二つ以上に離すことで、結合の対義語になる。", "睡眠": "眠ることを表す語で、つなげる・離すという対になる関係ではない。", "郷愁": "故郷などを懐かしむ気持ちを表す語で、結合と対になる語ではない。", "天候": "空模様や気象の状態を表す語で、物のつながりとは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「結合する」の対象（棒）を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉では、「棒より結合して」と動作の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す〈から〉では、「棒から結合して」と対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "名詞どうしをつなぐ〈の〉では、「棒の結合して」と動詞に続かない。"}], "correct_answer": "を", "explanations": {"を": "正解。「結合する」の対象（棒）を示す。", "より": "比較の〈より〉では、「棒より結合して」と動作の対象にならない。", "から": "起点を示す〈から〉では、「棒から結合して」と対象を示せない。", "の": "名詞どうしをつなぐ〈の〉では、「棒の結合して」と動詞に続かない。"}, "error_tags": {"より": "比較", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "正解。一つにまとまったものを二つ以上に離すことで、結合の対義語になる。"}, {"text": "停滞", "is_correct": false, "explanation": "物事が進まず止まることで、つなげる作業と反対の関係にはならない。"}, {"text": "喧騒", "is_correct": false, "explanation": "騒がしい状態を表す語で、物のつながりとは対になる関係にない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている時の息づかいを表す語で、結合と対になる語ではない。"}], "correct_answer": "分離", "explanations": {"分離": "正解。一つにまとまったものを二つ以上に離すことで、結合の対義語になる。", "停滞": "物事が進まず止まることで、つなげる作業と反対の関係にはならない。", "喧騒": "騒がしい状態を表す語で、物のつながりとは対になる関係にない。", "寝息": "眠っている時の息づかいを表す語で、結合と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "つなげること。", "primary_collocate": null, "pronunciation": "けつごう", "ipa": "ketsɯɡoː", "syllable_count": 4, "sentences": [{"text": "二つの部品の結合がゆるいと、機械は正しく動かない。", "target_word": "結合", "complexity_tier": "T3", "furigana": "二[ふた]つの部品[ぶひん]の結合[けつごう]がゆるいと、機械[きかい]は正[ただ]しく動[うご]かない。", "sentence_source": "generated"}, {"text": "強い接着剤を使って、板と板の結合を確かめた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "強[つよ]い接着剤[せっちゃくざい]を使[つか]って、板[いた]と板[いた]の結合[けつごう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "結合した部分から水がもれたので、すぐに直した。", "target_word": "結合", "complexity_tier": "T3", "furigana": "結合[けつごう]した部分[ぶぶん]から水[みず]がもれたので、すぐに直[なお]した。", "sentence_source": "generated"}, {"text": "小さな箱を結合すれば、長い机になる。", "target_word": "結合", "complexity_tier": "T3", "furigana": "小[ちい]さな箱[はこ]を結合[けつごう]すれば、長[なが]い机[つくえ]になる。", "sentence_source": "generated"}, {"text": "二つの言葉の結合によって、新しい単語が生まれた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "二[ふた]つの言葉[ことば]の結合[けつごう]によって、新[あたら]しい単語[たんご]が生[う]まれた。", "sentence_source": "generated"}, {"text": "結合が弱かったので、橋の一部が壊れてしまった。", "target_word": "結合", "complexity_tier": "T3", "furigana": "結合[けつごう]が弱[よわ]かったので、橋[はし]の一部[いちぶ]が壊[こわ]れてしまった。", "sentence_source": "generated"}, {"text": "部品の結合には、ねじを四本使う。", "target_word": "結合", "complexity_tier": "T3", "furigana": "部品[ぶひん]の結合[けつごう]には、ねじを四本[よんほん]使[つか]う。", "sentence_source": "generated"}, {"text": "棒を結合して長いはしごを作った。", "target_word": "結合", "complexity_tier": "T3", "furigana": "棒[ぼう]を結合[けつごう]して長[なが]いはしごを作[つく]った。", "sentence_source": "generated"}, {"text": "パイプの結合を終えてから、水を流してみた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "パイプの結合[けつごう]を終[お]えてから、水[みず]を流[なが]してみた。", "sentence_source": "generated"}, {"text": "ブロックの結合は簡単なので、子どもでも遊べる。", "target_word": "結合", "complexity_tier": "T3", "furigana": "ブロックの結合[けつごう]は簡単[かんたん]なので、子[こ]どもでも遊[あそ]べる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結合", "label": "基本形"}, {"form": "結合する", "label": "辞書形"}, {"form": "結合した", "label": "過去形"}, {"form": "結合して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "部品や物を一つにつなげること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結合", "is_correct": true, "explanation": "正解。部品どうしをつなげた状態を指し、「ゆるい」と合う。"}, {"text": "解除", "is_correct": false, "explanation": "取り去ることを表す語で、部品のつながり具合には当てはまらない。"}, {"text": "注油", "is_correct": false, "explanation": "油をさす作業を表す語で、つながりの状態を指す語ではない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を抜くことを表す語で、部品のつながりには当てはまらない。"}], "explanations": {"結合": "正解。部品どうしをつなげた状態を指し、「ゆるい」と合う。", "解除": "取り去ることを表す語で、部品のつながり具合には当てはまらない。", "注油": "油をさす作業を表す語で、つながりの状態を指す語ではない。", "乾燥": "水分を抜くことを表す語で、部品のつながりには当てはまらない。"}, "sentence_index": 0, "correct_answer": "結合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "包丁で大根を結合した。", "explanation": "ここは〈切断〉の意味。結合はつなげることで、切って分けるときには使わない。"}, {"text": "祖母は、古い家の雨漏りを結合した。", "explanation": "ここは〈修理〉の意味。結合はつなげることで、雨漏りを直す行為には使わない。"}, {"text": "母は、米を結合して、夕食を作った。", "explanation": "ここは〈炊く〉の意味。結合はつなげることで、米を火にかけて炊く調理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結合", "is_correct": true, "explanation": "正解。部品をつなげる作業を指し、「結合には」と続く。"}, {"text": "放送", "is_correct": false, "explanation": "電波で知らせることを表す語で、部品をつなげる作業とは合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "汚れを取り除くことを表す語で、部品をつなげる作業は指さない。"}, {"text": "献立", "is_correct": false, "explanation": "料理の予定表を表す語で、部品の作業には関係しない。"}], "explanations": {"結合": "正解。部品をつなげる作業を指し、「結合には」と続く。", "放送": "電波で知らせることを表す語で、部品をつなげる作業とは合わない。", "清掃": "汚れを取り除くことを表す語で、部品をつなげる作業は指さない。", "献立": "料理の予定表を表す語で、部品の作業には関係しない。"}, "sentence_index": 6, "correct_answer": "結合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になり、街灯が結合した。", "explanation": "ここは〈点灯〉の意味。結合は物をつなげることで、明かりをともす場面には使わない。"}, {"text": "夕方、公園を結合した。", "explanation": "ここは〈散策〉の意味。結合は物をつなげることで、歩き回る行為には使わない。"}, {"text": "母は洗濯機で服を結合した。", "explanation": "ここは〈洗濯〉の意味。結合は物をつなげることで、汚れを落とす行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの板は、ねじでしっかり結合ます。", "corrected_sentence": "二つの板は、ねじでしっかり結合します。", "error_description": "サ変動詞「結合する」の丁寧形は「結合します」。「結合ます」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場では、鉄の部品の結合に強める薬を使っている。", "corrected_sentence": "この工場では、鉄の部品の結合を強める薬を使っている。", "error_description": "「強める」の対象は〈を〉で示す。〈に〉は誤り。正しくは「結合を強める」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「結合によって」の一部で、結合の直後に来る。"}, {"text": "が", "is_correct": false, "explanation": "「結合が」だと主語になり、後ろの「よって」と文がつながらない。"}, {"text": "を", "is_correct": false, "explanation": "「結合を」は目的語になるが、「によって」の前に置くと不自然で文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「結合で」は手段を表すが、後ろの「よって」と合わず文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「結合によって」の一部で、結合の直後に来る。", "が": "「結合が」だと主語になり、後ろの「よって」と文がつながらない。", "を": "「結合を」は目的語になるが、「によって」の前に置くと不自然で文が成り立たない。", "で": "「結合で」は手段を表すが、後ろの「よって」と合わず文が成立しない。"}, "error_tags": {"が": "主語の助詞", "を": "目的語の助詞", "で": "手段の助詞"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "正解。分離は一つにまとまったものを二つ以上に離すことで、結合の対義語になる。"}, {"text": "減少", "is_correct": false, "explanation": "減少は数や量が減ることで、まとめる結合の対義語とは言えない。"}, {"text": "拡散", "is_correct": false, "explanation": "拡散は広がり散ることで、まとめる結合の対義語にはならない。"}, {"text": "解放", "is_correct": false, "explanation": "解放は束縛をとくことで、物の結びつきを表す結合の対義語としては挙がらない。"}], "correct_answer": "分離", "explanations": {"分離": "正解。分離は一つにまとまったものを二つ以上に離すことで、結合の対義語になる。", "減少": "減少は数や量が減ることで、まとめる結合の対義語とは言えない。", "拡散": "拡散は広がり散ることで、まとめる結合の対義語にはならない。", "解放": "解放は束縛をとくことで、物の結びつきを表す結合の対義語としては挙がらない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "正解。分離は一つにまとまったものを二つ以上に離すことで、結合の対義語になる。"}, {"text": "拡大", "is_correct": false, "explanation": "拡大は規模を広げることで、まとめる結合の対義語にはならない。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は手放すことで、一つにする結合の対義語とは言えない。"}, {"text": "独占", "is_correct": false, "explanation": "独占は一人で占めることで、結合の対義語としては挙がらない。"}], "correct_answer": "分離", "explanations": {"分離": "正解。分離は一つにまとまったものを二つ以上に離すことで、結合の対義語になる。", "拡大": "拡大は規模を広げることで、まとめる結合の対義語にはならない。", "放棄": "放棄は手放すことで、一つにする結合の対義語とは言えない。", "独占": "独占は一人で占めることで、結合の対義語としては挙がらない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上のものが、一つになるようにつながること。また、つなげること。", "primary_collocate": null, "pronunciation": "けつごう", "ipa": "ketsɯɡoː", "syllable_count": 4, "sentences": [{"text": "水素と酸素が結合して、水ができる。", "target_word": "結合", "complexity_tier": "T3", "furigana": "水素[すいそ]と酸素[さんそ]が結合[けつごう]して、水[みず]ができる。", "sentence_source": "generated"}, {"text": "二つの会社の結合によって、大きな新会社が生まれた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の結合[けつごう]によって、大[おお]きな新会社[しんがいしゃ]が生[う]まれた。", "sentence_source": "generated"}, {"text": "原子の結合が強いほど、その物質は壊れにくい。", "target_word": "結合", "complexity_tier": "T3", "furigana": "原子[げんし]の結合[けつごう]が強[つよ]いほど、その物質[ぶっしつ]は壊[こわ]れにくい。", "sentence_source": "generated"}, {"text": "細胞が結合して、一つの大きな組織になる。", "target_word": "結合", "complexity_tier": "T3", "furigana": "細胞[さいぼう]が結合[けつごう]して、一[ひと]つの大[おお]きな組織[そしき]になる。", "sentence_source": "generated"}, {"text": "異なる技術の結合によって、これまでにない製品が生まれた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "異[こと]なる技術[ぎじゅつ]の結合[けつごう]によって、これまでにない製品[せいひん]が生まれた。", "sentence_source": "generated"}, {"text": "結合した二つの図形は、大きな円に見える。", "target_word": "結合", "complexity_tier": "T3", "furigana": "結合[けつごう]した二[ふた]つの図形[ずけい]は、大[おお]きな円[えん]に見[み]える。", "sentence_source": "generated"}, {"text": "言葉と音楽の結合から、新しい芸術が生まれた。", "target_word": "結合", "complexity_tier": "T3", "furigana": "言葉[ことば]と音楽[おんがく]の結合[けつごう]から、新[あたら]しい芸術[げいじゅつ]が生[う]まれた。", "sentence_source": "generated"}, {"text": "水の分子は、結合の仕方によって性質が変わる。", "target_word": "結合", "complexity_tier": "T3", "furigana": "水[みず]の分子[ぶんし]は、結合[けつごう]の仕方[しかた]によって性質[せいしつ]が変[か]わる。", "sentence_source": "generated"}, {"text": "この薬は体の中のたんぱく質と結合して、働きを示す。", "target_word": "結合", "complexity_tier": "T3", "furigana": "この薬[くすり]は体[からだ]の中[なか]のたんぱく質[しつ]と結合[けつごう]して、働[はたら]きを示[しめ]す。", "sentence_source": "generated"}, {"text": "小さな国々が結合して、一つの連合になった。", "target_word": "結合", "complexity_tier": "T3", "furigana": "小[ちい]さな国々[くにぐに]が結合[けつごう]して、一[ひと]つの連合[れんごう]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結合", "label": "基本形"}, {"form": "結合する", "label": "辞書形"}, {"form": "結合した", "label": "過去形"}, {"form": "結合して", "label": "て形"}], "register": "formal", "sense_fingerprint": "二つ以上のものが合わさって一つになること（化学・組織などにも使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結合", "is_correct": true, "explanation": "正解。水素と酸素がつながって水という一つの物質になる意味で、ここに入る。"}, {"text": "分解", "is_correct": false, "explanation": "分解は一つのものをばらばらにすることなので、水素と酸素が分解して水ができるという文に合わない。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は液体が気体になることなので、水素と酸素を主語にして水ができる文の述語には合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "凝固は液体が固まることなので、気体の水素と酸素が水をつくる文には当てはまらない。"}], "explanations": {"結合": "正解。水素と酸素がつながって水という一つの物質になる意味で、ここに入る。", "分解": "分解は一つのものをばらばらにすることなので、水素と酸素が分解して水ができるという文に合わない。", "蒸発": "蒸発は液体が気体になることなので、水素と酸素を主語にして水ができる文の述語には合わない。", "凝固": "凝固は液体が固まることなので、気体の水素と酸素が水をつくる文には当てはまらない。"}, "sentence_index": 0, "correct_answer": "結合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説の結合は、主人公が村を去る場面だ。", "explanation": "ここは〈結末〉の意味。物語の終わりを指す語なので、ものをつなぐ〈結合〉とは言えない。"}, {"text": "会議の最後に、その議論の結合をまとめた。", "explanation": "ここは〈結論〉の意味。議論の末に出す答えを指すので、〈結合〉は合わない。"}, {"text": "絵の具の赤と青を結合させて、紫色を作った。", "explanation": "ここは〈混合〉の意味。色を混ぜ合わせることは混合で、結合は分子などが化学的につながることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結合", "is_correct": true, "explanation": "正解。言葉と音楽が一つにまとまって新しい芸術になる流れに合う。"}, {"text": "消滅", "is_correct": false, "explanation": "消滅はなくなることなので、新しい芸術が生まれる文の原因にはならない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温かさなので、言葉と音楽の結びつきから芸術が生まれる文には入らない。"}, {"text": "停止", "is_correct": false, "explanation": "停止は動きを止めることなので、新しい芸術が生まれるという結果と結びつかない。"}], "explanations": {"結合": "正解。言葉と音楽が一つにまとまって新しい芸術になる流れに合う。", "消滅": "消滅はなくなることなので、新しい芸術が生まれる文の原因にはならない。", "気温": "気温は空気の温かさなので、言葉と音楽の結びつきから芸術が生まれる文には入らない。", "停止": "停止は動きを止めることなので、新しい芸術が生まれるという結果と結びつかない。"}, "sentence_index": 6, "correct_answer": "結合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両国は、平和条約を結合した。", "explanation": "ここは〈締結〉の意味。条約を取り交わして成立させることは締結で、結合とは言わない。"}, {"text": "靴ひもを結合して、しっかり締めた。", "explanation": "ここは〈結ぶ〉の意味。ひもを縛ってつなぐ動作は結ぶで、結合は合わない。"}, {"text": "生徒たちは背の順に結合した。", "explanation": "ここは〈整列〉の意味。順に並べることは整列で、一つにつながる結合とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ナトリウムと塩素が結合に、食塩ができる。", "corrected_sentence": "ナトリウムと塩素が結合して、食塩ができる。", "error_description": "誤りは「結合に」。正しくは「結合して」。結合は動詞なので、後ろの「食塩ができる」へつなぐには連用形の「して」が必要。「に」では文がつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38637, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "タンパク質が酵素と結合が、反応が進む。", "corrected_sentence": "タンパク質が酵素と結合して、反応が進む。", "error_description": "誤りは「結合が」。正しくは「結合して」。「結合」は動詞ではなく、「が」では文が完結しない。連用形「して」で後ろへつなぐ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「様式は」で、様式を話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「様式を、国や地方によって」は目的語になるが、違うという述語と結びつかず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「様式で、国や地方によって違う」は手段の意味になり、違うという述語と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「様式へ」は方向を表すが、違うという意味にならない。"}], "correct_answer": "は", "explanations": {"は": "正解。「様式は」で、様式を話題として示す。", "を": "「様式を、国や地方によって」は目的語になるが、違うという述語と結びつかず不自然。", "で": "「様式で、国や地方によって違う」は手段の意味になり、違うという述語と合わない。", "へ": "「様式へ」は方向を表すが、違うという意味にならない。"}, "error_tags": {"を": "目的語の助詞", "で": "手段の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「様式が統一されている」で、統一される主語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「報告書の様式の社内で」と続かず、統一される主語を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「様式を社内で統一されている」は目的語になるが、受け身の文と合わず成立しない。"}, {"text": "より", "is_correct": false, "explanation": "「様式より社内で統一」は比較の意味になり、受け身の文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "正解。「様式が統一されている」で、統一される主語を示す。", "の": "「報告書の様式の社内で」と続かず、統一される主語を示せない。", "を": "「様式を社内で統一されている」は目的語になるが、受け身の文と合わず成立しない。", "より": "「様式より社内で統一」は比較の意味になり、受け身の文として成立しない。"}, "error_tags": {"の": "連体修飾の誤り", "を": "目的語の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、決まった形ややり方のこと。", "primary_collocate": null, "pronunciation": "ようしき", "ipa": "joːɕiki", "syllable_count": 4, "sentences": [{"text": "日本の家の様式は、気候に合わせて長い年月をかけて変わってきた。", "target_word": "様式", "complexity_tier": "T3", "furigana": "日本[にほん]の家[いえ]の様式[ようしき]は、気候[きこう]に合[あ]わせて長[なが]い年月[としつき]をかけて変[か]わってきた。", "sentence_source": "generated"}, {"text": "結婚式の様式は、国や地方によってかなり違う。", "target_word": "様式", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の様式[ようしき]は、国[くに]や地方[ちほう]によってかなり違[ちが]う。", "sentence_source": "generated"}, {"text": "この書類は決まった様式で書かないと、受け付けてもらえない。", "target_word": "様式", "complexity_tier": "T3", "furigana": "この書類[しょるい]は決[き]まった様式[ようしき]で書[か]かないと、受[う]け付[つ]けてもらえない。", "sentence_source": "generated"}, {"text": "都会と田舎では、人びとの暮らしの様式が異なる。", "target_word": "様式", "complexity_tier": "T3", "furigana": "都会[とかい]と田舎[いなか]では、人[ひと]びとの暮[く]らしの様式[ようしき]が異[こと]なる。", "sentence_source": "generated"}, {"text": "彼の絵は、古い様式を守りながら新しい色を取り入れている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]は、古[ふる]い様式[ようしき]を守[まも]りながら新[あたら]しい色[いろ]を取[と]り入[い]れている。", "sentence_source": "generated"}, {"text": "手紙の様式を学ぶために、見本をいくつも読んだ。", "target_word": "様式", "complexity_tier": "T3", "furigana": "手紙[てがみ]の様式[ようしき]を学[まな]ぶために、見本[みほん]をいくつも読[よ]んだ。", "sentence_source": "generated"}, {"text": "この神社は、平安時代の様式で建てられている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "この神社[じんじゃ]は、平安時代[へいあんじだい]の様式[ようしき]で建[た]てられている。", "sentence_source": "generated"}, {"text": "この会社では、報告書の様式が社内で統一されている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、報告書[ほうこくしょ]の様式[ようしき]が社内[しゃない]で統一[とういつ]されている。", "sentence_source": "generated"}, {"text": "茶道では、お茶をいれる様式がきちんと決まっている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "茶道[さどう]では、お茶[ちゃ]をいれる様式[ようしき]がきちんと決[き]まっている。", "sentence_source": "generated"}, {"text": "昔の様式にこだわらず、自由な形で発表してもよい。", "target_word": "様式", "complexity_tier": "T3", "furigana": "昔[むかし]の様式[ようしき]にこだわらず、自由[じゆう]な形[かたち]で発表[はっぴょう]してもよい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "様式", "label": "基本形"}], "register": "formal", "sense_fingerprint": "ある分野や場面で決まっている形ややり方（書式・建て方・作法など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "様式", "is_correct": true, "explanation": "正解。家の建て方や作りの型を表すので、家の様式として変わってきたという文に入る。"}, {"text": "感情", "is_correct": false, "explanation": "感情は人の心の動きなので、家の作りが気候に合わせて変わるという文には合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠たい感覚なので、家が長い年月をかけて変わる対象にはならない。"}, {"text": "体調", "is_correct": false, "explanation": "体調は体の状態を指すので、建物について述べる文には使えない。"}], "explanations": {"様式": "正解。家の建て方や作りの型を表すので、家の様式として変わってきたという文に入る。", "感情": "感情は人の心の動きなので、家の作りが気候に合わせて変わるという文には合わない。", "眠気": "眠気は眠たい感覚なので、家が長い年月をかけて変わる対象にはならない。", "体調": "体調は体の状態を指すので、建物について述べる文には使えない。"}, "sentence_index": 0, "correct_answer": "様式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その映画を見終わって、私は様式を述べた。", "explanation": "ここは〈感想〉の意味。見た後の気持ちを言葉にするのは感想で、様式は形ややり方なので述べる対象にならない。"}, {"text": "彼は様式を鎮めるため、深呼吸をした。", "explanation": "ここは〈怒り〉の意味。鎮めるのは感情で、様式は形ややり方なので鎮める対象にならない。"}, {"text": "ケーキを焼くために、様式に生地を流し込んだ。", "explanation": "ここは〈型〉の意味。生地を流し込んで形を作る器を指すので、抽象的な様式は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "様式", "is_correct": true, "explanation": "正解。平安時代に特有の建て方を表すので、神社の建て方を述べる文に入る。"}, {"text": "年号", "is_correct": false, "explanation": "年号は年の呼び名なので、建物の建て方を表す文には入らない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時の点を指すので、建て方を表すことはできない。"}, {"text": "人数", "is_correct": false, "explanation": "人数は人の数なので、神社の建て方を述べる文に合わない。"}], "explanations": {"様式": "正解。平安時代に特有の建て方を表すので、神社の建て方を述べる文に入る。", "年号": "年号は年の呼び名なので、建物の建て方を表す文には入らない。", "時刻": "時刻は時の点を指すので、建て方を表すことはできない。", "人数": "人数は人の数なので、神社の建て方を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "様式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テレビで明日の様式を予報する。", "explanation": "ここは〈天気〉の意味。空模様を予報するのは天気で、様式は予報の対象にならない。"}, {"text": "春の様式が、ゆっくり町に訪れた。", "explanation": "ここは〈季節〉の意味。季節が町に訪れるとは言えるが、決まった形ややり方の様式は訪れない。"}, {"text": "時間の様式を計るため、タイマーを使った。", "explanation": "ここは〈時刻〉の意味。時の刻みを計るのは時刻や秒数で、決まった形ややり方の様式は計る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この建物は、古い様式を建てられている。", "corrected_sentence": "この建物は、古い様式で建てられている。", "error_description": "誤りは「様式を」。正しくは「様式で」。様式は建て方の手段を表すので「で」が必要。「を」だと様式そのものを建てることになり、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の様式を従って、注文票を書く。", "corrected_sentence": "この店の様式に従って、注文票を書く。", "error_description": "誤りは「様式を」。正しくは「様式に」。「従う」の対象は〈に〉で示す。〈を〉は誤り。正しくは「様式に従って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「細菌の働き」で、名詞どうしを結ぶ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「細菌を働き」と名詞が続かず、不自然。「を」は目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「細菌に働き」は成り立たない。「に」は相手・帰着点を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「細菌へ働き」は成り立たない。「へ」は方向を示す。"}], "correct_answer": "の", "explanations": {"の": "正解。「細菌の働き」で、名詞どうしを結ぶ「の」。", "を": "「細菌を働き」と名詞が続かず、不自然。「を」は目的語を示す。", "に": "「細菌に働き」は成り立たない。「に」は相手・帰着点を示す。", "へ": "「細菌へ働き」は成り立たない。「へ」は方向を示す。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「細菌は」で、細菌について述べる主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「細菌を条件がよければ」は成り立たない。「を」は目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「細菌に条件がよければ」は成り立たない。「に」は相手・帰着点を示す。"}, {"text": "で", "is_correct": false, "explanation": "「細菌で条件がよければ」は成り立たない。「で」は手段・場所を示す。"}], "correct_answer": "は", "explanations": {"は": "正解。「細菌は」で、細菌について述べる主題を示す。", "を": "「細菌を条件がよければ」は成り立たない。「を」は目的語を示す。", "に": "「細菌に条件がよければ」は成り立たない。「に」は相手・帰着点を示す。", "で": "「細菌で条件がよければ」は成り立たない。「で」は手段・場所を示す。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "肉眼では見えない微小な生物。環境中に広く存在し、分解や発酵などの働きをする。", "primary_collocate": null, "pronunciation": "さいきん", "ipa": "saikiɴ", "syllable_count": 4, "sentences": [{"text": "土の中の細菌が、落ち葉を分解している。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "土[つち]の中[なか]の細菌[さいきん]が、落[お]ち葉[ば]を分解[ぶんかい]している。", "sentence_source": "generated"}, {"text": "ヨーグルトは乳酸菌という細菌の働きで作られる。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "ヨーグルトは乳酸菌[にゅうさんきん]という細菌[さいきん]の働[はたら]きで作[つく]られる。", "sentence_source": "generated"}, {"text": "納豆は、納豆菌という細菌が大豆を発酵させたものだ。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "納豆[なっとう]は、納豆菌[なっとうきん]という細菌[さいきん]が大豆[だいず]を発酵[はっこう]させたものだ。", "sentence_source": "generated"}, {"text": "細菌は核を持たない単細胞の生物だ。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "細菌[さいきん]は核[かく]を持[も]たない単細胞[たんさいぼう]の生物[せいぶつ]だ。", "sentence_source": "generated"}, {"text": "抗生物質は、細菌による感染症の治療に使われる。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "抗生物質[こうせいぶっしつ]は、細菌[さいきん]による感染症[かんせんしょう]の治療[ちりょう]に使[つか]われる。", "sentence_source": "generated"}, {"text": "下水処理場では、細菌が汚れを分解する。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "下水[げすい]処理場[しょりじょう]では、細菌[さいきん]が汚[よご]れを分解[ぶんかい]する。", "sentence_source": "generated"}, {"text": "細菌の中には、人間の腸内で役に立つものもいる。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "細菌[さいきん]の中[なか]には、人間[にんげん]の腸内[ちょうない]で役[やく]に立[た]つものもいる。", "sentence_source": "generated"}, {"text": "細菌は条件がよければ、短時間で何倍にも増殖する。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "細菌[さいきん]は条件[じょうけん]がよければ、短時間[たんじかん]で何倍[なんばい]にも増殖[ぞうしょく]する。", "sentence_source": "generated"}, {"text": "研究者は、海底にすむ新しい細菌を発見した。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、海底[かいてい]にすむ新[あたら]しい細菌[さいきん]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "細菌とウイルスでは、増え方も大きさもちがう。", "target_word": "細菌", "complexity_tier": "T3", "furigana": "細菌[さいきん]とウイルスでは、増[ふ]え方[かた]も大[おお]きさもちがう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "細菌", "label": "基本形"}], "register": "formal", "sense_fingerprint": "分解・発酵・感染などに関わる単細胞の微生物（生物学・科学の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "細菌", "is_correct": true, "explanation": "正解。落ち葉を分解する生物として文が成り立つ唯一の語。"}, {"text": "石", "is_correct": false, "explanation": "石は分解の働きをしないので、落ち葉を分解する主語にならない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は分解の働きをしないので、「落ち葉を分解している」の主語として合わない。"}, {"text": "水晶", "is_correct": false, "explanation": "水晶は鉱物で分解の働きをしないので、文の主語として成り立たない。"}], "explanations": {"細菌": "正解。落ち葉を分解する生物として文が成り立つ唯一の語。", "石": "石は分解の働きをしないので、落ち葉を分解する主語にならない。", "砂": "砂は分解の働きをしないので、「落ち葉を分解している」の主語として合わない。", "水晶": "水晶は鉱物で分解の働きをしないので、文の主語として成り立たない。"}, "sentence_index": 0, "correct_answer": "細菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ミミズは細菌の一種で、土の中にたくさんいる。", "explanation": "ここは〈動物〉の意味。ミミズは肉眼で見える動物で、肉眼では見えない細菌の一種とするのは合わない。"}, {"text": "コンピューターが細菌に感染して、画面が止まった。", "explanation": "ここは〈ウイルス〉の意味。コンピューターに感染して壊すのはウイルスで、細菌は合わない。"}, {"text": "タケノコは細菌で、春に土から出てくる。", "explanation": "ここは〈植物〉の意味。タケノコは肉眼で見える植物で、肉眼では見えない細菌とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "細菌", "is_correct": true, "explanation": "正解。人間の腸内で役に立つ生き物を指す。"}, {"text": "酸素", "is_correct": false, "explanation": "「〜ものもいる」は生き物を指すので、酸素は文が成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "「〜ものもいる」は生き物を指すので、電池は文が成り立たない。"}, {"text": "石油", "is_correct": false, "explanation": "「〜ものもいる」は生き物を指すので、石油は文が成り立たない。"}], "explanations": {"細菌": "正解。人間の腸内で役に立つ生き物を指す。", "酸素": "「〜ものもいる」は生き物を指すので、酸素は文が成り立たない。", "電池": "「〜ものもいる」は生き物を指すので、電池は文が成り立たない。", "石油": "「〜ものもいる」は生き物を指すので、石油は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "細菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "細菌は、池で跳ねて鳴く。", "explanation": "ここは〈カエル〉の意味。カエルは肉眼で見える動物で、肉眼では見えない細菌とは合わない。"}, {"text": "細菌は、磁石にくっつき、家電の部品に使われる。", "explanation": "ここは〈金属〉の意味。金属は磁石にくっつき家電の部品に使われるが、細菌は肉眼では見えない微生物で、磁石にはくっつかないので合わない。"}, {"text": "細菌は、畑で草を食べて大きくなる。", "explanation": "ここは〈牛〉の意味。牛は肉眼で見える動物で、肉眼では見えない細菌とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池の底の細菌を、落ち葉を分解している。", "corrected_sentence": "池の底の細菌が、落ち葉を分解している。", "error_description": "「分解している」の主語を示すには「細菌が」が必要。「細菌を」は目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38641, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "探検隊は、深海にすむ新しい細菌に発見した。", "corrected_sentence": "探検隊は、深海にすむ新しい細菌を発見した。", "error_description": "「発見する」の対象は目的語なので「細菌を」を使う。「細菌に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「真菌の一種」の「の」で、真菌と一種を結ぶ。"}, {"text": "が", "is_correct": false, "explanation": "「真菌が一種です」では主語になり、一種という名詞とつながらない。"}, {"text": "を", "is_correct": false, "explanation": "「真菌を一種です」は目的語にならず、文がつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「真菌で一種です」は手段の意味になり、一種と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "正解。「真菌の一種」の「の」で、真菌と一種を結ぶ。", "が": "「真菌が一種です」では主語になり、一種という名詞とつながらない。", "を": "「真菌を一種です」は目的語にならず、文がつながらない。", "で": "「真菌で一種です」は手段の意味になり、一種と結びつかない。"}, "error_tags": {"が": "主語の助詞", "を": "目的語の助詞", "で": "手段の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「真菌の中」の「の」で、真菌とその中を結ぶ。"}, {"text": "に", "is_correct": false, "explanation": "「真菌に中には」と続かず、場所の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「真菌へ中には」は方向を表すが、中の範囲を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「真菌と中には」は並列の意味になり、中を指せない。"}], "correct_answer": "の", "explanations": {"の": "正解。「真菌の中」の「の」で、真菌とその中を結ぶ。", "に": "「真菌に中には」と続かず、場所の関係が成り立たない。", "へ": "「真菌へ中には」は方向を表すが、中の範囲を示せない。", "と": "「真菌と中には」は並列の意味になり、中を指せない。"}, "error_tags": {"に": "格助詞の誤り", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物のなかまの一つで、かびやきのこのことです。", "primary_collocate": null, "pronunciation": "しんきん", "ipa": "ɕiŋkiɴ", "syllable_count": 4, "sentences": [{"text": "真菌は、かびやきのこのなかまの生き物です。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "真菌[しんきん]は、かびやきのこのなかまの生[い]き物[もの]です。", "sentence_source": "generated"}, {"text": "パンに生えるかびは真菌の一種です。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "パンに生[は]えるかびは真菌[しんきん]の一種[いっしゅ]です。", "sentence_source": "generated"}, {"text": "台所のスポンジに生えた黒いかびも、真菌のなかまです。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "台所[だいどころ]のスポンジに生[は]えた黒[くろ]いかびも、真菌[しんきん]のなかまです。", "sentence_source": "generated"}, {"text": "しいたけやしめじも、実は真菌のなかまです。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "しいたけやしめじも、実[じつ]は真菌[しんきん]のなかまです。", "sentence_source": "generated"}, {"text": "真菌は植物ではないので、光で栄養をつくることができません。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "真菌[しんきん]は植物[しょくぶつ]ではないので、光[ひかり]で栄養[えいよう]をつくることができません。", "sentence_source": "generated"}, {"text": "先生は、きのこもかびも同じ真菌だと説明しました。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "先生[せんせい]は、きのこもかびも同[おな]じ真菌[しんきん]だと説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "風呂場の壁が黒くなったのは、真菌が増えたからです。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "風呂場[ふろば]の壁[かべ]が黒[くろ]くなったのは、真菌[しんきん]が増[ふ]えたからです。", "sentence_source": "generated"}, {"text": "真菌の中には、パンやお酒をつくるときに役に立つものもあります。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "真菌[しんきん]の中[なか]には、パンやお酒[さけ]をつくるときに役[やく]に立[た]つものもあります。", "sentence_source": "generated"}, {"text": "理科の授業で、虫めがねを使って真菌を観察しました。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、虫[むし]めがねを使[つか]って真菌[しんきん]を観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "夏は気温も湿度も高いので、真菌がよく育ちます。", "target_word": "真菌", "complexity_tier": "T3", "furigana": "夏[なつ]は気温[きおん]も湿度[しつど]も高[たか]いので、真菌[しんきん]がよく育[そだ]ちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "真菌", "label": "基本形"}], "register": "丁寧（です・ます）", "sense_fingerprint": "かびやきのこをまとめて指す、生き物のなかまの名前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 虫めがね (Zipf 1.44)']::text[], '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真菌", "is_correct": true, "explanation": "正解。かびやきのこをまとめて指す生き物のなかまの名前で、ここに入る。"}, {"text": "胞子", "is_correct": false, "explanation": "胞子は生殖に使われる細胞で、生き物のなかまを指す語ではない。"}, {"text": "栄養", "is_correct": false, "explanation": "栄養は体に取り入れる物質で、生き物のなかまの名前にはならない。"}, {"text": "水分", "is_correct": false, "explanation": "水分は水の量を指す語で、生き物のなかまの名前として当てはまらない。"}], "explanations": {"真菌": "正解。かびやきのこをまとめて指す生き物のなかまの名前で、ここに入る。", "胞子": "胞子は生殖に使われる細胞で、生き物のなかまを指す語ではない。", "栄養": "栄養は体に取り入れる物質で、生き物のなかまの名前にはならない。", "水分": "水分は水の量を指す語で、生き物のなかまの名前として当てはまらない。"}, "sentence_index": 0, "correct_answer": "真菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その事件の真菌を明らかにするため、調査を続けた。", "explanation": "ここは〈真実〉の意味。隠れた事実を明らかにする場面で、生き物の名前である真菌は合わない。"}, {"text": "実験では、食品を真菌の状態で保存した。", "explanation": "ここは〈真空〉の意味。空気を抜いた状態を指すので、真菌の状態とは言えない。"}, {"text": "真菌の暑さに、体がついていけなかった。", "explanation": "ここは〈真夏〉の意味。夏の盛りを指すので、真菌の暑さとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真菌", "is_correct": true, "explanation": "正解。湿気の多い場所で増えて壁を黒くする生物を指すので、ここに入る。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える部品で、増えて壁を黒くする理由にならない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、増えるものではないので理由として合わない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "窓ガラスは増えるものではなく、壁が黒くなる原因として当てはまらない。"}], "explanations": {"真菌": "正解。湿気の多い場所で増えて壁を黒くする生物を指すので、ここに入る。", "電池": "電池は電気を蓄える部品で、増えて壁を黒くする理由にならない。", "天井": "天井は部屋の上の面で、増えるものではないので理由として合わない。", "窓ガラス": "窓ガラスは増えるものではなく、壁が黒くなる原因として当てはまらない。"}, "sentence_index": 6, "correct_answer": "真菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の真菌は晴れるでしょう。", "explanation": "ここは〈天気〉の意味。空の状態を言うので、生き物の名前である真菌は使えない。"}, {"text": "夏の真菌が高いので、エアコンをつけた。", "explanation": "ここは〈気温〉の意味。暑さの度合いを言うので、真菌が高いとは言えない。"}, {"text": "毎月、大家さんに真菌を払う。", "explanation": "ここは〈家賃〉の意味。部屋を借りる代金を払うので、真菌を払うとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土の中には、真菌を多く住んでいます。", "corrected_sentence": "土の中には、真菌が多く住んでいます。", "error_description": "誤りは「真菌を」。正しくは「真菌が」。「住む」は自動詞なので、主語の「が」を使う。「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は、真菌が一気に広げます。", "corrected_sentence": "夏は、真菌が一気に広がります。", "error_description": "誤りは「広げます」。正しくは「広がります」。真菌は自ら広がる自動詞の主語なので、他動詞の「広げる」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「長いテープの切断」と名詞を修飾する形なので『の』が正しい。"}, {"text": "が", "is_correct": false, "explanation": "『長いテープが切断は』では主語の形にならず、文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "『長いテープを切断は』では目的語の形として不自然で、文の流れに合わない。"}, {"text": "に", "is_correct": false, "explanation": "『長いテープに切断は』では位置や相手の意味が通らず、合わない。"}], "correct_answer": "の", "explanations": {"の": "「長いテープの切断」と名詞を修飾する形なので『の』が正しい。", "が": "『長いテープが切断は』では主語の形にならず、文が崩れる。", "を": "『長いテープを切断は』では目的語の形として不自然で、文の流れに合わない。", "に": "『長いテープに切断は』では位置や相手の意味が通らず、合わない。"}, "error_tags": {"が": "主格", "を": "対格", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "長いものを、はさみなどで二つに切ること。", "primary_collocate": null, "pronunciation": "せつだん", "ipa": "setsɯdaɴ", "syllable_count": 4, "sentences": [{"text": "ひもを二本に分けるため、はさみで切断した。", "target_word": "切断", "complexity_tier": "T3", "furigana": "ひもを二本[にほん]に分[わ]けるため、はさみで切断[せつだん]した。", "sentence_source": "generated"}, {"text": "長いテープの切断は、まっすぐ線を引いてからするときれいにできる。", "target_word": "切断", "complexity_tier": "T3", "furigana": "長[なが]いテープの切断[せつだん]は、まっすぐ線[せん]を引[ひ]いてからするときれいにできる。", "sentence_source": "generated"}, {"text": "この太い針金は、手では切断できないので、工具を使う。", "target_word": "切断", "complexity_tier": "T3", "furigana": "この太[ふと]い針金[はりがね]は、手[て]では切断[せつだん]できないので、工具[こうぐ]を使[つか]う。", "sentence_source": "generated"}, {"text": "切断した紙のはしを、のりでつなぎ合わせた。", "target_word": "切断", "complexity_tier": "T3", "furigana": "切断[せつだん]した紙[かみ]のはしを、のりでつなぎ合[あ]わせた。", "sentence_source": "generated"}, {"text": "長いロープを半分に切断すると、使いやすい長さになる。", "target_word": "切断", "complexity_tier": "T3", "furigana": "長[なが]いロープを半分[はんぶん]に切断[せつだん]すると、使[つか]いやすい長[なが]さになる。", "sentence_source": "generated"}, {"text": "布の切断には、よく切れるはさみが必要だ。", "target_word": "切断", "complexity_tier": "T3", "furigana": "布[ぬの]の切断[せつだん]には、よく切[き]れるはさみが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "切断した竹を、さらに短く切って花びんにした。", "target_word": "切断", "complexity_tier": "T3", "furigana": "切断[せつだん]した竹[たけ]を、さらに短[みじか]く切[き]って花[はな]びんにした。", "sentence_source": "generated"}, {"text": "はさみの刃がこぼれて、リボンの切断がうまくできない。", "target_word": "切断", "complexity_tier": "T3", "furigana": "はさみの刃[は]がこぼれて、リボンの切断[せつだん]がうまくできない。", "sentence_source": "generated"}, {"text": "工作の時間に、細い木の棒を二本に切断した。", "target_word": "切断", "complexity_tier": "T3", "furigana": "工作[こうさく]の時間[じかん]に、細[ほそ]い木[き]の棒[ぼう]を二本[にほん]に切断[せつだん]した。", "sentence_source": "generated"}, {"text": "長い板を切断したが、切り口がまがっていたので、もう一度切り直した。", "target_word": "切断", "complexity_tier": "T3", "furigana": "長[なが]い板[いた]を切断[せつだん]したが、切[き]り口[ぐち]がまがっていたので、もう一度[いちど]切[き]り直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切断", "label": "基本形"}, {"form": "切断する", "label": "サ変動詞（辞書形）"}, {"form": "切断した", "label": "過去形"}, {"form": "切断できない", "label": "可能否定形"}], "register": "中立（だ・である調）", "sense_fingerprint": "ひも・紙・布など長いものを、はさみで切って二つに分ける動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 花びん (Zipf 1.51)']::text[], '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "ここは〈切断〉の意味。はさみで長いひもを二つに切る動作を表し、文の意味に合う。"}, {"text": "接着", "is_correct": false, "explanation": "接着はのりなどで貼り合わせること。はさみで接着するという動作は文に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べて確かめること。はさみで点検するのは意味が通らないので合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は汚れを落とすこと。はさみで洗濯するという動作は不自然で、文の流れに合わない。"}], "explanations": {"切断": "ここは〈切断〉の意味。はさみで長いひもを二つに切る動作を表し、文の意味に合う。", "接着": "接着はのりなどで貼り合わせること。はさみで接着するという動作は文に合わない。", "点検": "点検は調べて確かめること。はさみで点検するのは意味が通らないので合わない。", "洗濯": "洗濯は汚れを落とすこと。はさみで洗濯するという動作は不自然で、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この厚いカーテンは、外からの光を切断するので、部屋がとても暗い。", "explanation": "ここは〈遮断〉の意味。光や音をさえぎる時は遮断を使う。切断は長いものをはさみなどで二つに切ることなので合わない。"}, {"text": "健康のため、夜に飲むお酒を切断することにした。", "explanation": "ここは〈断つ〉の意味。飲食をやめる時は断つを使う。切断は物を二つに切る動作なので合わない。"}, {"text": "不要な写真を切断して、パソコンの容量を空けた。", "explanation": "ここは〈削除〉の意味。データを消す時は削除を使う。切断は物を切る動作なので、この文脈では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "ここは〈切断〉の意味。竹を短く切る動作を表し、文の流れに合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などに点数をつけること。竹を採点するという意味は成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は別の言語に置き換えること。竹には使えず、文に合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくること。竹を作曲するという文は意味が通らない。"}], "explanations": {"切断": "ここは〈切断〉の意味。竹を短く切る動作を表し、文の流れに合う。", "採点": "採点は答案などに点数をつけること。竹を採点するという意味は成り立たない。", "翻訳": "翻訳は別の言語に置き換えること。竹には使えず、文に合わない。", "作曲": "作曲は曲をつくること。竹を作曲するという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長く続いた戦争で、その国は二つに切断された。", "explanation": "ここは〈分断〉の意味。国や社会が二つに分かれる時は分断を使う。切断は長いものを物理的に切る動作で、国には使わない。"}, {"text": "文章を句点ごとに切断して、読みやすくした。", "explanation": "ここは〈区切る〉の意味。文章の切れ目を示す時は区切るを使う。切断は物を切り離す動作なので合わない。"}, {"text": "遺産を三人の兄弟で切断した。", "explanation": "ここは〈分割〉の意味。財産を分けるのは分割を使う。切断は物を切る動作なので、遺産には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "布の切断を、よく切れるはさみを使う。", "corrected_sentence": "布の切断に、よく切れるはさみを使う。", "error_description": "「〜に使う」は目的を表すので、切断の直後は「に」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉄の棒の切断を、工具を使うと安全だ。", "corrected_sentence": "鉄の棒の切断は、工具を使うと安全だ。", "error_description": "切断は文の主題なので「は」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ロープを切断して」と目的語を表すので『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『ロープに切断して』では位置や相手の意味にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『ロープへ切断して』では方向の意味にならず、文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "『ロープと切断して』では並列の意味にならず、文の流れに合わない。"}], "correct_answer": "を", "explanations": {"を": "「ロープを切断して」と目的語を表すので『を』が正しい。", "に": "『ロープに切断して』では位置や相手の意味にならず、不自然。", "へ": "『ロープへ切断して』では方向の意味にならず、文に合わない。", "と": "『ロープと切断して』では並列の意味にならず、文の流れに合わない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「刃物で切断する」と手段を表すので『で』が正しい。"}, {"text": "の", "is_correct": false, "explanation": "『刃物の切断すると』では動作の手段にならず、文が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "『刃物から切断すると』では起点の意味にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "『刃物より切断すると』では比較の意味になり、文の意味が合わない。"}], "correct_answer": "で", "explanations": {"で": "「刃物で切断する」と手段を表すので『で』が正しい。", "の": "『刃物の切断すると』では動作の手段にならず、文が崩れる。", "から": "『刃物から切断すると』では起点の意味にならず、不自然。", "より": "『刃物より切断すると』では比較の意味になり、文の意味が合わない。"}, "error_tags": {"の": "連体", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "つながっているものを、はさみや刃物などで切り離すこと。また、途中で断ち切ること。", "primary_collocate": null, "pronunciation": "せつだん", "ipa": "setsɯdaɴ", "syllable_count": 4, "sentences": [{"text": "事故で電線が切断され、町が停電しました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "事故[じこ]で電線[でんせん]が切断[せつだん]され、町[まち]が停電[ていでん]しました。", "sentence_source": "generated"}, {"text": "ナイフでロープを切断して、船を岸から離しました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "ナイフでロープを切断[せつだん]して、船[ふね]を岸[きし]から離[はな]しました。", "sentence_source": "generated"}, {"text": "電話の回線が切断されたため、通話が途中で終わりました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "電話[でんわ]の回線[かいせん]が切断[せつだん]されたため、通話[つうわ]が途中[とちゅう]で終[お]わりました。", "sentence_source": "generated"}, {"text": "木の枝を切断するときは、のこぎりを使います。", "target_word": "切断", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]を切断[せつだん]するときは、のこぎりを使[つか]います。", "sentence_source": "generated"}, {"text": "インターネットの接続が切断されて、画面が止まりました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "インターネットの接続[せつぞく]が切断[せつだん]されて、画面[がめん]が止[と]まりました。", "sentence_source": "generated"}, {"text": "医師は、けがをした足の切断が必要だと説明しました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "医師[いし]は、けがをした足[あし]の切断[せつだん]が必要[ひつよう]だと説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "工事で水道管が切断され、水が出なくなりました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "工事[こうじ]で水道管[すいどうかん]が切断[せつだん]され、水[みず]が出[で]なくなりました。", "sentence_source": "generated"}, {"text": "鋭い刃物で切断すると、切り口が平らになります。", "target_word": "切断", "complexity_tier": "T3", "furigana": "鋭[するど]い刃物[はもの]で切断[せつだん]すると、切[き]り口[くち]が平[たい]らになります。", "sentence_source": "generated"}, {"text": "配線を切断する前に、必ず電源を切ってください。", "target_word": "切断", "complexity_tier": "T3", "furigana": "配線[はいせん]を切断[せつだん]する前[まえ]に、必[かなら]ず電源[でんげん]を切[き]ってください。", "sentence_source": "generated"}, {"text": "強い風でつりばしのロープが切断され、渡れなくなりました。", "target_word": "切断", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]でつりばしのロープが切断[せつだん]され、渡[わた]れなくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切断", "label": "基本形"}, {"form": "切断する", "label": "サ変動詞（辞書形）"}, {"form": "切断された", "label": "受身過去形"}, {"form": "切断して", "label": "て形"}], "register": "丁寧（です・ます）", "sense_fingerprint": "つながっている線・管・回線などを切り離す、または途中で断ち切ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "ここは〈切断〉の意味。電線を切り離す動作を表し、停電の原因として文に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけること。電線が点灯されるという文は意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は別の言語に置き換えること。電線には使えず、文に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつけること。電線を採点するという文は成り立たない。"}], "explanations": {"切断": "ここは〈切断〉の意味。電線を切り離す動作を表し、停電の原因として文に合う。", "点灯": "点灯は明かりをつけること。電線が点灯されるという文は意味が通らない。", "翻訳": "翻訳は別の言語に置き換えること。電線には使えず、文に合わない。", "採点": "採点は点数をつけること。電線を採点するという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この厚い壁は、外の音を切断するので、部屋がとても静かです。", "explanation": "ここは〈遮断〉の意味。音や光をさえぎる時は遮断を使う。切断は物をつなぎ目で切り離す動作なので合わない。"}, {"text": "一度言った発言を切断して、なかったことにしました。", "explanation": "ここは〈撤回〉の意味。言ったことを取り消す時は撤回を使う。切断は物理的に切り離す動作なので、発言には使わない。"}, {"text": "不要なデータを切断して、パソコンの容量を空けました。", "explanation": "ここは〈削除〉の意味。データを消す時は削除を使う。切断は物を切り離す動作なので、この文脈では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切断", "is_correct": true, "explanation": "ここは〈切断〉の意味。水道管を切り離す動作で、断水の原因として文に合う。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくること。水道管を作曲するという文は意味が通らない。"}, {"text": "解説", "is_correct": false, "explanation": "解説は説明すること。水道管を解説するという文は成り立たない。"}, {"text": "点呼", "is_correct": false, "explanation": "点呼は人を順に呼んで確かめること。水道管には使えず、文に合わない。"}], "explanations": {"切断": "ここは〈切断〉の意味。水道管を切り離す動作で、断水の原因として文に合う。", "作曲": "作曲は曲をつくること。水道管を作曲するという文は意味が通らない。", "解説": "解説は説明すること。水道管を解説するという文は成り立たない。", "点呼": "点呼は人を順に呼んで確かめること。水道管には使えず、文に合わない。"}, "sentence_index": 6, "correct_answer": "切断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い戦争で、町の人々の心が切断されました。", "explanation": "ここは〈分断〉の意味。人の心や社会が二つに分かれる時は分断を使う。切断は物を切る動作なので合わない。"}, {"text": "話を三つの段落に切断して整理しました。", "explanation": "ここは〈区切る〉の意味。話や文章を区切る時は区切るを使う。切断は物理的に切り離す動作なので合わない。"}, {"text": "家の土地を家族の間で切断しました。", "explanation": "ここは〈分割〉の意味。土地を分けるのは分割を使う。切断は物を切る動作なので、土地には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電線の切断に防ぐため、支柱を立てました。", "corrected_sentence": "電線の切断を防ぐため、支柱を立てました。", "error_description": "「防ぐ」の目的語を示すには「を」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "配線の切断に、電源を切ってから行います。", "corrected_sentence": "配線の切断は、電源を切ってから行います。", "error_description": "「行う」の主題を示すには「は」が必要。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
