INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。『とうもろこしもバイオマスの一つだ』で、バイオマスに含まれる一つという関係を示す"}, {"text": "を", "is_correct": false, "explanation": "『バイオマスを一つだと教えた』では目的語が不自然で、文の意味が通らない"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、『バイオマスへ一つだ』は成り立たない"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すので、『バイオマスより一つだ』は意味が通らない"}], "correct_answer": "の", "explanations": {"の": "正解。『とうもろこしもバイオマスの一つだ』で、バイオマスに含まれる一つという関係を示す", "を": "『バイオマスを一つだと教えた』では目的語が不自然で、文の意味が通らない", "へ": "『へ』は方向を表すので、『バイオマスへ一つだ』は成り立たない", "より": "『より』は比較の基準を示すので、『バイオマスより一つだ』は意味が通らない"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物からできた、エネルギーや材料になるもののことです。", "primary_collocate": null, "pronunciation": "ばいおます", "ipa": "baiomasɯ", "syllable_count": 5, "sentences": [{"text": "木くずや草は、バイオマスとして燃料に使えます。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "木[き]くずや草[くさ]は、バイオマスとして燃料[ねんりょう]に使[つか]えます。", "sentence_source": "generated"}, {"text": "バイオマスは、生き物からできた資源のことです。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "バイオマスは、生[い]き物[もの]からできた資源[しげん]のことです。", "sentence_source": "generated"}, {"text": "食べ物の残りも、バイオマスとして使うことができる。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の残[のこ]りも、バイオマスとして使[つか]うことができる。", "sentence_source": "generated"}, {"text": "農家では、わらをバイオマスとして集めて暖房に使っています。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "農家[のうか]では、わらをバイオマスとして集[あつ]めて暖房[だんぼう]に使[つか]っています。", "sentence_source": "generated"}, {"text": "木を切ったあとの枝は、バイオマスとして役に立つ。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "木[き]を切[き]ったあとの枝[えだ]は、バイオマスとして役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "バイオマスを燃やすと、熱が出て、お湯をわかせます。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "バイオマスを燃[も]やすと、熱[ねつ]が出[で]て、お湯[ゆ]をわかせます。", "sentence_source": "generated"}, {"text": "石油と違って、バイオマスは植物を育てればまた作れます。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "石油[せきゆ]と違[ちが]って、バイオマスは植物[しょくぶつ]を育[そだ]てればまた作[つく]れます。", "sentence_source": "generated"}, {"text": "先生は、とうもろこしもバイオマスの一つだと教えてくれた。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "先生[せんせい]は、とうもろこしもバイオマスの一[ひと]つだと教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "町のごみの中から、バイオマスになるものを分けて集めます。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "町[まち]のごみの中[なか]から、バイオマスになるものを分[わ]けて集[あつ]めます。", "sentence_source": "generated"}, {"text": "バイオマスは、エネルギーにも材料にもなる大切な資源です。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "バイオマスは、エネルギーにも材料[ざいりょう]にもなる大切[たいせつ]な資源[しげん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バイオマス", "label": "基本形"}, {"form": "バイオマスを", "label": "を格"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "生き物由来でエネルギーや材料になる資源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バイオマス", "is_correct": true, "explanation": "正解。『木くずや草は、バイオマスとして燃料に使えます』で、生き物由来の資源を指す"}, {"text": "天気", "is_correct": false, "explanation": "『天気として燃料に使えます』は意味が通らず、燃料にできる資源ではない"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は燃料にできる資源ではないので、『教科書として燃料に使えます』は成り立たない"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫を燃料に使うという文は成り立たず、ここでは資源の名前が入る"}], "explanations": {"バイオマス": "正解。『木くずや草は、バイオマスとして燃料に使えます』で、生き物由来の資源を指す", "天気": "『天気として燃料に使えます』は意味が通らず、燃料にできる資源ではない", "教科書": "教科書は燃料にできる資源ではないので、『教科書として燃料に使えます』は成り立たない", "冷蔵庫": "冷蔵庫を燃料に使うという文は成り立たず、ここでは資源の名前が入る"}, "sentence_index": 0, "correct_answer": "バイオマス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "燃えないごみは、バイオマスとして分けて捨てます。", "explanation": "ここは〈廃棄物〉の意味。バイオマスは生き物からできた資源で、燃えないごみを指さないので合わない"}, {"text": "バイオマスは、地下深くから掘り出して精製する燃料だ。", "explanation": "ここは〈原油〉の意味。原油は地下から掘り出すが、バイオマスは生き物からできたもので、地下から掘り出すものではないので合わない"}, {"text": "畑では、春にバイオマスをまいて、秋に収穫する。", "explanation": "ここは〈種〉の意味。種は畑にまいて育てるものだが、バイオマスは生き物からできた資源で、まいて収穫する種ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バイオマス", "is_correct": true, "explanation": "正解。『石油と違って、バイオマスは植物を育てればまた作れます』で、生き物由来の資源を指す"}, {"text": "野球", "is_correct": false, "explanation": "『石油と違って、野球は植物を育てればまた作れます』は意味が通らない"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は植物を育てて作るものではないので、ここでは資源の名前が入る"}, {"text": "電車", "is_correct": false, "explanation": "電車は植物を育てて作るものではなく、『電車は植物を育てれば』は文が成り立たない"}], "explanations": {"バイオマス": "正解。『石油と違って、バイオマスは植物を育てればまた作れます』で、生き物由来の資源を指す", "野球": "『石油と違って、野球は植物を育てればまた作れます』は意味が通らない", "辞書": "辞書は植物を育てて作るものではないので、ここでは資源の名前が入る", "電車": "電車は植物を育てて作るものではなく、『電車は植物を育てれば』は文が成り立たない"}, "sentence_index": 6, "correct_answer": "バイオマス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バイオマスは、夜空に光る星の名前だ。", "explanation": "ここは〈星〉の意味。夜空に光るもので、生き物からできた資源ではないので合わない"}, {"text": "バイオマスは、地下の岩の間にたまった燃料だ。", "explanation": "ここは〈天然ガス〉の意味。地下の岩の間にたまる燃料で、バイオマスは地下にたまるものではないので合わない"}, {"text": "バイオマスは、燃やしても水しか出ない気体だ。", "explanation": "ここは〈水素〉の意味。燃やすと水だけが出る気体の説明で、生き物からできた資源のバイオマスには合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "とうもろこしは、バイオマスを一つだ。", "corrected_sentence": "とうもろこしは、バイオマスの一つだ。", "error_description": "誤りは『の一つ』の『の』が『を』になっていること。『を一つだ』は目的語が成り立たないので、正しくは『バイオマスの一つ』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家畜のふんは、バイオマスへガスを取り出せる。", "corrected_sentence": "家畜のふんは、バイオマスからガスを取り出せる。", "error_description": "誤りは『から』が『へ』になっていること。『取り出す』は起点を示す『から』を使うので、『へ』では文が成り立たない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。『バイオマスを原料にしている』で、原料にする対象を示す"}, {"text": "に", "is_correct": false, "explanation": "『バイオマスに原料にしている』では対象を示す位置に『に』が入り、文が成り立たない"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段を示すので、『バイオマスで原料にしている』は意味が通らない"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『バイオマスへ原料にしている』は成り立たない"}], "correct_answer": "を", "explanations": {"を": "正解。『バイオマスを原料にしている』で、原料にする対象を示す", "に": "『バイオマスに原料にしている』では対象を示す位置に『に』が入り、文が成り立たない", "で": "『で』は手段を示すので、『バイオマスで原料にしている』は意味が通らない", "へ": "『へ』は方向を示すので、『バイオマスへ原料にしている』は成り立たない"}, "error_tags": {"に": "目的語の位置", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。『バイオマスを使う動き』で、使う対象を示す"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、『バイオマスから使う動き』は意味が通らない"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すので、『バイオマスより使う動き』は成り立たない"}, {"text": "の", "is_correct": false, "explanation": "『バイオマスの使う動き』では動詞『使う』の目的語が欠け、文が成り立たない"}], "correct_answer": "を", "explanations": {"を": "正解。『バイオマスを使う動き』で、使う対象を示す", "から": "『から』は起点を示すので、『バイオマスから使う動き』は意味が通らない", "より": "『より』は比較の基準を示すので、『バイオマスより使う動き』は成り立たない", "の": "『バイオマスの使う動き』では動詞『使う』の目的語が欠け、文が成り立たない"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物由来の資源を指し、燃料やプラスチックの原料などに利用される有機物。", "primary_collocate": null, "pronunciation": "ばいおます", "ipa": "baiomasɯ", "syllable_count": 5, "sentences": [{"text": "研究所では、バイオマスから作るプラスチックの開発が進んでいる。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "研究所[けんきゅうじょ]では、バイオマスから作[つく]るプラスチックの開発[かいはつ]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "この袋はバイオマスを原料にしているので、石油の使用量が減る。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "この袋[ふくろ]はバイオマスを原料[げんりょう]にしているので、石油[せきゆ]の使用量[しようりょう]が減[へ]る。", "sentence_source": "generated"}, {"text": "間伐材は、バイオマスとして燃料に加工される。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "間伐材[かんばつざい]は、バイオマスとして燃料[ねんりょう]に加工[かこう]される。", "sentence_source": "generated"}, {"text": "工場は廃油などのバイオマスを回収し、燃料に変えている。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "工場[こうじょう]は廃油[はいゆ]などのバイオマスを回収[かいしゅう]し、燃料[ねんりょう]に変[か]えている。", "sentence_source": "generated"}, {"text": "サトウキビの搾りかすは、バイオマスの代表的な例だ。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "サトウキビの搾[しぼ]りかすは、バイオマスの代表的[だいひょうてき]な例[れい]だ。", "sentence_source": "generated"}, {"text": "バイオマスは再生できる資源なので、環境への負担が比較的小さい。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "バイオマスは再生[さいせい]できる資源[しげん]なので、環境[かんきょう]への負担[ふたん]が比較的[ひかくてき]小[ちい]さい。", "sentence_source": "generated"}, {"text": "家畜のふんもバイオマスに含まれ、ガスを取り出して利用される。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "家畜[かちく]のふんもバイオマスに含[ふく]まれ、ガスを取[と]り出[だ]して利用[りよう]される。", "sentence_source": "generated"}, {"text": "化石燃料の代わりにバイオマスを使う動きが広がっている。", "target_word": "バイオマス", "complexity_tier": "T4", "furigana": "化石燃料[かせきねんりょう]の代[か]わりにバイオマスを使[つか]う動[うご]きが広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "この会社は、バイオマスを使った食器を売り出した。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、バイオマスを使[つか]った食器[しょっき]を売[う]り出[だ]した。", "sentence_source": "generated"}, {"text": "木材やもみ殻など、バイオマスの種類は多い。", "target_word": "バイオマス", "complexity_tier": "T3", "furigana": "木材[もくざい]やもみ殻[がら]など、バイオマスの種類[しゅるい]は多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バイオマス", "label": "基本形"}, {"form": "バイオマスを", "label": "を格"}], "register": "標準（普通体）", "sense_fingerprint": "燃料やプラスチックの原料になる生物由来の有機資源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '729dc63f-8b18-4b3c-895a-efbae94aab11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バイオマス", "is_correct": true, "explanation": "正解。『バイオマスから作るプラスチックの開発が進んでいる』で、生き物由来の原料を指す"}, {"text": "天気", "is_correct": false, "explanation": "『天気から作るプラスチック』は意味が通らず、原料にならない"}, {"text": "教科書", "is_correct": false, "explanation": "教科書からプラスチックを作るという文は成り立たない"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "『冷蔵庫から作るプラスチック』は原料として成り立たない"}], "explanations": {"バイオマス": "正解。『バイオマスから作るプラスチックの開発が進んでいる』で、生き物由来の原料を指す", "天気": "『天気から作るプラスチック』は意味が通らず、原料にならない", "教科書": "教科書からプラスチックを作るという文は成り立たない", "冷蔵庫": "『冷蔵庫から作るプラスチック』は原料として成り立たない"}, "sentence_index": 0, "correct_answer": "バイオマス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バイオマスは、地下から取れる燃料だ。", "explanation": "ここは〈石油〉の意味。石油は地下から掘り出す燃料で、バイオマスは地下から取れるものではないので合わない"}, {"text": "バイオマスは、地中で長い年月をかけてできた、生き物とは関係のない物質だ。", "explanation": "ここは〈鉱物〉の意味。鉱物は地中でできて生き物と無関係だが、バイオマスは生き物由来の有機物なので合わない"}, {"text": "夏休みの宿題で、バイオマスを一ページ書いた。", "explanation": "ここは〈作文〉の意味。作文は文章を書くものだが、バイオマスは生き物由来の資源で、書けるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バイオマス", "is_correct": true, "explanation": "正解。『家畜のふんもバイオマスに含まれ』で、生き物由来の有機資源を指す"}, {"text": "野球", "is_correct": false, "explanation": "『家畜のふんも野球に含まれ』は意味が通らず、資源を指す語にならない"}, {"text": "辞書", "is_correct": false, "explanation": "『家畜のふんも辞書に含まれ』は成り立たず、ここでは資源の名前が入る"}, {"text": "電車", "is_correct": false, "explanation": "『家畜のふんも電車に含まれ』は文が成り立たない"}], "explanations": {"バイオマス": "正解。『家畜のふんもバイオマスに含まれ』で、生き物由来の有機資源を指す", "野球": "『家畜のふんも野球に含まれ』は意味が通らず、資源を指す語にならない", "辞書": "『家畜のふんも辞書に含まれ』は成り立たず、ここでは資源の名前が入る", "電車": "『家畜のふんも電車に含まれ』は文が成り立たない"}, "sentence_index": 6, "correct_answer": "バイオマス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バイオマスは、石油から作るプラスチックの材料だ。", "explanation": "ここは〈合成樹脂〉の意味。合成樹脂は石油から作るが、バイオマスは生き物由来で石油から作るものではないので合わない"}, {"text": "バイオマスは、サトウキビから作る甘い調味料だ。", "explanation": "ここは〈砂糖〉の意味。砂糖は甘い調味料だが、バイオマスは燃料や原料になる資源で、調味料ではないので合わない"}, {"text": "バイオマスは、宇宙から地上に落ちてきた石だ。", "explanation": "ここは〈隕石〉の意味。宇宙から落ちてきた石で、生き物からできた資源ではないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場は、バイオマスを原料を集めている。", "corrected_sentence": "この工場は、バイオマスの原料を集めている。", "error_description": "誤りは『バイオマスの原料』の『の』が『を』になっていること。『を原料を』と目的語が二つになり文が成り立たないので、正しくは『の原料』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木材もバイオマスで含まれる。", "corrected_sentence": "木材もバイオマスに含まれる。", "error_description": "誤りは『に含まれる』の『に』が『で』になっていること。『で含まれる』は文が成り立たないので、正しくは『に含まれる』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee2097c8-0e8d-4cdd-8ac4-99dfea61ce8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
