INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものを、べつのものにすること", "primary_collocate": null, "pronunciation": "へんかん", "ipa": "heŋkaɴ", "syllable_count": 4, "sentences": [{"text": "このソフトは、音楽のファイルを別の形式に変換できます。", "target_word": "変換", "complexity_tier": "T3", "furigana": "このソフトは、音楽[おんがく]のファイルを別[べつ]の形式[けいしき]に変換[へんかん]できます。", "sentence_source": "generated"}, {"text": "ひらがなを漢字に変換するには、スペースキーを押します。", "target_word": "変換", "complexity_tier": "T3", "furigana": "ひらがなを漢字[かんじ]に変換[へんかん]するには、スペースキーを押[お]します。", "sentence_source": "generated"}, {"text": "円をドルに変換するときは、その日のレートを確認します。", "target_word": "変換", "complexity_tier": "T3", "furigana": "円[えん]をドルに変換[へんかん]するときは、その日[ひ]のレートを確認[かくにん]します。", "sentence_source": "generated"}, {"text": "単位の変換をまちがえて、料理の味が変になりました。", "target_word": "変換", "complexity_tier": "T3", "furigana": "単位[たんい]の変換[へんかん]をまちがえて、料理[りょうり]の味[あじ]が変[へん]になりました。", "sentence_source": "generated"}, {"text": "漢字の変換をまちがえて、メールの名前が別の字になっていました。", "target_word": "変換", "complexity_tier": "T3", "furigana": "漢字[かんじ]の変換[へんかん]をまちがえて、メールの名前[なまえ]が別[べつ]の字[じ]になっていました。", "sentence_source": "generated"}, {"text": "太陽の光を電気に変換する装置が、屋根についています。", "target_word": "変換", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]を電気[でんき]に変換[へんかん]する装置[そうち]が、屋根[やね]についています。", "sentence_source": "generated"}, {"text": "この表を使えば、センチをインチに簡単に変換できます。", "target_word": "変換", "complexity_tier": "T3", "furigana": "この表[ひょう]を使[つか]えば、センチをインチに簡単[かんたん]に変換[へんかん]できます。", "sentence_source": "generated"}, {"text": "日本語の入力で、変換のキーがどれか分かりません。", "target_word": "変換", "complexity_tier": "T3", "furigana": "日本語[にほんご]の入力[にゅうりょく]で、変換[へんかん]のキーがどれか分[わ]かりません。", "sentence_source": "generated"}, {"text": "動画を変換するのに時間がかかるので、夜のあいだにやっておきます。", "target_word": "変換", "complexity_tier": "T3", "furigana": "動画[どうが]を変換[へんかん]するのに時間[じかん]がかかるので、夜[よる]のあいだにやっておきます。", "sentence_source": "generated"}, {"text": "音声を文字に変換する機能は、会議でとても便利です。", "target_word": "変換", "complexity_tier": "T3", "furigana": "音声[おんせい]を文字[もじ]に変換[へんかん]する機能[きのう]は、会議[かいぎ]でとても便利[べんり]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変換", "label": "基本形"}, {"form": "変換する", "label": "サ変動詞"}, {"form": "変換した", "label": "過去形"}, {"form": "変換して", "label": "て形"}, {"form": "変換できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "変換: あるものを別の形・種類・単位・文字などに替えること(スル動詞。文字入力や形式の切り替えでよく使う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: なを (Zipf 2.32)']::text[], '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変換", "is_correct": true, "explanation": "正解。形式を別のものに替える動作で、「できます」と続いて文が成り立つ。"}, {"text": "検索", "is_correct": false, "explanation": "検索は情報を探す動作で、「別の形式に検索できます」とは言わないので合わない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は状態を調べる動作で、ファイルを別の形式に替える意味にはならない。"}, {"text": "録音", "is_correct": false, "explanation": "録音は音を記録する動作で、「別の形式に録音できます」は意味が合わない。"}], "explanations": {"変換": "正解。形式を別のものに替える動作で、「できます」と続いて文が成り立つ。", "検索": "検索は情報を探す動作で、「別の形式に検索できます」とは言わないので合わない。", "点検": "点検は状態を調べる動作で、ファイルを別の形式に替える意味にはならない。", "録音": "録音は音を記録する動作で、「別の形式に録音できます」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "変換"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "予定を変換したので、友達に連絡しました。", "explanation": "ここは〈変更〉の意味。変換は形式や単位を別のものに替えることで、予定のような内容には使わないので合わない。"}, {"text": "壊れたスマホを変換して、すぐに直しました。", "explanation": "ここは〈修理〉の意味。変換は形式や単位を別のものに替える意味で、壊れたものを直す意味では使わないので合わない。"}, {"text": "照明を変換して、部屋を暗くしました。", "explanation": "ここは〈切り替える〉の意味。変換は形式や単位を別のものに替える意味で、明かりを点けたり消したりする場合には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変換", "is_correct": true, "explanation": "正解。形式や単位を替える動作で、「簡単に変換できます」と自然に続く。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は場所や物をきれいにする動作で、「センチをインチに清掃」とは言わないので合わない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は物を届ける動作で、単位を替える意味にはならず文が成り立たない。"}, {"text": "購入", "is_correct": false, "explanation": "購入は物を買う動作で、「センチをインチに購入」とは言わないので意味が合わない。"}], "explanations": {"変換": "正解。形式や単位を替える動作で、「簡単に変換できます」と自然に続く。", "清掃": "清掃は場所や物をきれいにする動作で、「センチをインチに清掃」とは言わないので合わない。", "配達": "配達は物を届ける動作で、単位を替える意味にはならず文が成り立たない。", "購入": "購入は物を買う動作で、「センチをインチに購入」とは言わないので意味が合わない。"}, "sentence_index": 6, "correct_answer": "変換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題は、先生の説明ですぐに変換しました。", "explanation": "ここは〈解決〉の意味。変換は形式や単位を替える意味で、問題を解く意味にはならないので合わない。"}, {"text": "試合の途中で、監督が選手を変換しました。", "explanation": "ここは〈交代〉の意味。変換は形式や性質を別のものに替える意味で、選手を入れ替える場合には使わないので合わない。"}, {"text": "壊れた冷蔵庫を業者が変換してくれました。", "explanation": "ここは〈修理〉の意味。変換は形式や単位を替える意味で、壊れた物を直す意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "音声データを文字に変換を、保存します。", "corrected_sentence": "音声データを文字に変換して、保存します。", "error_description": "正しくは「変換して」（て形）。「変換を」では「変換」が動詞として働かず、「保存します」と続けられない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38650, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スキャナーで書類を画像に変換られます。", "corrected_sentence": "スキャナーで書類を画像に変換できます。", "error_description": "正しくは「変換できます」（可能形）。「変換られます」は可能の形として誤りで、サ変動詞には「できます」を付ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を表し、「形式と変換すると」では変換される対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、比べる対象がないので文が成り立たない。"}, {"text": "を", "is_correct": true, "explanation": "「を」は変換される対象を示し、「形式を変換する」と続く。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞で、「形式の変換すると」は動詞と続かない。"}], "correct_answer": "を", "explanations": {"と": "「と」は並列・共同を表し、「形式と変換すると」では変換される対象を示せない。", "より": "「より」は比較を表し、比べる対象がないので文が成り立たない。", "を": "「を」は変換される対象を示し、「形式を変換する」と続く。", "の": "「の」は名詞を修飾する助詞で、「形式の変換すると」は動詞と続かない。"}, "error_tags": {"と": "並列・共同", "より": "比較", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の形や状態を変えて、別のものにすること", "primary_collocate": null, "pronunciation": "へんかん", "ipa": "heŋkaɴ", "syllable_count": 4, "sentences": [{"text": "古い書類を電子データに変換する作業を始めた。", "target_word": "変換", "complexity_tier": "T3", "furigana": "古[ふる]い書類[しょるい]を電子[でんし]データに変換[へんかん]する作業[さぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "動画の形式を変換すると、スマホでも見られる。", "target_word": "変換", "complexity_tier": "T3", "furigana": "動画[どうが]の形式[けいしき]を変換[へんかん]すると、スマホでも見[み]られる。", "sentence_source": "generated"}, {"text": "文章を声に変換するソフトが、目の不自由な人を助けている。", "target_word": "変換", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]を声[こえ]に変換[へんかん]するソフトが、目[め]の不自由[ふじゆう]な人[ひと]を助[たす]けている。", "sentence_source": "generated"}, {"text": "変換のあと、元のファイルは消さずに残しておく。", "target_word": "変換", "complexity_tier": "T3", "furigana": "変換[へんかん]のあと、元[もと]のファイルは消[け]さずに残[のこ]しておく。", "sentence_source": "generated"}, {"text": "図面をコンピューターの形式に変換するのに三日かかった。", "target_word": "変換", "complexity_tier": "T3", "furigana": "図面[ずめん]をコンピューターの形式[けいしき]に変換[へんかん]するのに三日[みっか]かかった。", "sentence_source": "generated"}, {"text": "音を電気の信号に変換する部品が、マイクの中にある。", "target_word": "変換", "complexity_tier": "T3", "furigana": "音[おと]を電気[でんき]の信号[しんごう]に変換[へんかん]する部品[ぶひん]が、マイクの中[なか]にある。", "sentence_source": "generated"}, {"text": "この計算では、温度を摂氏から華氏に変換する必要がある。", "target_word": "変換", "complexity_tier": "T3", "furigana": "この計算[けいさん]では、温度[おんど]を摂氏[せっし]から華氏[かし]に変換[へんかん]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "変換された画像は、少し色が暗くなってしまった。", "target_word": "変換", "complexity_tier": "T3", "furigana": "変換[へんかん]された画像[がぞう]は、少[すこ]し色[いろ]が暗[くら]くなってしまった。", "sentence_source": "generated"}, {"text": "紙の本を音声に変換して、通勤中に聞いている。", "target_word": "変換", "complexity_tier": "T3", "furigana": "紙[かみ]の本[ほん]を音声[おんせい]に変換[へんかん]して、通勤中[つうきんちゅう]に聞[き]いている。", "sentence_source": "generated"}, {"text": "変換の途中でエラーが出て、作業が止まった。", "target_word": "変換", "complexity_tier": "T3", "furigana": "変換[へんかん]の途中[とちゅう]でエラーが出[で]て、作業[さぎょう]が止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変換", "label": "基本形"}, {"form": "変換する", "label": "動詞形"}, {"form": "変換した", "label": "過去形"}, {"form": "変換される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "物事の形や状態を変えて別のものにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解体", "is_correct": false, "explanation": "分解する意味で、書類を電子データにする文脈に合わない。"}, {"text": "禁止", "is_correct": false, "explanation": "してはいけない意味で、「電子データに禁止する作業」は文が成り立たない。"}, {"text": "変換", "is_correct": true, "explanation": "書類の形式を電子データに変えることを表し、作業の説明に合う。"}, {"text": "発表", "is_correct": false, "explanation": "公に知らせる意味で、電子データに対しては使えない。"}], "explanations": {"解体": "分解する意味で、書類を電子データにする文脈に合わない。", "禁止": "してはいけない意味で、「電子データに禁止する作業」は文が成り立たない。", "変換": "書類の形式を電子データに変えることを表し、作業の説明に合う。", "発表": "公に知らせる意味で、電子データに対しては使えない。"}, "sentence_index": 0, "correct_answer": "変換"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達と古い本を変換した。", "explanation": "ここは〈交換〉の意味。変換は形式や性質を変えることで、物を互いにやり取りするのには合わない。"}, {"text": "大事な書類を金庫に変換した。", "explanation": "ここは〈保管〉の意味。変換は形を替えることで、大切に保存しておく意味には合わない。"}, {"text": "重い荷物を、車で駅まで変換した。", "explanation": "ここは〈運搬〉の意味。変換はものの形や性質を変えることで、運んで場所を移すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点検", "is_correct": false, "explanation": "調べる意味で、単位を替える文脈には合わない。"}, {"text": "整理", "is_correct": false, "explanation": "物をそろえる意味で、単位には使えない。"}, {"text": "削除", "is_correct": false, "explanation": "消す意味で、単位を替える文脈に合わない。"}, {"text": "変換", "is_correct": true, "explanation": "温度の単位を別の単位に変えることを表し、計算の文脈に合う。"}], "explanations": {"点検": "調べる意味で、単位を替える文脈には合わない。", "整理": "物をそろえる意味で、単位には使えない。", "削除": "消す意味で、単位を替える文脈に合わない。", "変換": "温度の単位を別の単位に変えることを表し、計算の文脈に合う。"}, "sentence_index": 6, "correct_answer": "変換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた機械を、変換して直した。", "explanation": "ここは〈修理〉の意味。変換は形や性質を替えることで、壊れたものを直すことには使わない。"}, {"text": "宝物を、変換して見つけた。", "explanation": "ここは〈発見〉の意味。変換は形を替えることで、隠れたものを見つけ出すことには合わない。"}, {"text": "旅行先で景色を変換した。", "explanation": "ここは〈撮影〉の意味。変換は形式や性質を替えることで、景色をカメラに収めることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手書きのメモを文字データを変換する。", "corrected_sentence": "手書きのメモを文字データに変換する。", "error_description": "「AをBに変換する」のBには「に」が必要。「を」を重ねると目的語が二つになり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の録音を文字と変換した。", "corrected_sentence": "会議の録音を文字に変換した。", "error_description": "「AをBに変換する」のBには「に」が必要。「と」では変換先を示せず、「文字と変換した」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「光が入ってきた」で、入ってくる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「光を入ってきた」では目的語になり、入ってくる主体として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「光に入ってきた」は相手や場所の形で、主語として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「光で入ってきた」は手段の形で、光が入ってくる文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「光が入ってきた」で、入ってくる主語を示す。", "を": "「光を入ってきた」では目的語になり、入ってくる主体として成り立たない。", "に": "「光に入ってきた」は相手や場所の形で、主語として成り立たない。", "で": "「光で入ってきた」は手段の形で、光が入ってくる文に合わない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目で見ることができる明るいものです。", "primary_collocate": null, "pronunciation": "ひかり", "ipa": "çikaɾi", "syllable_count": 3, "sentences": [{"text": "舞台の上に青い光が当たって、歌手が浮かび上がった。", "target_word": "光", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の上[うえ]に青[あお]い光[ひかり]が当[あ]たって、歌手[かしゅ]が浮[う]かび上[あ]がった。", "sentence_source": "generated"}, {"text": "朝になると、カーテンの隙間から光が入ってきた。", "target_word": "光", "complexity_tier": "T3", "furigana": "朝[あさ]になると、カーテンの隙間[すきま]から光[ひかり]が入[はい]ってきた。", "sentence_source": "generated"}, {"text": "暗いトンネルの先に、小さな光が見えた。", "target_word": "光", "complexity_tier": "T3", "furigana": "暗[くら]いトンネルの先[さき]に、小[ちい]さな光[ひかり]が見[み]えた。", "sentence_source": "generated"}, {"text": "夜道を歩いていると、遠くに家の光が見えて安心した。", "target_word": "光", "complexity_tier": "T3", "furigana": "夜道[よみち]を歩[ある]いていると、遠[とお]くに家[いえ]の光[ひかり]が見[み]えて安心[あんしん]した。", "sentence_source": "generated"}, {"text": "星の光は弱いので、街の中ではよく見えない。", "target_word": "光", "complexity_tier": "T3", "furigana": "星[ほし]の光[ひかり]は弱[よわ]いので、街[まち]の中[なか]ではよく見[み]えない。", "sentence_source": "generated"}, {"text": "携帯電話の光で、足もとを照らしながら歩いた。", "target_word": "光", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の光[ひかり]で、足[あし]もとを照[て]らしながら歩[ある]いた。", "sentence_source": "generated"}, {"text": "ろうそくの光が、部屋をやさしく照らしている。", "target_word": "光", "complexity_tier": "T3", "furigana": "ろうそくの光[ひかり]が、部屋[へや]をやさしく照[て]らしている。", "sentence_source": "generated"}, {"text": "雨が上がり、雲の間から光がさしてきた。", "target_word": "光", "complexity_tier": "T3", "furigana": "雨[あめ]が上[あ]がり、雲[くも]の間[あいだ]から光[ひかり]がさしてきた。", "sentence_source": "generated"}, {"text": "暗い森の中では、月の光だけが頼りだった。", "target_word": "光", "complexity_tier": "T3", "furigana": "暗[くら]い森[もり]の中[なか]では、月[つき]の光[ひかり]だけが頼[たよ]りだった。", "sentence_source": "generated"}, {"text": "夏の夜、川の上に蛍の光がぽつぽつと見えた。", "target_word": "光", "complexity_tier": "T3", "furigana": "夏[なつ]の夜[よる]、川[かわ]の上[うえ]に蛍[ほたる]の光[ひかり]がぽつぽつと見えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "光", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "日常で目に見える明るいもの(灯り・日ざし・月や星のかがやきなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: 足もと (Zipf 2.29)','sentence 6 above tier T1: 3 words above tier T1 (max 2): ろうそく (Zipf 3.15), やさしく (Zipf 3.6), 照らし (Zipf 3.72)']::text[], '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "「青い光が当たって」で、当たるものとして自然な語である。"}, {"text": "砂", "is_correct": false, "explanation": "砂は光を当てられて浮かび上がる対象ではなく、青い光の文脈に合わない。"}, {"text": "泥", "is_correct": false, "explanation": "泥は舞台照明の文脈で当たるものではなく、文意に合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は青く照らされる対象として書かれていないので、文が不自然になる。"}], "explanations": {"光": "「青い光が当たって」で、当たるものとして自然な語である。", "砂": "砂は光を当てられて浮かび上がる対象ではなく、青い光の文脈に合わない。", "泥": "泥は舞台照明の文脈で当たるものではなく、文意に合わない。", "石": "石は青く照らされる対象として書かれていないので、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の笑顔には、若者らしい光があった。", "explanation": "ここは〈生気・輝き〉の意味。目に見える明るいものではなく抽象的な様子を表すので、この義項とは別の用法になる。"}, {"text": "焚き火から光がもくもくと立ちのぼった。", "explanation": "ここは〈煙〉の意味。もくもくと立ちのぼるのは煙で、光は立ちのぼるものではないので合わない。"}, {"text": "花火の光が大きすぎて、耳がきーんと痛くなった。", "explanation": "ここは〈音〉の意味。耳で感じるのは音で、光は目で見えるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "「ろうそくの光が部屋を照らす」で、照らす主体として自然である。"}, {"text": "熱", "is_correct": false, "explanation": "熱は部屋を照らすものではなく、ここでは文意が通らない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は照らす働きを持たないので合わない。"}, {"text": "影", "is_correct": false, "explanation": "影は光に照らされてできるもので、部屋を照らす主体にはならない。"}], "explanations": {"光": "「ろうそくの光が部屋を照らす」で、照らす主体として自然である。", "熱": "熱は部屋を照らすものではなく、ここでは文意が通らない。", "煙": "煙は照らす働きを持たないので合わない。", "影": "影は光に照らされてできるもので、部屋を照らす主体にはならない。"}, "sentence_index": 6, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コンクールで入賞して、彼女は大きな光を手にした。", "explanation": "ここは〈栄光〉の意味。栄光を手にするとは言うが、光を手にするとは言わないので合わない。"}, {"text": "蛇口をひねると、光がいきおいよく流れ出た。", "explanation": "ここは〈水〉の意味。流れ出るのは水で、光は流れ出るものではないので合わない。"}, {"text": "冷房で部屋の光をさまして、涼しくした。", "explanation": "ここは〈熱〉の意味。さますのは熱で、光はさますものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から光が入れて、部屋が明るくなった。", "corrected_sentence": "窓から光が入って、部屋が明るくなった。", "error_description": "「入る」は自動詞なので、他動詞形の「入れて」は誤り。光が自ら入ってくる意味には「入って」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い光を、目が痛くなった。", "corrected_sentence": "強い光で、目が痛くなった。", "error_description": "原因を示す助詞が誤っている。まぶしさを原因にするには「で」を使い、「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「光は」は主題を示し、光の性質を説明する文として自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「光を」だと目的語になり、「持つ」の主語にならず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「光に」は相手・場所を示し、「波の性質を持つ」の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「光で」は手段を示し、光の性質を述べる文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「光は」は主題を示し、光の性質を説明する文として自然につながる。", "を": "「光を」だと目的語になり、「持つ」の主語にならず文が成り立たない。", "に": "「光に」は相手・場所を示し、「波の性質を持つ」の主語にはならない。", "で": "「光で」は手段を示し、光の性質を述べる文に合わない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「光を使って」は使う対象を示す目的語で、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「光が使って」では光が使う主体になり、使うのは植物なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「光に使って」は相手を示す形で、使う対象の表し方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「光と使って」は並列や相手の形で、対象を表す文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「光を使って」は使う対象を示す目的語で、文の意味に合う。", "が": "「光が使って」では光が使う主体になり、使うのは植物なので合わない。", "に": "「光に使って」は相手を示す形で、使う対象の表し方として不自然。", "と": "「光と使って」は並列や相手の形で、対象を表す文として成り立たない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電磁波の一種で、人間の目に見える範囲の波長を持つもの。明るさや光源を指すこともある。", "primary_collocate": null, "pronunciation": "ひかり", "ipa": "çikaɾi", "syllable_count": 3, "sentences": [{"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "光", "complexity_tier": "T3", "furigana": "これらにより、壁[かべ]を薄[うす]くして大[おお]きな窓[まど]を設[もう]けることが可能[かのう]となり、内部[ないぶ]は光[ひかり]に満[み]ちあふれました。", "sentence_source": "mined"}, {"text": "光は波の性質を持ち、人間の目には虹の色として見える。", "target_word": "光", "complexity_tier": "T3", "furigana": "光[ひかり]は波[なみ]の性質[せいしつ]を持[も]ち、人間[にんげん]の目[め]には虹[にじ]の色[いろ]として見[み]える。", "sentence_source": "generated"}, {"text": "太陽の光が地球に届くまでには、約八分かかる。", "target_word": "光", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]が地球[ちきゅう]に届[とど]くまでには、約[やく]八分[はっぷん]かかる。", "sentence_source": "generated"}, {"text": "プリズムを通すと、白い光はいろいろな色に分かれる。", "target_word": "光", "complexity_tier": "T3", "furigana": "プリズムを通[とお]すと、白[しろ]い光[ひかり]はいろいろな色[いろ]に分[わ]かれる。", "sentence_source": "generated"}, {"text": "光の速さは、音の速さよりもずっと速い。", "target_word": "光", "complexity_tier": "T3", "furigana": "光[ひかり]の速[はや]さは、音[おと]の速[はや]さよりもずっと速[はや]い。", "sentence_source": "generated"}, {"text": "暗い部屋に、窓から入る光が細い線のように差していた。", "target_word": "光", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]に、窓[まど]から入[はい]る光[ひかり]が細[ほそ]い線[せん]のように差[さ]していた。", "sentence_source": "generated"}, {"text": "水の中では、光が曲がって進むので、魚の位置が実際とずれて見える。", "target_word": "光", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]では、光[ひかり]が曲[ま]がって進[すす]むので、魚[さかな]の位置[いち]が実際[じっさい]とずれて見[み]える。", "sentence_source": "generated"}, {"text": "植物は光を使って、養分を作っている。", "target_word": "光", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は光[ひかり]を使[つか]って、養分[ようぶん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "夜の海に、灯台の光がゆっくりと回って見えた。", "target_word": "光", "complexity_tier": "T3", "furigana": "夜[よる]の海[うみ]に、灯台[とうだい]の光[ひかり]がゆっくりと回[まわ]って見[み]えた。", "sentence_source": "generated"}, {"text": "カーテンを開けると、強い光で目が痛くなった。", "target_word": "光", "complexity_tier": "T3", "furigana": "カーテンを開[あ]けると、強[つよ]い光[ひかり]で目[め]が痛[いた]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "光", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物理現象としての光(可視光の電磁波)。速さ・屈折・色などの性質や、明るさ・光源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): プリズム (Zipf 3.25), 通す (Zipf 3.91), 分かれる (Zipf 3.68)']::text[], '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "「内部は光に満ちあふれました」で、満ちあふれる対象は光である。"}, {"text": "壁", "is_correct": false, "explanation": "壁は建物の仕切りで、内部を満たして溢れる対象ではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は開口部で、満ちあふれるものとしては文意が通らない。"}, {"text": "設計", "is_correct": false, "explanation": "設計は計画のことで、空間を満たす物質ではないので合わない。"}], "explanations": {"光": "「内部は光に満ちあふれました」で、満ちあふれる対象は光である。", "壁": "壁は建物の仕切りで、内部を満たして溢れる対象ではないので合わない。", "窓": "窓は開口部で、満ちあふれるものとしては文意が通らない。", "設計": "設計は計画のことで、空間を満たす物質ではないので合わない。"}, "sentence_index": 0, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大会で勝って、チームは大きな光を手にした。", "explanation": "ここは〈栄光〉の意味。「光を手にする」とは言わず「栄光を手にする」と言う。電磁波の光とは別の語なので合わない。"}, {"text": "雷の光が大きすぎて、耳が痛くなった。", "explanation": "ここは〈音〉の意味。耳で感じるのは音で、光は目で見えるものなので合わない。"}, {"text": "木の下にできる光は、日差しがさえぎられた部分だ。", "explanation": "ここは〈影〉の意味。光が遮られてできる暗い部分を指すので、光そのものとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "水中で曲がって進むのは光で、屈折の主語として自然に成り立つ。"}, {"text": "石", "is_correct": false, "explanation": "石は水中で曲がって進む性質を持たないので合わない。"}, {"text": "車", "is_correct": false, "explanation": "車は水中を曲がって進む対象として文意に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は溶ける物質で、曲がって進む対象ではないので合わない。"}], "explanations": {"光": "水中で曲がって進むのは光で、屈折の主語として自然に成り立つ。", "石": "石は水中で曲がって進む性質を持たないので合わない。", "車": "車は水中を曲がって進む対象として文意に合わない。", "砂糖": "砂糖は溶ける物質で、曲がって進む対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷房で部屋の光をさまして、涼しくした。", "explanation": "ここは〈熱〉の意味。さますのは熱で、光はさますものではないので合わない。"}, {"text": "蛇口をひねると、光がいきおいよく流れ出た。", "explanation": "ここは〈水〉の意味。流れ出るのは水で、光は流れ出るものではないので合わない。"}, {"text": "朝から光が降り続き、道路が濡れていた。", "explanation": "ここは〈雨〉の意味。降るのは雨で、光が降るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月は自分で光が出さず、太陽の光を反射して輝いている。", "corrected_sentence": "月は自分で光を出さず、太陽の光を反射して輝いている。", "error_description": "「出す」は他動詞なので目的語の「を」が必要。「光が」にすると「出さず」が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38653, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨粒の中で光を屈折して、空に虹ができる。", "corrected_sentence": "雨粒の中で光が屈折して、空に虹ができる。", "error_description": "「光」に付く助詞が誤っている。光が自ら曲がる「屈折する」は主語の「が」を取るので、目的語の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38654, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この通りの並びには」と、並びに関する位置を表す『に』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『この通りの並びを、は』では目的語の形にならず、文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "『この通りの並びの、は』では修飾の形にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『この通りの並びへ、は』では方向の意味にならず、文に合わない。"}], "correct_answer": "に", "explanations": {"に": "「この通りの並びには」と、並びに関する位置を表す『に』が正しい。", "を": "『この通りの並びを、は』では目的語の形にならず、文が崩れる。", "の": "『この通りの並びの、は』では修飾の形にならず、不自然。", "へ": "『この通りの並びへ、は』では方向の意味にならず、文に合わない。"}, "error_tags": {"を": "対格", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38654, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「家の並びがそろっている」と主語を表すので『が』が正しい。"}, {"text": "と", "is_correct": false, "explanation": "『家の並びとそろっている』では並列の意味になり、文が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "『家の並びからそろっている』では起点の意味にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "『家の並びよりそろっている』では比較の意味になり、文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「家の並びがそろっている」と主語を表すので『が』が正しい。", "と": "『家の並びとそろっている』では並列の意味になり、文が崩れる。", "から": "『家の並びからそろっている』では起点の意味にならず、不自然。", "より": "『家の並びよりそろっている』では比較の意味になり、文に合わない。"}, "error_tags": {"と": "相手・並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38654, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが、一つの列（れつ）のように続いていること。", "primary_collocate": null, "pronunciation": "ならび", "ipa": "naɾabi", "syllable_count": 3, "sentences": [{"text": "本棚の本の並びがきれいで、気持ちがいい。", "target_word": "並び", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の本[ほん]の並[なら]びがきれいで、気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "この通りの並びには、古い店が多い。", "target_word": "並び", "complexity_tier": "T3", "furigana": "この通[とお]りの並[なら]びには、古[ふる]い店[みせ]が多[おお]い。", "sentence_source": "generated"}, {"text": "教室の机の並びが、昨日と少し違う。", "target_word": "並び", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の机[つくえ]の並[なら]びが、昨日[きのう]と少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "道ぞいの木の並びが美しく、散歩が楽しい。", "target_word": "並び", "complexity_tier": "T3", "furigana": "道[みち]ぞいの木[き]の並[なら]びが美[うつく]しく、散歩[さんぽ]が楽[たの]しい。", "sentence_source": "generated"}, {"text": "駅前の並びにコンビニが三軒もあって、便利だ。", "target_word": "並び", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の並[なら]びにコンビニが三軒[さんけん]もあって、便利[べんり]だ。", "sentence_source": "generated"}, {"text": "窓の並びが同じなので、どの部屋も同じに見える。", "target_word": "並び", "complexity_tier": "T3", "furigana": "窓[まど]の並[なら]びが同[おな]じなので、どの部屋[へや]も同[おな]じに見[み]える。", "sentence_source": "generated"}, {"text": "公園の入り口から、ベンチの並びが続いている。", "target_word": "並び", "complexity_tier": "T3", "furigana": "公園[こうえん]の入[い]り口[ぐち]から、ベンチの並[なら]びが続[つづ]いている。", "sentence_source": "generated"}, {"text": "家の並びがそろっているため、町全体がすっきり見える。", "target_word": "並び", "complexity_tier": "T3", "furigana": "家[いえ]の並[なら]びがそろっているため、町[まち]全体[ぜんたい]がすっきり見[み]える。", "sentence_source": "generated"}, {"text": "棚の皿の並びが乱れていたので、元にもどした。", "target_word": "並び", "complexity_tier": "T3", "furigana": "棚[たな]の皿[さら]の並[なら]びが乱[みだ]れていたので、元[もと]にもどした。", "sentence_source": "generated"}, {"text": "運動会で、旗の並びをまっすぐにそろえた。", "target_word": "並び", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]で、旗[はた]の並[なら]びをまっすぐにそろえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "並び", "label": "基本形（名詞）"}, {"form": "並ぶ", "label": "元の動詞（辞書形）"}], "register": "中立（だ・である調）", "sense_fingerprint": "本・店・家・木などが一列に続いている、その並んだ様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "並び", "is_correct": true, "explanation": "ここは〈並び〉の意味。本が一列に続いている様子を表し、きれいという評価に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは重量のこと。「重さがきれい」とは言えず、文に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のこと。本棚の本の値段がきれいという文は成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのこと。本の並びを表せず、文に合わない。"}], "explanations": {"並び": "ここは〈並び〉の意味。本が一列に続いている様子を表し、きれいという評価に合う。", "重さ": "重さは重量のこと。「重さがきれい」とは言えず、文に合わない。", "値段": "値段は価格のこと。本棚の本の値段がきれいという文は成り立たない。", "寿命": "寿命は命の長さのこと。本の並びを表せず、文に合わない。"}, "sentence_index": 0, "correct_answer": "並び"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟の並びが、この一年で大きく伸びた。", "explanation": "ここは〈身長〉の意味。背が伸びることは身長で表す。並びは一列の様子なので、伸びるという使い方はしない。"}, {"text": "夜の並びがさらに下がり、とても寒かった。", "explanation": "ここは〈気温〉の意味。気温が下がることは気温で表す。並びは一列の様子なので、下がるという使い方はしない。"}, {"text": "祖父の並びが、ついに七十を超えた。", "explanation": "ここは〈年齢〉の意味。人の年の数は年齢で表す。並びは一列の様子なので、七十を超えるという使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "並び", "is_correct": true, "explanation": "ここは〈並び〉の意味。ベンチが一列に続く様子を表し、入り口から続くという文脈に合う。"}, {"text": "税金", "is_correct": false, "explanation": "税金は国や自治体に納めるお金のこと。ベンチが続くという文には合わない。"}, {"text": "登録", "is_correct": false, "explanation": "登録は名前や情報を記録すること。ベンチの登録が続くという文は成り立たない。"}, {"text": "保証", "is_correct": false, "explanation": "保証は品質や約束を守ると確かにすること。ベンチが続くという文に合わない。"}], "explanations": {"並び": "ここは〈並び〉の意味。ベンチが一列に続く様子を表し、入り口から続くという文脈に合う。", "税金": "税金は国や自治体に納めるお金のこと。ベンチが続くという文には合わない。", "登録": "登録は名前や情報を記録すること。ベンチの登録が続くという文は成り立たない。", "保証": "保証は品質や約束を守ると確かにすること。ベンチが続くという文に合わない。"}, "sentence_index": 6, "correct_answer": "並び"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹の並びが、夏の間に少し増えた。", "explanation": "ここは〈体重〉の意味。体の重さが増えることは体重で表す。並びは一列の様子なので、増えるという使い方はしない。"}, {"text": "通りの並びが、夜になると急に暗くなった。", "explanation": "ここは〈明るさ〉の意味。明るさの変化は明るさで表す。並びは一列の様子なので、暗くなるという使い方はしない。"}, {"text": "このパンは並びが硬くて、食べにくい。", "explanation": "ここは〈食感〉の意味。パンのかたさは食感で表す。並びは物が一列に続く様子なので、食感の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
