INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38655, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が一列に続いていること。また、その順序や配列。", "primary_collocate": null, "pronunciation": "ならび", "ipa": "naɾabi", "syllable_count": 3, "sentences": [{"text": "名簿の名前の並びは、あいうえお順になっている。", "target_word": "並び", "complexity_tier": "T3", "furigana": "名簿[めいぼ]の名前[なまえ]の並[なら]びは、あいうえお順[じゅん]になっている。", "sentence_source": "generated"}, {"text": "文字の並びを変えると、別の言葉になる。", "target_word": "並び", "complexity_tier": "T3", "furigana": "文字[もじ]の並[なら]びを変[か]えると、別[べつ]の言葉[ことば]になる。", "sentence_source": "generated"}, {"text": "表の数字の並びに、ある決まりがあることに気づいた。", "target_word": "並び", "complexity_tier": "T3", "furigana": "表[ひょう]の数字[すうじ]の並[なら]びに、ある決[き]まりがあることに気[き]づいた。", "sentence_source": "generated"}, {"text": "駅名の並びを覚えると、路線図が読みやすい。", "target_word": "並び", "complexity_tier": "T3", "furigana": "駅名[えきめい]の並[なら]びを覚[おぼ]えると、路線図[ろせんず]が読[よ]みやすい。", "sentence_source": "generated"}, {"text": "棚の商品の並びは、売れる順に決められている。", "target_word": "並び", "complexity_tier": "T3", "furigana": "棚[たな]の商品[しょうひん]の並[なら]びは、売[う]れる順[じゅん]に決[き]められている。", "sentence_source": "generated"}, {"text": "星の並びを線でつなぐと、星座の形になる。", "target_word": "並び", "complexity_tier": "T3", "furigana": "星[ほし]の並[なら]びを線[せん]でつなぐと、星座[せいざ]の形[かたち]になる。", "sentence_source": "generated"}, {"text": "この暗号は、記号の並びを解くとわかる。", "target_word": "並び", "complexity_tier": "T3", "furigana": "この暗号[あんごう]は、記号[きごう]の並[なら]びを解[と]くとわかる。", "sentence_source": "generated"}, {"text": "カードの並びが逆だったので、ゲームの結果が変わった。", "target_word": "並び", "complexity_tier": "T3", "furigana": "カードの並[なら]びが逆[ぎゃく]だったので、ゲームの結果[けっか]が変[か]わった。", "sentence_source": "generated"}, {"text": "本の背表紙の色の並びがきれいで、思わず写真をとった。", "target_word": "並び", "complexity_tier": "T3", "furigana": "本[ほん]の背表紙[せびょうし]の色[いろ]の並[なら]びがきれいで、思[おも]わず写真[しゃしん]をとった。", "sentence_source": "generated"}, {"text": "席の並びは、くじ引きで決めることになった。", "target_word": "並び", "complexity_tier": "T3", "furigana": "席[せき]の並[なら]びは、くじ引[び]きで決[き]めることになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "並び", "label": "基本形（名詞）"}, {"form": "並ぶ", "label": "元の動詞（辞書形）"}], "register": "中立（だ・である調）", "sense_fingerprint": "文字・数字・名前・席などが一列に続く、その順序や配列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '451cd61c-6cd2-433f-917f-17b37e0a7fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "並び", "is_correct": true, "explanation": "ここは〈並び〉の意味。名簿の名前が一列に続き、あいうえお順になっていることを表す。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは重量のこと。名簿の名前の重さがあいうえお順になるという文は成り立たない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格のこと。名前の値段が順になるという文は意味が通らない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は命の長さのこと。名前の寿命が順になるという文には合わない。"}], "explanations": {"並び": "ここは〈並び〉の意味。名簿の名前が一列に続き、あいうえお順になっていることを表す。", "重さ": "重さは重量のこと。名簿の名前の重さがあいうえお順になるという文は成り立たない。", "値段": "値段は価格のこと。名前の値段が順になるという文は意味が通らない。", "寿命": "寿命は命の長さのこと。名前の寿命が順になるという文には合わない。"}, "sentence_index": 0, "correct_answer": "並び"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "切符の並びが上がって、旅行の費用が増えた。", "explanation": "ここは〈値段〉の意味。費用が上がるのは値段が上がると言う。並びは一列の様子なので、値段の意味にはならない。"}, {"text": "明日の並びを確認すると、傘を持つか決めやすい。", "explanation": "ここは〈天気〉の意味。傘を持つか決めるのは天気を確認するから。並びは一列の様子で、天気の意味にはならない。"}, {"text": "カーテンの並びを選ぶと、部屋が明るく見える。", "explanation": "ここは〈色〉の意味。カーテンの色を選ぶと部屋の明るさが変わる。並びは一列の様子で、色の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "並び", "is_correct": true, "explanation": "ここは〈並び〉の意味。記号が一列に続く配列を表し、解くという文脈に合う。"}, {"text": "人数", "is_correct": false, "explanation": "人数は人の数のこと。記号の人数を解くという文は成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は四季などの時期のこと。記号の季節を解くという文には合わない。"}, {"text": "代金", "is_correct": false, "explanation": "代金は支払うお金のこと。記号の代金を解くという文は意味が通らない。"}], "explanations": {"並び": "ここは〈並び〉の意味。記号が一列に続く配列を表し、解くという文脈に合う。", "人数": "人数は人の数のこと。記号の人数を解くという文は成り立たない。", "季節": "季節は四季などの時期のこと。記号の季節を解くという文には合わない。", "代金": "代金は支払うお金のこと。記号の代金を解くという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "並び"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姉の並びが、冬の間に少し増えた。", "explanation": "ここは〈体重〉の意味。体の重さが増えることは体重で表す。並びは一列の様子なので、増えるという使い方はしない。"}, {"text": "試合の並びが速くて、選手が疲れた。", "explanation": "ここは〈速さ〉の意味。試合の速さは速さで表す。並びは一列に続く様子で、速度の意味にはならない。"}, {"text": "旅行の並びを予約するため、店に電話した。", "explanation": "ここは〈予約〉の意味。席や部屋を前もって取ることは予約で表す。並びは一列の様子で、取るという使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の本の並ぶを整えた。", "corrected_sentence": "棚の本の並びを整えた。", "error_description": "「並び」は名詞。「並ぶ」は動詞なので、目的語の位置には名詞形の「並び」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記号の並びに、暗号の鍵になる。", "corrected_sentence": "記号の並びは、暗号の鍵になる。", "error_description": "「鍵になる」の主題は「は」で示す。「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d15591-e404-45af-8603-c3c5eb6cec80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
