INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「因子は」で、因子を主題として示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「因子から、人によってちがう」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「因子を」は目的語になり、「人によってちがう」の文には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「因子へ、人によってちがう」では文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「因子は」で、因子を主題として示す。", "から": "起点を表す「から」で、「因子から、人によってちがう」は成り立たない。", "を": "「因子を」は目的語になり、「人によってちがう」の文には入らない。", "へ": "方向を示す助詞で、「因子へ、人によってちがう」では文が成り立たない。"}, "error_tags": {"から": "起点", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こる理由や結果に影響を与える、まわりのようすやことです。", "primary_collocate": null, "pronunciation": "いんし", "ipa": "iɲɕi", "syllable_count": 3, "sentences": [{"text": "事故が起きた因子として、雨と暗さが挙げられた。", "target_word": "因子", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]きた因子[いんし]として、雨[あめ]と暗[くら]さが挙[あ]げられた。", "sentence_source": "generated"}, {"text": "人の考え方を変える因子は、年齢や経験など様々だ。", "target_word": "因子", "complexity_tier": "T3", "furigana": "人[ひと]の考[かんが]え方[かた]を変[か]える因子[いんし]は、年齢[ねんれい]や経験[けいけん]など様々[さまざま]だ。", "sentence_source": "generated"}, {"text": "寝不足は、集中力を下げる大きな因子になる。", "target_word": "因子", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]は、集中力[しゅうちゅうりょく]を下[さ]げる大[おお]きな因子[いんし]になる。", "sentence_source": "generated"}, {"text": "川の水の濁りに関わる因子は、上流の工事だと考えられている。", "target_word": "因子", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]の濁[にご]りに関[かか]わる因子[いんし]は、上流[じょうりゅう]の工事[こうじ]だと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "この町の人口減少に関わる因子を、市は調べている。", "target_word": "因子", "complexity_tier": "T3", "furigana": "この町[まち]の人口[じんこう]減少[げんしょう]に関[かか]わる因子[いんし]を、市[し]は調[しら]べている。", "sentence_source": "generated"}, {"text": "成績に関わる因子として、家庭の環境もよく取り上げられる。", "target_word": "因子", "complexity_tier": "T3", "furigana": "成績[せいせき]に関[かか]わる因子[いんし]として、家庭[かてい]の環境[かんきょう]もよく取[と]り上[あ]げられる。", "sentence_source": "generated"}, {"text": "病気が広がる因子を知ることで、予防の方法が見えてくる。", "target_word": "因子", "complexity_tier": "T3", "furigana": "病気[びょうき]が広[ひろ]がる因子[いんし]を知[し]ることで、予防[よぼう]の方法[ほうほう]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "旅行の満足度を決める因子は、人によってちがう。", "target_word": "因子", "complexity_tier": "T3", "furigana": "旅行[りょこう]の満足度[まんぞくど]を決[き]める因子[いんし]は、人[ひと]によってちがう。", "sentence_source": "generated"}, {"text": "彼女は、会社を辞める決心をさせた因子を話してくれた。", "target_word": "因子", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、会社[かいしゃ]を辞[や]める決心[けっしん]をさせた因子[いんし]を話[はな]してくれた。", "sentence_source": "generated"}, {"text": "天気も、試合の結果に影響する因子の一つだ。", "target_word": "因子", "complexity_tier": "T3", "furigana": "天気[てんき]も、試合[しあい]の結果[けっか]に影響[えいきょう]する因子[いんし]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "因子", "label": "基本形"}, {"form": "因子の", "label": "連体形"}], "register": "書き言葉", "sense_fingerprint": "出来事の理由や結果に影響する周囲の事情としての因子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因子", "is_correct": true, "explanation": "正解。事故の原因や結果に影響した周囲の事情を指し、「事故が起きた因子」として自然につながる。"}, {"text": "形式", "is_correct": false, "explanation": "〈形式〉は物事の決まった型の意味。「事故が起きた形式」では、事故の原因を述べる文脈に合わない。"}, {"text": "色調", "is_correct": false, "explanation": "〈色調〉は色合いの意味。事故の原因を表せず、「事故が起きた色調」は不自然。"}, {"text": "手法", "is_correct": false, "explanation": "〈手法〉はやり方の意味。事故が起きた原因を挙げる文には入らない。"}], "explanations": {"因子": "正解。事故の原因や結果に影響した周囲の事情を指し、「事故が起きた因子」として自然につながる。", "形式": "〈形式〉は物事の決まった型の意味。「事故が起きた形式」では、事故の原因を述べる文脈に合わない。", "色調": "〈色調〉は色合いの意味。事故の原因を表せず、「事故が起きた色調」は不自然。", "手法": "〈手法〉はやり方の意味。事故が起きた原因を挙げる文には入らない。"}, "sentence_index": 0, "correct_answer": "因子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このジュースは、ビタミンの因子が多い。", "explanation": "ここは〈成分〉の意味。因子は、ものごとの理由や結果に影響する要素を指すので、飲み物に含まれる物質の量には使えない。"}, {"text": "このパズルは、三つの因子をそろえると完成する。", "explanation": "ここは〈要素〉の意味。因子は結果に影響する原因の意味で、組み合わせて全体をつくる部品の意味では使えない。"}, {"text": "この建物の因子は、三階の大きな窓だ。", "explanation": "ここは〈部位〉の意味。因子は影響を与える条件の意味で、建物の一部には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因子", "is_correct": true, "explanation": "正解。病気が広がる原因や条件の意味で、「病気が広がる因子」として文が通る。"}, {"text": "作法", "is_correct": false, "explanation": "〈作法〉は礼儀にかなったふるまいの意味。「病気が広がる作法」は意味が通らない。"}, {"text": "礼儀", "is_correct": false, "explanation": "〈礼儀〉は人に対する敬意の示し方の意味。病気の広がりを表せず、「病気が広がる礼儀」は不自然。"}, {"text": "演技", "is_correct": false, "explanation": "〈演技〉は役を演じることの意味。病気の広がりとは関係がなく、「病気が広がる演技」は成立しない。"}], "explanations": {"因子": "正解。病気が広がる原因や条件の意味で、「病気が広がる因子」として文が通る。", "作法": "〈作法〉は礼儀にかなったふるまいの意味。「病気が広がる作法」は意味が通らない。", "礼儀": "〈礼儀〉は人に対する敬意の示し方の意味。病気の広がりを表せず、「病気が広がる礼儀」は不自然。", "演技": "〈演技〉は役を演じることの意味。病気の広がりとは関係がなく、「病気が広がる演技」は成立しない。"}, "sentence_index": 6, "correct_answer": "因子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このケーキは、因子をよく混ぜてから焼く。", "explanation": "ここは〈材料〉の意味。因子は影響を与える要素の意味で、食材そのものを指す用法はない。"}, {"text": "故障した車の因子を、新しく交換した。", "explanation": "ここは〈部品〉の意味。因子は原因や影響の意味で、交換できる機械の部分には使えない。"}, {"text": "待ち合わせの目印は、駅前の大きな木が因子だ。", "explanation": "ここは〈目印〉の意味。因子は結果に影響する要素を指すので、場所を示す目印には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その失敗を招いた因子を、準備不足が挙げられた。", "corrected_sentence": "その失敗を招いた因子として、準備不足が挙げられた。", "error_description": "「挙げられる」は「〜として挙げられる」の形をとり、原因は「として」で示す。「因子を」は目的語の格で、主語の「準備不足が」と並ぶため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38656, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査の結果、この町の人口減少に関わる因子が三つ見つけた。", "corrected_sentence": "調査の結果、この町の人口減少に関わる因子が三つ見つかった。", "error_description": "「見つける」は見つける人が主語の他動詞。因子は見つけられる側なので、自動詞「見つかる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「因子が変わる」の主語を示す「が」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「因子の変わると」は修飾の形にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「変わる」の主語にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「因子と変わると」は並列や共同の意味になり、ここでは通らない。"}], "correct_answer": "が", "explanations": {"が": "「因子が変わる」の主語を示す「が」が正しい。", "の": "「因子の変わると」は修飾の形にならず、文が成り立たない。", "より": "比較の「より」は「変わる」の主語にならず、不自然。", "と": "「因子と変わると」は並列や共同の意味になり、ここでは通らない。"}, "error_tags": {"の": "所属・修飾", "より": "比較", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事に影響を与える、周囲の状況や条件のこと。", "primary_collocate": null, "pronunciation": "いんし", "ipa": "iɲɕi", "syllable_count": 3, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価を左右する因子も大きく変わる。", "target_word": "因子", "complexity_tier": "T4", "furigana": "しかし、微生物[びせいぶつ]の営[いとな]みを経[へ]ることで、難消化性[なんしょうかせい]の成分[せいぶん]は低分子化[ていぶんしか]され、栄養価[えいようか]を左右[さゆう]する因子[いんし]も大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "病気になりやすくなる因子には、運動不足や睡眠不足などがある。", "target_word": "因子", "complexity_tier": "T3", "furigana": "病気[びょうき]になりやすくなる因子[いんし]には、運動不足[うんどうぶそく]や睡眠不足[すいみんぶそく]などがある。", "sentence_source": "generated"}, {"text": "売り上げが伸びた因子を調べるために、客のアンケートを集めた。", "target_word": "因子", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが伸[の]びた因子[いんし]を調[しら]べるために、客[きゃく]のアンケートを集[あつ]めた。", "sentence_source": "generated"}, {"text": "気温や湿度など、いくつもの因子が作物の育ち方を左右する。", "target_word": "因子", "complexity_tier": "T3", "furigana": "気温[きおん]や湿度[しつど]など、いくつもの因子[いんし]が作物[さくもつ]の育[そだ]ち方[かた]を左右[さゆう]する。", "sentence_source": "generated"}, {"text": "彼が試合に勝てた最大の因子は、毎日の練習だったと思う。", "target_word": "因子", "complexity_tier": "T3", "furigana": "彼[かれ]が試合[しあい]に勝[か]てた最大[さいだい]の因子[いんし]は、毎日[まいにち]の練習[れんしゅう]だったと思[おも]う。", "sentence_source": "generated"}, {"text": "景気を悪くしている因子を一つずつ取り除くべきだ。", "target_word": "因子", "complexity_tier": "T3", "furigana": "景気[けいき]を悪[わる]くしている因子[いんし]を一[ひと]つずつ取[と]り除[のぞ]くべきだ。", "sentence_source": "generated"}, {"text": "失敗の因子がわかれば、同じ間違いは防げる。", "target_word": "因子", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の因子[いんし]がわかれば、同[おな]じ間違[まちが]いは防[ふせ]げる。", "sentence_source": "generated"}, {"text": "環境の因子が変わると、生き物の数も変化する。", "target_word": "因子", "complexity_tier": "T3", "furigana": "環境[かんきょう]の因子[いんし]が変[か]わると、生[い]き物[もの]の数[かず]も変化[へんか]する。", "sentence_source": "generated"}, {"text": "研究チームは、渋滞を引き起こす因子を三つに絞った。", "target_word": "因子", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、渋滞[じゅうたい]を引[ひ]き起[お]こす因子[いんし]を三[みっ]つに絞[しぼ]った。", "sentence_source": "generated"}, {"text": "値段だけでなく、味も人気の因子の一つだ。", "target_word": "因子", "complexity_tier": "T3", "furigana": "値段[ねだん]だけでなく、味[あじ]も人気[にんき]の因子[いんし]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "因子", "label": "基本形"}, {"form": "因子の", "label": "連体形"}], "register": "書き言葉", "sense_fingerprint": "結果や変化に影響を与える条件・要素としての因子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因子", "is_correct": true, "explanation": "正解。「栄養価を左右する因子」として、栄養の変化に影響する要素を指すので文が通る。"}, {"text": "寝具", "is_correct": false, "explanation": "眠るときに使う道具で、栄養価を左右する要素とは言えない。"}, {"text": "演技", "is_correct": false, "explanation": "役を演じることを指し、栄養価の変化とは関係がない。"}, {"text": "礼儀", "is_correct": false, "explanation": "人に対するふるまいの作法で、食品の栄養価には関わらない。"}], "explanations": {"因子": "正解。「栄養価を左右する因子」として、栄養の変化に影響する要素を指すので文が通る。", "寝具": "眠るときに使う道具で、栄養価を左右する要素とは言えない。", "演技": "役を演じることを指し、栄養価の変化とは関係がない。", "礼儀": "人に対するふるまいの作法で、食品の栄養価には関わらない。"}, "sentence_index": 0, "correct_answer": "因子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場の因子は、部品を組み立てる機械だ。", "explanation": "ここは〈設備〉の意味。機械は物事に影響を与える条件ではないので、因子とは言わない。"}, {"text": "この料理の因子は、豆腐と味噌だ。", "explanation": "ここは〈材料〉の意味。料理の構成物は因子とは言わず、影響を与える条件の意味では合わない。"}, {"text": "試合の因子は、三番打者の山田選手だった。", "explanation": "ここは〈人物〉の意味。因子は条件や状況を指すので、選手のような人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因子", "is_correct": true, "explanation": "「失敗の因子」として、失敗を招いた要素を指すので正しい。"}, {"text": "天気", "is_correct": false, "explanation": "「失敗の天気」は意味が通らず、わかれば防げる対象として合わない。"}, {"text": "包装", "is_correct": false, "explanation": "「失敗の包装」は成り立たず、この文脈に入らない。"}, {"text": "寝具", "is_correct": false, "explanation": "「失敗の寝具」は意味をなさず、文の構造に入らない。"}], "explanations": {"因子": "「失敗の因子」として、失敗を招いた要素を指すので正しい。", "天気": "「失敗の天気」は意味が通らず、わかれば防げる対象として合わない。", "包装": "「失敗の包装」は成り立たず、この文脈に入らない。", "寝具": "「失敗の寝具」は意味をなさず、文の構造に入らない。"}, "sentence_index": 6, "correct_answer": "因子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲の因子は、リズムとメロディだ。", "explanation": "ここは〈要素〉の意味。曲を構成する部分を指す語で、影響を与える条件の意味の因子は合わない。"}, {"text": "今日の会議の因子は、予算の話し合いだ。", "explanation": "ここは〈議題〉の意味。会議で話し合う事柄は議題と言い、影響を与える条件の因子とは合わない。"}, {"text": "この式の因子は、右上の小さな数字だ。", "explanation": "ここは〈指数〉の意味。右上の小さな数字は指数で、影響を与える条件の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ストレスの因子を、胃の調子を悪くすることがある。", "corrected_sentence": "ストレスの因子が、胃の調子を悪くすることがある。", "error_description": "「因子」は文の主語なので「が」が正しい。「を」は目的語を示すため、ここでは不適。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38657, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ストレスは、胃潰瘍の発症に関わる因子に一つだと考えられている。", "corrected_sentence": "ストレスは、胃潰瘍の発症に関わる因子の一つだと考えられている。", "error_description": "「因子」に続く助詞が誤り。「因子の一つ」と「の」で続けるのが正しく、「に」では意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「実用を考えて」の「を」。考える対象を示す目的語の助詞で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「実用が考えて」は実用を考える主体のように読めてしまい、考える対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「実用に考えて」は考える対象を「に」で示すことができず、文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「実用の考えて」は名詞をつなぐ「の」で、動詞「考えて」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「実用を考えて」の「を」。考える対象を示す目的語の助詞で、正解。", "が": "「実用が考えて」は実用を考える主体のように読めてしまい、考える対象を示せない。", "に": "「実用に考えて」は考える対象を「に」で示すことができず、文として不自然。", "の": "「実用の考えて」は名詞をつなぐ「の」で、動詞「考えて」の対象を示せない。"}, "error_tags": {"が": "主格", "に": "対象・方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「実用のために」の「の」。名詞を「ため」につなぐ連体の「の」で、正解。"}, {"text": "と", "is_correct": false, "explanation": "「実用とために」は成り立たず、「と」は引用や並列を示すのでここでは名詞をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "「実用へために」は方向を表す「へ」になり、「ために」とつながらない。"}, {"text": "から", "is_correct": false, "explanation": "「実用からために」は起点の「から」になり、目的を表す「ために」には続かない。"}], "correct_answer": "の", "explanations": {"の": "「実用のために」の「の」。名詞を「ため」につなぐ連体の「の」で、正解。", "と": "「実用とために」は成り立たず、「と」は引用や並列を示すのでここでは名詞をつなげない。", "へ": "「実用へために」は方向を表す「へ」になり、「ために」とつながらない。", "から": "「実用からために」は起点の「から」になり、目的を表す「ために」には続かない。"}, "error_tags": {"と": "引用・並列", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に使うこと", "primary_collocate": null, "pronunciation": "じつよう", "ipa": "dʑitsɯjoː", "syllable_count": 4, "sentences": [{"text": "この機械はまだ実験中で、実用はこれからです。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この機械[きかい]はまだ実験中[じっけんちゅう]で、実用[じつよう]はこれからです。", "sentence_source": "generated"}, {"text": "実用を考えて、丈夫なかばんを選びました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実用[じつよう]を考[かんが]えて、丈夫[じょうぶ]なかばんを選[えら]びました。", "sentence_source": "generated"}, {"text": "この車は見た目はいいですが、実用には向きません。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この車[くるま]は見[み]た目[め]はいいですが、実用[じつよう]には向[む]きません。", "sentence_source": "generated"}, {"text": "新しい技術が実用の段階に入るまで、五年かかりました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]が実用[じつよう]の段階[だんかい]に入[はい]るまで、五年[ごねん]かかりました。", "sentence_source": "generated"}, {"text": "実験が成功したので、来年から実用が始まります。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実験[じっけん]が成功[せいこう]したので、来年[らいねん]から実用[じつよう]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "祖母は飾りより実用を大切にする人でした。", "target_word": "実用", "complexity_tier": "T3", "furigana": "祖母[そぼ]は飾[かざ]りより実用[じつよう]を大切[たいせつ]にする人[ひと]でした。", "sentence_source": "generated"}, {"text": "この道具は古いですが、今でも実用に耐えます。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は古[ふる]いですが、今[いま]でも実用[じつよう]に耐[た]えます。", "sentence_source": "generated"}, {"text": "展示用ではなく、実用のために作られた時計です。", "target_word": "実用", "complexity_tier": "T3", "furigana": "展示用[てんじよう]ではなく、実用[じつよう]のために作[つく]られた時計[とけい]です。", "sentence_source": "generated"}, {"text": "実用を目的にした小さなロボットが発売されました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実用[じつよう]を目的[もくてき]にした小[ちい]さなロボットが発売[はつばい]されました。", "sentence_source": "generated"}, {"text": "実用の前に、安全かどうかを確認してください。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実用[じつよう]の前[まえ]に、安全[あんぜん]かどうかを確認[かくにん]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実用", "label": "基本形"}], "register": "polite", "sense_fingerprint": "実用:実際に使うこと(試作・展示でなく現実に使用する段階)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実用", "is_correct": true, "explanation": "「実用はこれからです」は、実際に使える段階はまだ先だという意味になり、実験中の機械という文脈に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢はこれからです」は文として成り立たず、機械の実験段階を述べる文脈に合わない。"}, {"text": "床面積", "is_correct": false, "explanation": "床面積は部屋などの広さを指し、機械が実験段階にあることとは関係がないので合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は人が生まれた日を指し、機械の開発段階を述べる文には合わない。"}], "explanations": {"実用": "「実用はこれからです」は、実際に使える段階はまだ先だという意味になり、実験中の機械という文脈に合う。", "年齢": "「年齢はこれからです」は文として成り立たず、機械の実験段階を述べる文脈に合わない。", "床面積": "床面積は部屋などの広さを指し、機械が実験段階にあることとは関係がないので合わない。", "誕生日": "誕生日は人が生まれた日を指し、機械の開発段階を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "実用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館の実用は無料です。", "explanation": "ここは〈利用〉の意味。施設を使うことは利用と言い、実用は道具などを実際に役立てる意味なので合わない。"}, {"text": "博物館で、実用の化石を見ました。", "explanation": "ここは〈実物〉の意味。本物そのものは実物と言い、実用は使うことを表すので合わない。"}, {"text": "新薬はまだ動物で実用中です。", "explanation": "ここは〈実験〉の意味。まだ試している段階は実験中と言い、実用中は実際に使われている状態を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実用", "is_correct": true, "explanation": "「実用に耐える」は、実際に使うことに十分耐えられるという意味で、古い道具の文脈に合う。"}, {"text": "給料", "is_correct": false, "explanation": "「給料に耐える」は不自然で、古い道具が使い続けられるという文脈に合わない。"}, {"text": "年末", "is_correct": false, "explanation": "年末は時期を表すので、耐える対象にはならない。"}, {"text": "返事", "is_correct": false, "explanation": "返事は応答の言葉であり、古い道具の耐久性の文脈には合わない。"}], "explanations": {"実用": "「実用に耐える」は、実際に使うことに十分耐えられるという意味で、古い道具の文脈に合う。", "給料": "「給料に耐える」は不自然で、古い道具が使い続けられるという文脈に合わない。", "年末": "年末は時期を表すので、耐える対象にはならない。", "返事": "返事は応答の言葉であり、古い道具の耐久性の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "実用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美術館で、絵画の実用を楽しみました。", "explanation": "ここは〈鑑賞〉の意味。絵を見て味わうことは鑑賞と言い、実用は道具などを使って役立てることを指すので合わない。"}, {"text": "初めて海を見て、旅の実用がわいてきました。", "explanation": "ここは〈実感〉の意味。心で感じた手応えは実感と言い、実用は使うことを指すので合わない。"}, {"text": "実用の金額を教えてください。", "explanation": "ここは〈実際〉の意味。本当の数字は実際と言い、実用は使うことを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この古い工具は、長年使っても実用を耐えます。", "corrected_sentence": "この古い工具は、長年使っても実用に耐えます。", "error_description": "正しくは「実用に耐える」、誤りは「実用を耐える」。「耐える」は「〜に耐える」の形で、対象を表すのは「に」。「を」は不適切。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この新しい機器は、実用を入る前に安全を確かめます。", "corrected_sentence": "この新しい機器は、実用に入る前に安全を確かめます。", "error_description": "正しくは「実用に入る」、誤りは「実用を入る」。「入る」は「〜に入る」の形で、移る先を表すのは「に」。「を」は不適切。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38659, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「実用に役立つ」の「に」。役立つ先・対象を示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「実用を役立つ」は「役立つ」の対象を「を」で示せず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「実用の役立つ点」は名詞修飾の「の」で、役立つ先を示す助詞にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「実用と役立つ」は並列・引用の「と」になり、役立つ対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「実用に役立つ」の「に」。役立つ先・対象を示す。正解。", "を": "「実用を役立つ」は「役立つ」の対象を「を」で示せず、不自然。", "の": "「実用の役立つ点」は名詞修飾の「の」で、役立つ先を示す助詞にはならない。", "と": "「実用と役立つ」は並列・引用の「と」になり、役立つ対象を示せない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "と": "引用・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
