INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に役立つように使うこと。実社会で活用すること。", "primary_collocate": null, "pronunciation": "じつよう", "ipa": "dʑitsɯjoː", "syllable_count": 4, "sentences": [{"text": "研究で終わらせず、実社会での実用を目指しています。", "target_word": "実用", "complexity_tier": "T3", "furigana": "研究[けんきゅう]で終[お]わらせず、実社会[じっしゃかい]での実用[じつよう]を目指[めざ]しています。", "sentence_source": "generated"}, {"text": "この発明は、暮らしの中で実用に役立つ点が評価されました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この発明[はつめい]は、暮[く]らしの中[なか]で実用[じつよう]に役立[やくだ]つ点[てん]が評価[ひょうか]されました。", "sentence_source": "generated"}, {"text": "美しいだけでなく、実用にも優れた食器です。", "target_word": "実用", "complexity_tier": "T3", "furigana": "美[うつく]しいだけでなく、実用[じつよう]にも優[すぐ]れた食器[しょっき]です。", "sentence_source": "generated"}, {"text": "見た目より実用を重視して、仕事用の靴を買いました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "見[み]た目[め]より実用[じつよう]を重視[じゅうし]して、仕事用[しごとよう]の靴[くつ]を買[か]いました。", "sentence_source": "generated"}, {"text": "この翻訳ソフトは、旅行で使える実用の水準に達しました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この翻訳[ほんやく]ソフトは、旅行[りょこう]で使[つか]える実用[じつよう]の水準[すいじゅん]に達[たっ]しました。", "sentence_source": "generated"}, {"text": "理論は完成しましたが、実用にはまだ課題が残っています。", "target_word": "実用", "complexity_tier": "T3", "furigana": "理論[りろん]は完成[かんせい]しましたが、実用[じつよう]にはまだ課題[かだい]が残[のこ]っています。", "sentence_source": "generated"}, {"text": "実用を優先して、飾りのない作業服が作られました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実用[じつよう]を優先[ゆうせん]して、飾[かざ]りのない作業服[さぎょうふく]が作[つく]られました。", "sentence_source": "generated"}, {"text": "この講座は、実用を重んじて、仕事で使う英会話だけを教えています。", "target_word": "実用", "complexity_tier": "T3", "furigana": "この講座[こうざ]は、実用[じつよう]を重[おも]んじて、仕事[しごと]で使[つか]う英会話[えいかいわ]だけを教[おし]えています。", "sentence_source": "generated"}, {"text": "実用に役立つ資格を取るために、毎晩勉強しています。", "target_word": "実用", "complexity_tier": "T3", "furigana": "実用[じつよう]に役立[やくだ]つ資格[しかく]を取[と]るために、毎晩[まいばん]勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "太陽の光で動く車が、ついに実用の時代を迎えました。", "target_word": "実用", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]で動[うご]く車[くるま]が、ついに実用[じつよう]の時代[じだい]を迎[むか]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実用", "label": "基本形"}], "register": "polite", "sense_fingerprint": "実用:実社会で役立つように活用すること(見た目・理論と対比される実際的な有用さ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38659, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実用", "is_correct": true, "explanation": "「実社会での実用を目指す」は、役立つ形で実際に使えるようにするという意味で、正解。"}, {"text": "騒音", "is_correct": false, "explanation": "「実社会での騒音を目指す」は意味をなさず、文脈に合わない。"}, {"text": "床面積", "is_correct": false, "explanation": "床面積は部屋の広さを指し、社会で役立てるという目標の文脈には合わない。"}, {"text": "年末", "is_correct": false, "explanation": "年末は時期を表し、目指す対象にはならない。"}], "explanations": {"実用": "「実社会での実用を目指す」は、役立つ形で実際に使えるようにするという意味で、正解。", "騒音": "「実社会での騒音を目指す」は意味をなさず、文脈に合わない。", "床面積": "床面積は部屋の広さを指し、社会で役立てるという目標の文脈には合わない。", "年末": "年末は時期を表し、目指す対象にはならない。"}, "sentence_index": 0, "correct_answer": "実用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもへの実用は、言葉では言い表せません。", "explanation": "ここは〈愛情〉の意味。子どもへの深い気持ちは愛情と言い、実用は役立つ使い方を指すので合わない。"}, {"text": "彼は大きな実用を語りました。", "explanation": "ここは〈夢〉の意味。将来へのあこがれは夢と言い、実用は役立つことを指すので合わない。"}, {"text": "この映画は、実用として多くの人に楽しまれています。", "explanation": "ここは〈娯楽〉の意味。楽しむために見るものは娯楽と言い、実用は役立つ使い方を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38659, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実用", "is_correct": true, "explanation": "「実用を優先して」は、飾りより役立つことを重視するという意味で、作業服の文脈に合う。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足を優先して」は意味をなさず、作業服の文脈に合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は人が生まれた日を指し、作業服を作る判断の基準にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体重を優先して作業服を作るという文脈は不自然で、合わない。"}], "explanations": {"実用": "「実用を優先して」は、飾りより役立つことを重視するという意味で、作業服の文脈に合う。", "寝不足": "「寝不足を優先して」は意味をなさず、作業服の文脈に合わない。", "誕生日": "誕生日は人が生まれた日を指し、作業服を作る判断の基準にはならない。", "体重": "体重を優先して作業服を作るという文脈は不自然で、合わない。"}, "sentence_index": 6, "correct_answer": "実用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説は、読む人に深い実用を与えました。", "explanation": "ここは〈感動〉の意味。心を動かされる感情は感動と言い、実用は役立つ使い方を指すので合わない。"}, {"text": "この服は実用がかわいいと評判です。", "explanation": "ここは〈見た目〉の意味。外から見た感じは見た目と言い、実用は使って役立つことを指すので合わない。"}, {"text": "彼は、負けた実用をかみしめました。", "explanation": "ここは〈悔しさ〉の意味。負けた時の気持ちは悔しさと言い、実用は役立つ使い方を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
