INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをするときに、そのものを使うこと。", "primary_collocate": null, "pronunciation": "しよう", "ipa": "ɕijoː", "syllable_count": 3, "sentences": [{"text": "会議室の使用は、前の日までに申し込んでください。", "target_word": "使用", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]の使用[しよう]は、前[まえ]の日[ひ]までに申[もう]し込[こ]んでください。", "sentence_source": "generated"}, {"text": "このペンは水性なので、紙の裏にも使用できます。", "target_word": "使用", "complexity_tier": "T3", "furigana": "このペンは水性[すいせい]なので、紙[かみ]の裏[うら]にも使用[しよう]できます。", "sentence_source": "generated"}, {"text": "使用が終わったら、道具を元の場所に戻しましょう。", "target_word": "使用", "complexity_tier": "T3", "furigana": "使用[しよう]が終[お]わったら、道具[どうぐ]を元[もと]の場所[ばしょ]に戻[もど]しましょう。", "sentence_source": "generated"}, {"text": "携帯電話の使用は、館内では禁止されています。", "target_word": "使用", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の使用[しよう]は、館内[かんない]では禁止[きんし]されています。", "sentence_source": "generated"}, {"text": "この薬は、子どもの使用に注意が必要です。", "target_word": "使用", "complexity_tier": "T3", "furigana": "この薬[くすり]は、子[こ]どもの使用[しよう]に注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "この部屋は今、使用されていますので、入らないでください。", "target_word": "使用", "complexity_tier": "T3", "furigana": "この部屋[へや]は今[いま]、使用[しよう]されていますので、入[はい]らないでください。", "sentence_source": "generated"}, {"text": "古い建物なので、エレベーターの使用ができません。", "target_word": "使用", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]なので、エレベーターの使用[しよう]ができません。", "sentence_source": "generated"}, {"text": "説明書を読んでから、使用を始めてください。", "target_word": "使用", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]んでから、使用[しよう]を始[はじ]めてください。", "sentence_source": "generated"}, {"text": "夏は水の使用が増えるので、料金が高くなります。", "target_word": "使用", "complexity_tier": "T3", "furigana": "夏[なつ]は水[みず]の使用[しよう]が増[ふ]えるので、料金[りょうきん]が高[たか]くなります。", "sentence_source": "generated"}, {"text": "このトイレは、工事のため使用できません。", "target_word": "使用", "complexity_tier": "T3", "furigana": "このトイレは、工事[こうじ]のため使用[しよう]できません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使用する", "label": "辞書形"}, {"form": "使用した", "label": "過去形"}, {"form": "使用して", "label": "て形"}, {"form": "使用しない", "label": "否定形"}], "register": "polite", "sense_fingerprint": "使用:何かをするときにそのもの(場所・物)を使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38660, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用", "is_correct": true, "explanation": "「会議室の使用」は会議室を使うこと。前の日までに申し込む対象として自然で、正解。"}, {"text": "色合い", "is_correct": false, "explanation": "「会議室の色合いは、前の日までに申し込んでください」は意味をなさず、合わない。"}, {"text": "床面積", "is_correct": false, "explanation": "床面積を前の日までに申し込むという文は成り立たず、合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "会議室の誕生日を申し込むという文は意味をなさず、合わない。"}], "explanations": {"使用": "「会議室の使用」は会議室を使うこと。前の日までに申し込む対象として自然で、正解。", "色合い": "「会議室の色合いは、前の日までに申し込んでください」は意味をなさず、合わない。", "床面積": "床面積を前の日までに申し込むという文は成り立たず、合わない。", "誕生日": "会議室の誕生日を申し込むという文は意味をなさず、合わない。"}, "sentence_index": 0, "correct_answer": "使用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は重い使用を果たしました。", "explanation": "ここは〈使命〉の意味。任された役目は使命と言い、使用は物を使うことなので合わない。"}, {"text": "テストに合格して、大きな使用を感じました。", "explanation": "ここは〈喜び〉の意味。うれしい気持ちは喜びと言い、使用は物や方法を使うことなので合わない。"}, {"text": "子どもの頃の使用を、ついにかなえました。", "explanation": "ここは〈夢〉の意味。幼い頃の願いは夢と言い、使用は物を使うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38660, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用", "is_correct": true, "explanation": "「エレベーターの使用ができません」は、エレベーターを使えないという意味で、正解。"}, {"text": "給料", "is_correct": false, "explanation": "「エレベーターの給料ができません」は意味をなさず、合わない。"}, {"text": "年末", "is_correct": false, "explanation": "年末は時期を表し、エレベーターの対象にはならない。"}, {"text": "返事", "is_correct": false, "explanation": "返事はエレベーターの状態を表す言葉ではなく、文として合わない。"}], "explanations": {"使用": "「エレベーターの使用ができません」は、エレベーターを使えないという意味で、正解。", "給料": "「エレベーターの給料ができません」は意味をなさず、合わない。", "年末": "年末は時期を表し、エレベーターの対象にはならない。", "返事": "返事はエレベーターの状態を表す言葉ではなく、文として合わない。"}, "sentence_index": 6, "correct_answer": "使用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は音楽の使用を発揮して、会場を沸かせました。", "explanation": "ここは〈才能〉の意味。能力は才能と言い、使用は物を使うことなので「発揮」の対象にならない。"}, {"text": "母は子どもに深い使用を注いでいます。", "explanation": "ここは〈愛情〉の意味。子どもへの深い気持ちは愛情と言い、使用は物を使うことなので合わない。"}, {"text": "仲間の使用を失うと、取り戻すのは難しい。", "explanation": "ここは〈信頼〉の意味。相手を信じる気持ちは信頼と言い、使用は物を使うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38660, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工具は、高い場所での使用に避けてください。", "corrected_sentence": "この工具は、高い場所での使用を避けてください。", "error_description": "正しくは「使用を避ける」、誤りは「使用に避ける」。「避ける」は直接の対象を「を」で示す。「に」は不適切。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38660, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具は、使用したたびに手入れをしてください。", "corrected_sentence": "この道具は、使用するたびに手入れをしてください。", "error_description": "正しくは「使用するたびに」、誤りは「使用したたびに」。「〜たびに」は辞書形に付けて「〜する度に」を表すので、「する」を使う。「した」は接続できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「使用には」の「に」。「には」で使用に関する条件や要件を示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「使用をには」は成り立たず、「を」は動作の対象を示すので「には」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「使用へには」は方向を示す「へ」になり、要件を示す「には」とは続かない。"}, {"text": "と", "is_correct": false, "explanation": "「使用とには」は並列・引用の「と」になり、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「使用には」の「に」。「には」で使用に関する条件や要件を示す。正解。", "を": "「使用をには」は成り立たず、「を」は動作の対象を示すので「には」とは続かない。", "へ": "「使用へには」は方向を示す「へ」になり、要件を示す「には」とは続かない。", "と": "「使用とには」は並列・引用の「と」になり、文が成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "引用・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「使用で熱くなる」の「で」。原因・理由を示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「使用に熱くなります」は原因を「に」で示せず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「使用の熱くなります」は名詞をつなぐ「の」で、動詞の原因にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「使用を熱くなります」は「熱くなる」の対象を示せず、文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「使用で熱くなる」の「で」。原因・理由を示す。正解。", "に": "「使用に熱くなります」は原因を「に」で示せず、文が成り立たない。", "の": "「使用の熱くなります」は名詞をつなぐ「の」で、動詞の原因にはならない。", "を": "「使用を熱くなります」は「熱くなる」の対象を示せず、文として成り立たない。"}, "error_tags": {"に": "方向・対象", "の": "連体修飾", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある目的のために、道具や機械などを動かしたり、材料として使ったりすること。", "primary_collocate": null, "pronunciation": "しよう", "ipa": "ɕijoː", "syllable_count": 3, "sentences": [{"text": "この工場では、機械を使用する前に、必ず点検をします。", "target_word": "使用", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、機械[きかい]を使用[しよう]する前[まえ]に、必[かなら]ず点検[てんけん]をします。", "sentence_source": "generated"}, {"text": "新しい装置の使用には、特別な資格が必要です。", "target_word": "使用", "complexity_tier": "T3", "furigana": "新[あたら]しい装置[そうち]の使用[しよう]には、特別[とくべつ]な資格[しかく]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "電子レンジを使用しているときは、ふたを開けないでください。", "target_word": "使用", "complexity_tier": "T3", "furigana": "電子[でんし]レンジを使用[しよう]しているときは、ふたを開[あ]けないでください。", "sentence_source": "generated"}, {"text": "この家具は、国産の木材を使用して作られています。", "target_word": "使用", "complexity_tier": "T3", "furigana": "この家具[かぐ]は、国産[こくさん]の木材[もくざい]を使用[しよう]して作[つく]られています。", "sentence_source": "generated"}, {"text": "工事では、大型クレーンの使用が決まりました。", "target_word": "使用", "complexity_tier": "T3", "furigana": "工事[こうじ]では、大型[おおがた]クレーンの使用[しよう]が決[き]まりました。", "sentence_source": "generated"}, {"text": "使用する材料は、安全なものだけにしています。", "target_word": "使用", "complexity_tier": "T3", "furigana": "使用[しよう]する材料[ざいりょう]は、安全[あんぜん]なものだけにしています。", "sentence_source": "generated"}, {"text": "このカメラは、水中での使用を考えて作られています。", "target_word": "使用", "complexity_tier": "T3", "furigana": "このカメラは、水中[すいちゅう]での使用[しよう]を考[かんが]えて作[つく]られています。", "sentence_source": "generated"}, {"text": "古いコピー機は、長時間の使用で熱くなります。", "target_word": "使用", "complexity_tier": "T3", "furigana": "古[ふる]いコピー機[き]は、長時間[ちょうじかん]の使用[しよう]で熱[あつ]くなります。", "sentence_source": "generated"}, {"text": "実験で薬品を使用するときは、手袋をつけます。", "target_word": "使用", "complexity_tier": "T3", "furigana": "実験[じっけん]で薬品[やくひん]を使用[しよう]するときは、手袋[てぶくろ]をつけます。", "sentence_source": "generated"}, {"text": "ドローンの使用には、場所のルールがあります。", "target_word": "使用", "complexity_tier": "T3", "furigana": "ドローンの使用[しよう]には、場所[ばしょ]のルールがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使用する", "label": "辞書形"}, {"form": "使用した", "label": "過去形"}, {"form": "使用して", "label": "て形"}, {"form": "使用しない", "label": "否定形"}], "register": "polite", "sense_fingerprint": "使用:目的のために道具・機械を動かす、または材料として使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用", "is_correct": true, "explanation": "「機械を使用する前に」は、機械を目的のために動かす前にという意味で、正解。"}, {"text": "休憩", "is_correct": false, "explanation": "「機械を休憩する」は意味をなさず、機械の点検の文脈に合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "「機械を感謝する」は成り立たず、点検の文脈に合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "「機械を結婚する」は意味をなさず、合わない。"}], "explanations": {"使用": "「機械を使用する前に」は、機械を目的のために動かす前にという意味で、正解。", "休憩": "「機械を休憩する」は意味をなさず、機械の点検の文脈に合わない。", "感謝": "「機械を感謝する」は成り立たず、点検の文脈に合わない。", "結婚": "「機械を結婚する」は意味をなさず、合わない。"}, "sentence_index": 0, "correct_answer": "使用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母に心から使用しています。", "explanation": "ここは〈感謝〉の意味。人へのありがたい気持ちは感謝と言い、使用は物や方法を使うことなので合わない。"}, {"text": "合格の知らせに、大きな希望を使用しました。", "explanation": "ここは〈希望〉の意味。未来への期待は希望と言い、使用は物を使うことなので合わない。"}, {"text": "彼は、この仕事に大きな誇りを使用しています。", "explanation": "ここは〈誇り〉の意味。自分の仕事への自信や気位は誇りと言い、使用は物を使うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用", "is_correct": true, "explanation": "「水中での使用を考えて」は、水中で使うことを想定してという意味で、正解。"}, {"text": "給料", "is_correct": false, "explanation": "「水中での給料を考えて」は意味をなさず、カメラの設計の文脈に合わない。"}, {"text": "年末", "is_correct": false, "explanation": "年末は時期を表し、水中での設計の対象にはならない。"}, {"text": "頭痛", "is_correct": false, "explanation": "「水中での頭痛を考えて」は意味をなさず、合わない。"}], "explanations": {"使用": "「水中での使用を考えて」は、水中で使うことを想定してという意味で、正解。", "給料": "「水中での給料を考えて」は意味をなさず、カメラの設計の文脈に合わない。", "年末": "年末は時期を表し、水中での設計の対象にはならない。", "頭痛": "「水中での頭痛を考えて」は意味をなさず、合わない。"}, "sentence_index": 6, "correct_answer": "使用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、強い使用を持って挑みました。", "explanation": "ここは〈信念〉の意味。かたく信じる考えは信念と言い、使用は物を使うことなので合わない。"}, {"text": "二人は、ずっと守る使用を交わしました。", "explanation": "ここは〈約束〉の意味。互いに交わす取り決めは約束と言い、使用は物を使うことなので合わない。"}, {"text": "彼女は、昔の出来事に深い使用を感じました。", "explanation": "ここは〈悲しみ〉の意味。つらい気持ちは悲しみと言い、使用は物を使うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場では、新しい装置を使用しから、点検をします。", "corrected_sentence": "この工場では、新しい装置を使用してから、点検をします。", "error_description": "正しくは「使用してから」、誤りは「使用しから」。動詞「使用する」は「使用して」の形で「てから」に続ける必要があり、「使用し」では接続できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38661, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部屋では、ストーブの使用が禁じています。", "corrected_sentence": "この部屋では、ストーブの使用を禁じています。", "error_description": "正しくは「使用を禁じています」、誤りは「使用が禁じています」。「禁じる」は他動詞なので、対象は「を」で示す。「が」は不適切。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「両立に苦労している」の「に」。苦労の対象を示し、両立で何に困っているかを表す。"}, {"text": "を", "is_correct": false, "explanation": "「苦労する」に「を」は続かず、「両立を毎日苦労している」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示すが、ここでは苦労の対象にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、苦労の対象を表す文脈には入らない。"}], "correct_answer": "に", "explanations": {"に": "「両立に苦労している」の「に」。苦労の対象を示し、両立で何に困っているかを表す。", "を": "「苦労する」に「を」は続かず、「両立を毎日苦労している」は不自然。", "と": "「と」は共同の相手を示すが、ここでは苦労の対象にならず文が成り立たない。", "へ": "「へ」は方向を示すため、苦労の対象を表す文脈には入らない。"}, "error_tags": {"を": "目的語", "と": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「両立のために」の「の」。「のために」の形で目的を表す語句をつくる。"}, {"text": "を", "is_correct": false, "explanation": "「両立をために」は成り立たず、目的語の「を」はこの位置に入らない。"}, {"text": "が", "is_correct": false, "explanation": "「両立がために」は成り立たず、主語の「が」はここでは使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「両立へために」は不自然で、方向の「へ」はこの形に入らない。"}], "correct_answer": "の", "explanations": {"の": "「両立のために」の「の」。「のために」の形で目的を表す語句をつくる。", "を": "「両立をために」は成り立たず、目的語の「を」はこの位置に入らない。", "が": "「両立がために」は成り立たず、主語の「が」はここでは使えない。", "へ": "「両立へために」は不自然で、方向の「へ」はこの形に入らない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものがどちらも成り立つこと。", "primary_collocate": null, "pronunciation": "りょうりつ", "ipa": "ɾʲoːɾʲitsɯ", "syllable_count": 4, "sentences": [{"text": "仕事と育児を両立するのは簡単ではない。", "target_word": "両立", "complexity_tier": "T3", "furigana": "仕事[しごと]と育児[いくじ]を両立[りょうりつ]するのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "勉強と部活の両立に、毎日苦労している。", "target_word": "両立", "complexity_tier": "T3", "furigana": "勉強[べんきょう]と部活[ぶかつ]の両立[りょうりつ]に、毎日[まいにち]苦労[くろう]している。", "sentence_source": "generated"}, {"text": "環境保護と経済の発展は、両立できるだろうか。", "target_word": "両立", "complexity_tier": "T3", "furigana": "環境[かんきょう]保護[ほご]と経済[けいざい]の発展[はってん]は、両立[りょうりつ]できるだろうか。", "sentence_source": "generated"}, {"text": "彼は医者と作家を両立している。", "target_word": "両立", "complexity_tier": "T3", "furigana": "彼[かれ]は医者[いしゃ]と作家[さっか]を両立[りょうりつ]している。", "sentence_source": "generated"}, {"text": "両立が難しいときは、どちらかを減らすしかない。", "target_word": "両立", "complexity_tier": "T3", "furigana": "両立[りょうりつ]が難[むずか]しいときは、どちらかを減[へ]らすしかない。", "sentence_source": "generated"}, {"text": "安くて品質もよいという両立は、なかなか実現しない。", "target_word": "両立", "complexity_tier": "T3", "furigana": "安[やす]くて品質[ひんしつ]もよいという両立[りょうりつ]は、なかなか実現[じつげん]しない。", "sentence_source": "generated"}, {"text": "学業との両立を考えて、アルバイトは週二日にした。", "target_word": "両立", "complexity_tier": "T3", "furigana": "学業[がくぎょう]との両立[りょうりつ]を考[かんが]えて、アルバイトは週二日[しゅうふつか]にした。", "sentence_source": "generated"}, {"text": "家事と仕事の両立のために、夫婦で分担している。", "target_word": "両立", "complexity_tier": "T3", "furigana": "家事[かじ]と仕事[しごと]の両立[りょうりつ]のために、夫婦[ふうふ]で分担[ぶんたん]している。", "sentence_source": "generated"}, {"text": "時間が足りず、二つの夢の両立はあきらめた。", "target_word": "両立", "complexity_tier": "T3", "furigana": "時間[じかん]が足[た]りず、二[ふた]つの夢[ゆめ]の両立[りょうりつ]はあきらめた。", "sentence_source": "generated"}, {"text": "両立させるには、毎日の計画が大切だ。", "target_word": "両立", "complexity_tier": "T3", "furigana": "両立[りょうりつ]させるには、毎日[まいにち]の計画[けいかく]が大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "両立", "label": "基本形"}, {"form": "両立する", "label": "動詞形"}, {"form": "両立した", "label": "過去形"}, {"form": "両立させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "二つのことがどちらも成り立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "両立", "is_correct": true, "explanation": "「両立するのは」の形で、仕事と育児の二つが同時に成り立つという意味になり、文に合う。"}, {"text": "両替", "is_correct": false, "explanation": "「両替」は金銭を別の硬貨や紙幣に換えることで、仕事と育児には合わない。"}, {"text": "両断", "is_correct": false, "explanation": "「両断」は真っ二つに切ることで、仕事と育児を切り分ける意味にはならず文の意味に合わない。"}, {"text": "両生", "is_correct": false, "explanation": "「両生」は両生類を指す名詞で、動詞として「するのは」に続けると文が成り立たない。"}], "explanations": {"両立": "「両立するのは」の形で、仕事と育児の二つが同時に成り立つという意味になり、文に合う。", "両替": "「両替」は金銭を別の硬貨や紙幣に換えることで、仕事と育児には合わない。", "両断": "「両断」は真っ二つに切ることで、仕事と育児を切り分ける意味にはならず文の意味に合わない。", "両生": "「両生」は両生類を指す名詞で、動詞として「するのは」に続けると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "両立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父母と両立するため、家を建て直した。", "explanation": "ここは〈同居〉の意味。両立は二つのことが同時に成り立つことで、人と一緒に住むことは表さない。"}, {"text": "二人の勝負は両立して、引き分けになった。", "explanation": "ここは〈引き分け〉の意味。両立は二つのことが同時に成り立つことで、勝負の結果を表す意味では使わない。"}, {"text": "この薬は、解熱剤と両立して飲んではいけない。", "explanation": "ここは〈併用〉の意味。両立は二つのことが同時に成り立つことで、薬を一緒に飲む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "両立", "is_correct": true, "explanation": "「学業との両立を考えて」の名詞として、学業と別のことを同時に成り立たせる意味になり、文に合う。"}, {"text": "両刃", "is_correct": false, "explanation": "「両刃」は刃が両側にある刃物を指す語で、学業との関係を表す文には合わない。"}, {"text": "両目", "is_correct": false, "explanation": "「両目」は左右の目を指すため、「学業との」に続けても意味が通らない。"}, {"text": "両側", "is_correct": false, "explanation": "「両側」は左右の側面を指すため、学業とのつながりを考える文には合わない。"}], "explanations": {"両立": "「学業との両立を考えて」の名詞として、学業と別のことを同時に成り立たせる意味になり、文に合う。", "両刃": "「両刃」は刃が両側にある刃物を指す語で、学業との関係を表す文には合わない。", "両目": "「両目」は左右の目を指すため、「学業との」に続けても意味が通らない。", "両側": "「両側」は左右の側面を指すため、学業とのつながりを考える文には合わない。"}, "sentence_index": 6, "correct_answer": "両立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の喧嘩を両立させて、仲直りした。", "explanation": "ここは〈和解〉の意味。両立は二つのことが同時に成り立つことで、対立していた人が仲直りする意味では使わない。"}, {"text": "子どもは十八歳で親から両立した。", "explanation": "ここは〈独立〉の意味。両立は二つのことが同時に成り立つことで、親元を離れることは表さない。"}, {"text": "二人は両立して当番を回している。", "explanation": "ここは〈交代〉の意味。両立は同時に成り立つことで、順番に入れ替わる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家計と趣味の両立を、ずっと悩んでいる。", "corrected_sentence": "家計と趣味の両立に、ずっと悩んでいる。", "error_description": "「悩む」の対象は「に」で示す。「両立を」の「を」は誤りで、「両立に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夢と仕事の両立を取るため、週末は休みにした。", "corrected_sentence": "夢と仕事の両立を図るため、週末は休みにした。", "error_description": "「両立を」に続く動詞は「図る」。「取る」は誤った形で、「両立を取る」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
