INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38664, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "プラスチックのようなもの。微生物が食べて作る。", "primary_collocate": null, "pronunciation": "ぽりひどろきしあるかのえーと", "ipa": "poɾihidoɾokiɕiaɾɯkanoeːto", "syllable_count": 14, "sentences": [{"text": "ポリヒドロキシアルカノエートは、微生物が作るプラスチックのような物質です。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートは、微生物[びせいぶつ]が作[つく]るプラスチックのような物質[ぶっしつ]です。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートは土の中で分解されるので、ごみが増えません。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートは土[つち]の中[なか]で分解[ぶんかい]されるので、ごみが増[ふ]えません。", "sentence_source": "generated"}, {"text": "この会社はポリヒドロキシアルカノエートでストローを作っています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はポリヒドロキシアルカノエートでストローを作[つく]っています。", "sentence_source": "generated"}, {"text": "先生はポリヒドロキシアルカノエートについて、写真を見せながら説明しました。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "先生[せんせい]はポリヒドロキシアルカノエートについて、写真[しゃしん]を見[み]せながら説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートは石油からではなく、微生物から作られます。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートは石油[せきゆ]からではなく、微生物[びせいぶつ]から作[つく]られます。", "sentence_source": "generated"}, {"text": "海に捨てても、ポリヒドロキシアルカノエートは時間がたつと分解されます。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "海[うみ]に捨[す]てても、ポリヒドロキシアルカノエートは時間[じかん]がたつと分解[ぶんかい]されます。", "sentence_source": "generated"}, {"text": "普通のプラスチックと違って、ポリヒドロキシアルカノエートは環境に優しいです。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "普通[ふつう]のプラスチックと違[ちが]って、ポリヒドロキシアルカノエートは環境[かんきょう]に優[やさ]しいです。", "sentence_source": "generated"}, {"text": "研究者はポリヒドロキシアルカノエートを安く作る方法を探しています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]はポリヒドロキシアルカノエートを安[やす]く作[つく]る方法[ほうほう]を探[さが]しています。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートの袋は、使ったあとに土に埋めることができます。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートの袋[ふくろ]は、使[つか]ったあとに土[つち]に埋[う]めることができます。", "sentence_source": "generated"}, {"text": "新しい店では、ポリヒドロキシアルカノエートのスプーンを使っています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]では、ポリヒドロキシアルカノエートのスプーンを使[つか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリヒドロキシアルカノエート", "label": "基本形"}], "register": "専門的", "sense_fingerprint": "微生物が作るプラスチックに似た物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38664, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリヒドロキシアルカノエート", "is_correct": true, "explanation": "微生物が作るプラスチック状の物質を指すので、この語が入る。"}, {"text": "ポリエチレン", "is_correct": false, "explanation": "石油から作られる普通のプラスチックで、微生物が作るものではないので合わない。"}, {"text": "ナイロン", "is_correct": false, "explanation": "石油由来の合成樹脂・繊維で、微生物が作る物質ではないので合わない。"}, {"text": "ポリスチレン", "is_correct": false, "explanation": "石油から作る合成樹脂で、微生物が作るものではないので合わない。"}], "explanations": {"ポリヒドロキシアルカノエート": "微生物が作るプラスチック状の物質を指すので、この語が入る。", "ポリエチレン": "石油から作られる普通のプラスチックで、微生物が作るものではないので合わない。", "ナイロン": "石油由来の合成樹脂・繊維で、微生物が作る物質ではないので合わない。", "ポリスチレン": "石油から作る合成樹脂で、微生物が作るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ポリヒドロキシアルカノエート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポリヒドロキシアルカノエートは石油を精製して作るので、燃料として使われています。", "explanation": "ここは石油由来のポリエチレンの話。ポリヒドロキシアルカノエートは微生物が作る物質なので、石油を精製して作るとは言わない。"}, {"text": "彼女は、ごみを減らすという自分のポリヒドロキシアルカノエートを守っています。", "explanation": "ここは「方針・信条」のポリシーの意味。ポリヒドロキシアルカノエートは物質の名前で、主義や方針を守るものではないので合わない。"}, {"text": "ポリヒドロキシアルカノエートは、とうもろこしを発酵させて作るので、車の燃料になります。", "explanation": "ここは燃料のバイオエタノールの話。ポリヒドロキシアルカノエートはプラスチック状の物質で、燃料にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38664, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリヒドロキシアルカノエート", "is_correct": true, "explanation": "環境に優しい生分解性の物質の名前なので、この語が入る。"}, {"text": "ガソリン", "is_correct": false, "explanation": "石油製品で環境に優しいとは言えないので、『環境に優しい』と合わない。"}, {"text": "アスファルト", "is_correct": false, "explanation": "石油由来の舗装材で、環境に優しい素材とは言えないので合わない。"}, {"text": "石油", "is_correct": false, "explanation": "環境負荷の大きい化石燃料で、『環境に優しい』と合わない。"}], "explanations": {"ポリヒドロキシアルカノエート": "環境に優しい生分解性の物質の名前なので、この語が入る。", "ガソリン": "石油製品で環境に優しいとは言えないので、『環境に優しい』と合わない。", "アスファルト": "石油由来の舗装材で、環境に優しい素材とは言えないので合わない。", "石油": "環境負荷の大きい化石燃料で、『環境に優しい』と合わない。"}, "sentence_index": 6, "correct_answer": "ポリヒドロキシアルカノエート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カレーにポリヒドロキシアルカノエートを入れて、とろみをつけました。", "explanation": "ここは〈でんぷん〉の話（料理にとろみをつける）。ポリヒドロキシアルカノエートは微生物が作るプラスチックのような物質で、とろみ付けには使わないので合わない。"}, {"text": "ポリヒドロキシアルカノエートは、よく伸びて元に戻るので、靴のひもに使われます。", "explanation": "ここは弾性のあるゴムの話。ポリヒドロキシアルカノエートは伸び縮みを売りにする素材ではないので合わない。"}, {"text": "ポリヒドロキシアルカノエートは、果物に塗ってつやを出すために使います。", "explanation": "ここは果物に塗るろう（ワックス）の話。ポリヒドロキシアルカノエートは果物のつやを出すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38664, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポリヒドロキシアルカノエートを、土に埋めると分解される素材です。", "corrected_sentence": "ポリヒドロキシアルカノエートは、土に埋めると分解される素材です。", "error_description": "主題を示す『は』が正しい。『を』だと目的語になり、文の述語『素材です』と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38664, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は、ポリヒドロキシアルカノエートに袋を作っています。", "corrected_sentence": "この店は、ポリヒドロキシアルカノエートで袋を作っています。", "error_description": "材料を表すのは『で』。『に』は場所や相手を示すので、材料には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
