INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "微生物が、植物からできた糖を食べて作る、プラスチックのような物質。生分解性があり、環境に優しい。", "primary_collocate": null, "pronunciation": "ぽりひどろきしあるかのえーと", "ipa": "poɾihidoɾokiɕiaɾɯkanoeːto", "syllable_count": 14, "sentences": [{"text": "ポリヒドロキシアルカノエートは、微生物が植物の糖を食べて作る物質です。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートは、微生物[びせいぶつ]が植物[しょくぶつ]の糖[とう]を食[た]べて作[つく]る物質[ぶっしつ]です。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートには生分解性があり、環境に優しいです。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートには生分解性[せいぶんかいせい]があり、環境[かんきょう]に優[やさ]しいです。", "sentence_source": "generated"}, {"text": "工場では、ポリヒドロキシアルカノエートを作るために微生物を育てています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、ポリヒドロキシアルカノエートを作[つく]るために微生物[びせいぶつ]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートは自然の中で分解されるので、海のごみを減らせると期待されています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートは自然[しぜん]の中[なか]で分解[ぶんかい]されるので、海[うみ]のごみを減[へ]らせると期待[きたい]されています。", "sentence_source": "generated"}, {"text": "この袋はポリヒドロキシアルカノエートでできているので、土に埋めても心配ありません。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "この袋[ふくろ]はポリヒドロキシアルカノエートでできているので、土[つち]に埋[う]めても心配[しんぱい]ありません。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートの原料は、サトウキビなどの植物から取った糖です。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートの原料[げんりょう]は、サトウキビなどの植物[しょくぶつ]から取[と]った糖[とう]です。", "sentence_source": "generated"}, {"text": "値段が高いのが、ポリヒドロキシアルカノエートの課題の一つです。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]いのが、ポリヒドロキシアルカノエートの課題[かだい]の一[ひと]つです。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートの研究は、大学でも盛んに行われています。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートの研究[けんきゅう]は、大学[だいがく]でも盛[さか]んに行[おこな]われています。", "sentence_source": "generated"}, {"text": "彼女はポリヒドロキシアルカノエートを使った医療用の糸について調べました。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はポリヒドロキシアルカノエートを使[つか]った医療用[いりょうよう]の糸[いと]について調[しら]べました。", "sentence_source": "generated"}, {"text": "ポリヒドロキシアルカノエートが広まれば、石油から作るプラスチックを減らせます。", "target_word": "ポリヒドロキシアルカノエート", "complexity_tier": "T3", "furigana": "ポリヒドロキシアルカノエートが広[ひろ]まれば、石油[せきゆ]から作[つく]るプラスチックを減[へ]らせます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリヒドロキシアルカノエート", "label": "基本形"}], "register": "専門的", "sense_fingerprint": "糖から微生物が作る生分解性の物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c11be19-e1cc-49c2-a822-0ba302475d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリヒドロキシアルカノエート", "is_correct": true, "explanation": "植物の糖から微生物が作る物質の名前なので、この語が入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "微生物が作る物質ではなく、この文の説明と合わないので合わない。"}, {"text": "石油", "is_correct": false, "explanation": "微生物が作るものではなく、化石燃料なので合わない。"}, {"text": "塩", "is_correct": false, "explanation": "微生物が作る物質ではなく、鉱物なので合わない。"}], "explanations": {"ポリヒドロキシアルカノエート": "植物の糖から微生物が作る物質の名前なので、この語が入る。", "砂糖": "微生物が作る物質ではなく、この文の説明と合わないので合わない。", "石油": "微生物が作るものではなく、化石燃料なので合わない。", "塩": "微生物が作る物質ではなく、鉱物なので合わない。"}, "sentence_index": 0, "correct_answer": "ポリヒドロキシアルカノエート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポリヒドロキシアルカノエートは石油から作られるので、リサイクルして使われます。", "explanation": "ここは石油から作るPETの話。ポリヒドロキシアルカノエートは植物の糖から微生物が作るので、石油由来とは言わない。"}, {"text": "ポリヒドロキシアルカノエートのバランスが崩れると、体の調子が悪くなります。", "explanation": "ここは体内で働くホルモンの意味。ポリヒドロキシアルカノエートは素材の名前なので、体内の調整物質の話とは合わない。"}, {"text": "ポリヒドロキシアルカノエートは植物の細胞壁の主な成分で、紙の原料になります。", "explanation": "ここは植物の細胞壁を作るセルロースの話。ポリヒドロキシアルカノエートは微生物が作る物質で、細胞壁の成分ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリヒドロキシアルカノエート", "is_correct": true, "explanation": "値段が高いという課題を抱える、この物質の名前なので入る。"}, {"text": "天気", "is_correct": false, "explanation": "値段の課題とは無関係で、『の課題』と合わないので合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "値段の話とは無関係で、『の課題』と合わないので合わない。"}, {"text": "方言", "is_correct": false, "explanation": "値段が高いことの課題としては成り立たないので合わない。"}], "explanations": {"ポリヒドロキシアルカノエート": "値段が高いという課題を抱える、この物質の名前なので入る。", "天気": "値段の課題とは無関係で、『の課題』と合わないので合わない。", "睡眠": "値段の話とは無関係で、『の課題』と合わないので合わない。", "方言": "値段が高いことの課題としては成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "ポリヒドロキシアルカノエート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリヒドロキシアルカノエートは、じゃがいもから取れる白い粉です。", "explanation": "ここはじゃがいものでんぷんの話。ポリヒドロキシアルカノエートは微生物が作る物質で、じゃがいもから取る粉ではないので合わない。"}, {"text": "ビールを注ぐと、ポリヒドロキシアルカノエートが立ちます。", "explanation": "ここは『泡が立つ』の泡の意味。ポリヒドロキシアルカノエートは立つものではなく素材の名前なので合わない。"}, {"text": "ポリヒドロキシアルカノエートは植物の繊維で、服を作ります。", "explanation": "ここは植物繊維の綿の話。ポリヒドロキシアルカノエートは微生物が作る物質で、植物の繊維ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポリヒドロキシアルカノエートを、植物の糖から作られます。", "corrected_sentence": "ポリヒドロキシアルカノエートは、植物の糖から作られます。", "error_description": "主語を示す『は』が正しい。『を』だと目的語になり、受身の『作られます』と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場では、ポリヒドロキシアルカノエートを袋を作っています。", "corrected_sentence": "工場では、ポリヒドロキシアルカノエートで袋を作っています。", "error_description": "材料を表すのは『で』。『を』を重ねると目的語が二つになり、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '992c9737-f860-47cb-83d3-ff1358727cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
