INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "プラスチックの一種で、植物から作られるものがあります。", "primary_collocate": null, "pronunciation": "ピーエイチエー", "ipa": "piːeitɕiːeː", "syllable_count": 7, "sentences": [{"text": "PHA は、植物から作れるプラスチックの一種です。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は、植物[しょくぶつ]から作[つく]れるプラスチックの一種[いっしゅ]です。", "sentence_source": "generated"}, {"text": "このストローの材料は、PHA です。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "このストローの材料[ざいりょう]は、PHA です。", "sentence_source": "generated"}, {"text": "PHA は土の中で、ゆっくり分解されます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は土[つち]の中[なか]で、ゆっくり分解[ぶんかい]されます。", "sentence_source": "generated"}, {"text": "PHA を使った袋が、店で配られています。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA を使[つか]った袋[ふくろ]が、店[みせ]で配[くば]られています。", "sentence_source": "generated"}, {"text": "植物の油から作った PHA で、カップを作りました。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の油[あぶら]から作[つく]った PHA で、カップを作[つく]りました。", "sentence_source": "generated"}, {"text": "PHA は普通のプラスチックより値段が高いです。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は普通[ふつう]のプラスチックより値段[ねだん]が高[たか]いです。", "sentence_source": "generated"}, {"text": "海に流れても、PHA は少しずつ分解されます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "海[うみ]に流[なが]れても、PHA は少[すこ]しずつ分解[ぶんかい]されます。", "sentence_source": "generated"}, {"text": "環境のために、PHA の製品を選ぶ人が増えました。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "環境[かんきょう]のために、PHA の製品[せいひん]を選[えら]ぶ人[ひと]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "PHA でできたフォークは、少しやわらかいです。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA でできたフォークは、少[すこ]しやわらかいです。", "sentence_source": "generated"}, {"text": "この会社は、PHA のおもちゃを作っています。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、PHA のおもちゃを作[つく]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PHA", "label": "基本形"}], "register": "polite", "sense_fingerprint": "PHA:植物由来のものもあるプラスチックの一種(素材としてのPHA)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PHA", "is_correct": true, "explanation": "正解。植物から作れるプラスチックとして説明されている語。"}, {"text": "PET", "is_correct": false, "explanation": "PET は石油から作られるプラスチックなので、植物から作れるという説明と合わない。"}, {"text": "PVC", "is_correct": false, "explanation": "PVC は塩化ビニルを原料とするプラスチックで、植物から作るものではないので合わない。"}, {"text": "ABS", "is_correct": false, "explanation": "ABS は石油由来のプラスチックで、植物から作れるという説明と合わない。"}], "explanations": {"PHA": "正解。植物から作れるプラスチックとして説明されている語。", "PET": "PET は石油から作られるプラスチックなので、植物から作れるという説明と合わない。", "PVC": "PVC は塩化ビニルを原料とするプラスチックで、植物から作るものではないので合わない。", "ABS": "ABS は石油由来のプラスチックで、植物から作れるという説明と合わない。"}, "sentence_index": 0, "correct_answer": "PHA"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "PHA は、料理をあまくするために使います。", "explanation": "ここは〈砂糖〉の意味。PHA はプラスチックで、料理をあまくするものではないので合わない。"}, {"text": "PHA は、字を書くために使います。", "explanation": "ここは〈紙〉の意味。PHA は書くための紙ではなくプラスチックなので合わない。"}, {"text": "PHA は、汚れた服を洗うために使います。", "explanation": "ここは〈洗剤〉の意味。PHA は洗うための物ではなく、プラスチックなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PHA", "is_correct": true, "explanation": "正解。自然の中で分解される素材として文の内容に合う。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは海に流れても分解されず残るので、分解の文と合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は海に流れても分解されず残るので、分解の文に合わない。"}, {"text": "アルミ", "is_correct": false, "explanation": "アルミは海に流れても分解されないので、文の内容と合わない。"}], "explanations": {"PHA": "正解。自然の中で分解される素材として文の内容に合う。", "ガラス": "ガラスは海に流れても分解されず残るので、分解の文と合わない。", "石": "石は海に流れても分解されず残るので、分解の文に合わない。", "アルミ": "アルミは海に流れても分解されないので、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "PHA"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "PHA は、機械に電気を送る電池です。", "explanation": "ここは〈電池〉の意味。PHA は電気を送る電池ではなく、プラスチックなので合わない。"}, {"text": "PHA は、魚の味を引き立てる醤油です。", "explanation": "ここは〈醤油〉の意味。PHA は調味料ではないので、魚の味を引き立てる醤油とは合わない。"}, {"text": "PHA は、病気の人が飲んで治す薬です。", "explanation": "ここは〈薬〉の意味。PHA は飲んで病気を治すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "PHA に作った袋が、店で配られています。", "corrected_sentence": "PHA で作った袋が、店で配られています。", "error_description": "「PHA に作った」は誤り。材料を表すには「で」を使うので、「PHA で作った」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "環境のために、PHA を袋を使う店が増えました。", "corrected_sentence": "環境のために、PHA の袋を使う店が増えました。", "error_description": "「PHA を袋を」は目的語が二つ重なる誤り。「PHA の袋」と「の」でつなぐのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
