INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ポリヒドロキシアルカノエートの略。微生物が作る、自然に分解されるプラスチック。", "primary_collocate": null, "pronunciation": "ピーエイチエー", "ipa": "piːeitɕiːeː", "syllable_count": 7, "sentences": [{"text": "PHA はポリヒドロキシアルカノエートの略です。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA はポリヒドロキシアルカノエートの略[りゃく]です。", "sentence_source": "generated"}, {"text": "PHA は、微生物が体の中に作る物質です。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は、微生物[びせいぶつ]が体[からだ]の中[なか]に作[つく]る物質[ぶっしつ]です。", "sentence_source": "generated"}, {"text": "微生物にえさを与えて、PHA を作らせます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "微生物[びせいぶつ]にえさを与[あた]えて、PHA を作[つく]らせます。", "sentence_source": "generated"}, {"text": "PHA は自然の中で分解されるので、ごみが残りません。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は自然[しぜん]の中[なか]で分解[ぶんかい]されるので、ごみが残[のこ]りません。", "sentence_source": "generated"}, {"text": "研究者は、PHA を大量に作る菌を探しています。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、PHA を大量[たいりょう]に作[つく]る菌[きん]を探[さが]しています。", "sentence_source": "generated"}, {"text": "PHA は、土や海の中の微生物によって分解されます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA は、土[つち]や海[うみ]の中[なか]の微生物[びせいぶつ]によって分解[ぶんかい]されます。", "sentence_source": "generated"}, {"text": "この実験では、PHA の量を毎日測りました。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、PHA の量[りょう]を毎日[まいにち]測[はか]りました。", "sentence_source": "generated"}, {"text": "PHA を作る菌は、砂糖を食べて育ちます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "PHA を作[つく]る菌[きん]は、砂糖[さとう]を食[た]べて育[そだ]ちます。", "sentence_source": "generated"}, {"text": "授業で、PHA がなぜ分解されるのかを学びました。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、PHA がなぜ分解[ぶんかい]されるのかを学[まな]びました。", "sentence_source": "generated"}, {"text": "海でも分解される PHA は、医療にも使われます。", "target_word": "PHA", "complexity_tier": "T3", "furigana": "海[うみ]でも分解[ぶんかい]される PHA は、医療[いりょう]にも使[つか]われます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "PHA", "label": "基本形"}], "register": "polite", "sense_fingerprint": "PHA:ポリヒドロキシアルカノエートの略。微生物が作る生分解性プラスチック", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0493e7e2-a3df-44a8-bdab-7d88b7319a55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "PHA", "is_correct": true, "explanation": "正解。ポリヒドロキシアルカノエートの略として定義されている語。"}, {"text": "PLA", "is_correct": false, "explanation": "PLA はポリ乳酸の略で、ポリヒドロキシアルカノエートの略ではないので合わない。"}, {"text": "PET", "is_correct": false, "explanation": "PET は別のプラスチックの略で、この定義とは合わない。"}, {"text": "PVC", "is_correct": false, "explanation": "PVC は塩化ビニルのプラスチックの略で、この定義とは合わない。"}], "explanations": {"PHA": "正解。ポリヒドロキシアルカノエートの略として定義されている語。", "PLA": "PLA はポリ乳酸の略で、ポリヒドロキシアルカノエートの略ではないので合わない。", "PET": "PET は別のプラスチックの略で、この定義とは合わない。", "PVC": "PVC は塩化ビニルのプラスチックの略で、この定義とは合わない。"}, "sentence_index": 0, "correct_answer": "PHA"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "PHA は、パンをふくらませるために使います。", "explanation": "ここは〈酵母〉の意味。PHA は生分解性のプラスチックで、パンをふくらませる働きはないので合わない。"}, {"text": "PHA は、料理の味をととのえるために入れます。", "explanation": "ここは〈塩〉の意味。PHA は調味料ではないので、料理の味つけには合わない。"}, {"text": "PHA は、手の汚れを落とすために使います。", "explanation": "ここは〈石けん〉の意味。PHA は洗うためのものではなく、プラスチックなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "PHA", "is_correct": true, "explanation": "正解。「PHA の量」として、実験で測る対象に合う。"}, {"text": "性格", "is_correct": false, "explanation": "性格は量で測る対象ではないので、「性格の量」は文に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は量を測るものではないので、「名前の量」は文に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は実験で量を測る対象ではないので、文に合わない。"}], "explanations": {"PHA": "正解。「PHA の量」として、実験で測る対象に合う。", "性格": "性格は量で測る対象ではないので、「性格の量」は文に合わない。", "名前": "名前は量を測るものではないので、「名前の量」は文に合わない。", "年齢": "年齢は実験で量を測る対象ではないので、文に合わない。"}, "sentence_index": 6, "correct_answer": "PHA"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "PHA は、体の中で食べ物を消化する酵素です。", "explanation": "ここは〈酵素〉の意味。PHA は消化を助けるものではなく、プラスチックなので合わない。"}, {"text": "PHA は、ふろに入れて体を温める入浴剤です。", "explanation": "ここは〈入浴剤〉の意味。PHA はおふろに入れるものではないので合わない。"}, {"text": "PHA は、車を走らせるために入れるガソリンです。", "explanation": "ここは〈ガソリン〉の意味。PHA は燃料ではないので、車を走らせる用途とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630c81d5-3aa8-4681-8e2d-78de6c9979d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
