INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38668, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「ポリ」は、たくさんのものがつながったものを表す言葉です。", "primary_collocate": null, "pronunciation": "ぽり", "ipa": "poɾi", "syllable_count": 2, "sentences": [{"text": "「ポリ」は、たくさんのものがつながっていることを表します。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」は、たくさんのものがつながっていることを表(あらわ)します。", "sentence_source": "generated"}, {"text": "「ポリ」という言葉は、「多くの」という意味で使います。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」という言葉(ことば)は、「多(おお)くの」という意味(いみ)で使(つか)います。", "sentence_source": "generated"}, {"text": "先生は「ポリ」とは「たくさん」という意味だと説明しました。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "先生(せんせい)は「ポリ」とは「たくさん」という意味(いみ)だと説明(せつめい)しました。", "sentence_source": "generated"}, {"text": "「ポリ」のついた言葉には、小さな部分が長くつながったものが多い。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」のついた言葉(ことば)には、小(ちい)さな部分(ぶぶん)が長(なが)くつながったものが多(おお)い。", "sentence_source": "generated"}, {"text": "「ポリ」は「一つ」ではなく、「たくさん」を表す言葉です。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」は「一(ひと)つ」ではなく、「たくさん」を表(あらわ)す言葉(ことば)です。", "sentence_source": "generated"}, {"text": "「モノ」は「一つ」を、「ポリ」は「たくさん」を表します。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「モノ」は「一(ひと)つ」を、「ポリ」は「たくさん」を表(あらわ)します。", "sentence_source": "generated"}, {"text": "辞書で「ポリ」を引くと、「多くの」という意味が出ています。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "辞書(じしょ)で「ポリ」を引(ひ)くと、「多(おお)くの」という意味(いみ)が出(で)ています。", "sentence_source": "generated"}, {"text": "「ポリ」を言葉の前につけると、数が多いという意味になる。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」を言葉(ことば)の前(まえ)につけると、数(かず)が多(おお)いという意味(いみ)になる。", "sentence_source": "generated"}, {"text": "子どもに「ポリ」の意味を聞かれて、「たくさんつながったもの」と答えた。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "子(こ)どもに「ポリ」の意味(いみ)を聞(き)かれて、「たくさんつながったもの」と答(こた)えた。", "sentence_source": "generated"}, {"text": "「ポリ」の意味を知ると、新しい言葉が覚えやすくなります。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」の意味(いみ)を知(し)ると、新(あたら)しい言葉(ことば)が覚(おぼ)えやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリ", "label": "接頭辞形"}], "register": "neutral", "sense_fingerprint": "接頭語ポリ:たくさんのものがつながっていることを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリ", "is_correct": true, "explanation": "たくさんのものがつながっていることを表す接頭語で、ここに入るのはこの語だけ。"}, {"text": "ミニ", "is_correct": false, "explanation": "ミニは『小型』の意味で、たくさんのものがつながることは表さない。"}, {"text": "ソロ", "is_correct": false, "explanation": "ソロは『ひとりで』の意味で、多くのものがつながる意味には合わない。"}, {"text": "ゼロ", "is_correct": false, "explanation": "ゼロは『なし』の意味で、たくさんのものがつながるという意味とは反対。"}], "explanations": {"ポリ": "たくさんのものがつながっていることを表す接頭語で、ここに入るのはこの語だけ。", "ミニ": "ミニは『小型』の意味で、たくさんのものがつながることは表さない。", "ソロ": "ソロは『ひとりで』の意味で、多くのものがつながる意味には合わない。", "ゼロ": "ゼロは『なし』の意味で、たくさんのものがつながるという意味とは反対。"}, "sentence_index": 0, "correct_answer": "ポリ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアのポリが外れて、家に入れなかった。", "explanation": "ここは〈鎖〉の意味。ポリは物を連ねる金具の名前としては使わないので、この文脈では合わない。"}, {"text": "会場にはポリの人が集まった。", "explanation": "ポリは言葉の前に直接つける〈接頭語〉なので、『ポリの人』のように単独で名詞を修飾する使い方はできない。ここは使い方が誤り。"}, {"text": "ポリは、ひとりで取り組む作業のことを指す。", "explanation": "ここは〈単独〉の意味。ポリは多くのものがつながることを表すので、ひとりの作業を指す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリ", "is_correct": true, "explanation": "辞書で引くと『多くの』と出るのはポリ。ここに入るのはこの語だけ。"}, {"text": "モノ", "is_correct": false, "explanation": "モノは『一つ』を表す語で、『多くの』という意味は出ない。"}, {"text": "アンチ", "is_correct": false, "explanation": "アンチは『反対』の意味で、『多くの』とは結びつかない。"}, {"text": "ハーフ", "is_correct": false, "explanation": "ハーフは『半分』の意味で、『多くの』という説明とは合わない。"}], "explanations": {"ポリ": "辞書で引くと『多くの』と出るのはポリ。ここに入るのはこの語だけ。", "モノ": "モノは『一つ』を表す語で、『多くの』という意味は出ない。", "アンチ": "アンチは『反対』の意味で、『多くの』とは結びつかない。", "ハーフ": "ハーフは『半分』の意味で、『多くの』という説明とは合わない。"}, "sentence_index": 6, "correct_answer": "ポリ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリ店が町に増えた。", "explanation": "ここは〈チェーン店〉の意味。ポリはこの形で店の種類を表す語としては使えない。"}, {"text": "ポリ反応が次々と起きた。", "explanation": "ここは〈連鎖〉の意味。ポリはこの言い方の語を作らない。"}, {"text": "ポリは、一度きりの出来事を表す言葉です。", "explanation": "ここは〈一回〉の意味。ポリは多くのつながりを表すので、一度きりの出来事を表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38668, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "「ポリ」に言葉の前につけると、数が多いという意味がある。", "corrected_sentence": "「ポリ」を言葉の前につけると、数が多いという意味がある。", "error_description": "『つける』は目的語（ポリ）に『を』を使う。『に』は誤りで、文の働きが合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38668, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "「ポリ」を意味を覚えておくと、新しい言葉が理解しやすくなります。", "corrected_sentence": "「ポリ」の意味を覚えておくと、新しい言葉が理解しやすくなります。", "error_description": "目的語の『を』が二つ重なっている。『意味』は『の』で『ポリ』に続けて修飾する必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
