INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「ポリ」は接頭語で、多くの、複数の、あるいは重合体（ポリマー）であることを示します。化学や素材の分野でよく使われます。", "primary_collocate": null, "pronunciation": "ぽり", "ipa": "poɾi", "syllable_count": 2, "sentences": [{"text": "化学では、「ポリ」は重合体を示す接頭語として使われます。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "化学(かがく)では、「ポリ」は重合体(じゅうごうたい)を示(しめ)す接頭語(せっとうご)として使(つか)われます。", "sentence_source": "generated"}, {"text": "素材の名前に「ポリ」がつくと、重合体であることを表す。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "素材(そざい)の名前(なまえ)に「ポリ」がつくと、重合体(じゅうごうたい)であることを表(あらわ)す。", "sentence_source": "generated"}, {"text": "「ポリ」は「複数の」という意味を持つ接頭語です。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」は「複数(ふくすう)の」という意味(いみ)を持(も)つ接頭語(せっとうご)です。", "sentence_source": "generated"}, {"text": "理科の授業で、「ポリ」が重合体を示すことを学びました。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "理科(りか)の授業(じゅぎょう)で、「ポリ」が重合体(じゅうごうたい)を示(しめ)すことを学(まな)びました。", "sentence_source": "generated"}, {"text": "「ポリ」を「モノ」に替えると、重合体ではなく単量体を指す。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」を「モノ」に替(か)えると、重合体(じゅうごうたい)ではなく単量体(たんりょうたい)を指(さ)す。", "sentence_source": "generated"}, {"text": "素材の名前の初めにある「ポリ」は、多数の分子がつながっていることを示す。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "素材(そざい)の名前(なまえ)の初(はじ)めにある「ポリ」は、多数(たすう)の分子(ぶんし)がつながっていることを示(しめ)す。", "sentence_source": "generated"}, {"text": "化学の本では、「ポリ」という接頭語がよく出てきます。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "化学(かがく)の本(ほん)では、「ポリ」という接頭語(せっとうご)がよく出(で)てきます。", "sentence_source": "generated"}, {"text": "「ポリ」は、素材の名前を作るときによく使われる。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」は、素材(そざい)の名前(なまえ)を作(つく)るときによく使(つか)われる。", "sentence_source": "generated"}, {"text": "論文の用語集に、「ポリ」の意味が書いてありました。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "論文(ろんぶん)の用語集(ようごしゅう)に、「ポリ」の意味(いみ)が書(か)いてありました。", "sentence_source": "generated"}, {"text": "「ポリ」がつく素材の名前は、化学の本でよく見かけます。", "target_word": "ポリ", "complexity_tier": "T3", "furigana": "「ポリ」がつく素材(そざい)の名前(なまえ)は、化学(かがく)の本(ほん)でよく見(み)かけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリ", "label": "接頭辞形"}], "register": "technical", "sense_fingerprint": "接頭語ポリ:多数・複数、重合体であることを示す(化学・素材用語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリ", "is_correct": true, "explanation": "重合体を示す接頭語として使われるのはポリ。ここに入るのはこの語だけ。"}, {"text": "ジ", "is_correct": false, "explanation": "ジは『二つ』を表す接頭語で、重合体を示すものではない。"}, {"text": "トリ", "is_correct": false, "explanation": "トリは『三つ』を表す接頭語で、重合体を示すものではない。"}, {"text": "テトラ", "is_correct": false, "explanation": "テトラは『四つ』を表す接頭語で、重合体を示すものではない。"}], "explanations": {"ポリ": "重合体を示す接頭語として使われるのはポリ。ここに入るのはこの語だけ。", "ジ": "ジは『二つ』を表す接頭語で、重合体を示すものではない。", "トリ": "トリは『三つ』を表す接頭語で、重合体を示すものではない。", "テトラ": "テトラは『四つ』を表す接頭語で、重合体を示すものではない。"}, "sentence_index": 0, "correct_answer": "ポリ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポリは、同じ金属だけでできたものを指す。", "explanation": "ここは〈合金〉の意味。ポリは多数の分子がつながったものを表すので、この使い方は合わない。"}, {"text": "ポリは小さな分子で、ほかの分子と結びついて重合体を作る。", "explanation": "ここは〈モノマー（単量体）〉の説明。ポリは重合体そのものを表すので、小さな分子の意味では使えない。"}, {"text": "ポリは、電子が原子核の周りを回っている。", "explanation": "ここは〈原子〉の説明。ポリは原子を指す語ではないので、この文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリ", "is_correct": true, "explanation": "化学の本でよく出てくる『ポリ』という接頭語はこの語。ここに入るのはこの語だけ。"}, {"text": "リンゴ", "is_correct": false, "explanation": "リンゴは果物の名前で、接頭語ではないので入らない。"}, {"text": "ドラマ", "is_correct": false, "explanation": "ドラマは名詞で、接頭語ではないので入らない。"}, {"text": "ハンバーガー", "is_correct": false, "explanation": "ハンバーガーは名詞で、接頭語ではないので入らない。"}], "explanations": {"ポリ": "化学の本でよく出てくる『ポリ』という接頭語はこの語。ここに入るのはこの語だけ。", "リンゴ": "リンゴは果物の名前で、接頭語ではないので入らない。", "ドラマ": "ドラマは名詞で、接頭語ではないので入らない。", "ハンバーガー": "ハンバーガーは名詞で、接頭語ではないので入らない。"}, "sentence_index": 6, "correct_answer": "ポリ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリは、一つだけのものを指す語です。", "explanation": "ここは〈モノ〉（一つ）の意味。ポリは多くのものがつながったことを表すので、一つだけを指す語としては使えない。"}, {"text": "ポリは、静かな湖の水面のような、なめらかな状態を指す。", "explanation": "ここは〈平ら〉の意味。ポリは重合体や多数のつながりを表すので、表面の状態を指す語としては使えない。"}, {"text": "ポリは、凍った水が溶けて戻る現象を指す。", "explanation": "ここは〈融解〉の意味。ポリは重合体や多数のつながりを表すので、固体が液体になる現象を指す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "「ポリ」に重合体を示す接頭語として使われます。", "corrected_sentence": "「ポリ」は重合体を示す接頭語として使われます。", "error_description": "主題を示すのは『は』。『に』は誤りで、主題の助詞として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38669, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "「ポリ」を素材の名前の初めに付くことが多い。", "corrected_sentence": "「ポリ」が素材の名前の初めに付くことが多い。", "error_description": "『付く』は自動詞なので主語に『が』を使う。『を』では目的語になり、文として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
