INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ヨーグルトなどに ふくまれる すっぱい もの。", "primary_collocate": null, "pronunciation": "にゅうさん", "ipa": "ɲɯːsaɴ", "syllable_count": 4, "sentences": [{"text": "ヨーグルトがすっぱいのは、乳酸が入っているからです。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "ヨーグルトがすっぱいのは、乳酸(にゅうさん)が入(はい)っているからです。", "sentence_source": "generated"}, {"text": "この飲み物には乳酸が入っていて、少しすっぱいです。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "この飲(の)み物(もの)には乳酸(にゅうさん)が入(はい)っていて、少(すこ)しすっぱいです。", "sentence_source": "generated"}, {"text": "乳酸は、ヨーグルトやチーズに含まれています。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "乳酸(にゅうさん)は、ヨーグルトやチーズに含(ふく)まれています。", "sentence_source": "generated"}, {"text": "乳酸のおかげで、ヨーグルトはすっぱい味になります。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "乳酸(にゅうさん)のおかげで、ヨーグルトはすっぱい味(あじ)になります。", "sentence_source": "generated"}, {"text": "私はヨーグルトの乳酸のすっぱさが好きです。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "私(わたし)はヨーグルトの乳酸(にゅうさん)のすっぱさが好(す)きです。", "sentence_source": "generated"}, {"text": "乳酸が多い食べ物は、体にいいと言われます。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "乳酸(にゅうさん)が多(おお)い食(た)べ物(もの)は、体(からだ)にいいと言(い)われます。", "sentence_source": "generated"}, {"text": "漬物にも乳酸が含まれているので、少しすっぱいです。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "漬物(つけもの)にも乳酸(にゅうさん)が含(ふく)まれているので、少(すこ)しすっぱいです。", "sentence_source": "generated"}, {"text": "牛乳が発酵すると、乳酸ができてすっぱくなります。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "牛乳(ぎゅうにゅう)が発酵(はっこう)すると、乳酸(にゅうさん)ができてすっぱくなります。", "sentence_source": "generated"}, {"text": "運動のあと、足に乳酸がたまって疲れました。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "運動(うんどう)のあと、足(あし)に乳酸(にゅうさん)がたまって疲(つか)れました。", "sentence_source": "generated"}, {"text": "弟は乳酸の入った飲み物を毎朝飲んでいます。", "target_word": "乳酸", "complexity_tier": "T3", "furigana": "弟(おとうと)は乳酸(にゅうさん)の入(はい)った飲(の)み物(もの)を毎朝(まいあさ)飲(の)んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乳酸", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ヨーグルトなどに入っているすっぱいもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38670, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砂糖", "is_correct": false, "explanation": "砂糖が入っていても、ヨーグルトは甘くなるだけで、すっぱくなる理由にはならない。"}, {"text": "乳酸", "is_correct": true, "explanation": "すっぱさの原因となる物質で、「乳酸が入っているから」という理由が成り立つ。"}, {"text": "塩", "is_correct": false, "explanation": "塩はしょっぱさの原因で、すっぱさの理由にはならない。"}, {"text": "香料", "is_correct": false, "explanation": "香料は香りをつけるもので、すっぱさの理由にはならない。"}], "explanations": {"砂糖": "砂糖が入っていても、ヨーグルトは甘くなるだけで、すっぱくなる理由にはならない。", "乳酸": "すっぱさの原因となる物質で、「乳酸が入っているから」という理由が成り立つ。", "塩": "塩はしょっぱさの原因で、すっぱさの理由にはならない。", "香料": "香料は香りをつけるもので、すっぱさの理由にはならない。"}, "sentence_index": 0, "correct_answer": "乳酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ヨーグルトを作るときは、乳酸を砂糖と一緒に混ぜて、甘い味を作る。", "explanation": "ここは〈甘味〉の意味。乳酸はすっぱさのもとで、甘くする働きはない。"}, {"text": "ヨーグルトのなめらかな乳酸が好きだ。", "explanation": "ここは〈食感〉の意味。なめらかさは食感を表す語で、すっぱいものを指す乳酸とは合わない。"}, {"text": "ヨーグルトの乳酸の香りが食欲をそそる。", "explanation": "ここは〈香り〉の意味。乳酸はすっぱさのもとで、香りを表す語とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38670, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甘み", "is_correct": false, "explanation": "甘みが含まれていると、少しすっぱいという結果にはならず、文の理由として合わない。"}, {"text": "乳酸", "is_correct": true, "explanation": "すっぱさの原因となる物質で、「含まれているので、少しすっぱい」という理由が成り立つ。"}, {"text": "苦み", "is_correct": false, "explanation": "苦みはすっぱさの理由にならず、文の流れに合わない。"}, {"text": "辛み", "is_correct": false, "explanation": "辛みはすっぱさの理由にならず、文の流れに合わない。"}], "explanations": {"甘み": "甘みが含まれていると、少しすっぱいという結果にはならず、文の理由として合わない。", "乳酸": "すっぱさの原因となる物質で、「含まれているので、少しすっぱい」という理由が成り立つ。", "苦み": "苦みはすっぱさの理由にならず、文の流れに合わない。", "辛み": "辛みはすっぱさの理由にならず、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "乳酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は乳酸を入れて、ヨーグルトを甘くして食べている。", "explanation": "ここは〈砂糖〉の意味。甘くするために入れるのは砂糖で、すっぱさのもとの乳酸では甘くならない。"}, {"text": "弟は乳酸の白い色が好きで、毎朝食べている。", "explanation": "ここは〈色〉の意味。ヨーグルトの見た目を表す語で、すっぱさのもとの乳酸とは合わない。"}, {"text": "弟は、生クリームのために牛乳の乳酸を分けている。", "explanation": "ここは〈乳脂肪〉の意味。生クリームは牛乳の脂肪分を集めたもので、すっぱいものを指す乳酸では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このチーズは、乳酸を多いので酸味が強い。", "corrected_sentence": "このチーズは、乳酸が多いので酸味が強い。", "error_description": "「を」が誤り。「多い」は主語を示す「が」を取るので、「乳酸が多い」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38670, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ヨーグルトのすっぱい味は、乳酸をよるものだ。", "corrected_sentence": "ヨーグルトのすっぱい味は、乳酸によるものだ。", "error_description": "「を」が誤り。「よる」は原因を「に」で示すので「乳酸によるもの」が正しい。「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
