INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38671, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「できる」の主語は乳酸なので「が」。「乳酸ができて」で乳酸が生じるという意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「乳酸にできる」とは言わない。「できる」は「〜ができる」の形で主語を取る。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「乳酸へできる」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すので、「乳酸よりできる」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「できる」の主語は乳酸なので「が」。「乳酸ができて」で乳酸が生じるという意味になる。", "に": "「乳酸にできる」とは言わない。「できる」は「〜ができる」の形で主語を取る。", "へ": "「へ」は方向を表すので、「乳酸へできる」は成り立たない。", "より": "「より」は比較や起点を表すので、「乳酸よりできる」では意味が通らない。"}, "error_tags": {"に": "位置・対象", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
